struct LazySegmentTree {

	int n;
	std::vector<long long> nodes, lazy;
	LazySegmentTree(std::vector<long long> v) {
		int sz = (int)v.size();
		n = 1; while (n < sz) n *= 2;
		nodes.resize(2 * n - 1);
		lazy.resize(2 * n - 1, 0);

		for (int i = 0; i < sz; i++) nodes[i + n - 1] = v[i];
		for (int i = n - 2; i >= 0; i--) nodes[i] = nodes[i * 2 + 1] + nodes[i * 2 + 2];
	}

	void eval(int k, int l, int r) {
		if (lazy[k] != 0) {
			nodes[k] += lazy[k] * (r - l);
			if (r - l > 1) {
				lazy[2 * k + 1] += lazy[k];
				lazy[2 * k + 2] += lazy[k];
			}
			lazy[k] = 0;
		}
	}
	void add(int a, int b, int x) {
		add(a, b, x, 0, 0, n);
	}
	long long getsum(int a, int b) {
		return getsum(a, b, 0, 0, n);
	}
private:
	void add(int a, int b, int x, int k, int l, int r) {
		eval(k, l, r);
		if (b <= l || r <= a)return;
		if (a <= l && r <= b) {
			lazy[k] += x;
			eval(k, l, r);
		}
		else {
			add(a, b, x, 2 * k + 1, l, (l + r) / 2);
			add(a, b, x, 2 * k + 2, (l + r) / 2, r);
			nodes[k] = nodes[2 * k + 1] + nodes[2 * k + 2];
		}
	}

	long long getsum(int a, int b, int k, int l, int r) {
		if (b <= l || r <= a)return 0;
		eval(k, l, r);
		if (a <= l && r <= b)return nodes[k];
		return getsum(a, b, 2 * k + 1, l, (l + r) / 2) + getsum(a, b, 2 * k + 2, (l + r) / 2, r);
	}
};

int main() {
