template <typename Int>
class LazySegmentTree {
private:
    int N;
public:
    vector<Int> base, lazy;
    // sz: size of array size
    LazySegmentTree(int sz) {
        N = 1;
        while (N < sz) N *= 2;
        base.resize(2 * N - 1, 0);
        lazy.resize(2 * N - 1, 0);
    }

    // propagate k-th lazy node [l, r)
    // inner state does not change if repeating this >= 1 times
    void propagate(int k, int l, int r) {
        base[k] += lazy[k];
        if(r - l > 1) {
            lazy[2 * k + 1] += lazy[k];
            lazy[2 * k + 2] += lazy[k];
        }
        lazy[k] = 0;
    }

    // update
    void add(int a, int b, Int x, int k=0, int l=0, int r=-1) {
        if(r == -1) r = N;
        propagate(k, l, r);

        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] += x;
            propagate(k, l, r);
        }
        else {
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            base[k] = base[2 * k + 1] + base[2 * k + 2];
        }
    }

    // query
    ll get_sum(int a, int b, int k=0, int l=0, int r=-1) {
        if(r == -1) r = N;
        propagate(k, l, r);
        if(b <= l || r <= a) return 0;
        if(a <= l && r <= b) return base[k];
        Int vl = get_sum(a, b, 2 * k + 1, l, (l + r) / 2);
        Int vr = get_sum(a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;
    }
};

