template<typename T>
struct BIT{
    private:
        using Func = function<T(T, T)>;

        int n;
        vector<T> node;

        T init_v;
        Func func;

    public:

        BIT(vector<T> a, Func _func, T _init_v) {
            n = a.size() + 1;
            init_v = _init_v;
            func = _func;

            node.resize(n, init_v);
            for(int i=1; i<n; i++) if((i+(i&-i)) < n) node[i+(i&-i)] = func(node[i+(i&-i)], node[i]);
        }

        BIT() {}

        void add(int pos, T v) {
            while(pos < n){
                node[pos] = func(node[pos], v);
                pos += pos & -pos;
            }
        }

        T sum(int pos){
            T res = init_v;
            while(pos > 0){
                res = func(res, node[pos]);
                pos = pos & (pos-1);
            }
            return res;
        }
};

template<typename T>
struct SecAddBIT{
    private:
        using Func = function<T(T, T)>;
        using MulInt = function<T(T,int)>;
        using Unary = function<T(T)>;
        BIT<T> bit0, bit1;
        Func _add;
        MulInt _mul;
        Unary _inv;

    public:

        SecAddBIT(vector<T> a, Func add_func, MulInt mul_func, Unary inv, T _init_v) {
            int n = a.size();
            _add = add_func;
            _mul = mul_func;
            _inv = inv;
            bit0 = BIT<T>(a, add_func, _init_v);
            bit1 = BIT<T>(vector<T>(n,0), add_func, _init_v);
        }

        void add(int l, int r, T v) {
            bit0.add(l, _mul(_inv(v),l-1));
            bit0.add(r+1, _mul(v,r));
            bit1.add(l, v);
            bit1.add(r+1, _inv(v));
        }

        T sum(int pos){
            return _add(_mul(bit1.sum(pos),pos), bit0.sum(pos));
        }
};

