void add(int a, int b, int x){
	while(a <= b && a%B != 0){
		bucket[a/B][a%B] += x;
		a++;
	}
	while(a <= b && b%B != B-1){
		bucket[b/B][b%B] += x;
		b--;
	}
	while(a < b){
		udata[a/B] += x;
		a += B;
	}
}

int get(int a, int b){
	int ans = 0;
	while(a <= b && a%B != 0){
		ans += bucket[a/B][a%B];
		a++;
	}
	while(a <= b && b%B != B-1){
		ans += bucket[b/B][b%B];
		b--;
	}
	while(a < b){
		ans = udata[a/B];
		a += B;
	}
	return ans;
}

