struct LazySegTree {
	vector<ll> node, lazy;
	int n;

	LazySegTree(int _n) {
		n = 1;
		while (n < _n) n *= 2;

		node.resize(2 * n - 1, 0);
		lazy.resize(2 * n - 1, 0);
	}

	void eval(int k, int l, int r) {
		if (lazy[k] == 0) return;
		node[k] += lazy[k];

		if (r - l > 1) {
			lazy[k * 2 + 1] += lazy[k] / 2;
			lazy[k * 2 + 2] += lazy[k] / 2;
		}

		lazy[k] = 0;
	}

	void add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		eval(k, l, r);

		if (b <= l || r <= a) return;
		if (a <= l && r <= b) {
			lazy[k] += (r - l) * x;
			eval(k, l, r);
		}
		else {
			add(a, b, x, k * 2 + 1, l, (l + r) / 2);
			add(a, b, x, k * 2 + 2, (l + r) / 2, r);
			node[k] = node[k * 2 + 1] + node[k * 2 + 2];
		}
	}

	ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		eval(k, l, r);

		if (b <= l || r <= a) return 0;
		if (a <= l && r <= b) return node[k];
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return vl + vr;
	}
};

int main() {
	int n, q;
	cin >> n >> q;

	LazySegTree st(n);

	while (q--) {
		int a, b, c, d;
		cin >> a >> b >> c;
		if (a == 0) {
			cin >> d;
			st.add(b - 1, c, d);
		}
		else {
			cout << st.query(b - 1, c) << endl;
		}
	}
	return 0;
}

