//sqrtN -> 最大値のみに対応できればいいので，それを使う
const int sqrtN = 512;
struct SqrtDecomposition {
  int N, K;
  vector<int> data;
  vector<int> bucketData;
  vector<int> bucketSum;
  const int INIT_VALUE = 0;

  SqrtDecomposition(int n) : N(n) {
    //分割数
    K = (N + sqrtN - 1) / sqrtN;
    data.assign(K * sqrtN, INIT_VALUE);
    bucketData.assign(K, INIT_VALUE);
    bucketSum.assign(K, INIT_VALUE);
  }
  //ここまで共通

  void add(int s, int t, int x) {
    for(int k = 0; k < K; ++k) {
      //各バケツをループ
      int l = k * sqrtN;
      int r = (k + 1) * sqrtN;
      if(s >= r || t <= l) continue;
      if(l >= s && t >= r) {
        //完全に区間内
        bucketData[k] += x;
      } else {
        //バケツを分配
        // if(bucketData[k] != 0) {
        //   for(int i = l; i < r; ++i) {
        //     data[i] += bucketData[k];
        //   }
        //   bucketData[k] = 0;
        // }

        for(int i = max(s, l); i < min(t, r); ++i) {
          data[i] += x;
          bucketSum[k] += x;
        }
      }
    }
  }

  int getSum(int s, int t) {
    int sum = 0;
    for(int k = 0; k < K; ++k) {
      int l = k * sqrtN;
      int r = (k + 1) * sqrtN;
      if(r <= s || l >= t) continue;
      if(r <= t && l >= s) {
        sum += bucketData[k] * sqrtN + bucketSum[k];
      } else {
        for(int i = max(s, l); i < min(t, r); ++i) {
          sum += data[i] + bucketData[k];
        }
      }
    }
    return sum;
  }
};

signed main(void) {
  cin.tie(0); ios::sync_with_stdio(false);

  int n, q;
  cin >> n >> q;

  SqrtDecomposition sq(n);

  for(int i = 0; i < q; i++) {
    int qtype;
    cin >> qtype;
    if(qtype == 0) {
      int s, t, x;
      cin >> s >> t >> x;
      --s;
      sq.add(s, t, x);
    } else {
      int s, t;
      cin >> s >> t;
      --s;
      cout << sq.getSum(s, t) << endl;
    }
  }  

}

