	REP(_, q) {
		VAR(int, c);
		if (c == 0) {
			VAR(int, l, r, x);
			--l; --r;
			while (l <= r && l%DIV != 0) {
				a[l] += x;
				seg[l / DIV] += x;
				++l;
			}
			while (l <= r && r%DIV != DIV - 1) {
				a[r] += x;
				seg[r / DIV] += x;
				--r;
			}
			while (l < r) {
				lazy[l / DIV] += x;
				l += DIV;
			}
		}
		else {
			VAR(int, l, r);
			--l; --r;
			int res = 0;
			while (l <= r && l%DIV != 0) {
				int p = l / DIV;
				if (lazy[p] != 0) {
					FOR(i, p*DIV, (p + 1)*DIV) {
						a[i] += lazy[p];
						seg[p] += lazy[p];
					}
					lazy[p] = 0;
