template <class Monoid, class OperatorMonoid>
struct Segtree {
    using T = typename Monoid::T;
    using E = typename OperatorMonoid::E;
    int n, h;
    vector<T> dat;
    vector<E> laz;
    Segtree(int n_) {
        n = 1, h = 1;
        while(n < n_) {
            n <<= 1;
            ++h;
        }
        dat.resize(2 * n, Monoid::id());
        laz.resize(2 * n, OperatorMonoid::id());
    }
    int len(int k) { return (n >> (int)log2(k)); }
    T prop(int k) {
        if(laz[k] == OperatorMonoid::id()) {
            return dat[k];
        }
        dat[k] = OperatorMonoid::merge(dat[k], laz[k], len(k));
        if(k < n) {
            laz[k << 1] = OperatorMonoid::op(laz[k << 1], laz[k]);
            laz[k << 1 | 1] = OperatorMonoid::op(laz[k << 1 | 1], laz[k]);
        }
        laz[k] = OperatorMonoid::id();
        return dat[k];
    }
    void down(int k) {
        for(int i = h; i > 0; i--) {
            prop(k >> i);
        }
    }
    void up(int k) {
        while(k >>= 1) {
            dat[k] = Monoid::op(prop(k << 1), prop(k << 1 | 1));
        }
    }

    void update(int a, int b, const int& x) {  //[a,b]->[a,b)
        int l = a + n, r = b + n;
        // down(l);
        // down(r);
        for(++r; l < r; l >>= 1, r >>= 1) {
            if(l & 1) {
                laz[l] = OperatorMonoid::op(laz[l], x);
                l++;
            }
            if(r & 1) {
                --r;
                laz[r] = OperatorMonoid::op(laz[r], x);
            }
        }
        l = a + n, r = b + n;
        up(l);
        up(r);
    }
    T query(int a, int b) {  //[a,b]->[a,b)
        int l = a + n, r = b + n;
        down(l);
        down(r);
        T vl = Monoid::id(), vr = Monoid::id();
        for(++r; l < r; l >>= 1, r >>= 1) {
            if(l & 1) {
                vl = Monoid::op(vl, prop(l++));
            }
            if(r & 1) {
                vr = Monoid::op(prop(--r), vr);
            }
        }
        return Monoid::op(vl, vr);
    }
};
template <class U>
struct RangeSum {
    using T = U;
    static T op(const T& a, const T& b) { return a + b; }
    static constexpr T id() { return 0; }
};
template <class V>
struct RangeAdd {
    using E = V;
    static E op(const E& a, const E& b) { return a + b; }
    template <typename T>
    static T merge(const T& a, const E& b, const ll& len) {
        return a + b * len;
    }
    static constexpr E id() { return 0; }
};
