ll digitpower(ll a,ull b){//aのb乗を計算
  if(b==1){
    return a;
  }else if(b==0){
    return 1;
  }
  static int modmode=0;//%d9_7するのかどうか
  if(b%2==1){
    ll tmp = digitpower(a,(b-1)/2);
    if(modmode==1){
      tmp%=d9_7;
    }
    tmp*=tmp;
    if(modmode==1){
      tmp%=d9_7;
    }
    tmp*=a;
    if(modmode==1){
     return (tmp)%d9_7;
    }else{
      return tmp;
    }
  }else{
    ll tmp = digitpower(a,(b)/2);
    if(modmode==1){
      tmp%=d9_7;
    }
    tmp*=tmp;
    if(modmode==1){
      tmp%=d9_7;
    }
    if(modmode==1){
      return (tmp)%d9_7;
    }
    return tmp;
  }
}
template<class T>
class SegmentTree{
  public:
   int n;
   vector<T> nodes;
    //constructor
    SegmentTree(int size,T init){
      initialize(size,init);
    }
    //関数を定義(minなのかmaxなのかとか)
    T thisoperator(T a, T b){
      return a+b;
    }
    void update(int x,T a){//xがindex
      x+=n-1;
      nodes[x]+=a;
      while(x>0){
        x=(x-1)/2;
        nodes[x]=thisoperator(nodes[2*x+1],nodes[2*x+2]);
      }
    }
   void initialize(int inputn,T init){
      int k=0;
      while(inputn>digitpower(2,k)){
        k++;
      }
      n=digitpower(2,k);
      nodes=vector<T> (digitpower(2,k)*2-1,init);
   }
   T sec_get(int reql,int reqr,int nowindex=0,int nowl=0,int nowr=-1){
     // 最初に呼び出されたときの対象区間は [0, n)
    if(nowr < 0) nowr = n;

    // 要求区間と対象区間が交わらない -> 適当に返す
    if(nowr <= reql || reqr <= nowl) return 0;

    // 要求区間が対象区間を完全に被覆 -> 対象区間を答えの計算に使う
    if(reql <= nowl && nowr <= reqr) return nodes[nowindex];
    // 要求区間が対象区間の一部を被覆 -> 子について探索を行う
    // 左側の子を vl ・ 右側の子を vr としている
    // 新しい対象区間は、現在の対象区間を半分に割ったもの
    T val1 = sec_get(reql, reqr, 2*nowindex+1, nowl, (nowl+nowr)/2);
    T val2 = sec_get(reql, reqr, 2*nowindex+2, (nowl+nowr)/2, nowr);
    return thisoperator(val1, val2);
   }
   void Printn(){
     cout<<"Printvector"<<endl;
     rep(i,n){
       cout<<nodes[i+n-1]<<" ";
     }
     cout<<endl;
   }
};
