bool judgeIentersected(ld ax,ld ay,ld bx,ld by,ld cx,ld cy,ld dx,ld dy) {
  ld ta = (cx - dx) * (ay - cy) + (cy - dy) * (cx - ax);
  ld tb = (cx - dx) * (by - cy) + (cy - dy) * (cx - bx);
  ld tc = (ax - bx) * (cy - ay) + (ay - by) * (ax - cx);
  ld td = (ax - bx) * (dy - ay) + (ay - by) * (ax - dx);

  return tc * td < 0 && ta * tb < 0;
  // return tc * td <= 0 && ta * tb <= 0; // 端点を含む場合
};
template<class T>
class delaySegmentTree{
  public:
   int n;
   vector<T> nodes;
   vector<T> delaynodes;
    //constructor
    delaySegmentTree(int size,T init){
      initialize(size,init);
    }
    //関数を定義(minなのかmaxなのかとか)
    T thisoperator(T a, T b){
      return a+b;
    }
    void update(int x,T a){//xがindex
      x+=n-1;
      nodes[x]+=a;
      while(x>0){
        x=(x-1)/2;
        nodes[x]=thisoperator(nodes[2*x+1],nodes[2*x+2]);
      }
    }
   void initialize(int inputn,T init){
      int k=0;
      while(inputn>digitpower(2,k)){
        k++;
      }
      n=digitpower(2,k);
      nodes=vector<T> (digitpower(2,k)*2-1,init);
      delaynodes=vector<T> (digitpower(2,k)*2-1,init);
   }
    // k 番目のノードについて遅延評価を行う
    void eval(int k, int l, int r) {
      //kが今見てるindex
    // 遅延配列が空でない場合、自ノード及び子ノードへの
    // 値の伝播が起こる
      if(delaynodes[k] != 0) {
        nodes[k] += delaynodes[k];

        // 最下段かどうかのチェックをしよう
        // 子ノードは親ノードの 1/2 の範囲であるため、
        // 伝播させるときは半分にする
        if(r - l > 1) {
            delaynodes[2*k+1] += delaynodes[k] / 2;
            delaynodes[2*k+2] += delaynodes[k] / 2;
        }

        // 伝播が終わったので、自ノードの遅延配列を空にする
        delaynodes[k] = 0;
      }
    }


    void add(int a, int b, T x, int k=0, int l=0, int r=-1) {
      if(r < 0) r = n;

      // k 番目のノードに対して遅延評価を行う
      eval(k, l, r);

      // 範囲外なら何もしない
      if(b <= l || r <= a) return;

      // 完全に被覆しているならば、遅延配列に値を入れた後に評価
      if(a <= l && r <= b) {
          delaynodes[k] += (r - l) * x;
          eval(k, l, r);
      }

      // そうでないならば、子ノードの値を再帰的に計算して、
      // 計算済みの値をもらってくる
      else {
          add(a, b, x, 2*k+1, l, (l+r)/2);
          add(a, b, x, 2*k+2, (l+r)/2, r);
          nodes[k] = nodes[2*k+1] + nodes[2*k+2];
      }
    }



   T sec_get(int reql,int reqr,int nowindex=0,int nowl=0,int nowr=-1){
     // 最初に呼び出されたときの対象区間は [0, n)
    if(nowr < 0) nowr = n;

    // 要求区間と対象区間が交わらない -> 適当に返す
    if(nowr <= reql || reqr <= nowl) return 0;
    //関数が呼び出されるので評価
    eval(nowindex,nowl,nowr);
    // 要求区間が対象区間を完全に被覆 -> 対象区間を答えの計算に使う
    if(reql <= nowl && nowr <= reqr) return nodes[nowindex];
    // 要求区間が対象区間の一部を被覆 -> 子について探索を行う
    // 左側の子を vl ・ 右側の子を vr としている
    // 新しい対象区間は、現在の対象区間を半分に割ったもの
    T val1 = sec_get(reql, reqr, 2*nowindex+1, nowl, (nowl+nowr)/2);
    T val2 = sec_get(reql, reqr, 2*nowindex+2, (nowl+nowr)/2, nowr);
    return thisoperator(val1, val2);
   }
   void Printn(){
     cout<<"Printvector"<<endl;
     rep(i,n){
       cout<<nodes[i+n-1]<<" ";
     }
     cout<<endl;
   }
};
