void eval(int l, int r, int now){
    if(r - l > 1){
        lazy[now * 2 + 1] += lazy[now];
        lazy[now * 2 + 2] += lazy[now];
    }
    segtree[now] += lazy[now] * (r - l);
    lazy[now] = 0;
}

void add(int a, int b, long x, int l, int r, int now){
    eval(l, r, now);
    if(r <= a || b <= l){
        return;
    }else if(a <= l && r <= b){
        lazy[now] += x;
        eval(l, r, now);
    }else{
        add(a, b, x, l, (l + r) / 2, now * 2 + 1);
        add(a, b, x, (l + r) / 2, r, now * 2 + 2);
        segtree[now] = segtree[now * 2 + 1] + segtree[now * 2 + 2];
    }
}

long sum(int a, int b, int l, int r, int now){
    eval(l, r, now);
    if(r <= a || b <= l){
        return 0;
    }else if(a <= l && r <= b){
        return segtree[now];
    }else{
        return sum(a, b, l, (l + r) / 2, now * 2 + 1) + sum(a, b, (l + r) / 2, r, now * 2 + 2);
    }
}

