void push(int k) {
	if (lazy[k] != 0) {
		seg[k * 2] += lazy[k] >> 1; lazy[k * 2] = lazy[k] >> 1;
		seg[k * 2 + 1] += lazy[k] >> 1; lazy[k * 2 + 1] += lazy[k] >> 1;
		lazy[k] = 0;
	}
}
void add(int a, int b, int x, int k, int l, int r) {
	if (a <= l && r <= b) {
		seg[k] += x * (r - l), lazy[k] += x * (r - l);
		return;
	}
	if (r <= a || b <= l) return;
	push(k);
	add(a, b, x, k * 2, l, (l + r) >> 1);
	add(a, b, x, k * 2 + 1, (l + r) >> 1, r);
	seg[k] = seg[k * 2] + seg[k * 2 + 1];
}
ll query(int a, int b, int k, int l, int r) {
	if (a <= l && r <= b) return seg[k];
	if (r <= a || b <= l) return 0;
	push(k);
	ll lc = query(a, b, k * 2, l, (l + r) >> 1);
	ll rc = query(a, b, k * 2 + 1, (l + r) >> 1, r);
	return lc + rc;
}
