template <class T>
struct SegmentTree {
    using func = function<T(T, T)>;
    int size;
    vector<T> data;
    vector<T> lazy;
    vector<T> width;
    function<T(T,T)> merger, updater;
    T ident_update, ident_query;
    SegmentTree(int n, func update_func, func merge_func, T identity_update, T identity_query)
     : updater(update_func), merger(merge_func), ident_update(identity_update), ident_query(identity_query) {
        size = 1;
        while (size < n) size <<= 1;
        data.resize(size*2, ident_query);
        lazy.resize(size*2, ident_update);
        width.resize(size*2, 1);
        for (int i = size-2; i >= 0; i--) {
            width[i] = width[i*2+1] + width[i*2+2];
        }
    }
    void lazy_propagate(int p) {
        data[p] = updater(data[p], lazy[p] * width[p]);
        if (p < size-1) {
            lazy[p*2+1] = updater(lazy[p*2+1], lazy[p]);
            lazy[p*2+2] = updater(lazy[p*2+2], lazy[p]);
        }
        lazy[p] = ident_update;
    }
    void update(int wishL, int wishR, int x, int watchL = 0, int watchR = -1, int k = 0) {
        if (watchR == -1) watchR = size;
        if (wishR <= watchL || watchR <= wishL) {
            lazy_propagate(k);
            return;
        }
        if (wishL <= watchL && watchR <= wishR) {
            lazy[k] = updater(lazy[k], x);
            lazy_propagate(k);
            return;
        }

        int mid = (watchL+watchR)/2;
        lazy_propagate(k);
        update(wishL, wishR, x, watchL, mid, k*2+1);
        update(wishL, wishR, x, mid, watchR, k*2+2);
        data[k] = merger(data[k*2+1], data[k*2+2]);
    }
    T query(int wishL, int wishR, int watchL = 0, int watchR = -1, int k = 0) {
        if (watchR == -1) watchR = size;
        if (watchR <= wishL || wishR <= watchL) return ident_query;
        if (wishL <= watchL && watchR <= wishR) return data[k];
        T ld = query(wishL, wishR, watchL, (watchL+watchR)/2, k*2+1);
        T rd = query(wishL, wishR, (watchL+watchR)/2, watchR, k*2+2);
        return merger(ld, rd);
    }
    T at(int i) {
        return query(i, i+1);
    }
};
