class LazySegmentTree
{
  private:
    int N = 1;
    vector<ll> node, lazy;

  public:
    LazySegmentTree(vector<ll> vec)
    {
        int size = (int)vec.size();

        while (N < size)
            N *= 2;

        node.resize(2 * N - 1);
        lazy.resize(2 * N - 1, 0);

        rep(i, size) node[i + N - 1] = vec[i];
        for (int i = N - 2; i >= 0; i--)
            node[i] = node[i * 2 + 1] + node[i * 2 + 2];
    }

    void evaluate(int i, int l, int r)
    {
        if(lazy[i] != 0)
            node[i] += lazy[i];

        if(r - l > 1)
        {
            lazy[2 * i + 1] += lazy[i] / 2;
            lazy[2 * i + 2] += lazy[i] / 2;
        }

        lazy[i] = 0;
    }

    void add(int a, int b, ll x, int i = 0, int l = 0, int r = -1)
    {
        if(r < 0) r = N;

        evaluate(i, l, r);

        if(b <= l || r <= a) return;

        if(a <= l && r <= b)
        {
            lazy[i] += (r - l) * x;
            evaluate(i, l, r);
        }
        else
        {
            add(a, b, x, 2 * i + 1, l, (l + r) / 2);
            add(a, b, x, 2 * i + 2, (l + r) / 2, r);
            node[i] = node[2 * i + 1] + node[2 * i + 2];
        }
    }

    ll getsum(int a, int b, int i = 0, int l = 0, int r = -1)
    {
        if(r < 0) r = N;

        evaluate(i, l, r);

        if(b <= l || r <= a) return 0;
        if(a <= l && r <= b) return node[i];
        ll vl = getsum(a, b, 2 * i + 1, l, (l + r) / 2);
        ll vr = getsum(a, b, 2 * i + 2, (l + r) / 2, r);

        return vl + vr;
    }

};

