        while (n < asz)n *= 2;
        seg.assign(2 * n - 1, e);
        lazy.resize(2 * n - 1);
        rep(i, asz) seg[i + n - 1] = Monoid(i, a[i]);
        rer(i, n - 2)seg[i] = fu(seg[i * 2 + 1], seg[i * 2 + 2]);
    }
    void eval(int k, int l, int r) {
        if (lazy[k]) {
            seg[k].v += fe(r - l, lazy[k]);
            if (r - l > 1) {
                lazy[k * 2 + 1] += lazy[k];
                lazy[k * 2 + 2] += lazy[k];
            }
            lazy[k] = 0;
        }
    }
    void add(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
        if (r < 0)r = n;
        eval(k, l, r);
        if (b <= l || r <= a)return;
        if (a <= l && r <= b) {
            lazy[k] += x;
            eval(k, l, r);
        } else {
            add(a, b, x, k * 2 + 1, l, (l + r) / 2);
            add(a, b, x, k * 2 + 2, (l + r) / 2, r);
            seg[k] = fu(seg[k * 2 + 1], seg[k * 2 + 2]);
