ll query(ll a, ll b, ll v){
	ll sum = 0;
	ll c_a, c_b;
	c_a = a / sqr, c_b = b / sqr;
	if(c_a == c_b){
		for(int i = a;i <= b;i ++)
			A[i] += v, sum += A[i];
		return sum;
	}
	else{
		for(int i = a; i < (c_a + 1) * sqr;i ++)
			A[i] += v, sum += A[i];
