class BIT {
	int n;
	vector<ll> node;
public:
	BIT(int N) {
		n = N;
		node.resize(n + 1);
	}

	void add(int i, ll x) {
		for (++i;i <= n;i += (i&-i)) {
			node[i] += x;
		}
	}

	ll sum(int i) {
		ll s = 0;
		for (;i > 0;i -= (i&-i)) {
			s += node[i];
		}
		return s;
	}
};

class RSQ {
	int n;
	BIT a, b;

public:
	RSQ(int N) : n(N), a(N), b(N) {}

	void add(int l, int r, int x) {
		a.add(l, -l * x);
		a.add(r, r * x);
		b.add(l, x);
		b.add(r, -x);
	}

	ll sum(int i) {
		return a.sum(i) + b.sum(i) * i;
	}
};

