struct LST
{
	vector<ll> node;
	vector<ll> lazy;
	ll N;

	LST(ll* a,ll n)
	{
		N = 1;
		while (N < n)N *= 2;

		node.resize(2 * N - 1, 0);
		lazy.resize(2 * N - 1, 0);

		rep(i, 0, n)node[N - 1 + i] = a[i];
		rrep(i, 0, N - 1)node[i] = node[2 * i + 1] + node[2 * i + 2];
	}

	void eval(int k, int l, int r) {
		if (lazy[k] != 0) {
			node[k] += (lazy[k] * (r - l));

			if (r - l > 1) {
				lazy[2 * k + 1] += lazy[k];
				lazy[2 * k + 2] += lazy[k];
			}

			lazy[k] = 0;
		}
	}

	void update(int a, int b, ll x, int k, int l, int r = -1)
	{
		if (r == -1)
		{
			r = N;
		}
		if (r <= a || b <= l)
		{
			return;
		}

		if (a <= l&&r <= b)
		{
			lazy[k] += x;
			eval(k, l, r);
		}
		else
		{
			node[k] += x*(min(r, b) - max(l, a));
			eval(k, l, r);
			update(a, b, x, 2 * k + 1, l, (l + r) / 2);
			update(a, b, x, 2 * k + 2, (l + r) / 2, r);
		}
	}

	ll sum(int a, int b, int k, int l, int r = -1)
	{
		if (r == -1)
		{
			r = N;
		}
		if (r <= a || b <= l)
		{
			return 0;
		}

		eval(k, l, r);

		if (a <= l&&r <= b)
		{
			return node[k];
		}
		else
		{
			ll res = 0;
			res += sum(a, b, 2 * k + 1, l, (l + r) / 2);
			res += sum(a, b, 2 * k + 2, (l + r) / 2, r);
			return res;
		}
	}
};

