#include <bits/stdc++.h>
#define pb push_back
using namespace std;
typedef long long ll;
const int maxn=400005;

struct {
	ll sum,lazy;	
} S[maxn];
int n,q;

void update(int id,int ql,int qr,int v,int l,int r) {
	if (S[id].lazy) {
		S[id].sum+=S[id].lazy*(r-l+1);
		if (l!=r) {
			S[id<<1].lazy+=S[id].lazy;
			S[id<<1|1].lazy+=S[id].lazy;
		}
		S[id].lazy=0;
	}
	if (ql==l && qr==r) {
		S[id].lazy+=v;
		return;
	}
	int m=l+r>>1;
	if (qr<=m) update(id<<1,ql,qr,v,l,m);
	else if (ql>m) update(id<<1|1,ql,qr,v,m+1,r);
	else update(id<<1,ql,m,v,l,m), update(id<<1|1,m+1,qr,v,m+1,r);
	S[id].sum=S[id<<1].sum+S[id<<1|1].sum+S[id<<1].lazy*(m-l+1)+S[id<<1|1].lazy*(r-m);
}

int query(int id,int ql,int qr,int l,int r) {
	int m=l+r>>1;
	ll lz=S[id].lazy*(qr-ql+1);
	if (ql==l && qr==r) return lz+S[id].sum;
	if (qr<=m) return lz+query(id<<1,ql,qr,l,m);
	else if (ql>m) return lz+query(id<<1|1,ql,qr,m+1,r);
	else return lz+query(id<<1,ql,m,l,m)+query(id<<1|1,m+1,qr,m+1,r);
}

int main() {
	// freopen("test.out","w",stdout);
	cin>>n>>q;
	for (int i=0;i<q;i++) {
		bool op; cin>>op;
		int s,t,x;
		if (op) {
			cin>>s>>t;
			cout<<query(1,s,t,1,n)<<'\n';
		}
		else {
			cin>>s>>t>>x;
			update(1,s,t,x,1,n);
		}
	}
}

