         // lowest level
         for (int i = 0; i < SIZE; i++) 
            node[i + N - 1] = v[i];
         // others
         for (int i = N - 2; i >= 0; i--) 
            node[i] = node[2 * i + 1] + node[2 * i + 2];
      }

      void eval(int k, int l, int r) {
         if (lazy[k] != 0) {
            node[k] += lazy[k];

            if (r - l > 1) {
               lazy[2 * k + 1] += lazy[k] / 2;
               lazy[2 * k + 2] += lazy[k] / 2;
            }

            lazy[k] = 0;
         }
      }

      void add(int a, int b, T x, int k = 0, int l = 0, int r = -1) {
         if (r < 0) r = N;

         eval(k, l, r);
         if (b <= l || r <= a) return;
         if (a <= l && r <= b) {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
         } else {
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
         }
      }

      T getsum(int a, int b, int k = 0, int l = 0, int r = -1) {
         if (r < 0) r = N;
         if (b <= l || r <= a) return 0;

         eval(k, l, r);
         if (a <= l && r <= b) return node[k];
         T vl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
         T vr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);
         return vl + vr;
      }
};

int main() {
   int n, Q;
   cin >> n >> Q;
   LazySegT<ll> segt( vector<ll>(n, 0) );
   int t, a, b, x;
   for (int q = 0; q < Q; q++) {
      cin >> t;
      if (t == 0) {
         cin >> a >> b >> x;
         a--;
         b--;
         segt.add(a, b + 1, x);
      } else {
         cin >> a >> b;
         a--;
         b--;
         cout << segt.getsum(a, b + 1) << endl;
      }
   }
   return 0;
}

