// ノード: v (1-based)
// 元配列のインデックス: i (0-based)

struct SegTreeLazy {
    static constexpr i64 EMPTY() { return 0; }

    i64 n_;
    vector<i64> data_;  // 1-based
    vector<i64> lazy_;  // 1-based

    explicit SegTreeLazy(i64 n) : n_(pow2_ceil(n)), data_(2*n_,0), lazy_(2*n_,EMPTY()) {}

    void update(i64 i, i64 k, i64 x) {
        update_impl(i, i+k, x, 1, 0, n_);
    }

    i64 query(i64 i, i64 k) {
        return query_impl(i, i+k, 1, 0, n_);
    }

private:
    // [a,b): 要求区間
    // [l,r): ノード v の区間
    void update_impl(i64 a, i64 b, i64 x, i64 v, i64 l, i64 r) {
        // まず現ノードを評価
        // ここで lazy_[v] が空になる
        eval(v);

        // [a,b), [l,r) が共通部分を持たなければ何もしない
        if(b <= l || r <= a) return;

        // [a,b) が [l,r) を完全に被覆するなら lazy_[v] に値を入れた後に評価
        if(a <= l && r <= b) {
            lazy_[v] = (r-l) * x;
            eval(v);
        }
        // [a,b) が [l,r) と部分的に交わるなら子ノードを更新
        // 最後に data_[v] を更新
        else {
            update_impl(a, b, x, node_l(v), l, (l+r)/2);
            update_impl(a, b, x, node_r(v), (l+r)/2, r);
            data_[v] = data_[node_l(v)] + data_[node_r(v)];
        }
    }

    // [a,b): 要求区間
    // [l,r): ノード v の区間
    i64 query_impl(i64 a, i64 b, i64 v, i64 l, i64 r) {
        // [a,b), [l,r) が共通部分を持たなければ単位元を返す
        if(b <= l || r <= a) return 0;

        // 現ノードを評価
        eval(v);

        // [a,b) が [l,r) を完全に被覆するなら data_[v] を返す
        if(a <= l && r <= b) return data_[v];

        // [a,b) が [l,r) と部分的に交わるなら子ノードへクエリして計算
        i64 xl = query_impl(a, b, node_l(v), l, (l+r)/2);
        i64 xr = query_impl(a, b, node_r(v), (l+r)/2, r);
        return xl + xr;
    }

    void eval(i64 v) {
        if(lazy_[v] == EMPTY()) return;

        data_[v] += lazy_[v];
        if(!node_is_leaf(v)) {
            lazy_[node_l(v)] += lazy_[v] / 2;
            lazy_[node_r(v)] += lazy_[v] / 2;
        }

        lazy_[v] = EMPTY();
    }

    static i64 node_l(i64 v) {
        return 2*v;
    }

    static i64 node_r(i64 v) {
        return 2*v + 1;
    }

    bool node_is_leaf(i64 v) const {
        return v >= n_;
    }

    i64 node_leaf(i64 i) const {
        return i + n_;
    }
};

void solve() {
    i64 N; RD(N);
    i64 Q; RD(Q);

    SegTreeLazy seg(N);
    REP(_, Q) {
        i64 cmd; RD(cmd);
        if(cmd == 0) {
            i64 s,t; RD1(s); RD1(t);
            i64 x; RD(x);
            seg.update(s, t-s+1, x);
        }
        else if(cmd == 1) {
            i64 s,t; RD1(s); RD1(t);
            i64 ans = seg.query(s, t-s+1);
            PRINTLN(ans);
        }
        else {
            ASSERT(false);
        }
    }

    // * 小さいケースで試した?
    // * 不可能なケースはチェックした?
    // * MOD はとった?
    // * メモ化忘れてない?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
}

signed main() {


    solve();

    EXIT();
}

