    if(type==0){
      scanf("%lld %lld %lld",&s,&t,&value);
      A.Add(s,value);
      A.Add(t,-value);
      B.Add(t,value*(t-s+1));
    }
    if(type==1){
      scanf("%lld %lld",&s,&t);
      s--;
      printf("%lld\n", A.Sum(t)*t+B.Sum(t) - A.Sum(s)*s-B.Sum(s) );
    }
  }
  return 0;
}

