           //ST.update(s-1,t,x);
            bit.RangeAdd(s, t, x);
        }else{
            int s,t; cin >> s >> t;
            //cout << ST.query(s-1,t) <<endl;
            cout << bit.RangeSum(s, t) << endl;
        }
    }

    return 0;
}

