template <class T>
struct BIT {
    vector<T> a;
    BIT(int size) : a(size, 0) {}
    T sum(int r) const {
        T sm = 0;
        for (--r; r >= 0; r = (r & r + 1) - 1)
            sm += a[r];
        return sm;
    }
    T sum(int l, int r) const {
        return sum(r) - sum(l);
    }
    T at(int i) const {
        return sum(i, i + 1);
    }
    void add(int i, T v) {
        for (; i < (int)a.size(); i |= i + 1)
            a[i] += v;
    }
    void set(int i, T v) {
        add(i, v - at(i));
    }
};

template <class T>
struct BIT2 {
    BIT<T> a, b;
    BIT2(int size) : a(size), b(size) {}
    T sum(int r) const {
        return a.sum(r) + b.sum(r) * r;
    }
    T sum(int l, int r) const {
        return sum(r) - sum(l);
    }
    T at(int i) const {
        return sum(i, i + 1);
    }
    void _add(int r, T v) {
        a.add(r, v * r);
        b.add(r, -v);
    }
    void add(int l, int r, T v) {
        _add(l, -v);
        _add(r, v);
    }
    void add(int i, T v) {
        add(i, i + 1, v);
    }
};

