using ll = long long;
using namespace std;

struct LazySegmentTree {
private:
    int n;
    vector<ll> node, lazy;
public:
    LazySegmentTree(vector<ll> v) {
        int sz = (int)v.size();
        n = 1;
        while (n < sz) n *= 2;

        node.resize(2*n-1);
        lazy.resize(2*n-1, 0);

        for (int i=0; i<sz; ++i) node[i+n-1] = v[i];
        for (int i=n-2; i>=0; --i) node[i] = node[i*2+1] + node[i*2+2];
    }

    // 伝搬させるため
    void eval(int k, int l, int r) {
        if (lazy[k] != 0) {
            node[k] += lazy[k];

            // 範囲が半分になるから，値も半分になる
            if (r - l > 1) {
                lazy[2*k+1] += lazy[k] / 2;
                lazy[2*k+2] += lazy[k] / 2;
            }

            lazy[k] = 0;
        }
    }

    // [a, b)
    void add(int a, int b, ll x, int k=0, int l=0, int r=-1) {
        if (r < 0) r = n;

        // k番目のノードで遅延評価
        eval(k, l, r);

        // 範囲外なら何もしない
        if (r <= a or b <= l) return;

        // 完全に被覆していたら評価
        if (a <= l and r <= b) {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }
        else {
            // そうじゃないなら，被覆するまで下がる
            add(a, b, x, 2*k+1, l, (l+r)/2);
            add(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = node[2*k+1] + node[2*k+2];
        }
    }

    ll getsum(int a, int b, int k=0, int l=0, int r=-1) {
        if (r < 0) r = n;
        if (r <= a or b <= l) return 0;

        eval(k, l, r);
        if (a <= l and r <= b) return node[k];
        ll vl = getsum(a, b, 2*k+1, l, (l+r)/2);
        ll vr = getsum(a, b, 2*k+2, (l+r)/2, r);
        return vl + vr;
    }
};

int main() {
    int n, q;
    cin >> n >> q;
    vector<ll> v(n, 0);

    LazySegmentTree lst(v);
    rep(i, q) {
        int c;
        cin >> c;
        if (c == 0) {
            ll s, t, x;
            cin >> s >> t >> x;
            s--;
            lst.add(s, t, x);
        }
        else {
            ll s, t;
            cin >> s >> t;
            s--;
            cout << lst.getsum(s, t) << endl;
        }
    }
}

