class RSQTree:public LazySegmentTree<int64_t,int64_t>{

  int64_t MergeValue(const int64_t& a, const int64_t& b)override {
    return a+b;
  }
  int64_t MergeOperator(const int64_t& a,const int64_t& b)override {
    return a+b;
  }
  int64_t Operate(const int64_t& val, const int64_t& opl)override {
    return val+opl;
  }
  int64_t GetOperator(const int64_t& opl, const int64_t n)override {
    return opl*n;
  }

public:
  RSQTree(int64_t n):LazySegmentTree(0,0,std::vector<int64_t>(n,0)){}

};


