namespace SOLVE {
	VI A;

	struct SegTree {
		static const int maxn = 100000;

		struct node {
			ll l, r, value, lazy;
		};

		node no[maxn * 4];
		void push_up(int ind) {
			no[ind].value = no[lson].value + no[rson].value;
		}
		void push_down(int ind) {
			if (no[ind].lazy != 0) {
				no[ind].value -= (no[ind].lazy * (no[ind].r - no[ind].l + 1));
				no[lson].value += (no[ind].lazy * (no[lson].r - no[lson].l + 1));
				no[rson].value += (no[ind].lazy * (no[rson].r - no[rson].l + 1));
				no[lson].lazy += no[ind].lazy;
				no[rson].lazy += no[ind].lazy;
				no[ind].lazy = 0;
			}
		}

		void build(int l, int r, int ind) {
			no[ind].l = l;
			no[ind].r = r;
			no[ind].value = 0;
			no[ind].lazy = 0;
			if (l == r) {
				no[l].value = 0;
				no[l].lazy = 0;
			}
			else {
				int mid = (l + r) / 2;
				build(l, mid, lson);
				build(mid + 1, r, rson);
				push_up(ind);
			}
		}

		void update(int l, int r, int ind, ll val) {
			if (l > no[ind].r || r < no[ind].l)return;
			if (l <= no[ind].l && no[ind].r <= r) {
				no[ind].value += (val * (no[ind].r - no[ind].l + 1));
				no[ind].lazy += val;
			}
			else {
				push_down(ind);
				update(l, r, lson, val);
				update(l, r, rson, val);
				push_up(ind);
			}
		}
		void query(int l, int r, int ind, ll& ans) {
			if (l > no[ind].r || r < no[ind].l) {
				ans = 0; 
				return;
			}
			if (l <= no[ind].l && no[ind].r <= r) {
				ans = no[ind].value;
				return;
			}
			else {
				ll ans1, ans2;
				push_down(ind);
				query(l, r, lson, ans1);
				query(l, r, rson, ans2);
				ans = ans1 + ans2;
				push_up(ind);
				return;
			}
		}
		void show(int x) {
			REP(i, 1, x) {
				cout << no[i].value << ' ';
			}
			cout << endl;
		}
	};






	SegTree tree;

	void main() {
		ll n, q, a, b, c, d, ans;
		cin >> n >> q;

		A.resize(n, pow(2,31)-1);

		tree.build(1, n, 1);

		REP(i, 0, q) {
			cin >> a;
			if (a == 0) {
				cin >> b >> c >> d;
				tree.update(b, c, 1, d);

			}
			else {

				cin >> b >> c;
				tree.query(b, c, 1, ans);
				cout << ans << endl;
			}
		}
	}
}


