class Value{
public:
	Value(int_fast64_t a, int b):v(a), len(b){}
	int_fast64_t v, len;
	const bool operator==(const Value rhs) const{
		return (v == rhs.v) && (len == rhs.len);
	}
};

class ValueMonoid{
public:
	using value_type = Value;
	static value_type identity(){ return Value(0, 1); }
	static value_type operation(value_type a, value_type b){
		return Value(a.v+b.v, a.len+b.len);
	}
};

class OpMonoid{
public:
	using value_type = int_fast64_t;
	static value_type identity(){ return 0; }
	static value_type operation(value_type a, value_type b){
		return a+b;
	}
};

class Modifier{
public:
	static ValueMonoid::value_type operation(
			ValueMonoid::value_type a, OpMonoid::value_type b){
		if(b == OpMonoid::identity())
			return a;
		return Value(a.v+b*a.len, a.len);
	}
};

