template<class D>
struct SegmentTree{
  using DMerger = function<D(D,D)>;
  int length;
  D d_unit;
  vector<D> seg;
  DMerger dm;
  void update(int k,D x){
    k += length-1;
    seg[k] = x;
    while(k){
      k = (k-1)/2;
      seg[k] = dm(seg[2*k+1],seg[2*k+2]);
    }
  }
  D query(int a,int b,int k,int l,int r){
    if(r<=a||b<=l)return d_unit; 
    else if(a<=l&&r<=b)return seg[k];
    else{
      D lch = query(a,b,k*2+1,l,(l+r)/2);
      D rch = query(a,b,k*2+2,(l+r)/2,r);
      return dm(lch,rch);
    }
  }
  D query(int a,int b){
    return query(a,b,0,0,length);
  }
  D operator [] (int id) const {
    assert(0<=id&&id<length);
    return seg[length-1+id];
  }
  SegmentTree(int n,D d_unit,DMerger dm)
    :length(1),d_unit(d_unit),dm(dm) {
    while(length<n){ length <<= 1; }
    seg.assign(length * 2, d_unit);
  }
  SegmentTree(vector<D> vec,D d_unit,DMerger dm)
    :length(1),d_unit(d_unit),dm(dm) {
    while(length<vec.size()){ length <<= 1; }
    seg.assign(length * 2, d_unit);
    for(int i=0;i<vec.size();i++)seg[length-1+i] = vec[i];
    for(int i=length-2;i>=0;i--)seg[i] = dm(seg[i*2+1],seg[i*2+2]);
  }
};

template<class D>
struct SegmentTreeBeats{
  using DMerger = function<D(D,D)>;
  vector<D> seg;
  int length;
  DMerger dm;
  D d_unit;
  SegmentTreeBeats(const vector<D>& vec,DMerger dm,D d_unit = D()):length(1),dm(dm){
    while(length<=vec.size())length <<= 1;
    seg.assign(length*2,d_unit);
    for(int i=0;i<vec.size();i++){
      seg[i+length-1] = vec[i];
    }
    for(int i=length-2;i>=0;i--){
      seg[i] = dm(seg[i*2+1],seg[i*2+2]);
    }
  }
  template<class F,class... Args>
  void update(int a,int b,int k,int l,int r,F break_or_puttag,Args... args){
    if(r<=a||b<=l)return;
    if(a<=l&&r<=b&&(seg[k].*break_or_puttag)(args...))return;
    seg[k].pushdown(seg[k*2+1],seg[k*2+2]);
    update(a,b,k*2+1,l,(l+r)/2,break_or_puttag,args...);
    update(a,b,k*2+2,(l+r)/2,r,break_or_puttag,args...);
    seg[k] = dm(seg[k*2+1],seg[k*2+2]);
  }
  template<class F,class... Args>
  void update(int a,int b,F break_or_puttag,Args... args){
    update(a,b,0,0,length,break_or_puttag,args...);
  }
  template<class Getter,class QMerger,class Q>
  Q query(int a,int b,int k,int l,int r,Getter getter,QMerger qm,Q q_unit){
    if(r<=a||b<=l)return q_unit;
    if(a<=l&&r<=b)return (seg[k].*getter)();
    seg[k].pushdown(seg[k*2+1],seg[k*2+2]);
    Q lch = query(a,b,k*2+1,l,(l+r)/2,getter,qm,q_unit);
    Q rch = query(a,b,k*2+2,(l+r)/2,r,getter,qm,q_unit);
    return qm(lch,rch);
  }
  template<class Getter,class QMerger,class Q>
  Q query(int a,int b,Getter getter,QMerger qm,Q q_unit){
    return query(a,b,0,0,length,getter,qm,q_unit);
  }
};

// requirements :
// static Data merge(Data l,Data r)
// void pushdown(Data& l,Data& r) (push down tag)
// 
// for each update query :
// bool break_or_puttag_[QUERY] (TAGTYPE tag)
//   if puttag condition is satisfied, update data and put tag
//   return : if break condition or puttag condition is satisfied, return true, otherwise return false

struct Data{
  ll tag,num,sum,mx,mi,second_mx,second_mi,mx_num,mi_num;
  Data(ll v = 0ll):tag(0ll),num(1ll),sum(v),mx(v),mi(v),second_mx(-LLINF),second_mi(LLINF),mx_num(1),mi_num(1){}
  static Data merge(Data l,Data r){
    Data ret;
    ret.tag = 0;
    ret.sum = l.sum+r.sum;
    ret.num = l.num+r.num;
    ret.mx = max(l.mx,r.mx);
    ret.mi = min(l.mi,r.mi);

    ret.second_mx = -LLINF;
    if(l.mx==ret.mx){
      if(r.mx < ret.mx)chmax(ret.second_mx,r.mx);
      chmax(ret.second_mx,l.second_mx);
      chmax(ret.second_mx,r.second_mx);
    }
    if(r.mx==ret.mx){
      if(l.mx < ret.mx)chmax(ret.second_mx,l.mx);
      chmax(ret.second_mx,l.second_mx);
      chmax(ret.second_mx,r.second_mx);
    }

    ret.second_mi = LLINF;
    if(l.mi==ret.mi){
      if(r.mi > ret.mi)chmin(ret.second_mi,r.mi);
      chmin(ret.second_mi,l.second_mi);
      chmin(ret.second_mi,r.second_mi);
    }
    if(r.mi==ret.mi){
      if(l.mi > ret.mi)chmin(ret.second_mi,l.mi);
      chmin(ret.second_mi,l.second_mi);
      chmin(ret.second_mi,r.second_mi);
    }

    ret.mx_num = 0;
    if(ret.mx==l.mx) ret.mx_num += l.mx_num;
    if(ret.mx==r.mx) ret.mx_num += r.mx_num;

    ret.mi_num = 0;
    if(ret.mi==l.mi) ret.mi_num += l.mi_num;
    if(ret.mi==r.mi) ret.mi_num += r.mi_num;

    return ret;
  }
  bool add(ll x){
    sum += num*x;
    mx += x;
    if(second_mx!=-LLINF)second_mx += x;
    mi += x;
    if(second_mi!=LLINF)second_mi += x;
    tag += x;
    return true;
  }
  void pushdown(Data& l,Data& r){
    l.add(tag);
    r.add(tag);
    tag = 0ll;
  }
  bool chmax_query(ll x){
    if(mi>=x)return true;
    if(second_mi>x){
      if(second_mi==LLINF){ // 1 value only
        sum += (x-mi)*mi_num;
        mi = x;
        mx = x;
      }
      else if(second_mi==mx){ // 2 value only
        sum += (x-mi)*mi_num;
        mi = x;
        second_mx = x;
      }else{
        sum += (x-mi)*mi_num;
        mi = x;
      }
      return true;
    }
    return false;
  }
  bool chmin_query(ll x){
    if(mx<=x)return true;
    if(second_mx<x){
      if(second_mx==-LLINF){ // 1 value only
        sum -= (mx-x)*mx_num;
        mx = x;
        mi = x;
      }
      else if(second_mi==mx){ // 2 value only
        sum -= (mx-x)*mx_num;
        mx = x;
        second_mi = x;
      }else{
        sum -= (mx-x)*mx_num;
        mx = x;
      }
      return true;
    }
    return false;
  }
  ll get_sum(){
    return sum;
  }
};

