  scanf("%d %d", &N, &Q);

  auto f = [&](int64 a, int64 b) { return a + b; };
  auto p = [&](int64 a, int b) { return a * b; };
  LazySegmentTree< int64 > seg(N, f, f, f, p, 0, 0);

