template<typename T>
class LazySegmentTree{
    //[l, r)半開区間を扱う
private:
    std::vector<T> node, lazy;
    std::function<T(T, T)> f; // 取得の演算
    std::function<T(T, T)> g; // 更新の演算
    std::function<T(T, int)> pow; // 更新の演算をk回作用させたときの結果

    T f_ide; //演算fの単位元
    T g_ide; //演算gの単位元

    int size;
public:
    LazySegmentTree(int n, std::function<T(T, T)> f, std::function<T(T, T)> g, T f_ide, T g_ide) : 
    f(f),
    g(g),
    f_ide(f_ide),
    g_ide(g_ide)
    {
        init(n);
        pow = [=](T a, int k){
            T ans = g_ide;
            while(k > 0){
                if(k & 1)ans = g(ans, a);
                a = g(a, a);
                k >>= 1;
            }
            return ans;
        };
    }
    LazySegmentTree(int n, std::function<T(T, T)> f, std::function<T(T, T)> g, std::function<T(T, int)> pow, T f_ide, T g_ide) : 
    f(f),
    g(g),
    pow(pow),
    f_ide(f_ide),
    g_ide(g_ide)
    {
        init(n);
    }
    void init(int n){
        size = 1;
        while(size < n)size *= 2;
        node = std::vector<T>(2 * size - 1, f_ide);
        lazy = std::vector<T>(2 * size - 1, g_ide);
    }
    void eval(int k, int l, int r){
        node[k] = g(node[k], pow(lazy[k], r - l));

        if(r - l >= 2){
            lazy[2 * k + 1] = g(lazy[2 * k + 1], lazy[k]);
            lazy[2 * k + 2] = g(lazy[2 * k + 2], lazy[k]);
        }

        lazy[k] = g_ide;
    }
    void update(int a, int b, T x, int k = 0, int l = 0, int r = -1){
        if(r < 0)r = size;
        if(r <= a || b <= l)return;

        if(a <= l && r <= b){
            lazy[k] = g(lazy[k], x);
            eval(k, l, r);
        }else{
            update(a, b, x, 2 * k + 1, l, (l + r) / 2);
            update(a, b, x, 2 * k + 2, (l + r) / 2, r);
            eval(2 * k + 1, l, (l + r) / 2);
            eval(2 * k + 2, (l + r) / 2, r);

            node[k] = f(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    T get(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0)r = size;
        if(r <= a || b <= l)return f_ide;

        eval(k, l, r);

        if(a <= l && r <= b){
            return node[k];
        }else{
            T result_left = get(a, b, 2 * k + 1, l, (l + r) / 2);
            T result_right = get(a, b, 2 * k + 2, (l + r) / 2, r);
            return f(result_left, result_right);
        }
    }
};

int main(){
    int n,q;std::cin >> n >> q;
    std::function<long long(long long, long long)> f = [](long long a, long long b){
        return a + b;
    };
    auto g = f;
    LazySegmentTree<long long> Seg(n, f, g, 0, 0);
    while(q--){
        int a;std::cin >> a;
        if(a == 0){
            int s,t,x;
            std::cin >> s >> t >> x;
            Seg.update(s - 1, t, x);
        }else{
            int s,t;
            std::cin >> s >> t;
            std::cout<<Seg.get(s - 1, t)<<std::endl;
        }
    }
}

