struct LazySegmentTree{
private:
	lli n;
	vector<lli> node;
	vector<lli> lazy;

public:
	LazySegmentTree(vector<lli> &v){
		lli size = v.size();
		n = 1;while(n<size)n*=2;

		node.resize(2*n-1);
		lazy.resize(2*n-1,0);

		REP(i,0,size)node[i+n-1]=v[i];
		for(lli i=n-2;i>=0;i--)node[i] = node[2*i+1]+node[2*i+2];
	}

	void eval(lli k,lli l,lli r){
		if(lazy[k] != 0){
			node[k]+=lazy[k];

			if(r-l>1){
				lazy[2*k+1] += lazy[k]/2;
				lazy[2*k+2] += lazy[k]/2;
			}
			lazy[k]=0;
		}
	}

	void add(lli a,lli b,lli x,lli k=0,lli l=0,lli r=-1){
		if(r<0)r = n;
		eval(k,l,r);

		if(b<=l || r<=a)return;

		if(a<=l && r<=b){
			lazy[k] += (r-l)*x;
			eval(k,l,r);
		}
		else{
			add(a,b,x,2*k+1,l,(l+r)/2);
			add(a,b,x,2*k+2,(l+r)/2,r);
			node[k] = node[2*k+1]+node[2*k+2];
		}
	}
	lli getSum(lli a,lli b,lli k=0,lli l=0,lli r=-1){
		if(r<0)r=n;
		if(b<=l || r<=a)return 0;

		eval(k,l,r);
		if(a<=l && r<=b)return node[k];
		lli vl = getSum(a,b,2*k+1,l,(l+r)/2);
		lli vr = getSum(a,b,2*k+2,(l+r)/2,r);
		return vl+vr;
	}
};

