typedef struct lazysegtree{
	int n;
	vector<ll> arr,lazy;
	lazysegtree(){};
	lazysegtree(int n){init(n);};

	void init(int n_){
		n = 1;
		while(n<n_)n*=2;
		arr.resize(2*n-1,0);
		lazy.resize(2*n-1,0);
	}
	void lazyEvaluate(int pos,ll len){
		arr[pos]+=lazy[pos]*len;

		if(pos<n-1){
			lazy[2*pos+1]+=lazy[pos];
			lazy[2*pos+2]+=lazy[pos];
		}
		lazy[pos]=0;
	}


	//[a,b)にxを加える
	void update(int a,int b,int k,int l,int r,ll x){
		lazyEvaluate(k,r-l);
		if(r<=a || b<=l)return;
		if(a<=l&&r<=b){
			lazy[k]+=x;
			lazyEvaluate(k,r-l);
			return;
		}

		update(a,b,2*k+1,l,(l+r)/2,x);
		update(a,b,2*k+2,(l+r)/2,r,x);
		arr[k] = arr[2*k+1]+arr[2*k+2];

		return;
	}

	ll getSum(int a,int b,int k,int l,int r){
		lazyEvaluate(k,r-l);
		if(r<=a || b<=l)return 0;
		if(a<=l&&r<=b) return arr[k];

		ll left_value  = getSum(a,b,2*k+1,l,(l+r)/2);
		ll right_value = getSum(a,b,2*k+2,(l+r)/2,r);

		return left_value+right_value;
	}

}lazysegtree;

