void rep(int k,int r,int l){
    if(lazy[k]!=0){
        seg[k]+=(l-r+1)*lazy[k];
        if(l-r>0){
        lazy[k*2+1]+=lazy[k];
        lazy[k*2+2]+=lazy[k];
        }
    }
    lazy[k]=0;
}
void add(int a,int b,int r,int l,int k,int x){
    rep(k,r,l);

    if(a<=r&&l<=b){
        lazy[k]+=x;
        rep(k,r,l);
        return;
    }
    if(b<r||l<a)return;
    add(a,b,r,(r+l-1)/2,k*2+1,x);
    add(a,b,(r+l+1)/2,l,k*2+2,x);
    seg[k]=seg[k*2+1]+seg[k*2+2];


}
int sum(int a,int b,int r,int l,int k){
    rep(k,r,l);
    if(a<=r&&l<=b)return seg[k];
    if(b<r||l<a)return 0;
    return sum(a,b,r,(r+l-1)/2,k*2+1)+sum(a,b,(r+l+1)/2,l,k*2+2);
}
