auto eval(int l,int r){
    int lm=(l/(l&-l))/2,rm=(r/(r&-r))/2;
    vector<int>v;
    while(l<r){
        if(r<=rm)v.push_back(r);
        if(l<=lm)v.push_back(l);
        l/=2,r/=2;
    }
    while(l)v.push_back(l),l/=2;
    reverse(all(v));
    for(auto i:v)eval(i);
    reverse(all(v));
    return v;
}
