long long sum[maxn<<1];
long long lazy[maxn<<1];

long long init(int p,int l,int r){
    if(l == r){
        return sum[p];
    }
    int mid = (l+r)/2;

    init(p<<1,l,mid);
    init(p<<1|1,mid+1,r);
    sum[p] = sum[p<<1] + sum[p<<1|1];
    return sum[p];
}

void push_down(int p,int L,int R){
    long long l = lazy[p];
    int mid = (R+L)/2;
    if(lazy[p]){
        lazy[p<<1] += l;
        lazy[p<<1|1] += l;
        sum[p<<1]+= l*(mid-L+1);
        sum[p<<1|1]+= l*(R-mid);
        lazy[p] = 0;
    }
}

void update(int p,int l,int r,int L,int R,int num){
    if(l<= L && r>=R){
        lazy[p] += num;
        sum[p] += (R-L+1)*(long)num;
        return;
    }

    //printf("%d %d %d %d\n",r,L,l,R);
    if(l > R || r < L) return;
    push_down(p,L,R);
    int mid = (L+R)/2;
    update(p<<1,l,r,L,mid,num);
    update(p<<1|1,l,r,mid+1,R,num);
    sum[p] = sum[p<<1] + sum[p<<1|1];
}

long long query(int p,int l,int r,int L,int R){
    if(l <= L && r>= R){
        return sum[p];
    }
    if(l > R || r < L) return 0;
    push_down(p,L,R);
    int mid = (L+R)/2;
    return query(p<<1,l,r,L,mid) + query(p<<1|1,l,r,mid+1,R);
}

