using Value = long long int;
const Value INI = 0;
class starry_sky_tree {
public:
	int sz;
	vector<Value>data, lazy;
	starry_sky_tree(const int sz_) :sz(sz_), data(2 * sz_,INI), lazy(2 * sz_,INI) {

	}
	Value multiply(int a,int b,Value l,Value r) {
		return (b - a)*r + l ;
	}
	Value add(Value l,Value r) {
		return l + r;
	}
	void update(int l, int r, int node, int a, int b, Value val) {
		if (b <= l || r <= a)return;
		else if (l <= a&&b <= r) {
			lazy[node]=add(lazy[node],val); 
			return; 
		}
		int left = node * 2, right = left + 1;
		update(l, r, left, a, (a + b) / 2, val);
		update(l, r, right, (a + b) / 2,b, val);
		data[node] = add(
			multiply(a,(a+b)/2,data[left], lazy[left]), 
			multiply((a+b)/2, b, data[right] , lazy[right]));
	}
	void update(int l, int r, Value val) {
		update(l, r, 1, 0, sz, val);
	}
	Value query(int l, int r, int node, int a, int b) {
		if (b <= l || r <= a)return INI;
		else if (l <= a&&b <= r)return multiply(a,b,data[node],lazy[node]);
		Value vl = query(l, r, node * 2 + 0, a, (a + b) / 2);
		Value vr = query(l, r, node * 2 + 1, (a + b) / 2, b);
		return multiply(max(l,a),min(r,b),add(vl, vr),lazy[node]);
	}
	Value query(int l, int r) {
		return query(l, r, 1, 0, sz);
	}
};

int main() {
