// vector<int>を渡してあげると、それを元に遅延セグメント木を構築する。
// 区間加算です。いじれそうだったらいじって。

struct LazySegmentTree {
 private:
  int n;  // 最下段のノード数
  vector<ll> node, lazy;

 public:
  LazySegmentTree(vector<ll> v) {
    int sz = (int)v.size();
    n = 1;
    while (n < sz) n *= 2;  // 元のサイズ以上の最小の2冪
    node.resize(2 * n - 1, 0);
    lazy.resize(2 * n - 1, 0);

    // 最下段に突っ込む
    for (int i = 0; i < sz; i++) node[(n - 1) + i] = v[i];

    // 最下段以外を更新していく(下から上に)
    for (int i = n - 2; i >= 0; i--) {
      node[i] = node[i * 2 + 1] + node[i * 2 + 2];
    }
  }

  // 遅延評価をk番目について行う
  void eval(int k, int l, int r) {
    // 遅延配列が空でないなら、自ノード及び子ノードに伝搬する
    if (lazy[k]) {
      node[k] += lazy[k];

      // 最下段ならここは実行されません
      if (r - l > 1) {
        lazy[k * 2 + 1] += lazy[k] / 2;
        lazy[k * 2 + 2] += lazy[k] / 2;
      }
      lazy[k] = 0;  // 自分のぶんは役目を果たしたので
    }
  }

  // [a,b)に遅延評価をする。[l,r)は今呼ばれている区間。上から降りていく。
  void add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
    // 右端を要素の長さに
    if (r < 0) r = n;
    // まず呼ばれたので自分の所に遅延評価を施す
    eval(k, l, r);
    // 俺は関係ない
    if (r <= a || b <= l) return;
    // 完全に範囲に入っているので
    if (a <= l && r <= b) {
      lazy[k] += (r - l) * x;  // 横幅ぶん掛けたのを足す
      eval(k, l, r);
    } else {  // 部分的に重なっているので子ノードに投げる
      add(a, b, x, k * 2 + 1, l, (l + r) / 2);
      add(a, b, x, k * 2 + 2, (l + r) / 2, r);
      node[k] = node[k * 2 + 1] + node[k * 2 + 2];
    }
  }

  // [a,b) 中の結果を返す。[l,r)は対象区間の左端と右端。
  ll getsum(int a, int b, int now = 0, int l = 0, int r = -1) {
    // 右端を初期化
    if (r < 0) r = n;

    // 俺は関係ないとき -> 答えの邪魔にならない値を返す
    if (r <= a || b <= l) return 0;

    // ここまで来た時点で少なくとも重なっているので、遅延評価
    eval(now, l, r);

    // 要求区間の中にノードがすっぽり入ってる → 計算候補として返す
    if (a <= l && r <= b) return node[now];

    // ノードの一部分だけ要求区間に入ってる → 子を再帰的に探索する
    ll vl = getsum(a, b, 2 * now + 1, l, (l + r) / 2);  // 子(左)
    ll vr = getsum(a, b, 2 * now + 2, (l + r) / 2, r);  // 子(右)
    return vl + vr;
  }
};

