int main() {
  int n, q, c, s, t, x;
  cin >> n >> q;
  vector<ll> v(n, 0);
  LazySegmentTree seg(v);
  for (int i = 0; i < q; i++) {
    cin >> c >> s >> t;
    s--;  // tは半開区間なので引かない
    if (c == 0) {
      cin >> x;
      seg.add(s, t, x);
    } else {
      cout << seg.getsum(s, t) << endl;
    }
  }
}

