class SquareDivision{
    private:
        const int BUCKET_SIZE=256;
        ll N, B;
        vector<ll> data;
        vector<ll> bucket_sum;
        vector<ll> bucket_add;

    public:
        void prepare(int n){
            B=(n+BUCKET_SIZE-1)/BUCKET_SIZE;
            N=B*BUCKET_SIZE;
            data.assign(N, 0);
            bucket_add.assign(B, 0);
            bucket_sum.assign(B, 0);
        }

        // [s, t)
        void add(int s, int t, int x){
            for(int k=0; k<B; k++){
                int l=k*BUCKET_SIZE, r=(k+1)*BUCKET_SIZE;

                if(r<=s || t<=l) continue;

                if(s<=l && r<=t){
                    bucket_add[k]+=x;
                }
                else{
                    for(int i=max(s, l); i<min(t, r); i++){
                        data[i]+=x;
                        bucket_sum[k]+=x;
                    }
                }
            }
        }

        int getsum(int s, int t){
            int sum=0;
            for(int k=0; k<B; k++){
                int l=k*BUCKET_SIZE, r=(k+1)*BUCKET_SIZE;

                if(r<=s || t<=l) continue;

                if(s<=l && r<=t){
                    sum+=bucket_sum[k]+bucket_add[k]*BUCKET_SIZE;
                }
                else{
                    for(int i=max(s, l); i<min(t, r); i++){
                        sum+=data[i]+bucket_add[k];
                    }
                }
            }
            return sum;
        }
};

