#define K 200010
typedef long long ll;

ll n,q;
ll tree[K];
ll lazy[K];

ll query(ll node,ll a,ll b,ll i,ll j)
{
    if(a>b||a>j||b<i) return 0;
    if(lazy[node]!=0)
    {
        tree[node]+=lazy[node]*(b-a+1);
        if(a!=b)
        {
            lazy[2*node]+=lazy[node];
            lazy[2*node+1]+=lazy[node];
        }
        lazy[node]=0;
    }
    if(a>=i && b<=j) return tree[node];

    ll mid=(a+b)/2;
    ll q1 = query(2*node,a,mid,i,j);
    ll q2 = query(2*node+1,mid+1,b,i,j);

    return q1+q2;
}

void update(ll node,ll a,ll b,ll i,ll j,ll v)
{
    if(a>b) return;
    if(lazy[node]!=0)
    {
        tree[node]+=lazy[node]*(b-a+1);
        if(a!=b)
        {
            lazy[2*node]+=lazy[node];
            lazy[2*node+1]+=lazy[node];
        }
        lazy[node]=0;
    }
    if(a>b||a>j||b<i) return;

    if(a>=i && b<=j)
    {
        tree[node]+=v*(b-a+1);
        if(a!=b)
        {
            lazy[2*node]+=v;
            lazy[2*node+1]+=v;
        }
        return;
    }

    ll mid = (a+b)/2;
    update(2*node,a,mid,i,j,v);
    update(2*node+1,mid+1,b,i,j,v);
    tree[node] = tree[2*node]+tree[2*node+1];
}

