template<typename T>
struct BIT{
  int n;
  vector<T> bit[2];
  BIT(int n_=0):n(n_){
    bit[0].resize(n+1,0);
    bit[1].resize(n+1,0);
  }
  void add_sub(int p,int i,T x){
    for(i++;i<=n;i+=i&-i){
      bit[p][i]+=x;
    }
  }
  void add(int l,int r,T x){
    add_sub(0,l,-x*(l-1));
    add_sub(0,r,x*(r-1));
    add_sub(1,l,x);
    add_sub(1,r,-x);
  }
  T sum_sub(int p,int i){
    T s=0;
    for(i++;i;i-=i&-i){
      s+=bit[p][i];
    }
    return s;
  }
  T sum(int i){
    return sum_sub(0,i)+sum_sub(1,i)*i;
  }
  T sum(int l, int r){
    return sum(r-1) - sum(l-1);
  }
};

