template <class T>
class SegmentTree{
  ll N;
  vector<T> data;
  vector<T> lazy;
  T def;
  function<T(T,T)> operation;
  function<T(T,T)> update;
  public:
  SegmentTree(size_t _N,T _def,function<T(T,T)> _operaition,function<T(T,T)> _update):def(_def),operation(_operaition),update(_update){
          N = 1;
          while(N < _N){
              N *= 2;
          }
          data = vector<T>(2*N-1,def);
          lazy = vector<T>(2*N-1,0);
  }

  void change(ll i,ll x){
      i += N-1;
      data[i] = update(data[i],x);
      while(i > 0){
          i = (i-1)/2;
          data[i] = operation(data[i*2+1],data[i*2+2]);
      }
  }

  void eval(ll k,ll l,ll r){
      if(lazy[k] != 0){
          data[k] += lazy[k];
          if(r - l > 1){
              lazy[k*2+1] += (lazy[k] / 2);
              lazy[k*2+2] += (lazy[k] / 2);
          }
          lazy[k] = 0;
      }
  }

  void add(ll a,ll b,ll x,ll k = 0,ll l = 0,ll r = -1){
      if(r < 0) r = N;
      eval(k,l,r);
      if(b <= l || r <= a) return;
      if(a <= l && r <= b){
          lazy[k] += (r-l) * x;
          eval(k,l,r);
      }else{
          add(a,b,x,k*2+1,l,(l+r)/2);
          add(a,b,x,k*2+2,(l+r)/2,r);
          data[k] = data[k*2+1] + data[k*2+2];
      }
  }

  T query(ll a,ll b,ll k = 0,ll l = 0,ll r = -1){
      if(r < 0) r = N;
      eval(k,l,r);
      if(b <= l || r <= a) return def;
      if(a <= l && r <= b){
          return data[k];
      }else{
          T c1 = query(a,b,k*2+1,l,(l+r)/2);
          T c2 = query(a,b,k*2+2,(l+r)/2,r);
          return operation(c1,c2);
      }
  }

  T operator[](ll i){
      return lazy[i+N-1];
  }

  T oper(ll i){
      return data[i+N-1];
  }

};


int main(){
    ll N,Q;
    cin >> N >> Q;
    auto f = [](ll a,ll b){return a+b;};
    auto g = [](ll a,ll b){return b;};
