		Node(long long s, long long b) : sum(s), buf(b){}
	};
	vector<Node> node;
	long long defval;
	int N;
	int n;
public:
	void init(int n, long long defval = 0){
		N = 1;
		while(N < n)N<<=1;
		this->n = n;
		this->defval = defval;
		node.assign(N*2-1, Node(defval, 0));
	}
	long long query(int a, int b, int l = 0, int r = -1, int i = 0){
		if(r == -1) r = N;
		if(b <= l || r <= a) return defval;
		if(a <= l && r <= b) return node[i].sum;
		int rag = min(r, b) - max(l, a);
		return query(a,b,l,(l+r)/2,i*2+1) + query(a,b,(l+r)/2,r,i*2+2) + node[i].buf * rag;
	}
	void update(int a, int b, long long v, int l = 0, int r = -1, int i = 0){
		if(r == -1) r = N;
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) { node[i].buf += v; node[i].sum += v * (r-l); return; }

		update(a,b,v,l,(l+r)/2,i*2+1);
		update(a,b,v,(l+r)/2,r,i*2+2);

		node[i].sum = node[i*2+1].sum + node[i*2+2].sum + node[i].buf * (r-l);
	}

};


int main() {
	int n, q; cin >> n >> q;
	RAQ tr; tr.init(n, 0);

	vector<long long> ans;

	for(int i = 0; i < q; i++){
		int c; cin >> c;
		if(c == 0){
			int s,t,x; cin >> s >> t >> x;
			tr.update(s-1, t, x);
		}
		else {
			int s, t; cin >> s >> t;
			ans.push_back(tr.query(s-1, t));
		}
	}

	for(int i = 0; i < ans.size(); i++){
		cout << ans[i] << endl;
	}

    return 0;
}

