struct SegmentTree{
    SegmentTree(int n){
        size = 1;
        while(size < n){
            size *= 2;
        }
        for(int i=1;i<2*size;++i){
            data[i] = D;
        }
    }
    void propagate(int k){
        if(data2[k] != 0){
            data[k] += data2[k];
            if(k < size){
                data2[k*2] += data2[k] / 2;
                data2[k*2+1] += data2[k] / 2;
            }
            data2[k] = 0;
        }
    }
    void update(ll x, int l, int r){
        _update(1, 0, size, x, l, r);
    }
    inline void _update(int k, int a, int b, ll x, int l, int r){
        propagate(k);

        if(b <= l || r <= a){return;}
        if(l <= a && b <= r){
            data2[k] = x * (b - a);
            propagate(k);
        }else{
            int mid = (a + b) / 2;
            _update(k * 2, a, mid, x, l, r);
            _update(k * 2 + 1, mid, b, x, l, r);
            data[k] = data[k*2] + data[k*2+1];
        }
    }
    ll sum(int l, int r){
        return _sum(1, 0, size, l, r);
    }
    inline ll _sum(int k, int a, int b, int l, int r){
        propagate(k);

        if(b <= l || r <= a){return D;}
        if(l <= a && b <= r){return data[k];}
        int mid = (a + b) / 2;
        ll vl = _sum(k * 2, a, mid, l, r),
            vr = _sum(k * 2 + 1, mid, b, l, r);
        return vl + vr;
    }

    int size;
    ll data[400100], data2[400100];
    const ll D = 0;
};

