template<typename T, typename E>
struct segment_tree{
  typedef function<T(T,T)> F;
  typedef function<T(T,E)> G;
  typedef function<E(E,E)> H;
  typedef function<E(E,int)> P;

  vector<T> data;
  vector<E> lazy;

  F f;
  G g;
  H h;

  int n;

  T tid;
  E eid;

  P p;
  segment_tree(int size, F f, G g, H h, T tid, E eid, P p=[](E a, int b){b=0;return a+b;}):f(f),g(g),h(h),tid(tid),eid(eid),p(p){
    n = 1;
    while(n<size) n<<=1;
    data.assign(2*n-1,tid), lazy.assign(2*n-1,eid);
  }
  segment_tree(vector<T> v,F f, G g, H h, T tid, E eid, P p=[](E a, int b){b=0;return a+b;}):f(f),g(g),h(h),tid(tid),eid(eid),p(p){
    int size = v.size();
    n = 1;
    while(n<size) n<<=1;
    data.resize(n);
    assign(v);
  }
  void assign(vector<T> v){
    assert((int)v.size()<=n);
    for(size_t i=0;i<v.size();++i) data[i+n-1] = v[i];
    for(int i=v.size();i<n;++i) data[i+n-1] = tid;
    for(int i=n-2;i>=0;--i) data[i] = f(data[2*i+1],data[2*i+2]);
    lazy.assign(2*n-1,eid);
  }
  inline void eval(int k, int len){
    if(lazy[k]!=eid){
      data[k] = g(data[k],p(lazy[k],len));
      // k has children.
      if(len > 1){
        lazy[2*k+1] = h(lazy[2*k+1],lazy[k]);
        lazy[2*k+2] = h(lazy[2*k+2],lazy[k]);
      }
      lazy[k] = eid;
    }
  }
  void update(int i, E x){
    update(i,i+1,x,0,0,n);
  }
  void update(int a,int b,E x){
    update(a,b,x,0,0,n);
  }
  void update(int a, int b, E x,int k, int l, int r){
    eval(k,r-l);

    // [l,r) out of [a,b)
    if(b<=l||r<=a) return;
    // [l,r) in [a,b)
    if(a<=l && r<=b){
      lazy[k] = h(lazy[k],x);
      eval(k,r-l);
    }else{
      update(a,b,x,2*k+1,l,(l+r)/2);
      update(a,b,x,2*k+2,(l+r)/2,r);
      data[k] = f(data[2*k+1],data[2*k+2]);
    }
  }
  T find(int i){
    return find(i,i+1,0,0,n);
  }
  // [a,b)
  T find(int a,int b){
    return find(a,b,0,0,n);
  }
  T find(int a,int b,int k,int l,int r){
    eval(k,r-l);

    // [l,r) out of [a,b)
    if(r<=a||b<=l) return tid;

    // [l,r) in [a,b)
    if(a<=l&&r<=b) return data[k];

    // else
    return f(find(a,b,2*k+1,l,(l+r)/2),find(a,b,2*k+2,(l+r)/2,r));
  }
};
struct range_sum_query{
  int ui = 0;
  int mi = 0;
  segment_tree<int,int> seg;
  range_sum_query(int n):seg(n,plus<int>(),plus<int>(),plus<int>(),mi,ui,multiplies<int>()){}

  int getsum(int a, int b){
    return seg.find(a,b);
  }
  void add(int s,int t, int x){
    return seg.update(s,t,x);
  }
};
