//range add,sum
struct N{
	int lz,len,val,sum;
	N(int v=0):lz(0),len(1),val(v),sum(v){}
	void add(int v){
		lz+=v;
		val+=v;
		sum+=len*v;
	}
	void reverse(){}
	void push(N&x){
		x.add(lz);
	}
	void clear(){
		lz=0;
	}
	void single(){
		assert(lz==0);
		len=1;
		sum=val;
	}
	void upd(const N&x){
		assert(lz==0);
		len+=x.len;
		sum+=x.sum;
	}
	void updatel(const N&x){
		upd(x);
	}
	void updater(const N&x){
		upd(x);
	}
	bool find(int&x){
		if(x<len)return true;
		x-=len;
		return false;
	}
};

