template<class T,class A,class F,class G,class H>
inline void rrseg<T,A,F,G,H>::open(int siza){
	siz=1;
	hgt=0;
	while(siz<siza){
		siz*=2;
		++hgt;
	}
	siz=siza;
	node=siz-1;
	int n=node+siz;
	dat=new T[n];
	laz=new A[n];
	for(int i=0;i<n;++i){
		dat[i]=idt;
		laz[i]=ida;
	}
	return;
}
template<class T,class A,class F,class G,class H>
inline void rrseg<T,A,F,G,H>::close(void){
	siz=hgt=node=0;
	delete[] dat;
	delete[] laz;
	dat=laz=nullptr;
	return;
}
template<class T,class A,class F,class G,class H>
inline void rrseg<T,A,F,G,H>::put(int first,int last,A val){
	update(first);
	update(last-1);
	int s=first+=node;
	int t=last+=node;
	while(first<last){
		if(!(first&1)) laz[first]=apph(val,laz[first]);
		if(!(last&1)){
			laz[last-1]=apph(val,laz[last-1]);
			--last;
		}
		first/=2;
		last/=2;
	}
	int hs=s<(1<<hgt)-1?hgt-1:hgt;
	for(int i=0;i<hs;++i){
		s=(s-1)/2;
		dat[s]=appf(reflect(s*2+1,1<<i),reflect(s*2+2,1<<i));
	}
	int ht=t<=(1<<hgt)-1?hgt-1:hgt;
	for(int i=0;i<ht;++i){
		t/=2;
		dat[t-1]=appf(reflect(t*2-1,1<<i),reflect(t*2,1<<i));
	}
	return;
}
template<class T,class A,class F,class G,class H>
inline T rrseg<T,A,F,G,H>::get(int first,int last){
	update(first);
	update(last-1);
	first+=node;
	last+=node;
	T x=idt;
	int p=0;
	while(first<last){
		if(!(first&1)) x=appf(reflect(first,1<<p),x);
		if(!(last&1)) x=appf(reflect(--last,1<<p),x);
		first/=2;
		last/=2;
		++p;
	}
	return x;
}
template<class T,class A,class F,class G,class H>
inline void rrseg<T,A,F,G,H>::set(int num,T val){
	dat[num+node]=val;
	return;
}
template<class T,class A,class F,class G,class H>
inline void rrseg<T,A,F,G,H>::build(void){
	int d=node;
	for(int k=(1<<hgt-1)-1;k<d;++k) dat[k]=appf(dat[k*2+1],dat[k*2+2]);
	for(int i=hgt-2;i>=0;--i){
		int d=(1<<i+1)-1;
		for(int k=(1<<i)-1;k<d;++k) dat[k]=appf(dat[k*2+1],dat[k*2+2]);
	}
	return;
}
template<class T,class A,class F,class G,class H>
inline T rrseg<T,A,F,G,H>::reflect(int num,int cnt){
	return laz[num]!=ida?appg(laz[num],cnt,dat[num]):dat[num];
}
template<class T,class A,class F,class G,class H>
inline void rrseg<T,A,F,G,H>::update(int num){
	int k=0;
	int h=num+node<(1<<hgt)-1?hgt-1:hgt;
	for(int i=h-1;i>=0;--i){
		if(laz[k]!=ida){
			laz[k*2+1]=apph(laz[k],laz[k*2+1]);
			laz[k*2+2]=apph(laz[k],laz[k*2+2]);
			dat[k]=reflect(k,1<<i+1);
			laz[k]=ida;
		}
		k=k*2+1+(num+siz>>i&1);
	}
	return;
}
template<class T,class A,class F,class G,class H>
inline rrseg<T,A,F,G,H>::rrseg(T idta,A idaa){
	idt=idta;
	ida=idaa;
	siz=hgt=node=0;
	dat=laz=nullptr;
}
template<class T,class A,class F,class G,class H>
inline rrseg<T,A,F,G,H>::rrseg(T idta,A idaa,int siza){
	idt=idta;
	ida=idaa;
	open(siza);
}

