using namespace std;

template <typename T>
struct segtree_lazy {
	int n;
	vector<T> tree, lazy;
	T def = 0, none = 0;

	segtree_lazy(int n_) {
		for (n = 1; n < n_; n *= 2) {

		}
		tree.assign(2 * n, def);
		lazy.assign(2 * n, none);
	}

	T merge(T a, T b) {
		return a + b;
	}

	void set_lazy(int index, T x) {
		lazy[index] += x;
	}

	void push(int index, T num) {
		if (lazy[index] == none) {
			return;
		}
		tree[index] += lazy[index] * num;
		set_lazy(2 * index, lazy[index]);
		set_lazy(2 * index + 1, lazy[index]);
		lazy[index] = none;
	}

	void fix(int index) {
		tree[index] = merge(tree[2 * index], tree[2 * index + 1]);
	}

	void update(int a, int b, int index, int l, int r, T x, T num) {
		if (r <= a || b <= l) {
			push(index, num);
			return;
		}
		if (a <= l && r <= b) {
			set_lazy(index, x);
			push(index, num);
			return;
		}
		push(index, num);
		update(a, b, 2 * index, l, (l + r) / 2, x, num / 2);
		update(a, b, 2 * index + 1, (l + r) / 2, r, x, num / 2);
		fix(index);
	}

	void update(int l, int r, T x) {
		update(l, r, 1, 0, n, x, n);
	}

	T query(int a, int b, int index, int l, int r, T num) {
		if (r <= a || b <= l) {
			return none;
		}
		if (a <= l && r <= b) {
			push(index, num);
			return tree[index];
		}
		push(index, num);
		T puni = query(a, b, 2 * index, l, (l + r) / 2, num / 2);
		T muni = query(a, b, 2 * index + 1, (l + r) / 2, r, num / 2);
		return merge(puni, muni);
	}

	T query(int l, int r) {
		return query(l, r, 1, 0, n, n);
	}
};

int main() {
	int n, q;
	cin >> n >> q;
	segtree_lazy<int> seg(n);
	for (int i = 0; i < q; i++) {
		bool b;
		int s, t;
		cin >> b >> s >> t;
		if (b) {
			cout << seg.query(s - 1, t) << endl;
		} else {
			int x;
			cin >> x;
			seg.update(s - 1, t, x);
		}
	}
	return 0;
}

