using namespace std;

typedef long long ll;

struct s_tree
{
	vector<ll> st, lazy;

	s_tree(int n) : st(4*n, 0), lazy(4*n, 0) {}

	inline void push(int c, int b, int e, int m)
	{
		if (lazy[c] != 0)
		{
			st[c<<1] += (m-b)*lazy[c];
			st[c<<1|1] += (e-m)*lazy[c];
			lazy[c<<1] += lazy[c];
			lazy[c<<1|1] += lazy[c];
			lazy[c] = 0;
		}
	}

	ll query(int c, int b, int e, int l, int h)
	{
		if (b >= l && e-1 <= h)
			return st[c];
		int m = (b+e)>>1;
		push(c, b, e, m);
		ll s = 0;
		if (l < m)
			s += query(c<<1, b, m, l, h);
		if (m <= h)
			s += query(c<<1|1, m, e, l, h);
		return s;
	}

	void update(int c, int b, int e, int l, int h, ll v)
	{
		if (b >= l && e-1 <= h)
		{
			st[c] += v * (e-b);
			lazy[c] += v;
			return;
		}
		int m = (b+e)>>1;
		push(c, b, e, m);
		if (l < m)
			update(c<<1, b, m, l, h, v);
		if (m <= h)
			update(c<<1|1, m, e, l, h, v);
		st[c] = st[c<<1]+st[c<<1|1];
	}
};

int main()
{
	ios_base::sync_with_stdio(0), cin.tie(0);

	int n, q;
	cin >> n >> q;

	ll t, a, b, x;
	s_tree st(n+2);
	while (q--)
	{
		cin >> t >> a >> b;
		if (t)
		{
			cout << st.query(1, 1, n+2, a, b) << "\n";
			continue;
		}
		cin >> x;
		st.update(1, 1, n+2, a, b, x);
	}

	return 0;
}

