template <class T>
struct fenwick_tree {
	vector<T> x,lazy;
	fenwick_tree(int n) : x(n + 1, 0), lazy(n + 1, 0) { }
	T sum(int r) {
		T S = 0;

		for (; r > 0; r -= r&-r) {
			S += x[r] + lazy[r]*(r&-r);
			for (int cp = r + r&-r; cp < x.size() && cp != r - (r&-r); cp += cp&-cp)
				S += lazy[cp] * (r&-r);;
		}
		return S;
	}
	void add(int r, T a) {
		for (; r > 0; r -= r&-r) {
			lazy[r] += a;
			for (int cp = r + r&-r; cp < x.size() && cp != r - (r&-r); cp += cp&-cp)
				x[cp] += a * (r&-r);
		}
	}
};


