#define T long long

class BIT {
private:
    int n;
    vector<T> bit;
public:
    // 0_indexed で i 番目の要素に x を加える
    void add(int i, T x){
        i++;
        while(i < n){
            bit[i] += x, i += i & -i;
        }
    }
    // 0_indexed で [0,i] の要素の和(両閉区間！！)
    T sum(int i){
        i++;
        T s = 0;
        while(i > 0){
            s += bit[i], i -= i & -i;
        }
        return s;
    }
    BIT(){}
    //初期値がすべて0の場合
    BIT(int sz) : n(sz+1), bit(n, 0){}
    BIT(vector<T>& v) : n((int)v.size()+1), bit(n, 0){
        for(int i = 0; i < n-1; i++){
            add(i,v[i]);
        }
    }
    void print(){
        for(int i = 0; i < n-1; i++){
            cout<<sum(i)-sum(i-1)<< " ";
        }
        cout<<endl;
    }
    //-1スタート
    void print_sum(){
        for(int i = 0; i < n; i++){
            cout<<sum(i-1)<<" ";
        }
        cout<<endl;
    }
};

class BIT_1D_RangeAdd_RangeSum {
private:
    int n;
    BIT bitc, biti;
    void add(BIT& bit, int l, int r, T val){
        bit.add(l, val), bit.add(r, -val);
    }
public:
    BIT_1D_RangeAdd_RangeSum(int sz) : n(sz), bitc(sz), biti(sz){}
    void add(int l, int r, T val){
        add(bitc, l, r, val), add(biti, l, r, -val*(l-1)), add(biti, r, n, val*(r-l));
    }
    T sum(int x){
        return (long long)bitc.sum(x) * x + biti.sum(x);
    }
    T sum(int l, int r){
        return sum(r-1) - sum(l-1);
    }
    void print(){
        for(int i = 0; i < n; i++){
            cout<<sum(i,i+1)<< " ";
        }
        cout<<endl;
    }
};


int main()
{
    int n = in(), q = in();
    BIT_1D_RangeAdd_RangeSum bt(n);
    rep(i,q){
        int x = in();
        if(x){
            int s = in(), t = in();
            out(bt.sum(s-1,t));
        }else{
            int s = in(), t = in(), u = in();
            bt.add(s-1,t,u);
        }
    }
    return 0;
}

#include<bits/stdc++.h>
#define MAX_N 100000
using namespace std;
#define int long long
int dat[MAX_N*3],lazy[MAX_N*3];

class LazySegmentTree{
public:
    int n;
    LazySegmentTree(vector<int> v){
        n=1;
        while(n<v.size())n*=2;
        for(int i=0;i<v.size();++i)dat[i+n-1] = v[i];
        for(int i=0;i<2*n-1;++i)lazy[i] = 0;
        for(int i=n-2;i>=0;--i)dat[i] = dat[2*i+1]+dat[2*i+2];
    }

    void eval(int k,int l,int r){
        if(lazy[k]!=0){
            dat[k]+=lazy[k];
            if(r - l > 1){
                lazy[2*k+1] += lazy[k]/2;
                lazy[2*k+2] += lazy[k]/2;
            }
        }
        lazy[k] = 0;
    }

    void add(int a,int b,int x,int k,int l,int r){
        eval(k,l,r);
        if(b<=l || r<=a)return ;
        if(a<=l && r<=b){
            lazy[k] += (r-l)*x;
            eval(k,l,r);
        }
        else {
            add(a,b,x,2*k+1,l,(l+r)/2);
            add(a,b,x,2*k+2,(l+r)/2,r);
            dat[k] = dat[2*k+1]+dat[2*k+2];
        }
    }

    int query(int a,int b,int k,int l,int r){
        eval(k,l,r);
        if(b<=l || r<=a)return 0;
        if(a<=l && r<=b)return dat[k];
        int vl = query(a,b,2*k+1,l,(l+r)/2);
        int vr = query(a,b,2*k+2,(l+r)/2,r);
        return vl + vr;
    }

};

