		int q=in();
		if(q==1){
			int x=in()-1,t=in()-1;
			out(tree.Find(x,t+1));
		}
		else{
			int s=in()-1,t=in()-1,x=in();
			tree.UpdateRange(s,t+1,x);
		}
	}

	return 0;
}

