typedef long long i64;

struct LazySegment
{
	vector<i64> node;
	vector<i64> lazy;
	vector<bool> lazyFlag;
	int n;


	i64 init = 0;

	int left(int i)
	{
		return 2 * i + 1;
	}

	int right(int i )
	{
		return 2 * i + 2;
	}

	LazySegment(const vector<i64>& vec)
	{
		int sz = vec.size();

		n = 1;
		while(n < sz) n <<= 1;

		node.resize(2 * n - 1,init);
		lazy.resize(2 * n - 1,0);
		lazyFlag.resize(2 * n - 1,false);

		for(int i = 0;i < sz;i++)
		{
			node[n - 1 + i] = vec[i];
		}

		for(int i = n - 2;i >= 0;i--)
		{
			node[i] = node[left(i)] + node[right(i)];
		}
	}

	void eval(int k,int l,int r)
	{
		if(lazyFlag[k])
		{
			node[k] = node[k] + lazy[k];

			if(r - l > 1)
			{
				lazy[left(k)] += lazy[k] / 2;
				lazy[right(k)] += lazy[k] / 2;
				lazyFlag[left(k)] = true;
				lazyFlag[right(k)] = true;
			}

			lazyFlag[k] = false;

			lazy[k] = 0;
		}
	}

	void add_inter(int a,int b,i64 x,int k = 0,int l = 0,int r = -1)
	{
		if(r < 0) r = n;

		eval(k,l,r);

		if(b <= l || r <= a) return ;

		if(a <= l && r <= b)
		{
			lazy[k] += (r - l) * x;
			lazyFlag[k] = true;
			eval(k,l,r);
		}

		else
		{
			add_inter(a,b,x,left(k),l,(l + r) / 2);
			add_inter(a,b,x,right(k),(l + r) / 2,r);
			node[k] = node[left(k)] + node[right(k)];
		}
	}

	i64 get_inter(int a,int b,int k = 0,int l = 0,int r = -1)
	{
		if(r < 0) r = n;

		eval(k,l,r);
		if(b <= l || r <= a) return init;

		if(a <= l && r <= b) return node[k];

		i64 lv = get_inter(a,b,left(k),l , (l + r) / 2);
		i64 rv = get_inter(a,b,right(k),(l + r) / 2 , r);

		return lv + rv;
	}
};

int main()
{
	int n;
	int q;

	cin >> n >> q;

	LazySegment seg(vector<i64>(n,0));

	for(int i= 0;i < q;i++)
	{
