struct segment_tree{
    pair<int,int> map[2000010];
    void build(int now,int l,int r){
        map[now].first=map[now].second=0;
        if(l==r)return;
        int mid=(l+r)/2;
        build(now*2+1,l,mid);
        build(now*2+2,mid+1,r);
        return ;
    }
    void change(int n,int now,int L,int R,int l,int r){
        if(R<l||L>r)return;
        if(L>=l&&R<=r){
            map[now].second+=n;
            map[now].first+=(R-L+1)*n;
            return;
        }
        int mid=(L+R)/2;
        map[now*2+1].first+=map[now].second*(mid-L+1);
        map[now*2+2].first+=map[now].second*(R-mid);
        map[now*2+1].second+=map[now].second;
        map[now*2+2].second+=map[now].second;
        map[now].second=0;
        change(n,now*2+1,L,mid,l,r);
        change(n,now*2+2,mid+1,R,l,r);
        map[now].first=map[now*2+1].first+map[now*2+2].first;
        return ;
    }
    int find(int now,int L,int R,int l,int r){
        if(R<l||L>r)return 0;
        if(L>=l&&R<=r)return map[now].first;
        int mid=(L+R)/2;
        map[now*2+1].first+=map[now].second*(mid-L+1);
        map[now*2+2].first+=map[now].second*(R-mid);
        map[now*2+1].second+=map[now].second;
        map[now*2+2].second+=map[now].second;
        map[now].second=0;
        return find(now*2+1,L,mid,l,r)+find(now*2+2,mid+1,R,l,r);
    }
};
int main(){
    int n,m,k,l,r;
    segment_tree arr;
    scanf("%d%d",&n,&m);
    arr.build(0,1,n);
    while(m--){
        scanf("%d%d%d",&k,&l,&r);
        if(k==0){
            scanf("%d",&k);
            arr.change(k,0,1,n,l,r);
        }
        else printf("%d\n",arr.find(0,1,n,l,r));
    }
}

