		if (Com == 0) {
			long long A, B, X;
			cin >> A >> B >> X;
			Seg.Update(A - 1, B, X);
		}
		else {
			long long A, B;
			cin >> A >> B;
			cout << Seg.Query(A - 1, B) << endl;
		}
