using namespace std;

long all[2 * MAX_N - 1], part[2 * MAX_N - 1];

void init(){
    for(int i = 0; i < 2 * MAX_N - 1; i++)
        all[i] = part[i] = 0;
}

void add(int a, int b, long x, int k = 0, int l = 0, int r = MAX_N){
    if(a <= l && r <= b){
        all[k] += x;
    }
    else if(l < b && a < r){
        part[k] += (min(b, r) - max(a, l)) * x;
        add(a, b, x, k * 2 + 1, l, (l + r) / 2);
        add(a, b, x, k * 2 + 2, (l + r) / 2, r);
    }
}

long sum(int a, int b, int k = 0, int l = 0, int r = MAX_N){
    if(b <= l || r <= a) return 0;
    else if(a <= l && r <= b) return all[k] * (r - l) + part[k];
    else{
        long res;
        res = (min(b, r) - max(a, l)) * all[k];
        res += sum(a, b, k * 2 + 1, l, (l + r) / 2);
        res += sum(a, b, k * 2 + 2, (l + r) / 2, r);
        return res;
    }
}

