/**
 * Verify
 * RMQ (Add): http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=4529260
 * RMQ (Update): http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=4529538
 * @tparam E
 * @tparam T
 */
template<typename E, typename T>
class LazySegmentTree {
 private:
  E _e_id;
  T _t_id;
  size_t _size;
  /** E・E */
  function<E(E, E)> _ee;
  /** E・T */
  function<E(E, T)> _et;
  /** T・T */
  function<T(T, T)> _tt;
  /** 区間加算のとき、RSQ なら掛け算、RMQ なら T をそのまま返す関数 */
  function<T(T, ll)> _t_pow;

  /**
   * k の部分木の葉に一様に value を適用する
   * @param k
   */
  void _apply_to_subtree(int k, T value) {
    _tree[k] = _et(_tree[k], _t_pow(value, _leaves_counts[k]));
    if (k < _size) {
      _lazy[k] = _tt(_lazy[k], value);
    }
  }

  /**
   * k とその親たちの遅延配列を評価する
   * @param k
   */
  void _eval_parents(int k) {
    int v = k;
    int h = 0;
    while ((v >> h) > 1) h++;
    for (; h > 0; h--) {
      k = v >> h;
      _apply_to_subtree(k << 1, _lazy[k]);
      _apply_to_subtree(k << 1 | 1, _lazy[k]);
      _lazy[k] = _t_id;
    }
  }

  /**
   * _tree[k] の親たちを最新化する
   * @param k
   */
  void _update_parents(int k) {
    k >>= 1;
    while (k > 0) {
      _tree[k] = _et(
          _ee(_tree[k << 1], _tree[k << 1 | 1]),
          _t_pow(_lazy[k], _leaves_counts[k]));
      k >>= 1;
    }
  }

 public:
  vector<E> _tree;
  vector<T> _lazy;
  vector<ll> _leaves_counts;

  LazySegmentTree(
      const vector<E> &values,
      E e_id,
      T t_id,
      function<E(E, E)> op_ee,
      function<E(E, T)> op_et,
      function<T(T, T)> op_tt,
      function<T(T, ll)> t_pow = [](T e, ll n) { return e; }
  ) : _e_id(e_id),
      _t_id(t_id),
      _ee(std::move(op_ee)),
      _et(std::move(op_et)),
      _tt(std::move(op_tt)),
      _t_pow(std::move(t_pow)) {
    _size = values.size();
    _tree.resize(_size * 2, _e_id);
    _lazy.resize(_size * 2, _t_id);
    _leaves_counts.resize(_size * 2, 1);

    for (int i = 0; i < _size; i++) {
      _tree[i + _size] = values[i];
    }
    for (int i = _size - 1; i > 0; i--) {
      _tree[i] = _ee(_tree[i << 1], _tree[i << 1 | 1]);
      _leaves_counts[i] = _leaves_counts[i << 1] + _leaves_counts[i << 1 | 1];
    }
  }

  /**
   * [l, r) の範囲に value を適用する
   * @param l
   * @param r
   * @param value
   */
  void apply(int l, int r, T value) {
    l += _size;
    r += _size;
    int l0 = l;
    int r0 = r;

    // _et が上書き系の演算のときに、あとから古い値で上書きされないように、
    // 既存の遅延配列の値を評価して _tree に移しておく
    // http://judge.u-aizu.ac.jp/onlinejudge/review.jsp?rid=4529538
    _eval_parents(l);
    _eval_parents(r - 1);
    while (l < r) {
      if (l & 1) {
        _apply_to_subtree(l++, value);
      }
      if (r & 1) {
        _apply_to_subtree(--r, value);
      }
      l >>= 1;
      r >>= 1;
    }
    _update_parents(l0);
    _update_parents(r0 - 1);
  }

  /**
   * [l, r) に op_ee を適用した値を返す
   * @param l
   * @param r
   */
  auto query(int l, int r) -> E {
    l += _size;
    r += _size;
    _eval_parents(l);
    _eval_parents(r - 1);

    vector<E> ret, ret_r;
    while (l < r) {
      if (l & 1) {
        ret.push_back(_tree[l++]);
      }
      if (r & 1) {
        ret_r.push_back(_tree[--r]);
      }
      l >>= 1;
      r >>= 1;
    }
    reverse(ret_r.begin(), ret_r.end());
    ret.insert(ret.end(), ret_r.begin(), ret_r.end());
    return accumulate(ret.begin(), ret.end(), _e_id, _ee);
  }
};

