template<typename T>
struct SegmentTree {

	SegmentTree(int _n) : n(_n) { 
		t.resize(n * 4);
		lazy.resize(n * 4);
		len.resize(n * 4);
		lengths(1, 1, n);
	}

	SegmentTree(vector<T>& a) {
		n = (int)a.size();
		t.resize(4 * n);
		lazy.resize(4 * n);
		len.resize(4 * n);
		build(a, 1, 1, n);
		lengths(1, 1, n);
	}

	int n;
	vector<T> t, lazy, len;

	void build(vector<T>& a, int v, int tl, int tr) {
	    if (tl == tr) {
	        t[v] = a[tl - 1];
	    } else {
	        int tm = (tl + tr) / 2;
	        build(a, v*2, tl, tm);
	        build(a, v*2+1, tm+1, tr);
	        t[v] = t[v*2] + t[v*2+1];
	    }
	}

	void lengths(int v, int tl, int tr) {
	    if (tl == tr) {
	        len[v] = 1;
	    } else {
	        int tm = (tl + tr) / 2;
	        lengths(v*2, tl, tm);
	        lengths(v*2+1, tm+1, tr);
	        len[v] = len[v*2] + len[v*2+1];
	    }
	}

	void _push(int v) {
	    t[v*2] += (len[v * 2] * lazy[v]);
	    lazy[v*2] += lazy[v];
	    t[v*2+1] += (len[v * 2 + 1] * lazy[v]);
	    lazy[v*2+1] += lazy[v];
	    lazy[v] = 0;
	}

	void update(int l, int r, T addend) {
		_update(1, 1, n, l, r, addend);
	}

	void _update(int v, int tl, int tr, int l, int r, T addend) {
	    if (l > r) 
	        return;
	    if (l == tl && tr == r) {
	        t[v] += (r - l + 1) * addend;
	        lazy[v] += addend;
	    } else {
	        _push(v);
	        int tm = (tl + tr) / 2;
	        _update(v*2, tl, tm, l, min(r, tm), addend);
	        _update(v*2+1, tm+1, tr, max(l, tm+1), r, addend);
	        t[v] = t[v*2] + t[v*2+1];
	    }
	}

	T query(int l, int r) {
		return _query(1, 1, n, l, r);
	}

	T _query(int v, int tl, int tr, int l, int r) {
	    if (l > r)
	        return 0;
	    if (l <= tl && tr <= r)
	        return t[v];
	    _push(v);
	    int tm = (tl + tr) / 2;
	    return _query(v*2, tl, tm, l, min(r, tm)) +
	           _query(v*2+1, tm+1, tr, max(l, tm+1), r);
	}
};
