struct lst
{
    private:
        int n;
        vector<ll> node;
        vector<ll> lazy;
        vector<bool> lflg;

        void lazy2node(int k, int l, int r)
        {
            if(lflg[k])
            {
                node[k]+=(r-l+1)*lazy[k];
                lflg[k]=false;
                prop(lazy[k], k, l, r);
                lazy[k]=0;
            }
        }

        void prop(int v, int k, int l, int r)
        {
            if(r-l>0)
            {
                lazy[2*k+1]+=v;
                lazy[2*k+2]+=v;
                lflg[2*k+1]=lflg[2*k+2]=true;
            }
        }

    public:
        lst(int sz)
        {
            n=1; while(n<sz) n*=2;
            node.resize(2*n-1, 0);
            lazy.resize(2*n-1, 0);
            lflg.resize(2*n-1, false);
        }

        void update(int qa, int qb, int v, int k=0, int l=0, int r=-1)
        {
            if(r<0) r=n-1;
            lazy2node(k, l, r);
            if(qb<l || r<qa) return;
            if(qa<=l && r<=qb)
            {
                node[k]+=(r-l+1)*v;
                prop(v, k, l, r);
            }
            else
            {
                int m=(l+r)/2;
                update(qa, qb, v, 2*k+1, l, m);
                update(qa, qb, v, 2*k+2, m+1, r);
                node[k]=node[2*k+1]+node[2*k+2];
            }
        }

        ll get(int qa, int qb, int k=0, int l=0, int r=-1)
        {
            if(r<0) r=n-1;
            lazy2node(k, l, r);
            if(qb<l || r<qa) return 0;
            if(qa<=l && r<=qb) return node[k];
            else
            {
                int m=(l+r)/2;
                ll ls=get(qa, qb, 2*k+1, l, m);
                ll rs=get(qa, qb, 2*k+2, m+1, r);
                return ls+rs;
            }
        }
};

