#define MAX_N (1<<17) // 10^5

struct SegTree {
  long long seg[MAX_N*2-1];
  int lazy[MAX_N*2-1];
  SegTree() {
    for (int i=0; i<MAX_N*2-1; i++) seg[i] = 0, lazy[i] = 0;
  }

  inline void setLazy(int k, int v, int l, int r) {
    lazy[k] += v;
    seg[k] += 1LL*v*(r-l);
  }
  inline void fix(int k) {
    seg[k] = seg[k*2+1] + seg[k*2+2];
  }
  inline void push(int k, int l, int r) {
    if (lazy[k] == 0) return;
    setLazy(k*2+1, lazy[k], l, (l+r)/2);
    setLazy(k*2+2, lazy[k], (l+r)/2, r);
    lazy[k] = 0;
  }

  void fill(int a, int b, int x, int k=0, int l=0, int r=MAX_N) {
    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      setLazy(k, x, l, r);
      return;
    }
    push(k, l, r);
    fill(a, b, x, k*2+1, l, (l+r)/2);
    fill(a, b, x, k*2+2, (l+r)/2, r);
    fix(k);
  }

  long long query(int a, int b, int k=0, int l=0, int r=MAX_N) {
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return seg[k];
    push(k, l, r);
    return query(a, b, k*2+1, l, (l+r)/2) + query(a, b, k*2+2, (l+r)/2, r);
  }
};

int N, Q;
SegTree seg;

signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> N >> Q;
  rep(i, Q) {
    int t;
    cin >> t;
    if (t == 0) {
      int l, r, x;
      cin >> l >> r >> x;
      seg.fill(l, r+1, x);
    }
    else {
      int l, r;
      cin >> l >> r;
      cout << seg.query(l, r+1) << "\n";
    }
  }
  return 0;
}

