P dat[1000000];
int size_ = 1;
void init(int x) {
	while (size_ < x)size_ *= 2;
	//rep(i, 2 * size_ - 1)dat[i] = { ((int)(1) << 31) - 1,inf };
}
void eval(int k, int l, int r) {
	if (dat[k].second) {
		dat[k].first += dat[k].second;
		if (r - l > 1) {
			dat[k * 2 + 1].second += dat[k].second / 2;
			dat[k * 2 + 2].second += dat[k].second / 2;
		}
		dat[k].second = 0;
	}
}
void update(int a, int b, int k, int x, int l, int r) {
	eval(k, l, r);
	if (r <= a || b <= l)return;
	if (a <= l && r <= b) {
		dat[k].second += x * (r - l);
		eval(k, l, r);
	}
	else {
		update(a, b, k * 2 + 1, x, l, (l + r) / 2);
		update(a, b, k * 2 + 2, x, (l + r) / 2, r);
		dat[k].first = dat[k * 2 + 1].first + dat[k * 2 + 2].first;
	}
}
int query(int a, int b, int k, int l, int r) {
	eval(k, l, r);
	if (r <= a || b <= l)return 0;
	if (a <= l && r <= b) {
		return dat[k].first;
	}
	int lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
	int rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
	return lv + rv;
}
