  int size = 1;
  std::vector<T> tree; // 1-indexed
  std::vector<Q> lazy; // 1-indexed

  void flush(int i, int l, int r) {
    tree[i] = lstTrait.apply(tree[i], powm<ActionMonoid>(lazy[i], r - l)); // TODO
    if (i < size) {
      lazy[i * 2] = actionM(lazy[i * 2], lazy[i]);
      lazy[i * 2 + 1] = actionM(lazy[i * 2 + 1], lazy[i]);
    }
    lazy[i] = actionM.id();
  }

public:
  LazySegTree(const int n) {
    while (size < n) size *= 2;
    tree.assign(size * 2, foldM.id());
    lazy.assign(size * 2, actionM.id());
  }

  // [l, r)
  void act(int l, int r, const int x) { act(l, r, x, 1, 0, size); }
  void act(const int l, const int r, const int x, int i, int a, int b) {
    flush(i, a, b);
    if (b <= l || r <= a) return;
    if (l <= a && b <= r) {
      lazy[i] = actionM(lazy[i], x);
      flush(i, a, b);
      return;
    }
    act(l, r, x, i * 2, a, (a + b) / 2);
    act(l, r, x, i * 2 + 1, (a + b) / 2, b);
    tree[i] = foldM(tree[i * 2], tree[i * 2 + 1]);
  }

  // [l, r)
  T fold(int l, int r) { return fold(l, r, 1, 0, size); }
  T fold(int l, int r, int i, int a, int b) {
    flush(i, a, b);
    if (b <= l || r <= a) return foldM.id();
    if (l <= a && b <= r) return tree[i];
    T lhs = fold(l, r, i * 2, a, (a + b) / 2);
    T rhs = fold(l, r, i * 2 + 1, (a + b) / 2, b);
    tree[i] = foldM(tree[i * 2], tree[i * 2 + 1]);
    return foldM(lhs, rhs);
  }
};

template<typename T> struct sumMonoid {
  using value_type = T;
  constexpr value_type id() { return 0; }
  constexpr value_type operator()(const value_type &a, const value_type &b) { return a + b; }
};

template<typename T> struct RSQ_RAQ_Trait {
  using FoldMonoid = sumMonoid<T>;
  using ActionMonoid = sumMonoid<T>;
  typename FoldMonoid::value_type apply(typename FoldMonoid::value_type q, typename FoldMonoid::value_type t) { return q + t; }
};

main {
  int n, q;
  cin >> n >> q;
  LazySegTree<RSQ_RAQ_Trait<int>> lst(n);
  while (q--) {
    int a, s, t;
    cin >> a >> s >> t;
    --s, --t;
    if (a) {
      cout << lst.fold(s, t + 1) << endl;
    } else {
      int x;
      cin >> x;
      lst.act(s, t + 1, x);
    }
  }
}

