// Verified: AOJ2644 Longest Match (min, max)
enum query_type { min_query, max_query, sum_query };

template<class T> struct segtree {
  int N, K;
  vector<T> dat, sum;
  function<T(T, T)> func;
  T ngvalue;
  query_type qtype;

  void init(int n, function<T(T, T)>&& f, T ng, query_type type) {
    K = 0, N = 1;
    while(N < n) K++, N <<= 1;
    dat.assign(2 * N - 1, 0);
    sum.assign(2 * N - 1, 0);
    func = std::move(f);
    ngvalue = ng;
    qtype = type;
  }

  segtree() = default;

  segtree(int n, query_type qtype) {
    if(qtype == min_query) {
      init(n, [](T a, T b){return min(a, b);}, numeric_limits<T>::max(), max_query);
    }
    else if(qtype == max_query) {
      init(n, [](T a, T b){return max(a, b);}, numeric_limits<T>::min(), min_query);
    }
    else if(qtype == sum_query) {
      init(n, [](T a, T b){return a + b;}, 0, sum_query);
    }
    else {
      runtime_error("no matching query type");
    }
  }

  void add(int i, T x) {
    add(i, i + 1, x);
  }

  void add(int a, int b, T x) {
    add(a, b, x, 0, 0, N);
  }

  T add(int a, int b, T x, int k, int l, int r) {
    if(b <= l || r <= a) return dat[k];
    if(a <= l && r <= b) {
      sum[k] += x;
      return dat[k] += x * (qtype == sum_query ? r - l : 1);
    }
    int m = (l + r) / 2;
    return dat[k] = func(add(a, b, x, 2 * k + 1, l, m), add(a, b, x, 2 * k + 2, m, r)) + sum[k] * (qtype == sum_query ? r - l : 1);
  }

  T operator()(int a, int b) {
    return query(a, b, 0, 0, N);
  }

  T query(int a, int b, int k, int l, int r) {
    if(b <= l || r <= a) return ngvalue;
    if(a <= l && r <= b) return dat[k];
    int m = (l + r) / 2;
    return func(query(a, b, 2 * k + 1, l, m), query(a, b, 2 * k + 2, m, r)) + sum[k] * (qtype == sum_query ? (b < r ? b : r) - (a < l ? l : a) : 1);
  }
};

int main() {
  int N; cin >> N;
  segtree<ll> rsq(N, sum_query);
  int Q; cin >> Q;
  rep(_, Q) {
    int q; cin >> q;
    int s, t; cin >> s >> t; s--;
    if (q == 0) {
      int x; cin >> x;
      rsq.add(s, t, x);
    }
    else {
      cout << rsq(s, t) << "\n";
    }
  }
}

