constexpr int sqrtN = 512;

struct SqrtDecomposition {

    int N, K;

    vector<LL> data;
    vector<LL> bucket_add;
    vector<LL> bucket_sum;

    SqrtDecomposition(int N) : N(N) {
        K = (N + sqrtN - 1) / sqrtN;
        data.assign(sqrtN * K, 0);
        bucket_add.assign(K, 0);
        bucket_sum.assign(K, 0);
    }

    void add(int a, int b, LL x) {
        for (int k = 0; k < K; k++) {
            int l = k * sqrtN;
            int r = (k + 1) * sqrtN;
            if (r <= a or b <= l) continue;
            if (a <= l and r <= b) {
                bucket_add[k] += x;
            } else {
                for (int i = max(a, l); i < min(b, r); i++) data[i] += x;
                bucket_sum[k] = 0;
                for (int i = k * sqrtN; i < (k + 1) * sqrtN; i++) bucket_sum[k] += data[i];
            }
        }
    }

    LL get_sum(int a, int b) {
        LL ret = 0;
        for (int k = 0; k < K; k++) {
            int l = sqrtN * k;
            int r = (k + 1) * sqrtN;
            if (r <= a or b <= l) continue;
            if (a <= l and r <= b) {
                ret += bucket_add[k] * sqrtN;
                ret += bucket_sum[k];
            } else {
                for (int i = max(a, l); i < min(b, r); i++) ret += data[i] + bucket_add[k];
            }
        }
        return ret;
    }

};


int main() {

    int N, Q;
    cin >> N >> Q;

    SqrtDecomposition deco(N);

    while (Q--) {
        int w;
        cin >> w;
        if (w == 0) {
            int l, r, x;
            cin >> l >> r >> x;
            l--, r--;
            deco.add(l, r + 1, x);
        } else {
            int l, r;
            cin >> l >> r;
            l--, r--;
            cout << deco.get_sum(l, r + 1) << endl;
        }
    }


    return 0;
}

