ll query(int a, int b, ll v){
	ll sum = 0;
	ll c_a, c_b;
	c_a = a / sqr, c_b = b / sqr;
	if(c_a == c_b){
		for(int i = a;i < b;i ++)
			A[i] += v, sum += A[i];
		return sum;
	}
	else{
		for(int i = a; i < (c_a + 1) * sqr;i ++)
			A[i] += v, sum += A[i];
		for(int i = c_a + 1;i < c_b;i ++)
			B[i] += sqr * v, sum += B[i];
		for(int i = c_b * sqr;i < b;i ++)
			A[i] += v, sum += A[i];
		return sum;
	}
}

