    vi ceros(n);
    SegmentTree st(ceros);

    for(int i = 0; i < q; ++i) {
        cin>>t>>a>>b;
        a--; b--;
        if(t) { cout<<st.query(a,b)<<"\n"; continue; }
        cin>>v;
        st.update(a, b, v);
    }

    return 0;
}

