template<class Z>
struct SegTreeLazy {
  using T = Z;
  vector<T> data;
  vector<T> lazy;
  T UNIT;
  int n;
  ll s;
  SegTreeLazy(int n, T a) : n (n),UNIT(a){
    s = 1;
    while(s < n){
      s *= 2;
    }
    data = vector<T>(s*2 - 1,UNIT);
    lazy = vector<T>(s*2 - 1, UNIT);
  }

  void evaluate(int k, int l, int r){
    if(lazy[k] != 0){
      data[k] += lazy[k];
      if(r - l > 1){
        lazy[k*2+1] += lazy[k]/2;
        lazy[k*2+2] += lazy[k]/2;
      }
      lazy[k] = 0;
    }
  }

  void add(int a, int b,T x, int k=0, int l=0, int r=-1){
    if(r == -1)r = s;
    evaluate(k,l,r);
    if(b <= l || r <= a){
      return ;
    }
    if(a <= l && r <= b){
      lazy[k] += (r - l)*x;
      //dump(k);
      //dump(lazy[k]);
      evaluate(k,l,r);
    }
    else {
      add(a,b,x,k*2+1,l,(r+l)/2);
      add(a,b,x,k*2+2,(l+r)/2,r);
      data[k] = data[k*2+1] + data[k*2+2];
      //cout << "data[" << k << "] = " << data[k] << endl;
    }
  }
  T query(int a, int b, int k=0, int l=0, int r=-1){
    if(r == -1)r = s;
    evaluate(k,l,r);
    if(r <= a || b <= l)return UNIT;
    if(a <= l && r <= b)return data[k];
    T vl = query(a,b,k*2+1,l,(r+l)/2);
    T vr = query(a,b,k*2+2,(l+r)/2,r);
    //dump(vl);
    //dump(vr);
    return vl + vr;
  }
};
