// 遅延評価セグメント木をソラで書きたいあなたに
// http://tsutaj.hatenablog.com/entry/2017/03/30/224339
//　区間に対して更新が必要な時に用いる

struct LazySegmentTree {
  private:
    int n;
    vector<ll> node, lazy;

  public:
    LazySegmentTree(vector<ll> v) {
        int sz = (int)v.size();
        n = 1;
        while(n < sz) {
            n *= 2;
        }
        // node
        node.resize(2 * n - 1);
        //遅延評価用
        lazy.resize(2 * n - 1, 0);

        for(int i = 0; i < sz; i++) {
            node[i + n - 1] = v[i];
        }
        for(int i = n - 2; i >= 0; i--) {
            node[i] = node[i * 2 + 1] + node[i * 2 + 2];
        }
    }

    // k番目のノードについて遅延評価を行う
    //ノードの示す範囲をlとrでもつ
    void eval(int k, int l, int r) {
        if(lazy[k] != 0) {
            node[k] += lazy[k];
            //下のノードに伝搬させる
            if(r - l > 1) {
                lazy[2 * k + 1] += lazy[k] / 2;
                lazy[2 * k + 2] += lazy[k] / 2;
            }
            // 伝播が終わったので，自ノードの遅延配列を空にする
            lazy[k] = 0;
        }
    }

    //区間にたいするadd
    //したから上がってくる
    void add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
        if(r < 0) {
            r = n;
        }
        // k番目のノードに対して遅延評価を行う
        eval(k, l, r);
        if(b <= l || r <= a) {
            //[a, b) と[l, r)がdisjoint
            return;
        }
        if(a <= l and r <= b) {
            //[l,r] \subset [a, b)
            lazy[k] += (r - l) * x;
            //ここでの遅延評価本当に必要なのか？
            eval(k, l, r);
        }
        //子供ノードの値を再帰的に計算する
        else {
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }

    ll getsum(int a, int b, int k = 0, int l = 0, int r = -1) {
        if(r < 0) {
            r = n;
        }
        if(b <= l || r <= a) {
            return 0;
        }
        eval(k, l, r);
        if(a <= l and r <= b) {
            //[l,r) \subset [a, b)
            return node[k];
        }
        ll vl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;
    }
};

int main() {
    int N, Q;
    cin >> N >> Q;
    LazySegmentTree seg(vector<ll>(N, 0));
    for(int i = 0; i < Q; i++) {
        int query;
