struct RSAQ {

  /*　使い方まとめ(0-index)　*/

  /*

  RMUQ myvec(n) // 宣言 nは必要な要素数
  myvec.at(i) // 配列のi番目にアクセス
  myvec.update(i,k) // 配列のi番目をkにする
  myvec.add(i,k) // 配列のi番目にkを足す
  myvec.radd(L,R,k) // 配列のL番目からR番目をkに更新
  myvec.rsum(i,j) // 配列の[i,j]の範囲の和を返す

  myvec.debug() // 元データ配列とバケット配列を標準エラー出力

  */

  vector<int> data;
  vector<int> bucket1;
  vector<int> bucket2;
  int sq;

  RSAQ(int n) {
    sq = sqrt(n);
    if(sq*sq==n) sq--;
    sq++;
    data = Vi(sq*sq,0);
    bucket1 = Vi(sq,0); // 1はRAQ成分(0)
    bucket2 = Vi(sq,0); // 2はRSQ成分(0)
  }

  void radd(int L,int R,int k) { // [L,R]は範囲
    R++;
    int dL,dR;

    rep(i,0,sq+1) {
      dL = i*sq,dR = (i+1)*sq; // [dL,dR]は小範囲(バケット)

      if(dR <= L || R <= dL) continue; // バケットが完全に範囲外

      if(L <= dL && dR <= R) { // バケットが完全に範囲内
        bucket1[i] += k;
      }

      else { // バケットが範囲と一部重なる
        rep(j,max(L,dL),min(R,dR)) {
          data[j] += k;
          bucket2[i] += k;
        }
      }
    }
  }

  void add(int i,int k) {
    radd(i,i,k);
    return;
  }

  int at(int i) {
    int ib = i/sq;
    return data[i]+bucket1[ib];
  }

  void update(int i,int k) {
    int now = at(i);
    add(i,k-now);
    return;
  }

  int rsum(int L,int R) {
    R++;
    int sum = 0;
    int dL,dR;

    rep(i,0,sq+1) {
      dL = i*sq,dR = (i+1)*sq; // [dL,dR]は小範囲

      if(dR <= L || R <= dL) continue; // 小範囲が完全に範囲外

      if(L <= dL && dR <= R) { // 小範囲が完全に範囲内
        sum += bucket2[i];
        sum += bucket1[i]*sq;
      }

      else { // 小範囲が範囲と一部重なる
        rep(j,max(L,dL),min(R,dR)) {
          sum += data[j]+bucket1[i];
        }
      }
    }
    return sum;
  }

  void debug(){
    Verr(data);
    Verr(bucket1);
    Verr(bucket2);
    cerr << endl;
  }

};

