const ll sqrtN = 512;
struct SqrtDecomposition {
  int N, K;
  vector<ll> data;
  vector<ll> bucketadd;
  vector<ll> bucketsum;
  SqrtDecomposition(int n) : N(n) {
    K = (N + sqrtN - 1) / sqrtN;
    data.assign(K * sqrtN, 0);
    bucketadd.assign(K, 0);
    bucketsum.assign(K, 0);
  }
  void add(int s,int t,ll x) {
    for(int k=0;k<K;++k){
        int l=k*sqrtN,r=(k+1)*sqrtN;
        if (r <= s || t <= l)
          continue;
        if (s <= l && r <= t) {
            bucketadd[k]+=x;
        } 
        else {
            for (int i = max(s, l); i < min(t, r); ++i) {
                data[i]+=x;
            }
            ll  sum=0;
            for(int i = l;i<r;i++){
                sum+=data[i];
            }
            bucketsum[k]=sum;
        }
    }
  }
  // [x, y)
  ll get(int s,int t) {
    ll ret=0;
    for(int k=0;k<K;++k){
        int l=k*sqrtN,r=(k+1)*sqrtN;
        if (r <= s || t <= l)
          continue;
        if (s <= l && r <= t) {
            ret+=bucketsum[k]+bucketadd[k]*sqrtN;
        } 
        else {
            for (int i = max(s, l); i < min(t, r); ++i) {
                ret+=data[i]+bucketadd[k];
            }
        }
    }
    return ret;
  }
};



