signed main() {
	INIT;

	VAR(int, n, q);

	LazySegmentTree<MonoidOfValue::sum<int>, MonoidOfOperator::add<int>, ApplyOperator::RSQRAQ> lst(n);

	REP(_, q) {
		VAR(int, type, l, r); --l;
		if (type == 0) {
			VAR(int, x);
			lst.update(l, r, x);
		}
		else {
			OUT(lst.query(l, r))BR;
		}
	}

	return 0;
}

