class LazySegTree {
    int n = 1;
    vector<ll> node, lazy;

public:
    LazySegTree(vector<ll> v) {
        while (n < v.size()) n *= 2;
        node.resize(2*n-1, 0);
        lazy.resize(2*n-1, 0);

        for (int i = 0; i < v.size(); i++) node[i+n-1] = v[i];
        for (int i = n-2; i >= 0; i--) node[i] = node[i*2+1] + node[i*2+2];
    }

    ll eval(int k, int l, int r) {
        if (lazy[k] != 0) {
            node[k] += lazy[k];

            if (r - l > 1) {
                lazy[2*k+1] += lazy[k] / 2;
                lazy[2*k+2] += lazy[k] / 2;
            }

            lazy[k] = 0;
        }
        return node[k];
    }

    ll add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        eval(k, l, r);
        if (b <= l || r <= a) return 0;

        if (a <= l && r <= b) {
            lazy[k] += (r - l) * x;
            return eval(k, l, r);
        } else {
            add(a, b, x, k*2+1, l, (l+r)/2);
            add(a, b, x, k*2+2, (l+r)/2, r);
            return node[k] = node[k*2+1] + node[k*2+2];
        }
    }

    ll getSum(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (b <= l || r <= a) return 0;

        eval(k, l, r);
        if (a <= l && r <= b) return node[k];
        ll vl = getSum(a, b, k*2+1, l, (l+r)/2);
        ll vr = getSum(a, b, k*2+2, (l+r)/2, r);
        return vl + vr;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int N, Q;
    cin>>N>>Q;

    vector<ll> v(N, 0);
    LazySegTree lst(v);
    for (int q = 0; q < Q; q++) {
        int type;
        cin>>type;
        if (type == 0) {
            int s, t;
            ll x;
            cin>>s>>t>>x;
            lst.add(s-1, t, x);
        } else {
            int s, t;
            cin>>s>>t;
            cout<<lst.getSum(s-1, t)<<endl;
        }
    }

    return 0;
}

