template<class T>
class lpsg_tree {
private:
    vector<T> lazy;
    vector<T> seg;
    T def;
    lli num;
    void push(lli k){
        if(lazy[k] == def) return;
        set(k*2+1,lazy[k]/2);
        set(k*2+2,lazy[k]/2);
        lazy[k] = def;
    }
    void set(lli k,T x){
        lazy[k] += x;seg[k] += x;
    }
    void update(lli a,lli b,T x,lli k,lli l,lli r){
        if(r <= a || b <= l) return;
        if(a <= l && r <= b) set(k,x*(r-l));
        else {
            push(k);
            update(a,b,x,k*2+1,l,(r+l)/2);
            update(a,b,x,k*2+2,(l+r)/2,r);
            seg[k] = func(seg[k*2+1],seg[k*2+2]);
        }
    }
    T func(T a,T b){
        return a + b;
    }
    T query(lli a,lli b,lli k,lli l,lli r){
        if(r <= a || b <= l) return def;
        if(a <= l && r <= b) return seg[k];
        push(k);
        T vl = query(a,b,k*2+1,l,(l+r)/2);
        T vr = query(a,b,k*2+2,(l+r)/2,r);
        return func(vl,vr);
    }
public:
    lpsg_tree(){}
    lpsg_tree(lli n,lli d = 0):lazy(n*4,d),seg(n*4,d){
        def = d;
        num = 1;
        while(n > num) num <<= 1;
    }
    void update(lli a,lli b,lli x){
        update(a,b,x,0,0,num);
    }
    T query(lli a,lli b){
        return query(a,b,0,0,num);
    }

};


