struct LazySegmentTree {
  int N;
  vector<ll> node,lazy;
  vector<bool> delay;
  LazySegmentTree(int n_){
    N = 1; while (N < n_) N *= 2;
    node.assign(2*N-1, 0); // 暫定的な合計値
    lazy.assign(2*N-1, 0); // 一様に加えるやつ
    delay.assign(2*N-1, false); // 遅延しているかどうか
  }

  // 遅延評価
  void eval(int k,int l,int r){
    if (!delay[k]) return;
    node[k] += lazy[k] * (r - l);
    if (r-l > 1){
      // 葉ノードでなければlazyを伝播する
      lazy[2*k+1] += lazy[k]; delay[2*k+1] = true;
      lazy[2*k+2] += lazy[k]; delay[2*k+2] = true;
    }
    lazy[k] = 0; delay[k] = false;
  }

  // [a,b) に各々 x を加える。見ているノード k が [l,r)
  void add(int a,int b,ll x,int k=0,int l=0,int r=-1){
    if (r == -1) r = N;
    eval(k,l,r);
    if (b <= l || r <= a) return;
    if (a <= l && r <= b){
      lazy[k] += x; delay[k] = true;
      eval(k,l,r);
      return;
    }
    add(a, b, x, 2*k+1, l, (l+r)/2);
    add(a, b, x, 2*k+2, (l+r)/2, r);
    node[k] = node[2*k+1] + node[2*k+2];
  }

  // [a,b) の合計値を返す。見ているノード k が [l,r)
  ll getsum(int a,int b,int k=0,int l=0,int r=-1){
    if (r == -1) r = N;
    eval(k,l,r);
    if (b <= l || r <= a) return 0;
    if (a <= l && r <= b) return node[k];
    ll vl = getsum(a, b, 2*k+1, l, (l+r)/2);
    ll vr = getsum(a, b, 2*k+2, (l+r)/2, r);
    return vl + vr;
  }
};

