template <class num> struct LST {
private:
	int n;
	vector<num> node, lazy;
	void eval(int k, int l, int r) {
		if (lazy[k] != 0) {
			node[k] += lazy[k];
			if (r - l > 1) {
				lazy[2 * k + 1] += lazy[k] / 2;
				lazy[2 * k + 2] += lazy[k] / 2;
			}
			lazy[k] = 0;
		}
	}
public:
	LST(vector<num> v) {
		int sz = v.size();
		n = 1; while (n < sz)n *= 2;
		node.resize(n * 2 - 1, 0);
		lazy.resize(n * 2 - 1, 0);

		for (int i = 0; i < sz; i++)node[i + n - 1] = v[i];
		for (int i = n - 2; i >= 0; i--)node[i] = min(node[2 * i + 1], node[2 * i + 2]);
	}
	void update(int a, int b, num x, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		eval(k, l, r);

		if (b <= l || r <= a)return;
		if (a <= l && r <= b) {
			lazy[k] += (r - l)*x;
			eval(k, l, r);
		}
		else {
			update(a, b, x, 2 * k + 1, l, (l + r) / 2);
			update(a, b, x, 2 * k + 2, (l + r) / 2, r);
			node[k] = node[2 * k + 1] + node[2 * k + 2];
		}
	}
	num get(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		if (b <= l || r <= a)return 0;
		eval(k, l, r);
		if (a <= l && r <= b)return node[k];
		return get(a, b, 2 * k + 1, l, (l + r) / 2) + get(a, b, 2 * k + 2, (l + r) / 2, r);
	}
};
