using namespace std;

struct LazySegmentTree{//区間加算,区間和クエリ,0オリジン
    private:
        int n;
        vector<ll>node,lazy;

    public:
        LazySegmentTree(vector<ll>v){
            int sz=(int)v.size();
            n=1;
            while(n<sz)n*=2;
            node.resize(2*n-1);
            lazy.resize(2*n-1,0);

            for(int i=0;i<sz;i++)node[i+n-1]=v[i];
            for(int i=n-2;i>=0;--i)node[i]=node[2*i+1]+node[2*i+2];
        }

        //k番目のノードについて遅延評価
        void eval(int k,int l,int r){
            //遅延配列が空でなければ値の伝播が起こる
            if(lazy[k]!=0){
                node[k]+=lazy[k];

                if(r-l>1){//最下段かどうかの確認
                    lazy[2*k+1]+=lazy[k]/2;
                    lazy[2*k+2]+=lazy[k]/2;
                    //子ノードは親ノードの半分の範囲なので値も半分
                }

                lazy[k]=0;//空にする
            }
        }

        void add(int a,int b,ll x,int k=0,int l=0,int r=-1){
            if(r<0)r=n;

            //k番目のノードに遅延評価
            eval(k,l,r);

            //範囲外
            if(b<=l||r<=a)return;

            //完全に被覆しているなら遅延配列に代入した後に評価
            if(a<=l&&r<=b){
                lazy[k]+=(r-l)*x;
                eval(k,l,r);
            }

            //それ以外なら子ノードを再帰的に計算
            else{
                add(a,b,x,2*k+1,l,(l+r)/2);
                add(a,b,x,2*k+2,(l+r)/2,r);
                node[k]=node[2*k+1]+node[2*k+2];
            }
        }

        ll getsum(int a,int b,int k=0,int l=0,int r=-1){//区間和の取得
            if(r<0)r=n;
            if(b<=l||r<=a)return 0;

            eval(k,l,r);
            if(a<=l&&r<=b)return node[k];
            ll vall=getsum(a,b,2*k+1,l,(l+r)/2);
            ll valr=getsum(a,b,2*k+2,(l+r)/2,r);
            return vall+valr;
        }
};

void solve(){
    int n,q;
    cin>>n>>q;
    vector<ll>v(n);
    LazySegmentTree seg(v);
    while(q--){
