const int DEFAULT = 0;

//RSQ, RAQ
struct SegmentTree {
    int n;
    vector<int> heap;
    vector<int> lazy;

    SegmentTree(int n): n(n) {
        heap.assign(4 * n, DEFAULT);
        lazy.assign(4 * n, DEFAULT);
    }

    void add(int nodeId, int l, int r, int ql, int qr, int v) {
        if (qr < l || ql > r) {
            return;
        }
        else if (ql <= l && r <= qr) {
            lazy[nodeId] += v;
        }
        else {
            pushdown(nodeId, l, r);
            int m = l + (r - l)/2;
            add(nodeId * 2, l, m, ql, qr, v);
            add(nodeId * 2 + 1, m + 1, r, ql, qr, v);
            pushup(nodeId, l, r);
        }
    }

    void pushdown(int nodeId, int l, int r) {
        if (lazy[nodeId] > 0) {
            lazy[nodeId * 2] += lazy[nodeId];
            lazy[nodeId * 2 + 1] += lazy[nodeId];
            heap[nodeId] += lazy[nodeId] * (l - r + 1);
            lazy[nodeId] = 0;
        }
    }

      void pushup(int nodeId, int l, int r) {
          int m = l + (r - l)/2;
          heap[nodeId] = getSum(nodeId * 2, l, m) + getSum(nodeId * 2 + 1, m + 1, r);
      }

      int getSum(int nodeId, int l, int r) {
           return lazy[nodeId] * (r - l + 1) + heap[nodeId];

      }

    int query(int nodeId, int l, int r, int ql, int qr) {
        if (qr < l || ql > r) {
            return DEFAULT;
        }
        if (ql <= l && r <= qr) {
            return getSum(nodeId, l, r);
        } 
        else {
            pushdown(nodeId, l, r);
            int m = l + (r - l)/2;
            return query(nodeId * 2, l, m, ql, qr) + 
                   query(nodeId * 2 + 1, m + 1, r, ql, qr);
        }
    }  
};

