		else {
			update(a, b, 2 * k + 1, l, (l + r) / 2, x);
			update(a, b, 2 * k + 2, (l + r) / 2, r, x);
			if (gt > k) {
				seg[k] = seg[2 * k + 1] + lazy[2 * k + 1] * (r - l) / 2
					+ seg[2 * k + 2] + lazy[2 * k + 2] * (r - l) / 2;
			}
		}
	}

