void lazy( int ini, int fin, int lv ){
    if( ini == fin )
        return;
    T[lv*2].lazy += T[lv].lazy;
    T[lv*2+1].lazy += T[lv].lazy;
    int mit = (ini+fin)/2;

    T[lv*2].v += T[lv].lazy * (mit-ini+1);
    T[lv*2+1].v += T[lv].lazy * (fin-mit);
    T[lv].lazy = 0;
}

void update( int ini, int fin, int lv, int a, int b, ll v ){
    if( ini > b || fin < a )return;
    if( T[lv].lazy )
        lazy(ini,fin,lv);
    if( ini >= a && fin <= b ){
        T[lv].v += (fin-ini+1)*v;
        T[lv].lazy = v;
        return;
    }
    int mit = (ini+fin)/2;
    update(ini,mit,lv*2,a,b,v);
    update(mit+1,fin,lv*2+1,a,b,v);
    T[lv].v = T[lv*2].v + T[lv*2+1].v;
}

ll query( int ini, int fin, int lv, int a, int b ){
    if( ini > b || fin < a )return 0;
    if( T[lv].lazy )
        lazy(ini,fin,lv);
    if( ini >= a && fin <= b )return T[lv].v;
    int mit = (ini+fin)/2;
    return query(ini,mit,lv*2,a,b) + query(mit+1,fin,lv*2+1,a,b);
}

