template<class T>
struct LazySegmentTree {
private:
    int n;
    vector<T> node, lazy;
    vector<bool> updated;
    T def;
    function<T(T,T)> cmp;

    void init(const vector<T> &v, T _def, function<T(T,T)> _cmp) {
        def = _def; cmp = _cmp;
        int vl = (int)v.size();
        n = 1; while(n < vl) n *= 2;
        node.resize(2 * n - 1);
        lazy.resize(2 * n - 1, _def);
        updated.resize(2 * n - 1, false);
        for(int i = 0; i < vl; i++) node[i + n - 1] = v[i];
        for(int i = n - 2; i >= 0; i--) node[i] = cmp(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void eval(int k, int l, int r) {
        if (updated[k]) {
            node[k] += lazy[k];
            if ((r - l) > 1) {
                lazy[k * 2 + 1] += lazy[k] / 2;
                lazy[k * 2 + 2] += lazy[k] / 2;
                updated[k * 2 + 1] = updated[k * 2 + 2] = true;
            }
            lazy[k] = 0;
            updated[k] = false;
        }
    }

public:
    LazySegmentTree() {}
    LazySegmentTree(int _n, T _def, function<T(T,T)> _cmp) {
        init(vector<T>(_n, _def), _def, _cmp);
    }
    LazySegmentTree(const vector<T> &v, T _def, function<T(T,T)> _cmp) {
        init(v, _def, _cmp);
    }

    void update(int a, int b, T x, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        eval(k, l, r);
        if((b <= l) || (r <= a)) return;
        if((a <= l) && (r <= b)) {
            lazy[k] += (r - l) * x;
            updated[k] = true;
            eval(k, l, r);
        }
        else {
            update(a, b, x, 2 * k + 1, l, (l + r) / 2);
            update(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = cmp(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        eval(k, l, r);
        if ((b <= l) || (r <= a)) return def;
        if ((a <= l) && (r <= b)) return node[k];
        T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return cmp(vl, vr);
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    // ifstream in("input.txt");
    // cin.rdbuf(in.rdbuf());
    ll n, q;
    cin >> n >> q;
    LazySegmentTree<ll> lst(n, 0, [](ll a, ll b){ return a + b; });
    rep(i, q) {
        ll com;
        cin >> com;
        if (com == 0) {
            ll s, t, x;
            cin >> s >> t >> x;
            s--; t--;
            lst.update(s, t + 1, x);
        }
        else {
            ll s, t;
            cin >> s >> t;
            s--; t--;
            cout << lst.query(s, t + 1) << endl;
        }
    }
    return 0;
}

