#define lowbit(i) ((i)&-(i)) 

using namespace std;

typedef long long ll;

int n;
ll b1[100100],b2[100100];

void add(ll *bit,int i,ll x)
{
    while(i<=n)
    {
        bit[i]+=x;
        i+=lowbit(i);
    }
}

ll sum(ll *bit,int x)
{
    ll s=0;
    while(x>0)
    {
        s+=bit[x];
        x-=lowbit(x);
    }
    return s;
}

void add(ll x,ll y,ll s)
{
    add(b1,x,s);add(b1,y+1,-s);
    add(b2,x,x*s);add(b2,y+1,-(y+1)*s);
}

ll sum(ll x)
{
    return (x+1)*sum(b1,x+1)-sum(b2,x+1);
}

