struct LazySegTree_RSQ {
	int n;
	ll e = 0;
	vector<ll> a, b;
	int num_of_elements(int m) { int res = 1; while (res < m) res *= 2; return res; }
	LazySegTree_RSQ(int m) {
		n = num_of_elements(m);
		a = vector<ll>(2 * n - 1, e);
		b = vector<ll>(2 * n - 1, e);
	}
	LazySegTree_RSQ(vector<ll> &a_) {
		LazySegTree_RSQ(a_.size());
		rep(i, a_.size()) a[i + n - 1] = a_[i];
		rep3(k, n - 2, -1) a[k] = min(a[2 * k + 1], a[2 * k + 2]);
	}
	void eval(int k, int l, int r) {
		if (b[k] == e) return;
		a[k] += b[k];
		if (r - l > 1) {
			b[2 * k + 1] += b[k] / 2;
			b[2 * k + 2] += b[k] / 2;
		}
		b[k] = e;
	}
	void operate(int i, int j, ll val, int k, int l, int r) { // [i,j)
		// dbs(k, l, r);
		eval(k, l, r);
		if (j <= l or r <= i) return;
		if (i <= l and r <= j) {
			b[k] += val * (r - l);
			eval(k, l, r);
			return;
		}
		operate(i, j, val, 2 * k + 1, l, (l + r) / 2);
		operate(i, j, val, 2 * k + 2, (l + r) / 2, r);
		a[k] = a[2 * k + 1] + a[2 * k + 2];
	}
	void operate(int i, int j, ll val) { operate(i, j, val, 0, 0, n); }
	void update(int i, ll val) { // 遅延フラグが必要らしい
		int k = i + n - 1;
		a[k] = val;
		while (k > 0) {
			k = (k - 1) / 2;
			a[k] = min(a[2 * k + 1], a[2 * k + 2]);
		}
	}
	ll get(int i, int j, int k, int l, int r) { // [i,j)
		// dbs(k, l, r);
		if (j <= l or r <= i) return e;
		eval(k, l, r);
		if (i <= l and r <= j) return a[k];
		ll vl = get(i, j, 2 * k + 1, l, (l + r) / 2);
		ll vr = get(i, j, 2 * k + 2, (l + r) / 2, r);
		return vl + vr;
	}
	ll get(int i, int j) {
		return get(i, j, 0, 0, n);
	}
};


int main() {
	int n, q; cin >> n >> q;
	LazySegTree_RSQ lst(n);
	while(q--) {
		int com; cin >> com;
		if (!com) {
			int s, t, x; cin >> s >> t >> x; s--; t--;
			lst.operate(s, t + 1, x);
		} else {
			int s, t; cin >> s >> t; s--; t--;
			cout << lst.get(s, t + 1) << endl;
		}
		// dbl(lst.a); dbl(lst.b);
	}
}

#include<cstdio>
#include<vector>
#include<algorithm>
using namespace std;

int size;
vector<long long> dat,lazy;
void init(int n){
  size = 1;
  while(size<n) size *= 2;
  dat.assign(2*size-1,0);
  lazy.assign(2*size-1,0);
}
void lazy_evaluate(int k,int l,int r){
  dat[k] += lazy[k] * (r-l);
  if(k<size-1){
    lazy[2*k+1] += lazy[k];
    lazy[2*k+2] += lazy[k];
  }
  lazy[k] = 0;
}
void update(int a,int b,int x,int k,int l,int r){
  lazy_evaluate(k,l,r);
  if(b<=l||r<=a) return;
  else if(a<=l&&r<=b){
    lazy[k] += x;
    lazy_evaluate(k,l,r);
  }else{
    update(a,b,x,2*k+1,l,(l+r)/2);
    update(a,b,x,2*k+2,(l+r)/2,r);
    dat[k] = dat[2*k+1] + dat[2*k+2];
  }
}
long long query(int a,int b,int k,int l,int r){
  lazy_evaluate(k,l,r);
  if(b<=l||r<=a) return 0;
  else if(a<=l&&r<=b){
    return dat[k];
  }else{
    return query(a,b,2*k+1,l,(l+r)/2) + query(a,b,2*k+2,(l+r)/2,r);
  }
}

int main(){
  int n,q;
  scanf("%d %d",&n,&q);
  init(n);
  for(int i=0;i<q;i++){
    int cmd;
    scanf("%d",&cmd);
    if(cmd==0){
      int s,t,x;
      scanf("%d %d %d",&s,&t,&x);
      update(s-1,t,x,0,0,size);
    }else if(cmd==1){
      int s,t;
      scanf("%d %d",&s,&t);
      printf("%lld\n",query(s-1,t,0,0,size));
    }
  }
  return 0;
}

