int seg[MAX_N * 4], lazy[MAX_N * 4];

void init(int size) {

	n = 1;

	while (n < size)
		n *= 2;
}

void eval(int k, int l,int r ) {

	seg[k] += lazy[k];

	if (r - l > 1) {
		lazy[k * 2 + 1] += lazy[k] / 2;
		lazy[k * 2 + 2] += lazy[k] / 2;
	}

	lazy[k] = 0;
}

void add(int a, int b, int v, int k, int l, int r) {

	eval(k, l, r);

	if (r <= a || b <= l)
		return;

	if (a <= l&&r <= b) {

		lazy[k] = v*(r - l);

		eval(k, l, r);

		return;
	}

	add(a, b, v, k * 2 + 1, l, (l + r) / 2);
	add(a, b, v, k * 2 + 2, (l + r) / 2, r);

	seg[k] = seg[k * 2 + 1] + seg[k * 2 + 2];
}

int getSum(int a, int b, int k, int l, int r) {

	eval(k, l, r);

	if (r <= a || b <= l)
		return 0;

	if (a <= l&&r <= b)
		return seg[k];

	return getSum(a, b, k * 2 + 1, l, (l + r) / 2) + getSum(a, b, k * 2 + 2, (l + r) / 2, r);
}

