struct Segtree {
	int a[N_SIZE];
	int seg[N_SIZE * 2];
	int lazy[N_SIZE * 2];
	int gt;
	void init(int n) {
		gt = 1;
		while (n > gt)gt *= 2;
		REP(i, n)a[i] = 0;
		REP(i, N_SIZE) {
			seg[i] = 0;
			lazy[i] = 0;
		}
		REP(i, n)seg[i + gt - 1] = a[i];
	}

	void lazy_evaluate(int k) {
		seg[k] += lazy[k];
		if (gt > k) {
			lazy[2 * k + 1] += lazy[k];
			lazy[2 * k + 2] += lazy[k];
		}
		lazy[k] = 0;
	}

	//[a,b)
	void update(int a, int b, int x) { update(a, b, 0, 0, gt, x); }
	void update(int a, int b, int k, int l, int r, int x) {
		if (r <= a || b <= l) {
			return;
		}
		if (a <= l&&r <= b) {
			lazy[k] += x;
		}
		else {
			lazy_evaluate(k);
			update(a, b, 2 * k + 1, l, (l + r) / 2, x);
			update(a, b, 2 * k + 2, (l + r) / 2, r, x);
			if (gt > k)seg[k] = seg[2 * k + 1] + seg[2 * k + 2];
		}
	}

	//[a,b???min
	ll query(int a, int b) { return query(a, b, 0, 0, gt); }
	ll query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return 0;
		lazy_evaluate(k);
		if (gt > k) {
			return seg[k] = query(a, b, 2 * k + 1, l, (l + r) / 2)
				+ query(a, b, 2 * k + 2, (l + r) / 2, r);
		}
		else return seg[k];
	}

	void print() {
		REP(i, gt * 2)cout << "!" << i << " " << seg[i] << " " << lazy[i] << endl;
	}
};

