#include<bits/stdc++.h>
using namespace std;

using i64 = int64_t;

class LazySegmentTree {
  private:
    int n;
    vector<i64> node, lazy;

    void eval(int k, int l, int r) {
        if(lazy[k] == 0) return;

        node[k] += lazy[k];

        if(r - l > 1) {
            lazy[2*k+1] += lazy[k] / 2;
            lazy[2*k+2] += lazy[k] / 2;
        }

        lazy[k] = 0;
    }

  public:
    LazySegmentTree(vector<i64> v) {
        int size = (int)v.size();
        n = 1;
        while(n < size) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, 0);

        for(int i=0;i<size;++i) node[i+n-1] = v[i];
        for(int i=n-2;i>=0;--i) node[i] = node[2*i+1] + node[2*i+2];
    }

    void update(int a, int b, i64 x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;

        eval(k, l, r);

        if(b <= l || r <= a) return;

        if(a <= l && r <= b) {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }else{
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = node[2*k+1] + node[2*k+2];
        }
    }

    i64 query(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        if(b <= l || r <= a) return 0;

        eval(k, l, r);
        if(a <= l && r <= b) return node[k];
        i64 vl = query(a, b, 2*k+1, l, (l+r)/2);
        i64 vr = query(a, b, 2*k+2, (l+r)/2, r);
        return vl + vr;
    }
};

int main(){
    int n, q;
    cin >> n >> q;
    vector<i64> v(n+1, 0);
    LazySegmentTree lst = LazySegmentTree(v);
    for(int i=0;i<q;++i){
        int c;
        cin >> c;
        if(c == 0){
            int s, t, x;
            cin >> s >> t >> x;
            lst.update(s, t+1, x);
        }else{
            int s, t;
            cin >> s >> t;
            cout << lst.query(s, t+1) << endl;
        }
    }

    return 0;
}

