const int INF = 0x3f3f3f3f;
long long B1[100005], B2[100005];
int n, q, t1, t2, t3, t4;

long long qry(long long* ar, int p) {
	long long rt = 0;
	while (p) {
		rt += ar[p];
		p -= (p & -p);
	}
	return rt;
}

void upt(long long* ar, int p, long long val) {
	while (p <= n) {
		ar[p] += val;
		p += (p & -p);
	}
}

void rangeUpt(int l, int r, long long val) {
	upt(B1, l, val);
	upt(B1, r + 1, -val);
	upt(B2, l, val * (l - 1));
	upt(B2, r + 1, -val * r);
}

long long preSum(int p) {
	return qry(B1, p) * p - qry(B2, p);
}

long long rangeQry(int l, int r) {
	return preSum(r) - preSum(l - 1);
}

