struct lazy_segtree{
    int n;
    vector<lint> data, lazy;

    lazy_segtree(int _n){
        n = 1; while(n < _n) n *= 2;
        data = vector<lint>(n*2-1, 0);
        lazy = vector<lint>(n*2-1, 0);
    }
    /* k番目のノードについて遅延評価する. 自身のノードが指す範囲を[l,r)とする */
    void eval(int k, int l, int r){
        if(lazy[k] == 0) return;
        data[k] += lazy[k];
        if(r-l>1){
            lazy[k*2+1] += lazy[k]/2;
            lazy[k*2+2] += lazy[k]/2;
        }
        lazy[k] = 0;
    }
    /* 区間[a,b)に対する一様な加算 */
    void update(int a, int b, lint x, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b){
            lazy[k] += (r-l)*x;
            eval(k, l, r);
        }
        else{
            update(a, b, x, k*2+1, l, (l+r)/2);
            update(a, b, x, k*2+2, (l+r)/2, r);
            data[k] = data[2*k+1] + data[2*k+2];
        }
    }
    /* 区間[a,b)に対する区間和の取得 */
    lint query(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        if(b <= l || r <= a) return 0;
        eval(k, l, r);
        if(a <= l && r <= b) return data[k];
        lint ll = query(a, b, k*2+1, l, (l+r)/2);
        lint rr = query(a, b, k*2+2, (l+r)/2, r);
        return ll+rr;
    }
};

template<class T, class M>
class abstract_lazy_segtree{
    public:

    int n; vector<T> data; vector<M> lazy;
    T id; M def;
    function<T(T,T)> op;
    function<T(T,M)> upd;
    function<M(M,M)> merge;
    function<M(M,int)> p;

    abstract_lazy_segtree(size_t _n, T _id, M _def,
    function<T(T,T)> _op, function<T(T,M)> _upd, function<M(M,M)> _merge,
    function<M(M,int)> _p = [](M a, int b){ return a; })
    : id(_id), def(_def), op(_op), upd(_upd), merge(_merge), p(_p){
        n = 1;
        while(n < _n) n *= 2;
        data = vector<T>(2*n-1, id);
        lazy = vector<M>(2*n-1, def);
    }

    void eval(int k, int l, int r){
        if(lazy[k] == def) return;
        if(r-l>1){
            lazy[k*2+1] = merge(lazy[k], lazy[k*2+1]);
            lazy[k*2+2] = merge(lazy[k], lazy[k*2+2]);
        }
        data[k] = upd(data[k], lazy[k]);
        lazy[k] = def;
    }
    void update(int a, int b, M x, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b){
            eval(k, l, r);
            lazy[k] = merge(lazy[k],p(x, r-l));
            eval(k, l, r);
        }
        else{
            update(a, b, x, k*2+1, l, (l+r)/2);
            update(a, b, x, k*2+2, (l+r)/2, r);
            data[k] = op(data[2*k+1], data[2*k+2]);
        }
    }
    T query(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        if(b <= l || r <= a) return id;
        eval(k, l, r);
        if(a <= l && r <= b) return data[k];
        T ll = query(a, b, k*2+1, l, (l+r)/2);
        T rr = query(a, b, k*2+2, (l+r)/2, r);
        return op(ll,rr);
    }

    T operator[](int i){
        return data[i+n-1];
    }
};

int main(){
    int n, q; cin >> n >> q;
    abstract_lazy_segtree<lint, lint> st(n, 0, 0,
        [](lint l, lint r){ return l+r; },
        [](lint d, lint x){ return d+x; },
        [](lint x, lint y){ return x/2+y; },
        [](lint x, int l){ return x*l; });

    rep(i,q){
        lint c,s,t,x; cin>>c>>s>>t;
        if(c==0){
            cin>>x; st.update(s-1, t, x);
        }
        else{
            out(st.query(s-1, t));
        }
    }
}


/*
    dp[i] = (i文字目までを考えて、i文字目を'1'としたときのスコアの最大値)
    dp[i] = max(0, max(dp[j], j<i)) + {i文字目を1にしたことで得られるスコアの和}
    区間の終点がiになるような[l,r]に対して, aを加算すればよい
*/

#include <iostream>
#include <vector>
#include <climits>
#include <functional>

template<typename T>
struct segment_tree {
    long long N; // 木の頂点数
    long long M; // 葉の数
    std::vector<T> V; // セグメント木　1-indexed
	std::vector<T> W; // 遅延配列　1-indexed
	std::vector<bool> flag; // true : W[i] の子孫に更新していない遅延配列が存在
    std::function<T(T, T)> op1; // 二項演算
	std::function<T(T, T, T)> op2; // 遅延伝播用の二項演算
	std::function<T(T, T)> op3; // 遅延配列更新用の二項演算
    T id1; // 単位元
	T id2; // 遅延伝播用の単位元

    // ===============================================================

    segment_tree(
		std::vector<T>& a,
		std::function<T(T, T)> f,
		std::function<T(T, T, T)> g,
		std::function<T(T, T)> h,
		T t1, T t2
	) : op1(f), op2(g), op3(h), id1(t1), id2(t2) {
        M = 1;
        while (M < a.size()) M *= 2;
        N = 2 * M;
        V.resize(N, id1); W.resize(N, id2); flag.resize(N, false);
        for (long long i = 0; i < a.size(); i++) V[M + i] = a[i];
        for (long long i = M - 1; i > 0; i--) {
            V[i] = op1(V[2 * i], V[2 * i + 1]);
        }
    }

    segment_tree() {}

    // ===============================================================

    void init(
		std::vector<T>& a,
		std::function<T(T, T)> f,
		std::function<T(T, T, T)> g,
		std::function<T(T, T)> h,
		T t1, T t2
	) {
        op1 = f; op2 = g; op3 = h; id1 = t1; id2 = t2;
		M = 1;
        while (M < a.size()) M *= 2;
        N = 2 * M;
        V.resize(N, id1); W.resize(N, id2); flag.resize(N, false);
        for (long long i = 0; i < a.size(); i++) V[M + i] = a[i];
        for (long long i = M - 1; i > 0; i--) {
            V[i] = op1(V[2 * i], V[2 * i + 1]);
        }
    }

	void laze_eval(long long cur_node, long long width) {
		if (W[cur_node] != id2) {
			V[cur_node] = op2(V[cur_node], W[cur_node], width);
			if (width > 1) {
				W[cur_node * 2] = op3(W[cur_node * 2], W[cur_node]);
				W[cur_node * 2 + 1] = op3(W[cur_node * 2 + 1], W[cur_node]);
			}
			W[cur_node] = id2;
		}
	}

	void range_update(
		long long l, long long r, T x,
		long long cur_node = 1,
		long long cur_left = 0, long long cur_right = -1
	) {
		if (cur_right == -1) cur_right = M;
		long long width = cur_right - cur_left;
		if (cur_right <= l || r <= cur_left) return;
		if (l <= cur_left && cur_right <= r) {
			W[cur_node] = op3(W[cur_node], x);
		}
		else {
			laze_eval(cur_node, width);
			flag[cur_node] = true;
			long long mid = (cur_left + cur_right) / 2;
			range_update(l, r, x, cur_node * 2, cur_left, mid);
			range_update(l, r, x, cur_node * 2 + 1, mid, cur_right);
			V[cur_node] = op1(V[cur_node * 2], V[cur_node * 2 + 1]);
		}
	}

	T range_fold(
		long long l, long long r,
		long long cur_node = 1,
		long long cur_left = 0, long long cur_right = -1
	) {
		if (cur_right == -1) cur_right = M;
		long long width = cur_right - cur_left;
		if (cur_right <= l || r <= cur_left) return id1;
		laze_eval(cur_node, width);
		if (width == 1) {
			flag[cur_node] = false;
			return V[cur_node];
		}
		long long mid = (cur_left + cur_right) / 2;
		if (l <= cur_left && cur_right <= r && !flag[cur_node]) {
			return V[cur_node];
		}
		else if (l <= cur_left && cur_right <= r) {
			flag[cur_node] = false;
			range_fold(cur_left, mid);
			range_fold(mid, cur_right);
			return V[cur_node] = op1(V[cur_node * 2], V[cur_node * 2 + 1]);
		}
		return op1(
			range_fold(l, r, cur_node * 2, cur_left, mid),
			range_fold(l, r, cur_node * 2 + 1, mid, cur_right)
		);
	}
};

int main() {
	long long n, q;
	std::cin >> n >> q;
	std::vector<long long> a(n, 0);

	auto f = [] (long long x, long long y) {return x + y;};
	auto g = [] (long long x, long long y, long long z) {return x + y * z;};
	auto h = [] (long long x, long long y) {return x + y;};
	segment_tree<long long> sg(a, f, g, h, 0, 0);

	while (q--) {
		long long z, s, t;
		std::cin >> z >> s >> t;
		if (z == 0) {
			long long x;
			std::cin >> x;
			sg.range_update(s - 1, t, x);
		}
		else std::cout << sg.range_fold(s - 1, t) << '\n';
	}
}

