}

int main() {
  // DSL_2_G

  int n, q;
  cin >> n >> q;
  using L = int64_t;
  const L el = 0;
  SegmentTree<M, L> seg(
      n, M(0, 0), el, [&](M a, M b) -> M { return M(a.x + b.x, a.l + b.l); },
      [&](L f, L g) -> L { return f + g; },
      [&](L f, M a) -> M { return f == el ? a : M(a.x + f * a.l, a.l); });
  rep(i, n) { seg.set(i, M(0, 1)); }
  while (q--) {
