template<class T>
class segtree{
private:
	vector<T> dat;
	vector<T> lazy;
	int _size;  //the number of leaves
	T _init;

public:
	segtree(int __size=0 , T init=numeric_limits<T>::max() ):_size(__size), _init(init), dat(4*__size,init), lazy(4*__size,init){
		if(__size==0)return ;
		int x=1;
		while(x<_size)x*=2;
		_size = x;
	}


	void update(int s,int t, T x ,int num=1,int a=0,int b=-1){
		if(b==-1)b=_size-1; //I couldn't "int b=_size".
		if(b<s||t<a)return ;
		if(s<=a&&b<=t){
			lazy[num]+=x;	//addition

			//dat[num] += x;					//minimum	isn't verified
			//dat[num] += x;					//maximum
			dat[num]+=x*(b-a+1);	//sum
			return ;
		}
		update(s,t,x,num*2+0,a,(a+b)/2);
		update(s,t,x,num*2+1,(a+b)/2+1,b);
		//dat[num] = lazy[num]+min(dat[num*2],dat[num*2+1]);	//minimum	isn't verified
		//dat[num] = lazy[num]+max(dat[num*2],dat[num*2+1]);	//maximum
		dat[num] = dat[num*2]+dat[num*2+1]+lazy[num]*(b-a+1);	//sum
	}


	// call find(s,t)
	T find(int s,int t,int num=1,int a=0,int b=-1){
		if(b==-1)b=_size-1; //I couldn't "int b=_size".
		if(b<s||t<a)return _init;
		if(s<=a&&b<=t)return dat[num];
		T l = find(s,t,num*2,a,(a+b)/2);
		T r = find(s,t,num*2+1,(a+b)/2+1,b);
		//return lazy[num]+min(l,r);					//minimum	isn't verified
		//return lazy[num]+max(l,r);					//maximum
		return l+r+lazy[num]*(min(b,t)-max(a,s)+1);	//sum
	}

	int size(){return _size;}
};


