struct LintSumLazySegmentTree {
private:
    int n;
    vec<lint> node, lazy;

public:
    LintSumLazySegmentTree(vec<lint> v){
        int size = (int)v.size();
        n = 1;
        while (n < size) n *= 2;
        node.resize(2 * n - 1);
        lazy.resize(2 * n - 1, 0);

        for (int i = 0; i < size; i++) {
            node.at(i + n - 1) = v.at(i);
        }
        for (int i = n - 2; i >= 0; i--) {
            node.at(i) = node.at(2 * i + 1) + node.at(2 * i + 2);
        }
    }

    void eval(int idx, int cur_left, int cur_right) {
        if (lazy.at(idx) != 0) {
            node.at(idx) += lazy.at(idx);

            if (cur_right - cur_left > 1) {
                lazy.at(2 * idx + 1) += lazy.at(idx) / 2;
                lazy.at(2 * idx + 2) += lazy.at(idx) / 2;
            }
            lazy.at(idx)= 0;
        }
    }

    void update(int query_left, int query_right, lint val, int cur_idx=0, int cur_left=0, int cur_right=-1) {
        if (cur_right < 0) cur_right = n;

        eval(cur_idx, cur_left, cur_right);

        if (query_right <= cur_left || cur_right <= query_left) return;

        if (query_left <= cur_left && cur_right <= query_right) {
            lazy.at(cur_idx) += (cur_right - cur_left) * val;
            eval(cur_idx, cur_left, cur_right);
        } else {
            update(query_left, query_right, val, 2 * cur_idx + 1, cur_left, (cur_left + cur_right) / 2);
            update(query_left, query_right, val, 2 * cur_idx + 2, (cur_left + cur_right) / 2, cur_right);
            node.at(cur_idx) = node.at(2 * cur_idx + 1) + node.at(2 * cur_idx + 2);
        }
    }

    lint query(int query_left, int query_right, int cur_idx=0, int cur_left=0, int cur_right=-1) {
        if (cur_right < 0) cur_right = n;
        if (query_right <= cur_left || cur_right <= query_left) return 0;

        eval(cur_idx, cur_left, cur_right);

        if (query_left <= cur_left && cur_right <= query_right) return node.at(cur_idx);
        lint val_from_left = query(query_left, query_right, 2 * cur_idx + 1, cur_left, (cur_left + cur_right) / 2);
        lint val_from_right = query(query_left, query_right, 2 * cur_idx + 2, (cur_left + cur_right) / 2, cur_right);
        return val_from_left + val_from_right;
    }
};

int main() {
    cin.tie(0); cout.tie(0);
    ios::sync_with_stdio(false);

    int n, q;
    cin >> n >> q;

    LintSumLazySegmentTree segtree(vec<lint>(n, 0));
    for (int i = 0; i < q; i++) {
        int query;
        cin >> query;
        if (query == 0) {
            int s, t, x;
            cin >> s >> t >> x;
            segtree.update(s - 1, t, x);
        }
        else {
            int s, t;
            cin >> s >> t;
            cout << segtree.query(s - 1, t) << "\n";
        }
    }
}

