template <class T>
struct fenwick_tree {
	vector<T> x,lazy;
	fenwick_tree(int n) : x(n + 1, 0), lazy(n + 1, 0) { }
	T sum(int r) {
		T S = 0;

		for (int k = r; k > 0; k -= k&-k) {
			S += x[k] + lazy[k]*(k&-k);
			for (int cp = k + (k&-k); cp < x.size() && k - (k&-k) == cp - (cp&-cp); cp += cp&-cp)
				S += lazy[cp] * (r - (k - (k&-k)));
		}
		return S;
	}
	void add(int r, T a) {
		for (int k=r; k > 0; k -= k&-k) {
			lazy[k] += a;
			for (int cp = k + (k&-k); cp < x.size() && k-(k&-k) == cp-(cp&-cp); cp += cp&-cp)
				x[cp] += a * (r-(k - (k&-k)));
		}
	}
};


