template<class T,class E>struct SegmentTree {

    using F = function<T(T, T)>;
    using G = function<T(T, E, signed)>;
    using H = function<E(E, E)>;
    signed n, height;
    F fvv;//(v, v)
    G fvl;//(v, l, len)
    H fll;//(l, l)
    T ve; //演算における単位元
    E le; //作用素に対しての単位元
    vector<T> dat;
    vector<E> laz;
    vi len;
    SegmentTree(F fvv, G g, H h, T ti, E ei) : fvv(fvv), fvl(g), fll(h), ve(ti), le(ei) {}

    void init(signed n_) {
        n = 1;
        height = 0;
        while (n < n_) n <<= 1, height++;
        dat.assign(n << 1, ve);
        laz.assign(n << 1, le);
        len.assign(n << 1, 0);
        signed l = 1, v = n;
        rep(i, 1, n << 1) {
            if ((l << 1) == i) {
                l <<= 1;
                v >>= 1;
            }
            len[i] = v;
        }
    }
    void build(const vector<T> &v) {
        signed n_ = v.size();
        init(n_);
        for (signed i = 0; i < n_; i++) dat[n + i] = v[i];
        for (signed i = n - 1; i; i--)
            dat[i] = fvv(dat[(i << 1) | 0], dat[(i << 1) | 1]);
    }
    //おそらく1-indexed
    inline T reflect(signed k) {
        return laz[k] == le ? dat[k] : fvl(dat[k], laz[k], len[k]);
    }
    inline void eval(signed k) {
        if (laz[k] == le) return;
        laz[(k << 1) | 0] = fll(laz[(k << 1) | 0], laz[k]);
        laz[(k << 1) | 1] = fll(laz[(k << 1) | 1], laz[k]);
        dat[k] = reflect(k);
        laz[k] = le;
    }
    inline void thrust(signed k) {
        for (signed i = height; i; i--) eval(k >> i);
    }
    inline void recalc(signed k) {
        while (k >>= 1)dat[k] = fvv(reflect((k << 1) | 0), reflect((k << 1) | 1));
    }
    void update(signed a, signed b, E x) {
        thrust(a += n);
        thrust(b += n - 1);
        for (signed l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) laz[l] = fll(laz[l], x), l++;
            if (r & 1) --r, laz[r] = fll(laz[r], x);
        }
        recalc(a);
        recalc(b);
    }
    void set_val(signed a, T x) {
        thrust(a += n);
        dat[a] = x;
        laz[a] = le;
        recalc(a);
    }
    T query(signed a, signed b) {
        thrust(a += n);
        thrust(b += n - 1);
        T vl = ve, vr = ve;
        for (signed l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) vl = fvv(vl, reflect(l++));
            if (r & 1) vr = fvv(reflect(--r), vr);
        }
        return fvv(vl, vr);
    }
    void debu() {
        rep(i, n) {
            cout << query(i, i + 1) << " ";
        }
        cout << "" << endl;
    }
};


