  int n, q;
  cin >> n >> q;
  node *root = build(0, n - 1);
  while (q--) {
    int c;
    int s, t, x;
    cin >> c >> s >> t;
    if (c == 0) {
      int x;
      cin >> x;
      update(root, s - 1, t - 1, x);
    } else {
      cout << query(root, s - 1, t - 1) << '\n';
    }   
  }
  return 0;
}

