template <typename T> class LazySegmentTree {
private:

    int n;
    vector < int > node, lazy;

    void  lazy_eval (int l, int r, int k) {
        node[k] += lazy[k];
        if (r - l > 1) {
            lazy[2 * k + 1] += lazy[k] >> 1;
            lazy[2 * k + 2] += lazy[k] >> 1;
        }
        lazy[k] = 0;
    }

    void _add (int a, int b, T val, int k, int l, int r) {
        lazy_eval(l, r, k);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            lazy[k] += (r - l) * val;
            lazy_eval(l, r, k);
        } else {
            _add (a, b, val, 2 * k + 1, l, (l + r) / 2);
            _add (a, b, val, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }

    T _get_sum (int a, int b, int k, int l, int r) {
        lazy_eval (l, r, k);
        if (b <= l || r <= a) return 0;
        if (a <= l && r <= b) return node[k];
        T vl = _get_sum (a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = _get_sum (a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;
    }

public:

    LazySegmentTree (int _n) : n(1) {
        while (n < _n) n <<= 1;
        node.resize (2 * n, 0);
        lazy.resize (2 * n, 0);
    }

    void add (int l, int r, T val) {
        _add (l, r, val, 0, 0, n);
    }

    T get_sum (int l, int r) {
        return _get_sum (l, r, 0, 0, n);
    }

};

int main() {

    int n,q; cin >> n >> q;

    LazySegmentTree < ll > inst(100010);

    REP(i,q) {
        int a,l,r;
        cin >> a >> l >> r;
        if (a == 0) {
            ll x; cin >> x;
            inst.add(l, r + 1, x);
        } else {
            cout << inst.get_sum(l, r + 1) << endl;
        }
    }

    return 0;
}

