	lseg.init(n+2, 0);

	for(int i = 0; i < q; i++){
		int com, s, t, x;
		cin>>com>>s>>t;

		if(com){
			cout<<lseg.query(s,t+1)<<endl;
		} else {
			cin>>x;
			lseg.update(s, t+1, x);
		}
	}

	return 0;
}

