const int segsize = 19;

ll SegTree[1<<segsize],Lazy[1<<segsize];
bool Flag[1<<segsize];
void denpa(int k,int l,int r)
{
	if(Flag[k])
	{
		SegTree[k]+=Lazy[k];
		//if(Lazy[k]!=INT_MAX)
		if(r-l>1)
		{
			Lazy[2*k] += Lazy[k]/2;
			Lazy[2*k+1] += Lazy[k]/2;
			Flag[k*2] = Flag[k*2+1]=true;
		}
		Lazy[k]=0;
		Flag[k] = false;

	}
}

void update(int a,int b,ll x,int k=1,int l=0,int r =-1)
{
	if(r<0)r=(1<<(segsize-1));
	//cout<<a<<' '<<b<<' '<<x<<' '<<k<<' '<<l<<' '<<r<<endl;
	denpa(k,l,r);
	if(b<=l||r<=a)return;
	if(a<=l&&r<=b)
	{
		Lazy[k] = (1LL)*(r-l)*x;
		Flag[k] = true;
		denpa(k,l,r);
	}
	else
	{
		update(a,b,x,k*2,l,(l+r)/2);
		update(a,b,x,k*2+1,(l+r)/2,r);
		SegTree[k] =SegTree[k*2]+SegTree[k*2+1];
	}
}

ll getsum(int a,int b,int k=1,int l=0,int r=-1)
{
	if(r<0)r = 1<<(segsize-1);
	denpa(k,l,r);
	if(b<=l||r<=a)return 0;
	if(a<=l&&r<=b)return SegTree[k];
	ll vl = getsum(a,b,k*2,l,(l+r)/2);
	ll vr = getsum(a,b,2*k+1,(l+r)/2,r);
	return vl+vr;
}

