//1-indexed!!!!!!
//区間に対する更新と区間に対する和を求めることが出来ます
//ある区間[l,r]にwを加えたいとき、add(l,r,w)としてください
//ある区間[0,r]の和を求めたいとき、sum(r)としてください(prefixです)
//ある区間[l,r]の和(v[l]+...+v[r])を求めたい時、sum(r)-sum(l-1)としてください
class RAQ_RSQ{
public:
    explicit RAQ_RSQ(int n):size(n+1){//意図的にbitのsizeは1多くしてあります(書き換えないでください)
        tbl1.resize(static_cast<unsigned long>(size + 10), 0);
        tbl2.resize(static_cast<unsigned long>(size + 10), 0);
    }
    void add(int l,int r,ll w){//v[l]...v[r]にwを加える , 1-indexed!!!
        add(l,-w*l,tbl1);
        add(r+1,w*(r+1),tbl1);
        add(l,w,tbl2);
        add(r+1,-w,tbl2);
    }
    ll sum(int r){//v[1]+...+v[r]を求めます , 1-indexed!!!
        ll res=0;
        res+=sum(r+1,tbl1);
        res+=sum(r+1,tbl2)*(r+1);
        return res;
    }
private:
    vector<ll> tbl1,tbl2;
    int size;
    void add(int a,ll w,vector<ll> &v){
        for(int i=a;i<=size;i+=i&-i)v[i]+=w;
    }
    ll sum(int a,vector<ll> &v){
        ll res=0;
        for(int i=a;i>0;i-=i&-i)res+=v[i];
        return res;
    }
};
