struct segtree {
    vector<int> dat, lazy;
    int n;
    segtree(int n, int init) {
        this->n = 1;
        while (this->n < n) this->n *= 2;
        dat.resize(this->n*2, init);
        lazy.resize(this->n*2, -1);
    }

    void add(int l, int r, int x) {
        add(l, r, x, 1, 0, n);
    }

    void add(int ql, int qr, int x, int s, int sl, int sr) {
        // dump(ql, qr, x, s, sl, sr);
        apply(s, sl, sr);
        if (ql <= sl && sr <= qr) {
            if (lazy[s] == -1) lazy[s] = 0;
            lazy[s] += x;
        } else if (sr <= ql || qr <= sl) {
            return;
        } else {
            int sm = (sl + sr) / 2;
            add(ql, qr, x, s*2    , sl, sm);
            add(ql, qr, x, s*2 + 1, sm, sr);
        }
        update(s, sl, sr);
    }

    int sum(int l, int r) {
        return sum(l, r, 1, 0, n);
    }

    int sum(int ql, int qr, int s, int sl, int sr) {
        apply(s, sl, sr);
        // dump(ql, qr, s, sl, sr);
        if (ql <= sl && sr <= qr) {
            return dat[s];
        } else if (sr <= ql || qr <= sl) {
            return 0;
        } else {
            int sm = (sl + sr) / 2;
            return sum(ql, qr, s*2, sl, sm) + sum(ql, qr, s*2 + 1, sm, sr);
        }
    }

    void apply(int s, int sl, int sr) {
        if (lazy[s] != -1) {
            dat[s] += lazy[s] * (sr - sl);
            if (s*2 + 1 < (int)dat.size()) {
                if (lazy[s*2] == -1) lazy[s*2] = 0;
                lazy[s*2] += lazy[s];
                if (lazy[s*2 + 1] == -1) lazy[s*2 + 1] = 0;
                lazy[s*2+1] += lazy[s];
            }
            lazy[s] = -1;
        }
    }

    void update(int s, int sl, int sr) {
        if (s*2 + 1 < (int)dat.size()) {
            if (lazy[s*2+0] != -1) dat[s] += lazy[s*2+0] * ((sr - sl) / 2);
            if (lazy[s*2+1] != -1) dat[s] += lazy[s*2+1] * ((sr - sl) / 2);
        }
    }

    void show() {
        cout << "dat" << endl;
        FOR(i, 1, n*2) {
            cout << dat[i] << ' ';
            if (__builtin_popcount(i + 1) == 1) cout << endl;
        }
        cout << "lazy" << endl;
        FOR(i, 1, n*2) {
            cout << lazy[i] << ' ';
            if (__builtin_popcount(i + 1) == 1) cout << endl;
        }
        cout << "==" << endl;
    }
};

