struct LzSegT{
  int sz;
  vector<int>v;
  vector<int>lz;
  LzSegT(int n){
    sz=1;while(sz<n)sz*=2;
    v.resize(2*sz-1,0);
    lz.resize(2*sz-1,0);
  }
  void eval(int k,int l,int r){
    if(lz[k]!=0){
      v[k]+=lz[k];
      if(2*k+1<2*sz-1){
        lz[2*k+1]+=lz[k]/2;
        lz[2*k+2]+=lz[k]/2;
      }
      lz[k]=0;
    }
  }
  void add(int a,int b,int x){
    add_(a,b,x,0,0,sz);
  }
  void add_(int a,int b,int x,int k,int l,int r){
    eval(k,l,r);
    if(b<=l||r<=a)return;
    if(a<=l&&r<=b){
      lz[k]+=x*(r-l);
      eval(k,l,r);
    }
    else{
      add_(a,b,x,2*k+1,l,(l+r)/2);
      add_(a,b,x,2*k+2,(l+r)/2,r);
      v[k]=v[2*k+1]+v[2*k+2];
    }
  }
  int sum(int a,int b){
    return sum_(a,b,0,0,sz);
  }
  int sum_(int a,int b,int k,int l,int r){
    eval(k,l,r);
    if(b<=l||r<=a)return 0;
    if(a<=l&&r<=b)return v[k];
    int vl=sum_(a,b,2*k+1,l,(l+r)/2);
    int vr=sum_(a,b,2*k+2,(l+r)/2,r);
    return vl+vr;
  }
};

