//(T,f,e). ex.(lint,+,0) -> Segtree t(/*初期vector*/,[](lint a,lint b){return a+b},0);
class Segtree{
public:
	using T=lint;
	using func=function<T(T,T)>;

	int n,sz;
	vector<T> node,lazy;
	bool lazyFlag[MAXN];

	//inline lint f(lint x,lint y){ return x|y; }
	func f;
	T e;

	enum lazytype{
		lt_add,
		lt_update,

		lt_end
	};

	Segtree(vector<T> v,func f,T e):f(f),e(e){
		sz=v.size();n=1;
		while(n<sz)n<<=1;
		node.resize(2*n,e);lazy.resize(2*n,0);
		rep(i,sz)node[n+i]=v[i];
		for(int i=n-1;i>0;--i)node[i]=f(node[2*i],node[2*i+1]);
	}
	void eval(lazytype t,int k,int l,int r){
		switch(t){
			case lt_add:{
				if(!lazy[k])return;
				node[k]+=lazy[k];
				if(r-l>1){
					lazy[2*k]+=lazy[k]/2;
					lazy[2*k+1]+=lazy[k]/2;
				}
				lazy[k]=0;
				break;
			}
			case lt_update:{
				if(!lazyFlag[k])break;
				node[k]=lazy[k];
				if(r-l>1){
					lazy[2*k]=lazy[2*k+1]=lazy[k];
					lazyFlag[2*k]=lazyFlag[2*k+1]=1;
				}
				lazyFlag[k]=0;
				break;
			}
			default:break;
		}
	}
	void update(int i,T x){
		node[i+=n]=x;
		while(i>>=1)node[i]=f(node[2*i],node[2*i+1]);
	}
	void update(int a,int b,T x,int k=1,int l=0,int r=-1){
		if(r<0)r=n;
		eval(lt_update,k,l,r);
		if(b<=l||r<=a)return;
		if(a<=l&&r<=b){
			lazy[k]=x;
			lazyFlag[k]=1;
			eval(lt_update,k,l,r);
		}else{
			update(a,b,x,2*k,l,(l+r)/2);
			update(a,b,x,2*k+1,(l+r)/2,r);
			node[k] = min(node[2*k],node[2*k+1]);
		}
	}
	void add(int a,int b,T x,int k=1,int l=0,int r=-1){
		if(r<0)r=n;
		eval(lt_add,k,l,r);
		if(b<=l||r<=a)return;
		if(a<=l&&r<=b)lazy[k]+=(r-l)*x,eval(lt_add,k,l,r);
		else{
			add(a,b,x,2*k,l,(l+r)/2);
			add(a,b,x,2*k+1,(l+r)/2,r);
			node[k]=f(node[2*k],node[2*k+1]);
		}
	}
	lint query(int a,int b,lazytype t=lt_add,int k=1,int l=0,int r=-1){
		if(r<0)r=n;
		if(r<=a||b<=l)return e;
		eval(t,k,l,r);
		if(a<=l&&r<=b)return node[k];
		return f(query(a,b,t,2*k,l,(l+r)/2),query(a,b,t,2*k+1,(l+r)/2,r));
	}
};

int main(){
	lint n,q,com,s,t,x;in(n,q);
	vector<lint> a(n);
	Segtree tree(a,[](lint a,lint b){return a+b;},0);
	rep(q){
		in(com,s,t);--s;//0-indexed,half-closed
		if(com)o(tree.query(s,t));
		else in(x),tree.add(s,t,x);
	}
}

