int ope(int a,int b)
{
	return a + b;
}

int l_ope(int node,int lazy)
{
	return node + lazy;
}

int l_throw(int lazy)
{
	return lazy / 2;
}

int l_add(int l,int r,int x)
{
	return (r - l) * x;
}

struct LazySegment
{
	vector<int> node;
	vector<int> lazy;
	int n;


	int init = 0;

	LazySegment(const vector<int>& vec)
	{
		int sz = vec.size();

		n = 1;
		while(n < sz) n <<= 1;

		node.resize(2 * n - 1,init);
		lazy.resize(2 * n - 1,0);

		for(int i = 0;i < sz;i++)
		{
			node[n - 1 + i] = vec[i];
		}

		for(int i = n - 2;i >= 0;i--)
		{
			node[i] = ope(node[i * 2 + 1] , node[i * 2 + 2]);
		}
	}

	void eval(int k,int l,int r)
	{
		if(lazy[k] != 0)
		{
			node[k] = l_ope(node[k],lazy[k]);

			if(r - l > 1)
			{
				lazy[2 * k + 1] += l_throw(lazy[k]);
				lazy[2 * k + 2] += l_throw(lazy[k]);
			}

			lazy[k] = 0;
		}
	}

	void add_inter(int a,int b,int x,int k = 0,int l = 0,int r = -1)
	{
		if(r < 0) r = n;

		eval(k,l,r);

		if(b <= l || r <= a) return ;

		if(a <= l && r <= b)
		{
			lazy[k] += l_add(l,r,x);
			eval(k,l,r);
		}

		else
		{
			add_inter(a,b,x,2 * k + 1,l,(l + r) / 2);
			add_inter(a,b,x,2 * k + 2,(l + r) / 2,r);
			node[k] = ope(node[2 * k + 1], node[2 * k + 2]);
		}
	}

	int get_inter(int a,int b,int k = 0,int l = 0,int r = -1)
	{
		if(r < 0) r = n;

		eval(k,l,r);
		if(b <= l || r <= a) return init;

		if(a <= l && r <= b) return node[k];

		int lv = get_inter(a,b,k * 2 + 1,l , (l + r) / 2);
		int rv = get_inter(a,b,k * 2 + 2,(l + r) / 2 , r);

		return ope(lv , rv);
	}
};

signed main()
{
	int n;
	int q;
	cin >> n >> q;
	LazySegment seg(vector<int>(n,0));

	for(int i = 0;i < q;i++)
	{
		int t;
		cin >> t;
		if(t == 0)
		{
			int a,b,x;
			cin >> a >> b >> x;
			a--;
			b--;
			seg.add_inter(a,b + 1,x);
		}
		else
		{
			int a,b;
			cin >> a >> b;
			a--;
			b--;

			cout << seg.get_inter(a,b + 1) << endl;
		}
	}

	return 0;
}

