		while(n < size) n *= 2;
		dat.resize(2 * n - 1, 0);
		dat2.resize(2 * n - 1, 0);
	}
	void add(int l, int r, ll x){
		rangeAdd(l, r + 1, x, 0, 0, n);
	}
	void rangeAdd(int a, int b, ll x, int k, int l, int r){
		if(a <= l && r <= b){
			dat[k] += x;
		}else if(l < b && a < r){
			dat2[k] += (min(b, r) - max(a, l)) * x;
			rangeAdd(a, b, x, 2 * k + 1, l, (l + r) / 2);
			rangeAdd(a, b, x, 2 * k + 2, (l + r) / 2, r);
		}
	}
	ll getSum(int s, int t){
		return query(s, t + 1, 0, 0, n);
	}
	ll query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l) return 0;
		if(a <= l && r <= b) return dat[k] * (r - l) + dat2[k];
		else{
			ll ret = (min(b, r) - max(a, l)) * dat[k];
			ll vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
			ll vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
			return ret + vl + vr;
		}
	}
};

int main(){
