template<class T>
class lazySegmentTree{
private:
    vector<T> dat;
    vector<T> lazy;
    int _size;  //the number of leaves
    T _init;

public:
    lazySegmentTree( vector<T> vec, T init = numeric_limits<T>::max() ): _init(init){
        int size = vec.size();
        if(size==0)return ;

        _size = 1;
        while(_size<size)_size*=2;
        dat.resize(_size*2);
        rep(i,vec.size())dat[i+_size] = vec[i];
        lazy.resize(_size*2,_init);
    }


    void eval(int num, int l, int r){
        if(lazy[num]==0) return ;
        dat[num] += lazy[num];


        if(r-l>1){  //?????§?????????
            lazy[num*2] += lazy[num]/2;
            lazy[num*2+1] += lazy[num]/2;
        }
        lazy[num] = 0;
    }



    T update(int s, int t, T x, int num=1, int l=0, int r=-1){
        if(r==-1)r =_size;

        eval(num,l,r);

        if(r<=s || t<=l) return dat[num];   //????±??????????
        if(s<=l && r<=t){
            lazy[num] += x * (r-l);
            eval(num,l,r);
        }
        else{
            int res1 = update(s, t, x, num*2, l, (l+r)/2);
            int res2 = update(s, t, x, num*2+1, (l+r)/2, r);
            dat[num] = res1+res2;
        }
        return dat[num];
    }


    T find(int s, int t, int num=1, int l=0, int r=-1){
        if(r==-1)r = _size;

        eval(num,l,r);


        if(r<=s || t<=l) return _init;  //????±??????????
        if(s<=l && r<=t) return dat[num];
        else{
            return find(s, t, num*2, l, (l+r)/2) + find(s, t, num*2+1, (l+r)/2, r);
        }
    }

    int size(){ return _size; }
};

