class Segtree{

	private:
	int V;
	typedef struct st{
		ll a,len;
	}st;
	st st0=(st){(ll)0,1};
	typedef struct op{
		ll a;
	}op;
	op op0=(op){0};
	st f(st p,st q){
		return (st){p.a+q.a,p.len+q.len};
	}
	void g(st &p,op q){
		p.a+=q.a*p.len;
	}
	void h(op &p,op q){
		p.a+=q.a;
	}

	st *dat;
	op *laz;

	st propagate(ll k){
		if(k<V){
			h(laz[k*2],laz[k]);
			h(laz[k*2+1],laz[k]);
		}
		g(dat[k],laz[k]);
		laz[k]=op0;
		return dat[k];
	}
	void upd(ll l,ll r,op p){
		l+=V,r+=V+1;
		for(ll d=20;d>=0;d--){
			propagate(l>>d);
			propagate(r>>d);
		}
		for(ll a=l,b=r;a<b;a>>=1,b>>=1){
			if(a&1){h(laz[a],p);a++;}
			if(b&1){b--;h(laz[b],p);}
		}
		for(ll a=l,b=r;a+b;a>>=1,b>>=1){
			dat[a/2]=f(propagate(a/2*2),propagate(a/2*2+1));
			dat[b/2]=f(propagate(b/2*2),propagate(b/2*2+1));
		}
	}
	st qry(ll l,ll r){
		l+=V,r+=V+1;
		for(ll d=20;d>=0;d--){
			propagate(l>>d);
			propagate(r>>d);
		}
		st L=st0,R=st0;
		for(ll a=l,b=r;a<b;a>>=1,b>>=1){
			if(a&1){L=f(L,propagate(a));a++;}
			if(b&1){b--;R=f(propagate(b),R);}
		}
		st res=f(L,R);
		return res;
	}

	public:
	void init(int ns){
		V=1;
		while(V<=ns)V*=2;
		dat=new st[2*V];
		laz=new op[2*V];
		for(int i=0;i<2*V;i++){
			dat[i]=st0;
			laz[i]=op0;
		}

		ll *len=new ll[2*V];
		for(int i=2*V-1;i>=0;i--){
			if(V<=i)len[i]=1;
			else len[i]=len[i*2]*2;
			dat[i]=(st){0,len[i]};
			laz[i]=op0;
		}
	}
	void update(ll l,ll r,ll a){
		upd(l,r,(op){a});
	}
	ll query(ll l,ll r){
		st res=qry(l,r);
		return res.a;
	}
};
Segtree seg;

int main(){
	int n,q;
	cin>>n>>q;
	seg.init(n+1);
	rep(i,n)seg.update(i,i,0);
	while(q--){
		ll p,s,t,x;
		cin>>p;
		if(p==0){
			cin>>s>>t>>x;
			seg.update(s,t,x);
		}
		if(p==1){
			cin>>s>>t;
			cout<<seg.query(s,t)<<"\n";
		}
	}
}

