using namespace std;


struct Node {
	Node *left;
	Node *right;
	int l;
	int r;
	int value;
	int addition;

	Node (int l, int r, int value) {
		this->left = nullptr;
		this->right = nullptr;
		this->l = l;
		this->r = r;
		this->value = value;
		this->addition = 0;
	}
};


class SegmentTree {
	private:
		Node *root;

		int build (vector<int> &array, Node *node = nullptr) {
			if (node->l == node->r) {
				node->left = nullptr;
				node->right = nullptr;
				return node->value = array[node->l];
			}

			int size = node->r - node->l + 1;
			int middle = (size - 1) / 2;
			Node *left = new Node(node->l, node->l + middle, 0);
			Node *right = new Node(node->l + middle + 1, node->r, 0);
			node->left = left;
			node->right = right;

			return node->value = build(array, left) + build(array, right);
		}

		void push (Node *node) {
			if (node->left != nullptr)
				node->left->addition += node->addition;

			if (node->right != nullptr)
				node->right->addition += node->addition;

			node->value += node->addition * (node->r - node->l + 1);
			node->addition = 0;
		}

	public:
		SegmentTree (vector<int> &array) {
			root = new Node(0, array.size() - 1, 0);
			root->value = build(array, root);
		}

		int RSQ (int l, int r, Node *node = nullptr) {
			if (node == nullptr)
				node = root;

			push(node);

			// Текущий отрезок вложен в отрезок запроса.
			if (l <= node->l && node->r <= r)
				return node->value;

			// Текущий отрезок не пересекается с отрезком запроса.
			else if (node->r < l || r < node->l)
				return 0;

			// Иначе отрезки пересекаются, либо отрезок запроса вложен в текущий отрезок.
			return RSQ(l, r, node->left) + RSQ(l, r, node->right);
		}

		void RAQ (int l , int r, int delta, Node *node = nullptr) {
			if (node == nullptr)
				node = root;

			push(node);

			// Текущий отрезок вложен в отрезок запроса.
			if (l <= node->l && node->r <= r) {
				node->addition += delta;
				push(node);
				return;
			}

			// Текущий отрезок не пересекается с отрезком запроса.
			else if (node->r < l || r < node->l)
				return;

			// Иначе отрезки пересекаются, либо отрезок запроса вложен в текущий отрезок.
			RAQ(l, r, delta, node->left);
			RAQ(l, r, delta, node->right);
			node->value = node->left->value + node->right->value;
		}

		void print () const {
			queue<Node*> nodeQueue;
			nodeQueue.push(root);

			while (!nodeQueue.empty()) {
				Node *current = nodeQueue.front();
				nodeQueue.pop();

				cout << current->l << "-" << current->r << ", value = " << current->value << "(" << current->addition << "): ";
				cout << "left: ";

				if (current->left != nullptr) {
					cout << current->left->l << "-" << current->left->r;
					nodeQueue.push(current->left);
				}

				else
					cout << "nullptr";

				cout << "; right: ";

				if (current->right != nullptr) {
					cout << current->right->l << "-" << current->right->r;
					nodeQueue.push(current->right);
				}

				else
					cout << "nullptr";

				cout << endl;
			}
		}
};

