long long find_seg(long long now,long long now_l,long long now_r,long long want_l,long long want_r,long long bit){
	if(want_l <= now_l&&now_r <= want_r){
		if(bit == 0){
			return seg_tree[0][now] + seg_tree[1][now] * (now_r - now_l);
		}else{
			seg_tree[1][now] += bit;
			return 0;
		}
	}
	if(now_r <= want_l||want_r <= now_l) return 0;
	if(bit != 0){
		seg_tree[0][now] += bit * (min(want_r,now_r) - max(want_l,now_l));
	}
	seg_tree[1][now*2] += seg_tree[1][now];
	seg_tree[1][now*2+1] += seg_tree[1][now];
	seg_tree[0][now] += seg_tree[1][now] * (now_r - now_l);
	seg_tree[1][now] = 0;
	return find_seg(now*2,now_l,(now_l+now_r)/2,want_l,want_r,bit) + find_seg(now*2+1,(now_l+now_r)/2,now_r,want_l,want_r,bit);
}
