// Range Sum, Range Add
template<class T>
struct lazy_segment_tree{
  std::vector<T> data,lazy;
  T identity1,identity2;
  int n;
  lazy_segment_tree(){}
  lazy_segment_tree(int sz,T ide1,T ide2):identity1(ide1),identity2(ide2){
    n = 1;
    while(n<sz)n<<=1;
    data.resize(2*n-1,identity1);
    lazy.resize(2*n-1,identity2);
  }
  void eval(int k){
    if(lazy[k]==identity2)return;
    if(k<n-1){
      lazy[2*k+1] += lazy[k]/2;
      lazy[2*k+2] += lazy[k]/2;
    }
    data[k] += lazy[k];
    lazy[k] = identity2;
  }
  void add_impl(int a,int b,T x,int k,int l,int r){
    eval(k);
    if(a<=l&&r<=b){
      lazy[k] += x*(r-l);
      eval(k);
    }
    else if(a<r&&l<b){
      add_impl(a,b,x,2*k+1,l,(l+r)/2);
      add_impl(a,b,x,2*k+2,(l+r)/2,r);
      data[k] = data[2*k+1] + data[2*k+2];
    }
  }
  T query_impl(int a,int b,int k,int l,int r){
    eval(k);
    if(r<=a||b<=l){
      return identity1;
    }
    if(a<=l&&r<=b){
      return data[k];
    }
    else{
      T vl = query_impl(a,b,2*k+1,l,(l+r)/2);
      T vr = query_impl(a,b,2*k+2,(l+r)/2,r);
      return vl + vr;
    }
  }
  void add(int a,int b,T x){
    add_impl(a,b,x,0,0,n);
  }
  T query(int a,int b){
    return query_impl(a,b,0,0,n);
  }
  T operator[](int i){
    return query_impl(i,i+1,0,0,n);
  }
};
signed main(){
  int n,q;
  cin>>n>>q;
  lazy_segment_tree<int64_t> data(n,0,0);
  while(q--){
    int c;cin>>c;
    if(c==0){
      int64_t s,t,x;cin>>s>>t>>x;
      s--;t--;
      data.add(s,t+1,x);
    }else{
      int s,t;cin>>s>>t;
      s--;t--;
      cout<< data.query(s,t+1) <<endl;
    }
  }
}

