using namespace std;

template <typename T> class LazySegmentTree {
private:
    const int array_size;
    int n;
    std::vector<T> node, lazy;
    std::function<T (T,T)> op;
    T unit;

public:
    enum Mode {
        RangeMinimumQuery,
        RangeMaximumQuery,
        RangeSummationQuery,
    };

    LazySegmentTree(const std::vector<LL> &v, Mode mode) : array_size(v.size()) {
        if (mode == RangeMinimumQuery) {
            unit = INT_MAX;
            op = [](T a, T b) { return std::min(a, b); };
        }
        else if (mode == RangeMaximumQuery) {
            unit = -INT_MAX;
            op = [](T a, T b) { return std::max(a, b); };
        }
        else if (mode == RangeSummationQuery) {
            unit = 0;
            op = [](T a, T b) { return a + b; };
        }
        else {
            assert(false);
        }

        n = 1;
        while (n < array_size) { n *= 2; }
        node.resize(2 * n - 1, unit);
        lazy.resize(2 * n - 1, 0);

        for (int i = 0; i < array_size; ++i) {
            node[i + n - 1] = v[i];
        }
        for (int i = n - 2; i >= 0; i--) {
            node[i] = node[i * 2 + 1] + node[i * 2 + 2];
        }
    }

    // array[idx] += x
    void add(int idx, T x) {
        add(idx, idx + 1, x);
    }

    // array[left, right) += x
    void add(int left, int right, T x) {
        assert(0 <= left and left < right and right <= array_size);
        add(left, right, x, 0, 0, n);
    }

    // sum(array[a, b))
    T query(int left, int right) {
        return query(left, right, 0, 0, n);
    }

private:
    void add(int a, int b, LL x, int k, int l, int r) {
        eval(k, l, r);

        // 範囲外
        if (b <= l or r <= a) {
            return;
        }
        // 完全に含む
        else if (a <= l and r <= b) {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }
        // 一部含む
        else {
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);    // 左の子
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);    // 右の子
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }

    // [a, b)の目的値をノードk（区間[l, r]）から検索
    T query(int a, int b, int k, int l, int r) {
        eval(k, l, r);

        // 範囲外
        if (b <= l or r <= a) {
            return unit;
        }
        // 完全に含む
        else if (a <= l && r <= b) {
            return node[k];
        }
        // 一部含む
        else {
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return op(vl, vr);
        }
    }

    void eval(int k, int l, int r) {
        if (lazy[k] == 0) {
            return;
        }

        node[k] += lazy[k];
        if (r - l > 1) {
            lazy[2 * k + 1] += lazy[k] / 2;
            lazy[2 * k + 2] += lazy[k] / 2;
        }
        lazy[k] = 0;
    }
};

