const int DATA_NIL = 0;
const int LAZY_NIL = 0;

class SegmentTreeLazy {
private:
    const int n, h;
    vector<int> dat, lazy;

    void calc(int p, int k)
    {
        // if (lazy[p] == 0) dat[p] = dat[p<<1] + dat[p<<1|1];
        // else dat[p] = lazy[p] * k;
        dat[p] = dat[p<<1] + dat[p<<1|1] + lazy[p] * k;
    }

    void apply(int p, int value, int k)
    {
        dat[p] += value * k;
        if (p < n) lazy[p] += value;
    }

    void build(int l, int r)
    {
        int k = 2;
        for (l += n, r += n-1; l > 1; k <<= 1) {
            l >>= 1, r >>= 1;
            for (int i = r; i >= l; i--) calc(i, k);
        }
    }

    void push(int l, int r)
    {
        int s = h, k = 1 << (h - 1);
        for (l += n, r += n-1; s > 0; s--, k >>= 1) {
            for (int i = l>>s; i <= r>>s; i++) {
                if (lazy[i] != 0) {
                    apply(i<<1, lazy[i], k);
                    apply(i<<1|1, lazy[i], k);
                    lazy[i] = 0;
                }
            }
        }
    }

public:
    SegmentTreeLazy(int _n) : n(_n), h(__lg(n)), dat(2*n, DATA_NIL), lazy(2*n) {}

    void modify(int l, int r, int value)
    {
        push(l, l+1);
        push(r-1, r);

        int l0 = l, r0 = r, k = 1;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1, k <<= 1) {
            if (l&1) apply(l++, value, k);
            if (r&1) apply(r-1, value, k);
        }

        build(l0, l0 + 1);
        build(r0 - 1, r0);
    }

    int query(int l, int r)
    {
        push(l, l+1);
        push(r-1, r);

        int res = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l&1) res += dat[l++];
            if (r&1) res += dat[r-1];
        }

        return res;
    }

    void dump()
    {
        cerr << "-----------" << endl;
        int hh = __lg(2*n);
        for (int i=1; i<=hh; i++) {
            for (int j=0; j<1<<(i-1); j++) {
                int idx = (1<<(i-1)) + j;
                cerr << dat[idx] << " (" << lazy[idx] << ") ";
            }
            cerr << endl;
        }
        cerr << "-----------" << endl;
    }

};

