template<class T> struct LSSUM{
    int n;
    T e;
    vector<T> dat,lazy;

    LSSUM(T n_,T e_=0){
        n=1;e=e_;
        while(n<n_) n*=2;
        dat.resize(2*n-1,e);
        lazy.resize(2*n-1,e);
    }

    void prop(int k,int l,int r){
        if(lazy[k]==0) return;
        dat[k]+=lazy[k];
        if(r-l>1){
            lazy[2*k+1]+=lazy[k]/2;
            lazy[2*k+2]+=lazy[k]/2;
        }
        lazy[k]=0;
    }

    void ud(int be,int en,T t,int k,int l,int r){
        prop(k,l,r);
        if(r<=be||en<=l) return;
        if(be<=l&&r<=en){
            lazy[k]+=t*(r-l);
            prop(k,l,r);
            return;
        }
        ud(be,en,t,k*2+1,l,(l+r)/2);
        ud(be,en,t,k*2+2,(l+r)/2,r);
        dat[k]=dat[2*k+1]+dat[2*k+2];
    }

    void ud(int be,int en,T t){
        ud(be,en,t,0,0,n);
    }

    T gt(int be,int en,int k,int l,int r){
        if(r<=be||en<=l) return e;
        prop(k,l,r);
        if(be<=l&&r<=en) return dat[k];
        return gt(be,en,k*2+1,l,(l+r)/2)+gt(be,en,k*2+2,(l+r)/2,r);
    }

    T gt(int be,int en){
        return gt(be,en,0,0,n);
    }
};

