typedef long long ll;
const ll INF = (1LL << 31) - 1;
const ll sqrtN = 512;
struct SqrtDecomposition {
  ll N, K;
  vector<ll> data;
  vector<ll> bucketSum;
  vector<ll> lazyUpdate;
  SqrtDecomposition(ll n) : N(n) {
    K = (N + sqrtN - 1) / sqrtN;
    data.assign(K * sqrtN, 0);
    bucketSum.assign(K, 0);
    lazyUpdate.assign(K, 0);
  }
  void eval(ll k) {
    if (lazyUpdate[k]) {
      for (ll i = k * sqrtN; i < (k + 1) * sqrtN; ++i) {
        data[i] += lazyUpdate[k];
      }
      lazyUpdate[k] = 0;
    }
  }
  // [s, t)
  void update(ll s, ll t, ll x) {
    for (ll k = 0; k < K; ++k) {
      ll l = k * sqrtN, r = (k + 1) * sqrtN;
      if (r <= s || t <= l)
        continue;
      if (s <= l && r <= t) {
        bucketSum[k] += x * sqrtN;
        lazyUpdate[k] += x;
      } else {
        eval(k);
        for (ll i = max(s, l); i < min(t, r); ++i) {
          data[i] += x;
        }
        for (ll i = l; i < r; ++i) {
          bucketSum[k] += data[i];
        }
      }
    }
  }
  // [s, t)
  ll find(ll s, ll t) {
    ll ans = 0;
    for (ll k = 0; k < K; ++k) {
      ll l = k * sqrtN, r = (k + 1) * sqrtN;
      if (r <= s || t <= l)
        continue;
      if (s <= l && r <= t) {
        ans += bucketSum[k];
      } else {
        eval(k);
        for (ll i = l; i < r; ++i) {
          bucketSum[k] += data[i];
        }
        for (ll i = max(s, l); i < min(t, r); ++i) {
          ans += data[i];
        }
      }
    }
    return ans;
  }
};

