		chien(k,l,r);
		if(a<=l && r<=b){
			lazy[k]+=w*(r-l);

			chien(k,l,r);
			return ;
		}
		if(r<=a || b<=l){
			return ;
		}

		rangeadd(a,b,w,k*2,l,(l+r)/2);
		rangeadd(a,b,w,k*2+1,(l+r)/2,r);
		vec[k]=vec[2*k]+vec[2*k+1];
		return ;
