using namespace std;

void lazy_query(ll k,ll l,ll r, vector<ll>& node, vector<ll>& lazy, ll n) {
	node[k] += lazy[k] * (r - l);
	if (k < n - 1) {
		lazy[2 * k + 1] += lazy[k];
		lazy[2 * k + 2] += lazy[k];
	}
	lazy[k] = 0;
}

void add(ll a, ll b, ll x, ll k, ll l, ll r, vector<ll>&node, vector<ll>& lazy, ll n) {
	lazy_query(k, l, r, node, lazy, n);
	if (r <= a || b <= l)return;
	if (a <= l && r <= b) {
		lazy[k] += x;
		lazy_query(k, l, r, node, lazy, n);
		return;
	}
	else {
		add(a, b, x, 2 * k + 1, l, (l + r) / 2, node, lazy, n);
		add(a, b, x, 2 * k + 2, (l + r) / 2, r, node, lazy, n);
		node[k] = node[2 * k + 1] + node[2 * k + 2];
		return;
	}
}

ll getSum(ll a, ll b, ll k, ll l, ll r, vector<ll>&node, vector<ll>& lazy, ll n) {
	lazy_query(k, l, r, node, lazy, n);
	if (r <= a || b <= l)return 0;
	if (a <= l && r <= b) {
		return node[k];
	}
	else {
		ll vl = getSum(a, b, 2 * k + 1, l, (l + r) / 2, node, lazy, n);
		ll vr = getSum(a, b, 2 * k + 2, (l + r) / 2, r, node, lazy, n);
		node[k] = node[2 * k + 1] + node[2 * k + 2];
		return vr + vl;
	}
}

int main() {
	cin.tie(0); ios::sync_with_stdio(false);
	int n_, q;  cin >> n_ >> q;
	int n = 1;
	while (n < n_) n *= 2;
	vector<ll> node(2 * n - 1, 0);
	vector<ll> lazy(2 * n - 1, 0);

	for (int i = 0; i < q; i++) {
		int com; cin >> com;
		if (com == 0) {
			ll s, t, x; cin >> s >> t >> x;
			add(s - 1, t, x, 0, 0, n, node, lazy, n);
		}
		else {
			ll s, t; cin >> s >> t;
			cout << getSum(s - 1, t, 0, 0, n, node, lazy, n) << endl;
		}
	}
}

