const int N = 1e5;

struct LazySegTree {
	ll data[N*4];
	ll lazy[N*4];
	int m;
	void init(int n) {
		m=1;
		while(m<n) m<<=1;
		REP(i, m*2-1) {
			data[i] = 0;
			lazy[i] = 0;
		}
	}
	void eval(int k, int l, int r) {
		if(lazy[k] == 0) return;
		data[k] += lazy[k]; ///
		if(r-l>1) {
			lazy[k*2+1] =
			lazy[k*2+2] = lazy[k] / 2;
		}
		lazy[k] = 0;
	}
	void update(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
		if(r<0) r=m;
		eval(k, l, r);
		if(b<=l||r<=a) return;
		if(a<=l&&r<=b) {
			lazy[k] += (r-l) * x;
			eval(k, l, r);
			return; ///
		}
		update(a, b, x, k*2+1, l, (l+r)/2);
		update(a, b, x, k*2+2, (l+r)/2, r);
		data[k] = data[k*2+1] + data[k*2+2];
	}
	ll sum(int a, int b, int k = 0, int l = 0, int r = -1) {
		if(r<0) r=m;
		eval(k, l, r);
		if(b<=l||r<=a) return 0;
		if(a<=l&&r<=b) {
			return data[k];
		}
		return sum(a, b, k*2+1, l, (l+r)/2) +
				sum(a, b, k*2+2, (l+r)/2, r);
	}
};

