#include <iostream>
#include <vector>
using namespace std;
struct SegTree{
	//
	int n;
	vector<int> dat,laz;
	//
	SegTree(int n_){
		init(n_);
	}
	//
	void init(int n_){
		n=1;
		while(n<n_){
			n*=2;
		}
		for(int i=0;i<2*n-1;i++){
			dat.push_back(0);
			laz.push_back(0);
		}
	}
	//
	void eval(int l,int k){
		if(k*2+1<n*2-1){
			laz[k*2+1]+=laz[k];
			laz[k*2+2]+=laz[k];
		}
		dat[k]+=laz[k]*l;
		laz[k]=0;
	}
	//
	int update(int a,int b,int x,int k=0,int l=0,int r=-1){
		if(r==-1){
			r=n;
		}
		eval(r-l,k);
		if(r<=a||b<=l){
			return dat[k]+laz[k]*(r-l);
		}else if(a<=l&&r<=b){
			return dat[k]+(laz[k]+=x)*(r-l);
		}else{
			eval(r-l,k);
			int va=update(a,b,x,k*2+1,l,(l+r)/2);
			int vb=update(a,b,x,k*2+2,(l+r)/2,r);
			return dat[k]=va+vb;
		}
	}
	//
	int query(int a,int b,int k=0,int l=0,int r=-1){
		if(r==-1){
			r=n;
		}
		eval(r-l,k);
		if(r<=a||b<=l){
			return 0;
		}else if(a<=l&&r<=b){
			return dat[k];
		}else{
			int va=query(a,b,k*2+1,l,(l+r)/2);
			int vb=query(a,b,k*2+2,(l+r)/2,r);
			return va+vb;
		}
	}
	//
};
int main(){
	int N,Q;
	cin>>N>>Q;
	SegTree Seg(N);
	while(Q--){
		int C;
		cin>>C;
		if(C==1){
			int S,T;
			cin>>S>>T;
			cout<<Seg.query(S-1,T)<<endl;
		}else{
			int S,T,X;
			cin>>S>>T>>X;
			Seg.update(S-1,T,X);
		}
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
struct SegTree {
	int size;
	LL *dat,*lazy;
	SegTree(int n) {
		size=1;
		while(size<n) size*=2;
		dat=(LL*)malloc(sizeof(LL)*(size*2-1));
		fill(dat,dat+(size*2-1),0);
		lazy=(LL*)malloc(sizeof(LL)*(size*2-1));
		fill(lazy,lazy+(size*2-1),0);
	}
	void eval(int k,int len) {
		dat[k]+=lazy[k]*len;
		if(k<size-1) lazy[k*2+1]+=lazy[k],lazy[k*2+2]+=lazy[k];
		lazy[k]=0;
	}
	void add(int a,int b,int  x,int k,int l,int r) {
		eval(k,r-l);
		if(r<=a||b<=l) return;
		if(a<=l&&r<=b) {
			lazy[k]+=x;
			eval(k,r-l);
		}else {
			add(a,b,x,k*2+1,l,(l+r)/2);
			add(a,b,x,k*2+2,(l+r)/2,r);
			dat[k]=dat[k*2+1]+dat[k*2+2];
		}
	}
	LL sum(int a,int b,int k,int l,int r) {
		eval(k,r-l);
		if(r<=a||b<=l) return 0;
		if(a<=l&&r<=b) return dat[k];
		return sum(a,b,k*2+1,l,(l+r)/2)+sum(a,b,k*2+2,(l+r)/2,r);
	}
};
int main() {
	int n,q;
	scanf("%d %d",&n,&q);
	SegTree S(n);
	for(int i=0;i<q;i++) {
		int type,s,t,x;
		scanf("%d",&type);
		if(type==0) {
			scanf("%d %d %d",&s,&t,&x);s--;
			S.add(s,t,x,0,0,S.size);
		}else {
			scanf("%d %d",&s,&t);s--;
			printf("%lld\n",S.sum(s,t,0,0,S.size));
		}
	}
}

