namespace RandomizedBinarySearchTree {
  struct Node;
  using Tree = Node*;
  struct Node {
    lint val, sum, laz;
    Tree cl, cr;
    int n;
    Node() {}
    Node(lint v);
  };
  Tree nil = new Node();
  Node::Node(lint v) :
    val(v), sum(v), laz(0), cl(nil), cr(nil), n(1) {}

  Tree update(Tree t) {
    t->sum = t->cl->sum + t->val + t->cr->sum;
    t->n = t->cl->n + 1 + t->cr->n;
    return t;
  }

  void push(Tree t) {
    t->cl->val += t->laz;
    t->cl->sum += t->laz * t->cl->n;
    t->cl->laz += t->laz;
    t->cr->val += t->laz;
    t->cr->sum += t->laz * t->cr->n;
    t->cr->laz += t->laz;
    t->laz = 0;
  }

  Tree merge(Tree tl, Tree tr) {
    if (tr == nil) return tl;
    if (tl == nil) return tr;
    if (rng(0, tl->n + tr->n) < tl->n) {
      push(tl);
      tl->cr = merge(tl->cr, tr);
      return update(tl);
    } else {
      push(tr);
      tr->cl = merge(tl, tr->cl);
      return update(tr);
    }
  }

  pair<Tree, Tree> split(Tree t, int i) {
    if (t == nil) return {nil, nil};
    push(t);
    if (i <= t->cl->n) {
      Tree resl;
      tie(resl, t->cl) = split(t->cl, i);
      return {resl, update(t)};
    } else {
      Tree resr;
      tie(t->cr, resr) = split(t->cr, i - t->cl->n - 1);
      return {update(t), resr};
    }
  }

  Tree insert(Tree t, int i, lint v) {
    Tree tl, tr;
    tie(tl, tr) = split(t, i);
    return merge(merge(tl, new Node(v)), tr);
  }

  Tree erase(Tree t, int i) {
    Tree tl, tr;
    tie(tl, tr) = split(t, i);
    tr = split(tr, 1).second;
    return merge(tl, tr);
  }
}

