const int INF = 2147483647;
#define B 100

int bucket[MAX/B][B];
int udata[MAX/B], data[MAX/B];
void add(int a, int b, int x){
	while(a <= b && a%B != 0){
		bucket[a/B][a%B] += x;
		a++;
	}
	while(a <= b && b%B != B-1){
		bucket[b/B][b%B] += x;
		b--;
	}
	while(a < b){
		udata[a/B] += x;
		a += B;
	}
}

int get(int a, int b){
	int ans = 0;
	while(a <= b && a%B != 0){
		ans += bucket[a/B][a%B];
		a++;
	}
	while(a <= b && b%B != B-1){
		ans += bucket[b/B][b%B];
		b--;
	}
	while(a < b){
		if(udata[a/B] != -1)ans = udata[a/B];
		a += B;
	}
	return ans;
}

int main(){
	int n, q, c, s, t, x, ans;
	scanf("%d%d", &n, &q);
	fill(udata, udata+MAX/B, -1);
	//fill(data, data+MAX/B, INF);
	fill((int*)bucket, (int*)(bucket+MAX/B), 0);
	while(q--){
		scanf("%d", &c);
		if(!c){
			scanf("%d%d%d", &s, &t, &x);
			add(s-1, t-1, x);
		}else{
			scanf("%d%d", &s, &t);
			ans = get(s-1, t-1);
			printf("%d\n", ans);
		}
	}
	//rep(i,n)printf("%d ", bucket[0][i]);
	return 0;
}

