  LazySegTree<RSQ_RAQ_Trait<int>> lst(n);
  while (q--) {
    int a, s, t;
    cin >> a >> s >> t;
    --s, --t;
    if (a) {
      cout << lst.fold(s, t + 1) << endl;
    } else {
      int x;
      cin >> x;
      lst.act(s, t + 1, x);
    }
  }
}

