template<typename T>
struct BIT {
	int n;
	vector<T> bit;
	BIT() :n(0) {}
	BIT(int _n) :n(_n) { bit = vector<T>(n + 1); }
	void add1(int idx, T val) {
		for (int i = idx; i <= n; i += i & -i) bit[i] += val;
	}
	T sum1(int idx) {
		T res = 0;
		for (int i = idx; i > 0; i -= i & -i) res += bit[i];
		return res;
	}
	//0-indexed
	void add(int idx, T val) { add1(idx + 1, val); }
	//0-indexed [left, right)
	T sum(int left, int right) { return sum1(right) - sum1(left); }

	int lower_bound(T x) {
		int res = 0;
		int k = 1;
		while (2 * k <= n) k <<= 1;
		for (; k > 0; k >>= 1) {
			if (res + k <= n and bit[res + k] < x) {
				x -= bit[res + k];
				res += k;
			}
		}
		return res;
	}
};


template<typename T>
struct RangeAddBIT {
	int n;
	BIT<T> bit[2];
	RangeAddBIT() :n(0) {}
	RangeAddBIT(int _n) :n(_n) { bit[0] = bit[1] = BIT<T>(n); }

	//0-indexed, [left, right)
	void add(int left, int right, T val) {
		bit[0].add(left, -val * (left - 1));
		bit[0].add(right, val * (right - 1));
		bit[1].add(left, val);
		bit[1].add(right, -val);
	}

	//0-indexed, [left, right)
	T sum(int left, int right) {
		T suml = bit[0].sum(0, left) + bit[1].sum(0, left) * (left - 1);
		T sumr = bit[0].sum(0, right) + bit[1].sum(0, right) * (right - 1);
		return sumr - suml;
	}
};

