template<typename T>
class Lazy_Segment_Tree {//0-indexed ??????
public:
	vector<T> data,lazy;
	int n;
	Lazy_Segment_Tree(int a) :n(1) {
		while (n < a) n *= 2;
		data.resize(n * 2 - 1);
		lazy.resize(n * 2 - 1);
	}

	void add(int a, int b, T ad, int num = 0, int base = 1) {
		int l = (num + 1 - base) * (n / base), r = l + n / base;
		if (a == l && b == r)
			lazy[num] += ad;
		else {
			data[num] += ad*(b-a);
			int nr = (l + r) / 2;
			if (nr > a) add(a, min(b, nr), ad, num * 2 + 1, base * 2);
			if (nr < b) add(max(a, nr), b, ad, num * 2 + 2, base * 2);
		}
	}

	T sum(int a, int b, T luz = 0, int num = 0, int base = 1) {
		int l = (num + 1 - base) * (n / base), r = l + n / base;
		luz += lazy[num];
		if (a == l && b == r)
			return data[num]+luz*(b - a);
		else {
			int nr = (l + r) / 2;
			T ret = T();
			data[num] += luz*(b - a);
			lazy[num] = T();
			if (nr > a) ret += sum(a, min(b, nr), luz, num * 2 + 1, base * 2);
			if (nr < b) ret += sum(max(a, nr), b, luz, num * 2 + 2, base * 2);
			return ret;
		}
	}
};




