template<typename T = int, class F = std::plus<T>, class F_INV = std::minus<T>, T E = 0>
struct BinaryIndexedTree {
    const F op = F(); const F_INV op_inv = F_INV();
    int n; vector<T> dat;
    void build(const vector<T>& v) {
        n = v.size(); dat.assign(n, E); for (int i = 0; i < n; ++i) add(i, v[i]);
    }
    void add(int k, T v) { for (int i = k; i < n; i |= i + 1) dat[i] = op(dat[i], v); }
    T query(int a, int b) const {
        T ret = E; if (a == b) return ret;
        for (int i = b - 1; i >= 0; i = (i & (i + 1)) - 1) ret = op(ret, dat[i]);
        return op_inv(ret, query(0, a));
    }
};

struct RangeAddRangeSumQuery {
    int n;
    BinaryIndexedTree<ll> bit0, bit1;
    void build(int n_) {
        n = n_;
        bit0.build(vector<ll>(n + 1));
        bit1.build(vector<ll>(n + 1));
    }
    void range_add(int l, int r, ll x) {
        bit0.add(l, -x * l);
        bit1.add(l, x);
        bit0.add(r, x * r);
        bit1.add(r, -x);
    }
    ll range_sum(int l, int r) {
        return bit0.query(l, r) + r * bit1.query(0, r) - l * bit1.query(0, l);
    }
};

