using V = vector<long>;

struct RSAQ {
	int n;
	V b0, b1;
	RSAQ(int s) : n {s}, b0(s + 1), b1(s + 1) {}
	long sum(V &b, int i) {
		long r {};
		for (; i > 0; i -= i & -i)
			r += b[i];
		return r;
	}
	long sum(int s, int t) {
		s--;
		return sum(b0, t) + sum(b1, t) * t - sum(b0, s) - sum(b1, s) * (s);
	}
	void add(V &b, int i, int v) {
		for (; i <= n; i += i & -i)
			b[i] += v;
	}
	void add(int s, int t, int v) {
		add(b0, s, -v * (s - 1));
		add(b1, s, v);
		add(b0, t + 1, v * t);
		add(b1, t + 1, -v);
	}
};

