template <class T>
struct LazySegmentTreeRangeAddRangeSum {
    const T query_ident = 0;
    const T prop_ident = 0;
    int size;
    vector<T> data;
    vector<T> lazy;
    vi width;

    LazySegmentTreeRangeAddRangeSum(int n) {
        size = 1;
        while (size < n) size *= 2;
        data.assign(size * 2, query_ident);
        lazy.assign(size * 2, prop_ident);
        width.assign(size * 2, 1);
        rrep(k, 0, size - 1) {
            width[k] = width[k * 2 + 1] + width[k * 2 + 2];
        }
    }
    void lazy_propagate(int k) {
        if (lazy[k] == prop_ident) return;
        data[k] += lazy[k] * width[k];  // !
        if (k < size - 1) {
            lazy[k * 2 + 1] += lazy[k];  // !
            lazy[k * 2 + 2] += lazy[k];  // !
        }
        lazy[k] = prop_ident;
    }
    void range_add(int ql, int qr, T value) {
        range_add(ql, qr, value, 0, 0, size);
    }
    void range_add(int ql, int qr, T value, int k, int nl, int nr) {
        if (qr <= nl || nr <= ql) {
            lazy_propagate(k);
            return;
        }
        if (ql <= nl && nr <= qr) {
            lazy[k] += value;  // !
            lazy_propagate(k);
            return;
        }
        int nm = (nl + nr) / 2;
        lazy_propagate(k);
        range_add(ql, qr, value, k * 2 + 1, nl, nm);
        range_add(ql, qr, value, k * 2 + 2, nm, nr);
        data[k] = data[k * 2 + 1] + data[k * 2 + 2];  // !
    }
    T range_sum(int ql, int qr) {
        return range_sum(ql, qr, 0, 0, size);
    }
    T range_sum(int ql, int qr, int k, int nl, int nr) {
        if (qr <= nl || nr <= ql) {
            return query_ident;
        }
        if (ql <= nl && nr <= qr) {
            lazy_propagate(k);
            return data[k];
        }
        lazy_propagate(k);
        int nm = (nl + nr) / 2;
        T res_l = range_sum(ql, qr, k * 2 + 1, nl, nm);
        T res_r = range_sum(ql, qr, k * 2 + 2, nm, nr);
        return res_l + res_r;  // !
    }
};

