            int l = k * sqrtN, r = (k + 1) * sqrtN;
            if (r <= s || t <= l)
                continue;
            if (s <= l && r <= t)
            {
                sum += bucket_sum[k] + bucket_add[k] * sqrtN;
            }
            else
            {
                eval(k);
                for (int i = max(s, l); i < min(t, r); ++i)
                {
                    sum += data[i];
                }
            }
        }
        return sum;
    }
    void update(int i, T val)
    {
        int k = i / sqrtN;
        eval(k);
        data[i] = val;
    }
    void eval(int k)
    {
        if (bucket_add[k] == 0)
        {
            return;
        }
        for (int i = sqrtN * k; i <= sqrtN * (k + 1); i++)
        {
            data[i] += bucket_add[k];
        }
        bucket_add[k] = 0;
    }
    T get(int i)
    {
        int k = i / sqrtN;
        return data[i] + bucket_add[k];
    }
};
//end
int main()
{
    ios::sync_with_stdio(false);
    int N, Q;
    cin >> N >> Q;
    SqrtDecompositionRangeAddRangeSum<ll> decomp(N);
    while (Q--)
    {
        int c;
        cin >> c;
        if (c == 0)
        {
            int s, t, x;
            cin >> s >> t >> x;
            decomp.add(s, t + 1, (long long)x);
        }
        else
        {
            int s, t;
            cin >> s >> t;
            cout << decomp.get_sum(s, t + 1) << endl;
        }
    }
}

