typedef long long ll;

const int BUCKET = 400,SIZE = 300;
int N,Q;
ll bucketAdd [BUCKET];
ll bucketSum [BUCKET];
ll A [100000];

void update(int l,int r,ll val)
{
	FOR(i,0,BUCKET){
		int bucketL = i * SIZE,bucketR = (i + 1) * SIZE;
		if(r <= bucketL || bucketR <= l) continue;
		if(l <= bucketL && bucketR <= r){
			bucketAdd [i] += val;
			bucketSum [i] += val * SIZE;
			continue;
		}
		FOR(j,bucketL,bucketR){
			if(l <= j && j < r){
				bucketSum [i] += val;
				A [j] += val;
			}
		}
	}
}

ll getSum(int l,int r)
{
	ll res = 0;
	FOR(i,0,BUCKET){
		int bucketL = i * SIZE,bucketR = (i + 1) * SIZE;
		if(r <= bucketL || bucketR <= l) continue;
		if(l <= bucketL && bucketR <= r){
			res += bucketSum [i];
			continue;
		}
		FOR(j,bucketL,bucketR){
			if(l <= j && j < r){
				res += bucketAdd [i] + A [j];
			}
		}
	}
	return res;
}

int main()
{
	scanf("%d%d",&N,&Q);
	vector<ll> ans;
	FOR(i,0,Q){
		int com;
		scanf("%d",&com);
		if(com == 0){
			int s,t,x;
			scanf("%d%d%d",&s,&t,&x);
			update(s - 1,t,x);
		}
		else{
			int s,t;
			scanf("%d%d",&s,&t);
			ans.push_back(getSum(s - 1,t));
		}
	}

	FOR(i,0,ans.size()){
		printf("%lld\n",ans [i]);
	}

	return 0;
}

