using namespace std;
typedef long long lint;

class SegTree {
private:
    lint l, r, v, lazy;
    SegTree *sl, *sr;

public:
    SegTree(lint* arr, int l, int r) 
        : l(l), r(r), lazy(0), sl(NULL), sr(NULL) {
        if (l == r) {
            v = arr != NULL ? arr[l] : 0;
            return;
        }

        int m = l + r >> 1;
        sl = new SegTree(arr, l, m);
        sr = new SegTree(arr, m + 1, r);

        // Recalculate node
        v = sl->get() + sr->get();
    }

    // Get size of segment tree
    int size() { return r - l + 1; }

    // a[ql..qr] += qv
    void update(int ql, int qr, int qv) {
        if (ql == l && qr == r) {
            lazy += qv;
            return;
        }
        // Push down
        sl->lazy += lazy;
        sr->lazy += lazy;
        lazy = 0;
        // Update
        int m = l + r >> 1;
        if (qr <= m) {
            sl->update(ql, qr, qv);
        } else if (ql > m) {
            sr->update(ql, qr, qv);
        } else {
            sl->update(ql, m, qv);
            sr->update(m + 1, qr, qv);
        }
        // Recalculate
        v = sl->get() + sr->get() + lazy * size();
    }

    // a[l] + a[l+1] + ... + a[r]
    lint get() {
        return v + lazy * size();
    }

    // a[ql] + a[ql+1] + ... + a[qr]
    lint query(int ql, int qr) {
        if (ql == l && qr == r) return get();

        int m = l + r >> 1;
        if (qr <= m) {
            return sl->query(ql, qr);
        } else if (ql > m) {
            return sr->query(ql, qr);
        } else {
            return sl->query(ql, m) + sr->query(m + 1, qr);
        }
    }
};

