struct SegmentTree{

   static const int N=1<<17;
   static const int Z=0;
   vector<int> seg, lazy;
   SegmentTree(){
      seg.resize(2*N-1, 0);
      lazy.resize(2*N-1, 0);
   }

   inline void refresh(int i, int l, int r){
      if(lazy[i]){
         seg[i]+=lazy[i]*(r-l);
         if(r-l>1){
            lazy[2*i+1]+=lazy[i];
            lazy[2*i+2]+=lazy[i];
         }
         lazy[i]=0;
      }
   }

   void add(int a, int b, int x, int i=0, int l=0, int r=N){
      refresh(i, l, r);
      if(b<=l or r<=a){
         return;
      }else if(a<=l and r<=b){
         lazy[i]+=x;
         refresh(i, l, r);
      }else{
         int m=(r+l)/2;
         add(a, b, x, 2*i+1, l, m);
         add(a, b, x, 2*i+2, m, r);
         seg[i]=seg[2*i+1]+seg[2*i+2];
      }
   }

   int sum(int a, int b, int i=0, int l=0, int r=N){
      refresh(i, l, r);
      if(b<=l or r<=a){
         return Z;
      }else if(a<=l and r<=b){
         return seg[i];
      }else{
         int m=(r+l)/2;
         int vl=sum(a, b, 2*i+1, l, m);
         int vr=sum(a, b, 2*i+2, m, r);
         return vl+vr;
      }
   }

};

