typedef long long ll;

struct segment_tree
{
	vector<ll> st, lazy;

	segment_tree(int n) : st(4 * n), lazy(4 * n) { }

	void push(int p, int b, int e)
	{
		if(lazy[p])
		{
			int m = (b + e) >> 1, l = p << 1, r = l | 1;
			if(b + 1 < e)
			{
				st[l] += lazy[p] * (m - b), lazy[l] += lazy[p];
				st[r] += lazy[p] * (e - m), lazy[r] += lazy[p];
			}

			lazy[p] = 0;
		}
	}

	void update(int p, int b, int e, int x, int y, int v)
	{
		if(x <= b && e <= y)
			st[p] += (ll) v * (e - b), lazy[p] += v;
		else
		{
			int m = (b + e) >> 1, l = p << 1, r = l | 1;
			if(x < m)
				update(l, b, m, x, y, v);
			if(m < y)
				update(r, m, e, x, y, v);

			push(p, b, e);
			st[p] = st[l] + st[r];
		}
	}

	ll query(int p, int b, int e, int x, int y)
	{
		if(x <= b && e <= y)
			return st[p];
		else
		{
			int m = (b + e) >> 1, l = p << 1, r = l | 1;
			ll ans = 0;
			if(x < m)
				ans += query(l, b, m, x, y);
			if(m < y)
				ans += query(r, m, e, x, y);

			push(p, b, e);
			st[p] = st[l] + st[r];

			return ans;
		}
	}
};


