	while(q--)
	{
		cin >> op;
		if(op)
		{
			int x, y; cin >> x >> y, --x;
			cout << st.query(1, 0, n, x, y) << endl;
		}
		else
		{
			int x, y, v; cin >> x >> y >> v, --x;
			st.update(1, 0, n, x, y, v);
		}
	}

    return 0;
}

