using namespace std;

const int DEPTH = 17;

struct SegTree {
	int lazySum[1 << DEPTH + 1];
	int segSum[1 << DEPTH + 1];

	SegTree() {
		for (int i = 0; i < 1 << DEPTH + 1; i++) {
			lazySum[i] = 0;
			segSum[i] = 0;
		}
	}

	void lazy_evaluate(int id) {
		if (lazySum[id] == 0) return;
		segSum[id] += lazySum[id];

		if (id < (1 << DEPTH) - 1) {
			lazySum[id * 2 + 1] += lazySum[id] / 2;
			lazySum[id * 2 + 2] += lazySum[id] / 2;
		}
		lazySum[id] = 0;
	}

	void add(int l, int r, int x, int a = 0, int b = (1 << DEPTH), int id = 0) {
		lazy_evaluate(id);

		if (a >= r || b <= l) return;
		if (l <= a && b <= r) {
			lazySum[id] += x * (b - a);
			lazy_evaluate(id);
			return;
		}
		add(l, r, x, a, (a + b) / 2, id * 2 + 1);
		add(l, r, x, (a + b) / 2, b, id * 2 + 2);
		segSum[id] = segSum[id * 2 + 1] + segSum[id * 2 + 2];
	}

	int getSum(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return 0;

		lazy_evaluate(id);
		if (l <= a && b <= r) {
			return segSum[id];
		}

		int res1 = getSum(l, r, a, (a + b) / 2, id * 2 + 1);
		int res2 = getSum(l, r, (a + b) / 2, b, id * 2 + 2);
		return res1 + res2;
	}
};

