long long n, q, t1, t2, t3, t4, mb, t[200005], d[200005];

void apply(int p, int val) {
	t[p] += val;
	if (p < n) d[p] += val;
}

void build(int p) {
	while (p > 1) p >>= 1, t[p] = t[p << 1] + t[p << 1 | 1] + d[p];
}

void push(int p) {
	for (int s = mb; s > 0; --s) {
		int i = p >> s;
		if (d[i] != 0) {
			apply(i << 1, d[i] / 2);
			apply(i << 1 | 1, d[i] / 2);
			d[i] = 0;
		}
	}
}

void inc(int l, int r, int val) {
	l += n, r += n;
	int l0 = l, r0 = r;
	for (; l < r; l >>= 1, r >>= 1, val += val) {
		if (l & 1) apply(l++, val);
		if (r & 1) apply(--r, val);
	}
	build(l0);
	build(r0 - 1);
}

long long query(int l, int r) {
	l += n, r += n;
	push(l);
	push(r - 1);
	long long ans = 0;
	for (; l < r; l >>= 1, r >>= 1) {
		if (l & 1) ans += t[l++];
		if (r & 1) ans += t[--r];
	}
	return ans;
}

int main() {
	cin >> n >> q;
	t1 = 1;
	while (t1 < n) {
		t1 <<= 1, mb++;
	}
	for (int i = 0; i < q; i++) {
		cin >> t1;
		if (t1 == 0) {
			cin >> t2 >> t3 >> t4;
			inc(t2 - 1, t3, t4);
		}
		else {
			cin >> t2 >> t3;
			cout << query(t2 - 1, t3) << endl;
		}
	}
}

