int n;

void init(int _n){
    n = 1;
    while(n < _n){
        n *= 2;
    }
    for(int i = 0; i < 2 * n - 1; i++){
        dat[i] = 0;
        dat_added[i] = 0;
    }
}

void radd(int a, int b, int k, int l, int r, int x){
    if(r <= a || b <= l){
        return;
    }
    if(a <= l && r <= b){
        dat_added[k] += x;
        return;
    }
    dat[k] += (min(b, r) - max(a, l)) * x;
    radd(a, b, 2 * k + 1, l, (l + r) / 2, x);
    radd(a, b, 2 * k + 2, (l + r) / 2, r, x);
}

long long rsum(int a, int b, int k, int l, int r){
    if(r <= a || b <= l){
        return 0;
    }
    if(a <= l && r <= b){
        return dat[k] + dat_added[k] * (r - l);
    }
    long long vl = rsum(a, b, 2 * k + 1, l, (l + r)/2);
    long long vr = rsum(a, b, 2 * k + 2, (l + r)/2, r);
    return vl + vr + dat_added[k] * (min(b, r) - max(a, l));
}

