			if (lazy[right >> 1]) {
				calc[right] = lazy[right] ? calc[right] * calc[right >> 1] : calc[right >> 1];
				calc[right ^ 1] = lazy[right ^ 1] ? calc[right ^ 1] * calc[right >> 1] : calc[right >> 1];
				lazy[right >> 1] = false; lazy[right] = true; lazy[right ^ 1] = true;
			}
		}
		for (left = begin, right = end + 1;left < right;left >>= 1, right >>= 1) {
			if (left & 1) {
				calc[left] = lazy[left] ? calc[left] * data : data;
				lazy[left] = true;
				++left;
			}
			if (right & 1) {
				--right;
				calc[right] = lazy[right] ? calc[right] * data : data;
				lazy[right] = true;
			}
		}
		for (begin >>= 1, end >>= 1;begin < end;begin >>= 1, end >>= 1) {
			tree[begin] = (lazy[begin << 1] ? tree[begin << 1] * calc[begin << 1] : tree[begin << 1]) + (lazy[begin << 1 | 1] ? tree[begin << 1 | 1] * calc[begin << 1 | 1] : tree[begin << 1 | 1]);
			tree[end] = (lazy[end << 1] ? tree[end << 1] * calc[end << 1] : tree[end << 1]) + (lazy[end << 1 | 1] ? tree[end << 1 | 1] * calc[end << 1 | 1] : tree[end << 1 | 1]);
		}
		begin <<= 1;
		while (begin >>= 1) {
			tree[begin] = (lazy[begin << 1] ? tree[begin << 1] * calc[begin << 1] : tree[begin << 1]) + (lazy[begin << 1 | 1] ? tree[begin << 1 | 1] * calc[begin << 1 | 1] : tree[begin << 1 | 1]);
		}
	}
	//[begin,end)??????????????????
	Monoid range(size_t begin, size_t end) {
		Monoid retL, retR;
		begin += size;end += size - 1;
		size_t left, right;
		i = hight;
		while (i--) {
			left = begin >> i;
			right = end >> i;
			if (lazy[left >> 1]) {
				calc[left] = lazy[left] ? calc[left] * calc[left >> 1] : calc[left >> 1];
				calc[left ^ 1] = lazy[left ^ 1] ? calc[left ^ 1] * calc[left >> 1] : calc[left >> 1];
				tree[left >> 1] = tree[left >> 1] * calc[left >> 1];
				lazy[left >> 1] = false; lazy[left] = true; lazy[left ^ 1] = true;
			}
			if (lazy[right >> 1]) {
				calc[right] = lazy[right] ? calc[right] * calc[right >> 1] : calc[right >> 1];
				calc[right ^ 1] = lazy[right ^ 1] ? calc[right ^ 1] * calc[right >> 1] : calc[right >> 1];
				tree[right >> 1] = tree[right >> 1] * calc[right];
				lazy[right >> 1] = false; lazy[right] = true; lazy[right ^ 1] = true;
			}
		}
		++end;
		for (;begin < end;(++begin) >>= 1, end >>= 1) {
			if (begin & 1) {
				if (lazy[begin]) { retL = retL + (tree[begin] * calc[begin]); }
				else { retL = retL + tree[begin]; }
			}
			if (end & 1) {
				if (lazy[--end]) { retR = retR + (tree[end] * calc[end]); }
				else { retR = retR + tree[end]; }
			}
		}
		return retL + retR;
	}
};

