class sqrt_decomposition{
    public:
    const i64 B=2000;
    int n;
    vector<i64> data,unif,sum; //uni??????????????????????§?????¶?????????????
    sqrt_decomposition(int n,i64 init):n(n),data(n,init),unif((n+B-1)/B),sum((n+B-1)/B){
        rep(i,0,(n+B-1)/B) unif[i]=init;
        rep(i,0,n) sum[i/B]+=init;
    }

    //[s,t)???x??????????????´???[s,t)???????¨??????????
    i64 add(int s,int t,i64 x){
        i64 res=0;
        while(s<t and s%B!=0){
            data[s]+=x;
            sum[s/B]+=x;
            res+=data[s]+unif[s/B];
            ++s;
        }
        while(s<t and t%B!=0){
            --t;
            data[t]+=x;
            sum[t/B]+=x;
            res+=data[t]+unif[t/B];
        }

        while(s<t){
            int i=s/B;
            unif[i]+=x;
            sum[i]+=x*B;
            res+=sum[i];
            s+=B;
        }
        return res;
    }
};

