class sqrt_decomposition{
    public:
    const int B=1000;
    int n;
    vector<i64> data,sum; //sum??????????????????data???????¨?
    sqrt_decomposition(int n,i64 init):n(n),data(n,init),sum((n+B-1)/B){
        rep(i,0,n) sum[i/B]+=init;
    }

    //[s,t)???x??????????????´???[s,t)???????¨??????????
    i64 add(int s,int t,i64 x){
        i64 res=0;
        while(s<t and s%B!=0){
            data[s]+=x;
            sum[s/B]+=x;
            res+=data[s];
            ++s;
        }
        while(s<t and t%B!=0){
            --t;
            data[t]+=x;
            sum[s/B]+=x;
            res+=data[t];
        }

        while(s<t){
            int i=s/B;
            sum[i]+=x*B;
            res+=sum[i];
            s+=B;
        }
        return res;
    }
};

