                where=to;
            }
            E.push_back({parent,nodes[w].high,nodes[end].high,w,end,late_seg_tree(tree,err_T,err_U)});
            count++;
        }
    }

    //[low,high]
    void up_update(ll where,ll low,ll high,U u){
        ll High=E[where].high;
        ll Low=E[where].low;
        u=P(u,High,Low,false);
        high=max(High,high);
        low=min(Low,low);
        high-=High;
        low-=High;
        E[where].seg.update(high,low+1,u);
    }

    //[high,low]
    void down_update(ll where,ll high,ll low,U u){
        ll High=E[where].high;
        ll Low=E[where].low;
        u=P(u,High,Low,true);
        high=max(High,high);
        low=min(Low,low);
        high-=High;
        low-=High;
        E[where].seg.update(high,low+1,u);
    }

    void UPDATE(ll s,ll t,U u){
        ll mid=lca.search_lca(s,t);
        if(s!=mid){
            ll w=s;
            ll high=nodes[mid].high+1;
            while(1){
                ll low=nodes[w].high;
                ll where=nodes[w].edge_number;
                if(low<high){break;}
                up_update(where,low,high,u);
                w=E[where].parent;
            }
        }
        ll w=t;
        ll high=nodes[mid].high;
        while(1){
            ll low=nodes[w].high;
            ll where=nodes[w].edge_number;
            if(low<high){break;}
            down_update(where,high,low,u);
            if(where==0){break;}
            w=E[where].parent;
        }
    }

    //[low,high]
    T up_search(ll where,ll low,ll high){
        ll High=E[where].high;
        ll Low=E[where].low;
        high=max(High,high);
        low=min(Low,low);
        high-=High;
        low-=High;
        return E[where].seg.search(high,low+1);
    }

    //[high,low]
    T down_search(ll where,ll high,ll low){
        ll High=E[where].high;
        ll Low=E[where].low;
        high=max(High,high);
        low=min(Low,low);
        high-=High;
        low-=High;
        return E[where].seg.search(high,low+1);
    }

    T SEARCH(ll s,ll t){
        T ret=err_T;
        ll mid=lca.search_lca(s,t);
        if(s!=mid){
            ll w=s;
            ll high=nodes[mid].high+1;
            while(1){
                ll low=nodes[w].high;
                ll where=nodes[w].edge_number;
                if(low<high){break;}
                ret=F(ret,up_search(where,low,high));
                w=E[where].parent;
            }
        }
        ll w=t;
        ll high=nodes[mid].high;
        while(1){
            ll low=nodes[w].high;
            ll where=nodes[w].edge_number;
            if(low<high){break;}
            ret=F(ret,down_search(where,high,low));
            if(where==0){break;}
            w=E[where].parent;
        }
        return ret;
    }

public:
    HLD(ll v,ll root,T err_T,U err_U):v(v),root(root),err_T(err_T),err_U(err_U),lca(v,root){
        edge.resize(v);
        nodes.resize(v,{-1,-1,-1,-1,{},err_T});
        made=false;
    }

    HLD(ll v,ll root,vector<T> t,T err_T,U err_U):v(v),root(root),err_T(err_T),err_U(err_U),lca(v,root){
        lca(v,root);
        edge.resize(v);
        nodes.resize(v,{-1,-1,-1,-1,{},err_T});
        made=false;
        for(int i=0;i<v;i++){
            nodes[i].a=t[i];
        }
    }

    //無向
    void add_edge(ll from,ll to){
        edge[from].push_back(to);
        edge[to].push_back(from);
        lca.add_edge(from,to);
        lca.add_edge(to,from);
    }

    void update(ll from,ll to,U u){
        MK_TREE();
        UPDATE(from,to,u);
    }

    T search(ll s,ll t){
        MK_TREE();
        return SEARCH(s,t);
    }
};



int main(){
    ll n;
    cin>>n;
    HLD<ll,ll> tree(n,max((ll)0,n-100),0,0);
    for(int i=1;i<n;i++){
        tree.add_edge(i,i-1);
