using namespace std;

struct SegmentTree
{
  const int INF = 1 << 30;

  vector< int > add, seg;
  int sz;

  SegmentTree(int n)
  {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz - 1, 0);
    add.assign(2 * sz - 1, 0);
  }

  void update(int a, int b, int x, int k, int l, int r)
  {
    if(a >= r || b <= l) return;
    if(a <= l && r <= b) {
      add[k] += x;
      return;
    }
    update(a, b, x, 2 * k + 1, l, (l + r) >> 1);
    update(a, b, x, 2 * k + 2, (l + r) >> 1, r);
    seg[k] = seg[2 * k + 1] + seg[2 * k + 2] + add[2 * k + 1] + add[2 * k + 2];
  }

  void update(int a, int b, int x)
  {
    update(a, b, x, 0, 0, sz);
  }

  long long query(int a, int b, int k, int l, int r)
  {
    if(a >= r || b <= l) return (0LL);
    if(a <= l && r <= b) return (seg[k] + add[k]);
    return (query(a, b, 2 * k + 1, l, (l + r) >> 1) +
            query(a, b, 2 * k + 2, (l + r) >> 1, r) + add[k]);
  }

  long long query(int a, int b)
  {
    return (query(a, b, 0, 0, sz));
  }
};

int main()
{
  int N, Q;
  scanf("%d %d", &N, &Q);
  SegmentTree tree(N);
  while(Q--) {
    int t;
    scanf("%d", &t);
    if(t == 0) {
      int s, t, x;
      scanf("%d %d %d", &s, &t, &x);
      tree.update(--s, t, x);
    } else {
      int s, t;
      scanf("%d %d", &s, &t);
      printf("%lld\n", tree.query(--s, t));
    }
  }
}

