class LazySegmentTreeRSQ{
private:
    std::vector<long long> node, lazy;
    int size;
public:
    LazySegmentTreeRSQ(int n){
        init(n);
    }
    void init(int n){
        size = 1;
        while(size < n)size *= 2;
        lazy = std::vector<long long>(2 * size - 1, 0);
        node = std::vector<long long>(2 * size - 1, 0);
    }
    void eval(int k, int l, int r){
        node[k] += lazy[k];

        if(r - l >= 2){
            lazy[2 * k + 1] += lazy[k] / 2;
            lazy[2 * k + 2] += lazy[k] / 2;
        }

        lazy[k] = 0;
    }
    void add(int a, int b, long long x, int k = 0, int l = 0, int r = -1){
        if(r < 0)r = size;

        eval(k, l, r);

        if(r <= a || b <= l)return;

        if(a <= l && r <= b){
            lazy[k] += x * (r - l);
            eval(k, l, r);
        }else{
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }
    long long query(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0)r = size;
        if(r <= a || b <= l)return 0;

        eval(k, l, r);

        if(a <= l && r <= b){
            return node[k];
        }else{
            long long result_left = query(a, b, 2 * k + 1, l, (l + r) / 2);
            long long result_right = query(a, b, 2 * k + 2, (l + r) / 2, r);
            return result_left + result_right;
        }
    }
};

