template <class T> struct RangeAddFenwickTree {

   vector<T> node1, node2;
   RangeAddFenwickTree (int n) : node1(n,0), node2(n,0) {}

    void add(int l, int r, T val) {
      for (int i = l; i < node1.size(); i |= i + 1) {
         node1[i] += -l * val;
         node2[i] += val;
      }
      for (int i = r; i < node1.size(); i |= i + 1) {
         node1[i] += r * val;
         node2[i] += -val;
      }
   }

   T sum(int idx) {
      T sum1 = 0, sum2 = 0;
      for (int i = idx; i >= 0; i = (i & (i + 1)) - 1) {
         sum1 += node1[i];
         sum2 += node2[i] * idx;
      }
      return sum1 + sum2;
   }

};

