template<class T>
struct Lazy_BIT {
	vector<T> x, lazy;
#define SZ(a) (a&-a)
#define LEFT(a) (a - SZ(a))
#define UP(a) (a + SZ(a))

	Lazy_BIT(int n) :x(n + 1), lazy(n + 1) {}
	T sum(int r) {
		T ret = 0;
		for (int k = r; 0 < k; k = LEFT(k)) {
			ret += lazy[k] * (r - LEFT(k)) + x[k];
			for (int cp = UP(k); LEFT(k) == LEFT(cp) && k < x.size(); cp = UP(cp)) {
				ret += lazy[cp] * (r - LEFT(cp));
			}
		}
		return ret;
	}
	void add(int r, int v) {
		for (int k = r; 0 < k; k = LEFT(k)) {
			lazy[k] += v;
			for (int cp = UP(k); LEFT(k) == LEFT(cp) && k < x.size(); cp = UP(cp)) {
				x[cp] += v * (r - LEFT(cp));
			}
		}
	}


};


