#include <bits/stdc++.h>
using namespace std;

long long segTree[300000] = {};
long long lazy[300000] = {};
int segSize = 1;

int n, q;

void init(){
  while(segSize < n) segSize *= 2;
  return;
}

void eval(int k, int l, int r){

  if(lazy[k] != 0){
    segTree[k] += lazy[k];

    if(r-l > 1){
      lazy[2*k+1] += lazy[k] / 2;
      lazy[2*k+2] += lazy[k] / 2;
    }

    lazy[k] = 0;
  }

  return;
}

void add(int a, int b, long long x, int k = 0, int l = 0, int r = -1){

  if(r == -1) r = segSize;

  eval(k,l,r);

  if(r <= a || b <= l) return;

  if(a <= l && r <= b){
    lazy[k] += (r-l) * x;
    eval(k,l,r);
  }else{
    add(a, b, x, 2*k+1, l, (l+r)/2);
    add(a, b, x, 2*k+2, (l+r)/2, r);
    segTree[k] = segTree[2*k+1] + segTree[2*k+2];
  }
  return;
}


long long getSum(int a, int b, int k = 0, int l = 0, int r = -1){
  if(r == -1) r = segSize;

  eval(k, l, r);

  if(r <= a || b <= l) return 0;
  if(a <= l && r <= b) return segTree[k];
  return getSum(a, b, 2*k+1, l, (l+r)/2) + getSum(a, b, 2*k+2, (l+r)/2, r);
}

int main(){
  cin >> n >> q;

  init();

  int p, a, b, c;
  for(int i = 0;i < q;i++){
    cin >> p;
    if(p == 0){
      cin >> a >> b >> c;
      a--; b--;
      add(a, b+1, c);
    }else{
      cin >> a >> b;
      a--; b--;
      cout << getSum(a, b+1) << endl;
    }
  }

  return 0;
}

