		lazy[i] = LAZY_INIT;
	}
}

void setLazy(int k, int x, int nodeL, int nodeR) {
	lazy[k] += x;
	sum[k] += (nodeR - nodeL) * (ll) x;
}

void push(int k, int nodeL, int nodeR) {
	if (lazy[k] == LAZY_INIT) {
		return;
	}
	int nodeM = (nodeL + nodeR) / 2;
	setLazy(k * 2 + 1, lazy[k], nodeL, nodeM);
	setLazy(k * 2 + 2, lazy[k], nodeM, nodeR);
	lazy[k] = LAZY_INIT;
}

void fix(int k) {
	sum[k] = sum[k * 2 + 1] + sum[k * 2 + 2];
}

void add(int queryL, int queryR, int x, int k = 0, int nodeL = 0,
		int nodeR = N) {
	if (queryR <= nodeL || nodeR <= queryL) {
		return;
	}
	if (queryL <= nodeL && nodeR <= queryR) {
		setLazy(k, x, nodeL, nodeR);
		return;
	}
	push(k, nodeL, nodeR);
	int nodeM = (nodeL + nodeR) / 2;
	add(queryL, queryR, x, k * 2 + 1, nodeL, nodeM);
	add(queryL, queryR, x, k * 2 + 2, nodeM, nodeR);
	fix(k);
}

ll getSum(int queryL, int queryR, int k = 0, int nodeL = 0, int nodeR = N) {
	if (queryR <= nodeL || nodeR <= queryL) {
		return 0;
	}
	if (queryL <= nodeL && nodeR <= queryR) {
		return sum[k];
	}
	push(k, nodeL, nodeR);
	int nodeM = (nodeL + nodeR) / 2;
	ll vl = getSum(queryL, queryR, k * 2 + 1, nodeL, nodeM);
	ll vr = getSum(queryL, queryR, k * 2 + 2, nodeM, nodeR);
	fix(k);
	return vl + vr;
}

