using namespace std;
long long A[N+1], T[4*N+1], lazy[4*N+1];

void build(int l, int r, int k) {
    if (l == r) {
        T[k] = A[l];
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, k * 2);
    build(mid + 1, r, k * 2 + 1);
    T[k] = T[2 * k] + T[2 * k + 1];
}
void pushdown(int k, int l, int r, int mid) {
    if (lazy[k]) {
        lazy[2*k] += lazy[k];
        lazy[2*k+1] += lazy[k];
        T[2*k] += lazy[k]*(mid-l+1);
        T[2*k+1] += lazy[k]*(r-mid);
        lazy[k] = 0;
    }
}
void updata(int L, int R, int data ,int l, int r ,int k) {
    if (L <= l && r <= R) {
        T[k] += data*(r-l+1);
        lazy[k] += data;
        return;
    }
    int mid = (l + r) / 2;
    pushdown(k, l, r, mid);
    if (mid >= L) updata(L, R, data, l, mid, 2*k);
    if (mid < R) updata(L, R, data, mid+1, r, 2*k+1);
    T[k] = T[2 * k] + T[2 * k + 1];
}
long long find(int L, int R, int l, int r, int k) {
    if (L <= l && r <= R) return T[k];
    int mid = (l + r) / 2;
    pushdown(k, l, r, mid);
    long long ans = 0;
    if (mid >= L) ans = ans + find(L, R, l, mid, k * 2);
    if (mid < R) ans = ans + find(L, R, mid + 1, r, k * 2 + 1);
    return ans;
}
int main() {
    int n, q;
    scanf("%d%d", &n, &q);
    for (int i = 0; i <= n; i++)
        A[i] = 0;
    for (int i = 0; i <= 4*n; i++)
        lazy[i] = 0;
    build(1, n, 1);
    int com, s, t, x, y;
    while (q--) {
        scanf("%d", &com);
        if (com == 0) {
            scanf("%d%d%d", &s, &t, &x);
            updata(s, t, x, 1, n, 1);
        }
        else {
            scanf("%d%d", &s, &t);
            printf("%ld\n", find(s, t, 1, n, 1));
        }
    }
    return 0;
}

