// ini：上限（下限）,base：元の配列,monoid：モノイド,tree：セグ木,depth：treeの深さ,
// basesize：baseの要素数,treesize：treeの要素数,num：treesize-basesize
// 初期値（上限とか下限）を決定
template <class num_type>
struct segtree {
    int num, depth, basesize, treesize;
    vector<num_type> base, tree, lazy;
    // #####  monoidのiniの設定  #####
    // 区間和のとき
    num_type ini = 0;
    // #####  operatorのiniの設定  #####
    // 区間加算のとき
    num_type ini_op = 0;
    // 区間更新のとき
    // num_type ini_op = pow(10, 9);
    // #####  モノイド #####
    // 区間和のとき
    num_type monoid(num_type& x, num_type& y) { return x + y; }
    // #####  lazyをスケール変換する関数 #####
    // 区間和のとき
    num_type modify(int width, num_type& value) { return width * value; }
    // #####  yにxを作用させる関数  #####
    // 区間加算のとき
    num_type operate(num_type& x, num_type& y) { return x + y; }
    // 区間更新のとき
    // num_type operate(num_type& x, num_type& y) { UNUSED(y); return x; }

    // 元の配列, モノイド, 初期値
    segtree(vector<num_type> temp) : base(temp) {
        basesize = (int)base.size();
        num = 1;
        depth = 1;
        while (num < basesize) {
            num *= 2;
            depth++;
        }
        num--;
        treesize = num * 2 + 1;
        tree.assign(treesize, ini);
        lazy.assign(treesize, ini_op);
        for (int i = num; i < num + basesize; i++) { tree[i] = base[i - num]; }
        for (int i = num + basesize; i < treesize; i++) { tree[i] = ini; }
        for (int i = num - 1; i > -1; i--) {
            tree[i] = monoid(tree[2 * i + 1], tree[2 * i + 2]);
        }
    }
    // modifyとoperateを同時に行う関数
    num_type mod_op(int width, int node) {
        if (lazy[node] != ini_op) {
            num_type temp = modify(width, lazy[node]);
            return operate(temp, tree[node]);
        } else {
            return tree[node];
        }
    }
    // 半開区間[lower,upper)の最小値（とか）を探す関数
    num_type search(int lower, int upper) {
        num_type ret = ini, temp;
        vector<tuple<int, int, int>> stack(1, make_tuple(0, num + 1, 0));
        int l, r, m, node;
        while (stack.size()) {
            tie(l, r, node) = stack.back();
            stack.pop_back();
            m = (l + r) / 2;
            if (lower <= l && r <= upper) {
                temp = mod_op(r - l, node);
                ret = monoid(ret, temp);
            } else {
                eval(l, r, node);
                if (upper <= m) {
                    stack.push_back(make_tuple(l, m, node * 2 + 1));
                } else if (m <= lower) {
                    stack.push_back(make_tuple(m, r, node * 2 + 2));
                } else {
                    stack.push_back(make_tuple(l, m, node * 2 + 1));
                    stack.push_back(make_tuple(m, r, node * 2 + 2));
                }
            }
        }
        return ret;
    }
    // 葉方向に伝播させる関数
    void eval(int& l, int& r, int& node) {
        if (lazy[node] != ini_op) {
            if (2 * node + 1 < treesize) {
                if (num <= node * 2 + 1) {
                    tree[node * 2 + 1] =
                        operate(lazy[node], tree[node * 2 + 1]);
                    tree[node * 2 + 2] =
                        operate(lazy[node], tree[node * 2 + 2]);
                } else {
                    lazy[node * 2 + 1] =
                        operate(lazy[node], lazy[node * 2 + 1]);
                    lazy[node * 2 + 2] =
                        operate(lazy[node], lazy[node * 2 + 2]);
                }
            }
            num_type temp = modify(r - l, lazy[node]);
            tree[node] = operate(temp, tree[node]);
            lazy[node] = ini_op;
        }
    }
    // base[l:r)をsに更新してセグ木全体を更新する関数
    void update(int lower, int upper, num_type new_value) {
        vector<tuple<int, int, int>> stack(1, make_tuple(0, num + 1, 0));
        set<tuple<int, int>> nodeset;
        int l, r, m, node, parent, width;
        num_type value;
        while (stack.size()) {
            tie(l, r, node) = stack.back();
            stack.pop_back();
            m = (l + r) / 2;
            width = r - l;
            if (lower <= l && r <= upper) {
                lazy[node] = operate(new_value, lazy[node]);
                value = modify(width, new_value);
                if (node != 0) {
                    parent = (node - 1) / 2;
                    nodeset.insert(make_tuple(parent, width));
                }
                if (width == 1) {
                    value = modify(width, value);
                    tree[node] = operate(value, tree[node]);
                    lazy[node] = ini_op;
                }
            } else {
                eval(l, r, node);
                if (upper <= m) {
                    stack.push_back(make_tuple(l, m, node * 2 + 1));
                } else if (m <= lower) {
                    stack.push_back(make_tuple(m, r, node * 2 + 2));
                } else {
                    stack.push_back(make_tuple(l, m, node * 2 + 1));
                    stack.push_back(make_tuple(m, r, node * 2 + 2));
                }
            }
        }
        // DEBUG(tree, lazy);
        num_type tmp1, tmp2;
        while (nodeset.size()) {
            tie(node, width) = *rbegin(nodeset);
            nodeset.erase(make_tuple(node, width));
            // PRINT(node, width);
            tmp1 = mod_op(width, node * 2 + 1);
            tmp2 = mod_op(width, node * 2 + 2);
            tree[node] = monoid(tmp1, tmp2);
            if (node != 0) {
                nodeset.insert(make_tuple((node - 1) >> 1, width << 1));
            }
        }
        // DEBUG(tree, lazy);
    }
};

