struct LazySegmentTree{
	int n;
	vector<ll> node,lazy;

	LazySegmentTree(int sz){
		n=1;
		while(sz>n) n<<=1;
		node.assign(2*n,0);
		lazy.assign(2*n,0);
	}

	void eval(int k,int l,int r){
		if(lazy[k]){
			node[k]+=lazy[k];
			if(r-l>1){
				lazy[2*k]+=lazy[k]/2;
				lazy[2*k+1]+=lazy[k]/2;
			}
			lazy[k]=0;
		}
	}

	void add(int a,int b,ll x,int k=1,int l=0,int r=-1){
		if(r<0) r=n;
		eval(k,l,r);
		if(r<=a||b<=l) return;
		if(a<=l&&r<=b){
			lazy[k]+=(r-l)*x;
			eval(k,l,r);
		}
		else{
			add(a,b,x,2*k,l,(l+r)/2);
			add(a,b,x,2*k+1,(l+r)/2,r);
			node[k]=node[2*k]+node[2*k+1];
		}
	}

	ll getSum(int a,int b,int k=1,int l=0,int r=-1){
		if(r<0) r=n;
		eval(k,l,r);
		if(r<=a||b<=l) return 0;
		if(a<=l&&r<=b) return node[k];
		ll vl=getSum(a,b,2*k,l,(l+r)/2);
		ll vr=getSum(a,b,2*k+1,(l+r)/2,r);
		return vl+vr;
	}
};

