using namespace std;
typedef long long ll;
const int maxn=400005;

struct {
	ll sum,lazy;	
} S[maxn];
int n,q;

void update(int id,int ql,int qr,int v,int l,int r) {
	if (ql==l && qr==r) {
		S[id].lazy+=v;
		return;
	}
	if (S[id].lazy) {
		S[id].sum+=S[id].lazy*(r-l+1);
		if (l!=r) {
			S[id<<1].lazy+=S[id].lazy;
			S[id<<1|1].lazy+=S[id].lazy;
		}
		S[id].lazy=0;
	}
	int m=l+r>>1;
	if (qr<=m) update(id<<1,ql,qr,v,l,m);
	else if (ql>m) update(id<<1|1,ql,qr,v,m+1,r);
	else update(id<<1,ql,m,v,l,m), update(id<<1|1,m+1,qr,v,m+1,r);
	S[id].sum=S[id<<1].sum+S[id<<1|1].sum+S[id<<1].lazy*(m-l+1)+S[id<<1|1].lazy*(r-m);
}

ll query(int id,int ql,int qr,int l,int r) {
	if (S[id].lazy) {
		S[id].sum+=S[id].lazy*(r-l+1);
		if (l!=r) {
			S[id<<1].lazy+=S[id].lazy;
			S[id<<1|1].lazy+=S[id].lazy;
		}
		S[id].lazy=0;
	}
	int m=l+r>>1;
	if (ql==l && qr==r) return S[id].sum;
	if (qr<=m) return query(id<<1,ql,qr,l,m);
	else if (ql>m) return query(id<<1|1,ql,qr,m+1,r);
	else return query(id<<1,ql,m,l,m)+query(id<<1|1,m+1,qr,m+1,r);
}

