class SquareDivision{
    private:
        const int bucketSize = 256;
        ll N, B;
        vector<ll> data;
        vector<ll> bucketSum;
        vector<ll> bucketAdd;

    public:
        void prepare(int n){
            B = (n + bucketSize - 1)/ bucketSize;
            N = B * bucketSize;
            data.assign(N, 0);
            bucketSum.assign(B, 0);
            bucketAdd.assign(B, 0);
        }

        void add(int s, int t, int x){
            for(int k=0; k<B; k++){
                int l = k * bucketSize;
                int r = (k + 1) * bucketSize;

                if(r <= s || t <= l) continue;

                if(s <= l && r <= t){
                    bucketAdd[k] += x;
                }
                else{
                    for(int i=max(s, l); i<min(t, r); i++){
                        data[i] += x;
                        bucketSum[k] += x;
                    }
                }
            }
        }

        ll getsum(int s, int t){
            ll sum=0;
            for(int k=0; k<B; k++){
                int l = k * bucketSize;
                int r = (k + 1) * bucketSize;

                if(r <= s || t <= l) continue;

                if(s <= l && r <= t){
                    sum += bucketSum[k] + bucketAdd[k] * bucketSize;
                }
                else{
                    for(int i=max(s, l); i<min(t, r); i++){
                        sum += data[i] + bucketAdd[k];
                    }
                }
            }

            return sum;
        }
};

