    lazy.resize(2 * N - 1);
  }
  // k番目のノードにのlazyを伝搬
  void eval(int k) {
    if (lazy[k] == 0) return;
    node[k] += lazy[k];
    if (k < N - 1) {
      // 最下段でなければ下のlazyに伝搬
      lazy[2 * k + 1] += lazy[k] / 2;
      lazy[2 * k + 2] += lazy[k] / 2;
    }
    lazy[k] = 0;
  }
  // k番目のノード[l, r)について、[a, b)にxを加算
  void add(int a, int b, int x, int k, int l, int r) {
    eval(k);
    if (b <= l || r <= a) return;
    if (a <= l && r <= b) {
      lazy[k] += (r - l) * x;
      eval(k);
    } else {
      add(a, b, x, 2 * k + 1, l, (l + r) / 2);
      add(a, b, x, 2 * k + 2, (l + r) / 2, r);
      node[k] = node[2 * k + 1] + node[2 * k + 2];
    }
  }
  // [a, b)にxを加算
  void add(int a, int b, int x) {
    add(a, b, x, 0, 0, N);
  }
  // k番目のノード[l, r)について、[a, b)のクエリを求める
  int query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return 0;
    eval(k);
    if (a <= l && r <= b) return node[k];
    int vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
    int vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
    return vl + vr;
  }
  // [a, b)
  int query(int a, int b) {
    return query(a, b, 0, 0, N);
  }
};
signed main() {
  int n, q; cin >> n >> q;
  SegmentTree seg(n);
  while (q--) {
    int z; cin >> z;
    if (z == 0) {
      int s, t, x; cin >> s >> t >> x;
      seg.add(s - 1, t, x);
    } else {
      int s, t; cin >> s >> t;
      cout << seg.query(s - 1, t) << endl;
    }
  }
}

