struct BIT{ //1-indexed
    vector<T> bit;
    int size;
    BIT(int n):size(n), bit(n+1, 0){}
    T sum(int i){
        T s=0;
        while(i>0){
            s+=bit[i];
            i-=(i&(-i));
        }
        return s;
    }
    void add(int i, T x){
        while(i<=size){
            bit[i]+=x;
            i+=(i&(-i));
        }
    }
};
template<typename T>
struct RangeAddRangeSum{
	int n;
	BIT<T> bit, bit2;
	RangeAddRangeSum(int n):n(n), bit(n), bit2(n){}
	void add(int l, int r, const T &x){
		bit.add(l+1, x);
		bit.add(r+1, -x);
		bit2.add(l+1, l*x);
		bit2.add(r+1, -r*x);
	}
	T sum(int r){
		return r*bit.sum(r)-bit2.sum(r);
	}
	T sum(int l, int r){
		return sum(r)-sum(l);
	}
};
