using namespace std;
struct SegTree {
	int size;
	int *dat,*lazy;
	SegTree(int n) {
		size=1;
		while(size<n) size*=2;
		dat=(int*)malloc(sizeof(int)*(size*2-1));
		fill(dat,dat+(size*2-1),0);
		lazy=(int*)malloc(sizeof(int)*(size*2-1));
		fill(lazy,lazy+(size*2-1),0);
	}
	void eval(int k,int len) {
		dat[k]+=lazy[k]*len;
		if(k<size-1) lazy[k*2+1]+=lazy[k],lazy[k*2+2]+=lazy[k];
		lazy[k]=0;
	}
	void add(int a,int b,int  x,int k,int l,int r) {
		eval(k,r-l);
		if(r<=a||b<=l) return;
		if(a<=l&&r<=b) {
			lazy[k]+=x;
			eval(k,r-l);
		}else {
			add(a,b,x,k*2+1,l,(l+r)/2);
			add(a,b,x,k*2+2,(l+r)/2,r);
			dat[k]=dat[k*2+1]+dat[k*2+2];
		}
	}
	int sum(int a,int b,int k,int l,int r) {
		eval(k,r-l);
		if(r<=a||b<=l) return 0;
		if(a<=l&&r<=b) return dat[k];
		return sum(a,b,k*2+1,l,(l+r)/2)+sum(a,b,k*2+2,(l+r)/2,r);
	}
};
int main() {
	int n,q;
	scanf("%d %d",&n,&q);
	SegTree S(n);
	for(int i=0;i<q;i++) {
		int type,s,t,x;
		scanf("%d",&type);
		if(type==0) {
			scanf("%d %d %d",&s,&t,&x);s--;
			S.add(s,t,x,0,0,S.size);
		}else {
			scanf("%d %d",&s,&t);s--;
			printf("%d\n",S.sum(s,t,0,0,S.size));
		}
	}
}

