template<class T>
class rangefenwick{
	private:
		int n;
		vector<T>f1,f2;
		void add1(int p,T x){
			while(p<=n){
				f1[p]+=x;
				p+=(p&-p);
			}
		}
		void add2(int p,T x){
			while(p<=n){
				f2[p]+=x;
				p+=(p&-p);
			}
		}
		T sum1(int p){
			T x=T();
			while(p>0){
				x+=f1[p];
				p-=(p&-p);
			}
			return x;
		}
		T sum2(int p){
			T x=T();
			while(p>0){
				x+=f2[p];
				p-=(p&-p);
			}
			return x;
		}
	public:
		rangefenwick(int n):n(n),f1(n+1),f2(n+1){}
		void update(int l,int r,T x){
			add1(l,x);
			add1(r+1,-x);
			add2(l,x*(l-1));
			add2(r+1,-x*r);
		}
		void update(int p,T x){
			update(p,p,x);
		}
		T query(int p){
			return sum1(p)*p-sum2(p);
		}
		T query(int l,int r){
			return query(r)-query(l-1);
		}
};
