const int DEFAULT = 0;

const int NIL = -1;

typedef long long ll;

struct Node {
    ll sum;
    ll lazy;
    int lchild;
    int rchild;
    Node(int sum = 0, int lazy = 0, int lchild = NIL, int rchild = NIL)
            :sum(sum), lazy(lazy), lchild(lchild), rchild(rchild) {
    }
};


struct SegmentTree {

    vector<Node> heap;
    int rootId;
    int lrange;
    int rrange;

    SegmentTree(int rootId, int lrange, int rrange) 
        : rootId(rootId), lrange(lrange), rrange(rrange) {
        heap.assign(rootId + 1, Node());
    }

    void add(int ql, int qr, int inc) {
        add(rootId, lrange, rrange, ql, qr, inc);
    }

    ll query(int ql, int qr) {
        return query(rootId, lrange, rrange, ql, qr);
    }

    void add(int nodeId, int l, int r, int ql, int qr, int inc) {
        if (qr < l || ql > r) {
            return;
        } else if (ql <= l && r <= qr) {
            heap[nodeId].lazy += inc;
        } else {
            pushDown(nodeId, l, r);
            int m = l + (r - l) / 2;
            add(heap[nodeId].lchild, l, m, ql, qr, inc);
            add(heap[nodeId].rchild, m + 1, r, ql, qr, inc);
            pullUp(nodeId, l, r);
        }
    }

    void pushDown(int nodeId, int l, int r) {    
        ensureChildren(nodeId);

        Node& node = heap[nodeId];
        if (node.lazy > 0) {
            heap[node.lchild].lazy += node.lazy;
            heap[node.rchild].lazy += node.lazy;

            heap[nodeId].sum = evalSum(nodeId, l, r);
            heap[nodeId].lazy = 0;
        }
    }

    void pullUp(int nodeId, int l, int r) {
        int m = l + (r - l) / 2;
        heap[nodeId].sum = evalSum(heap[nodeId].lchild, l, m) + evalSum(heap[nodeId].rchild, m + 1, r);
    }

    ll evalSum(int nodeId, int l, int r) {
        return heap[nodeId].lazy * (r - l + 1) + heap[nodeId].sum;
    }

    ll query(int nodeId, int l, int r, int ql, int qr) {
        if (qr < l || ql > r) {
            return DEFAULT;
        }
        if (ql <= l && r <= qr) {
            return evalSum(nodeId, l, r);
        }
        else {
            pushDown(nodeId, l, r);
            int m = l + (r - l) / 2;
            return query(heap[nodeId].lchild, l, m, ql, qr) +
                    query(heap[nodeId].rchild, m + 1, r, ql, qr);
        }
    }

    void ensureChildren(int nodeId) {
        if (heap[nodeId].lchild == NIL) {
            heap.push_back(Node());
            heap[nodeId].lchild = heap.size() - 1;
        }
        if (heap[nodeId].rchild == NIL) {
            heap.push_back(Node());
            heap[nodeId].rchild = heap.size() - 1;
        } 
    }
};

int main() {
    int n, q;
    cin >> n >> q;
    SegmentTree st(1, 1, n);
