// LazyAddSegmentTree
template<typename T>
class LazyAddSegTree{
public:
    int n;
    T defaultValue;
    vector<T> dat;
    vector<T> lazy;

    LazyAddSegTree(vector<T>& v, T value){
        n = 1;
        int vSize = (int)v.size();
        while(n < vSize){
            n *= 2;
        }
        dat.assign(2 * n - 1, value);
        lazy.assign(2 * n - 1, 0);
        defaultValue = value;

        for(int i = 0; i < vSize; i++){
            dat[i + n - 1] = v[i];
        }
        for(int i = n - 2; i >= 0; i--){
            dat[i] = ope(dat[2 * i + 1], dat[2 * i + 2]);
        }
    }

    T add(int a, int b, T value, int k = 0, int l = 0, int r = -1){
        if(r < 0){
            r = n;
        }
        propagate(k);

        if(r <= a || b <= l){
            return dat[k];
        }

        if(a <= l && r <= b){
            lazy[k] += lazyPlus(value, l, r);
            propagate(k);
            return dat[k];
        }
        else{
            T vl = add(a, b, value, 2 * k + 1, l, (l + r) / 2);
            T vr = add(a, b, value, 2 * k + 2, (l + r) / 2, r);
            dat[k] = ope(vl, vr);
            return dat[k];
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0){
            r = n;
        }

        if(r <= a || b <= l){
            return defaultValue;
        }
        propagate(k);

        if(a <= l && r <= b){
            return dat[k];
        }
        else{
            T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
            T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
            return ope(vl, vr);
        }
    }

private:

    void propagate(int k){
        if(lazy[k] != 0){
            dat[k] += lazy[k];
            if(k <= n - 2){
                T value = lazyPropPlus(lazy[k]);
                lazy[2 * k + 1] += value;
                lazy[2 * k + 2] += value;
            }

            lazy[k] = defaultValue;
        }
    }

    T ope(T a, T b){
        return a + b;
    }

    T lazyPlus(T value, int l, int r){
        return (r - l) * value;
    }

    T lazyPropPlus(T value){
        return value / 2;
    }
};

int main(){

    int n, q;
    cin >> n >> q;

    vector<long long> v(n, 0);
    LazyAddSegTree<long long> lazySegTree(v, 0);

    for(int loop = 0; loop < q; loop++){
        int com;
        cin >> com;
        if(com == 0){
            int s, t, x;
            cin >> s >> t >> x;
            lazySegTree.add(s - 1, t, x);
        }
        else{
            int s, t;
            cin >> s >> t;
            cout << lazySegTree.query(s - 1, t) << endl;
        }
    }

    return 0;
}

