namespace RandomizedBinarySearchTree {
  struct Node;
  using Tree = Node*;
  struct Node {
    lint val, sum, laz;
    Tree cl, cr;
    int n;
    Node() {}
    Node(lint v);
    Node(lint v, Tree cl, Tree cr) :
      val(v), sum(cl->sum + v + cr->sum), laz(0), cl(cl), cr(cr), n(cl->n + 1 + cr->n) {}
  };
  Tree nil = new Node();
  Node::Node(lint v) :
    val(v), sum(v), laz(0), cl(nil), cr(nil), n(1) {}

  Tree update(Tree t) {
    t->sum = t->cl->sum + t->val + t->cr->sum;
    t->n = t->cl->n + 1 + t->cr->n;
    return t;
  }

  void push(Tree t) {
    t->cl->val += t->laz;
    t->cl->sum += t->laz * t->cl->n;
    t->cl->laz += t->laz;
    t->cr->val += t->laz;
    t->cr->sum += t->laz * t->cr->n;
    t->cr->laz += t->laz;
    t->laz = 0;
  }

  Tree merge(Tree tl, Tree tr) {
    if (tr == nil) return tl;
    if (tl == nil) return tr;
    if (rng(0, tl->n + tr->n) < tl->n) {
      push(tl);
      return new Node(tl->val, tl->cl, merge(tl->cr, tr));
    } else {
      push(tr);
      return new Node(tr->val, merge(tl, tr->cl), tr->cr);
    }
  }

  pair<Tree, Tree> split(Tree t, int i) {
    if (t == nil) return {nil, nil};
    push(t);
    if (i <= t->cl->n) {
      Tree resl, resr;
      tie(resl, resr) = split(t->cl, i);
      resr = new Node(t->val, resr, t->cr);
      return {resl, resr};
    } else {
      Tree resl, resr;
      tie(resl, resr) = split(t->cr, i - t->cl->n - 1);
      resl = new Node(t->val, t->cl, resl);
      return {resl, resr};
    }
  }

  Tree insert(Tree t, int i, lint v) {
    Tree tl, tr;
    tie(tl, tr) = split(t, i);
    return merge(merge(tl, new Node(v)), tr);
  }

  Tree erase(Tree t, int i) {
    Tree tl, tr;
    tie(tl, tr) = split(t, i);
    tr = split(tr, 1).second;
    return merge(tl, tr);
  }
}

