class LazyBucket{
  public:
  vector<ll> buc,v,s;
  ll N,sqn,K;
  LazyBucket(){};
  LazyBucket(ll n){
    N = n;
    sqn = sqrt(N);
    K = (n + sqn - 1) /sqn;
    buc.assign(K,0);
    s.assign(K,0);
    v.assign(K * sqn,0);
  }
  ll getSum(int x,int y){
    ll res = 0;
    for (int k = 0; k < K; ++k) {
      int l = k * sqn, r = (k + 1) * sqn;
      if (r <= x || y <= l)
        continue;
      if (x <= l && r <= y) {
        res += s[k] + buc[k] * sqn;
      } else {
        lazyupdate(k);
        for (int i = max(x, l); i < min(y, r); ++i) {
          res += v[i] + buc[k];
        }
      }
    }
    return res;
  }
  void lazyupdate(int k){
    if(k >= K) return ;
    if(buc[k] != 0){
      for(int i = k * sqn; i < (k+1) * sqn;++i){
        v[i] += buc[k];
        s[k] += buc[k];
      }
    }
    buc[k] = 0;
  }
  void add(ll x,ll y,ll n){
    for (ll k = 0; k < K; ++k) {
      ll l = k * sqn, r = (k + 1) * sqn;
      if (r <= x || y <= l)
        continue;
      if (x <= l && r <= y) {
        buc[k] += n;
      }
      else {
        lazyupdate(k);
        for (int i = max(x, l); i < min(y, r); ++i) {
          v[i] += n;
          s[k] += n;
        }
      }
    }
  }
  void Debug(){
    cout << "sqn " << sqn << endl;
    for(int i = 0; i < N;++i){
      cout << buc[i/sqn] << ' ';
    }
    cout << endl;
    for(int i = 0; i < N;++i){
      cout << s[i/sqn] << ' ';
    }
    cout << endl;
    for(int i = 0; i < N;++i){
      cout << v[i] << ' ';
    }
    cout << endl;
  }
};

