struct segtree{
	int size;
	vector<int> dat,lazy;
	segtree(int n){
		size = 1;
		while(size<n) size *= 2;
		dat.assign(2*size-1,0);
		lazy.assign(2*size-1,0);
	}
	void lazy_evaluate(int k,int l,int r){
		dat[k] += lazy[k] * (r - l);
		if(k<size-1){
			lazy[2*k+1] += lazy[k];
			lazy[2*k+2] += lazy[k];
		}
		lazy[k] = 0;
	}
	void update(int a,int b,int x,int k,int l,int r){
		lazy_evaluate(k,l,r);
		if(b<=l||r<=a) return;
		else if(a<=l&&r<=b){
			lazy[k] += x;
			lazy_evaluate(k,l,r);
		}
		else{
			update(a,b,x,2*k+1,l,(l+r)/2);
			update(a,b,x,2*k+2,(l+r)/2,r);
			dat[k] = dat[2*k+1] + dat[2*k+2];
		}
	}
	void update(int a,int b,int x){
		update(a-1,b,x,0,0,size);
	}
	int sum(int a,int b,int k,int l,int r){
		lazy_evaluate(k,l,r);
		if(b<=l||r<=a) return 0;
		else if(a<=l&&r<=b) return dat[k];
		else{
			int vl = sum(a,b,2*k+1,l,(l+r)/2);
			int vr = sum(a,b,2*k+2,(l+r)/2,r);
			return vl + vr;
		}
	}
	int sum(int a,int b){
		return sum(a-1,b,0,0,size);
	}
};

