ll a[200005];
const int N = 1 << 18;
ll tree[2 * N];
ll lazy[2 * N];

void upd(int node)
{
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

void apply(ll val, int node, int p, int q)
{
    lazy[node] += val;
    tree[node] += 1ll * (q - p + 1) * val;
}

void prop(int node, int p, int q)
{
    if (node >= N)
        return;

    int mid = (p + q) / 2;
    apply(lazy[node], 2 * node, p, mid);
    apply(lazy[node], 2 * node + 1, mid + 1, q);
    lazy[node] = 0;
}

void update(int l, int r, ll val, int node = 1, int p = 1, int q = N)
{
    if (q < l || p > r)
        return;

    if (p >= l && q <= r)
    {
        apply(val, node, p, q);
        return;
    }

    int mid = (p + q) / 2;
    prop(node, p, q);
    update(l, r, val, 2 * node, p, mid);
    update(l, r, val, 2 * node + 1, mid + 1, q);
    upd(node);
}

ll query(int l, int r, int node = 1, int p = 1, int q = N)
{
    if (q < l || p > r)
        return 0;

    if (p >= l && q <= r)
        return tree[node];

    int mid = (p + q) / 2;
    prop(node, p, q);
    return query(l, r, 2 * node, p, mid) +
        query(l, r, 2 * node + 1, mid + 1, q);
}

