const int MAXN = 100110;
long long tree[4*MAXN], lazy[4*MAXN];

void push(int node, int start, int end, long long val){
	tree[node] += (end - start + 1) * val;
	if(start != end){
		lazy[2*node] += val;
		lazy[2*node+1] += val;
	}
}

void updateRange(int node, int start, int end, int l, int r, long long val){
	if(lazy[node]){
		push(node, start, end, lazy[node]);
		lazy[node] = 0;
	}
	if(start > end or start > r or end < l) return;
	if(l <= start and end <= r){
		push(node, start, end, val);
		return;
	}
	int mid = (start + end)/2;
	updateRange(2*node, start, mid, l, r, val);
	updateRange(2*node+1, mid+1, end, l, r, val);
	tree[node] = tree[2*node] + tree[2*node+1];
}

int queryRange(int node, int start, int end, int l, int r){
	if(start > end or start > r or end < l) return 0;
	if(lazy[node]){
		push(node, start, end, lazy[node]);
		lazy[node] = 0;
	}
	if(l <= start and end <= r) return tree[node];
	int mid = (start + end)/2;
	int p1 = queryRange(2*node, start, mid, l, r);
	int p2 = queryRange(2*node+1, mid+1, end, l, r);
	return p1 + p2;
}

