      seg.resize(2*N-1, 0);
      lazy.resize(2*N-1, 0);
   }

   void update(int i, int l, int r){
      if(lazy[i]){
         seg[i]+=lazy[i]*(r-l);
         if(r-l>1){
            lazy[2*i+1]+=lazy[i];
            lazy[2*i+2]+=lazy[i];
         }
         lazy[i]=0;
      }
   }

   void add(int a, int b, int x, int i=0, int l=0, int r=N){
      //update(i, l, r);
      if(b<=l or r<=a){
         return;
      }else if(a<=l and r<=b){
         lazy[i]+=x;
         update(i, l, r);
      }else{
         //update(i, l, r);
         int m=(r+l)/2;
         add(a, b, x, 2*i+1, l, m);
         add(a, b, x, 2*i+2, m, r);
         seg[i]=seg[2*i+1]+seg[2*i+2];
      }
   }

   int sum(int a, int b, int i=0, int l=0, int r=N){
      //update(i, l, r);
