	LazySegTree(int _n) {
		n = 1;
		while (n < _n) {
			n *= 2;
		}
		dat = vector<ll>(2 * n - 1, def);
		lazy = vector<ll>(2 * n - 1, NIL);
		depth = vector<int>(2 * n - 1);
		width = vector<int>(2 * n - 1);
		depth[0] = 0;
		width[0] = n;
		repl(i, 1, 2 * n - 1) {
			depth[i] = depth[(i - 1) / 2] + 1;
			width[i] = width[(i - 1) / 2] / 2;
		}
	}

	// ????????????????????????k???Lazy???v????????????
	void setLazy(int k, int v) {
		if (lazy[k] == NIL) {
			lazy[k] = v;
		}
		else {
			lazy[k] += v;
		}

		// min,max?????´???
		//dat[k] += v;

		// sum?????´???
		dat[k] = lazy[k] * width[k];
	}

	void push(int k) {
		//cout << "push: " << k << endl;
		if (lazy[k] == NIL)return;
		setLazy(k * 2 + 1, lazy[k]);
		setLazy(k * 2 + 2, lazy[k]);
		lazy[k] = NIL;
	}

	// ??????[a,b)???v????¶????
	void rangeAdd(int a, int b, int v, int k = 0, int l = 0, int r = -1) {
		if (r == -1)r = n;
		if (r <= a || b <= l)return;  // ???????????????
		if (a <= l && r <= b) {   // a,l,r,b????????§?????¨???????????????
			setLazy(k, v);
			return;
		}

		push(k);

		rangeAdd(a, b, v, 2 * k + 1, l, (l + r) / 2);    // ?????????
		rangeAdd(a, b, v, 2 * k + 2, (l + r) / 2, r);    // ?????????

		dat[k] = operation(dat[k * 2 + 1], dat[k * 2 + 2]);
	}

	// ??´???i(0-indexed)???x????¶????
	void add(int i, ll x) {
		i += n - 1;
		dat[i] += x;
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] += x;
		}
	}

	// ??´???i(0-indexed)?????????x?????´??°
	void change(int i, ll x) {
		i += n - 1;
		dat[i] = x;
		while (i > 0) {
			i = (i - 1) / 2;
			dat[i] = operation(dat[i * 2 + 1], dat[i * 2 + 2]);
		}
	}

	// ??????[a,b)?????????????????????k=[l,r)????????????????????????
	ll _query(int a, int b, int k, int l, int r) {
