		if (a <= l && r <= b)return dat[k];   // a,l,r,b????????§?????¨???????????????

		push(k);

		ll c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2);    // ?????????
		ll c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r);    // ?????????
		return operation(c1, c2);
	}

	// ?????¨?????¨???_query()???????????????
	ll query(int a, int b) {
