template <class Monoid, class OperatorMonoid>
struct Segtree {
    using T = typename Monoid::T;
    using E = typename OperatorMonoid::E;
    int n, h;
    vector<T> dat;
    vector<E> laz;
    vector<ll> len;
    Segtree(int n_) {
        n = 1, h = 0;
        while(n < n_) {
            n <<= 1;
            h++;
        }
        dat.resize(2 * n, Monoid::id());
        laz.resize(2 * n, OperatorMonoid::id());
        len.resize(2 * n, 1);
        for(int i = n - 1; i > 0; i--) {
            len[i] = len[i << 1] + len[i << 1 | 1];
        }
    }
    inline T reflect(int k) {
        if(laz[k] == OperatorMonoid::id()) {
            return dat[k];
        }
        return OperatorMonoid::merge(dat[k], laz[k], len[k]);
    }
    inline void prop(int k) {
        if(laz[k] == OperatorMonoid::id()) {
            return;
        }
        laz[k << 1] = OperatorMonoid::op(laz[k << 1], laz[k]);
        laz[k << 1 | 1] = OperatorMonoid::op(laz[k << 1 | 1], laz[k]);
        dat[k] = reflect(k);
        laz[k] = OperatorMonoid::id();
    }
    inline void down(int k) {
        for(int i = h; i > 0; i--) {
            prop(k >> i);
        }
    }
    inline void up(int k) {
        while(k >>= 1) {
            dat[k] = Monoid::op(reflect(k << 1), reflect(k << 1 | 1));
        }
    }
    void update(int a, int b, const E& x) {  //[a,b]->[a,b)
        int l = a + n, r = b + n;
        down(l);
        down(r);
        for(++r; l < r; l >>= 1, r >>= 1) {
            if(l & 1) {
                laz[l] = OperatorMonoid::op(laz[l], x);
                l++;
            }
            if(r & 1) {
                --r;
                laz[r] = OperatorMonoid::op(laz[r], x);
            }
        }
        l = a + n, r = b + n;
        up(l);
        up(r);
    }
    T query(int a, int b) {  //[a,b]->[a,b)
        int l = a + n, r = b + n;
        down(l);
        down(r);
        T vl = Monoid::id(), vr = Monoid::id();
        for(++r; l < r; l >>= 1, r >>= 1) {
            if(l & 1) {
                vl = Monoid::op(vl, reflect(l++));
            }
            if(r & 1) {
                vr = Monoid::op(reflect(--r), vr);
            }
        }
        return Monoid::op(vl, vr);
    }
};
template <class U>
struct RangeSum {
    using T = U;
    static T op(const T& a, const T& b) { return a + b; }
    static constexpr T id() { return 0; }
};
template <class V>
struct RangeAdd {
    using E = V;
    static E op(const E& a, const E& b) { return a + b; }
    template <typename T>
    static T merge(const T& a, const E& b, const ll& len) {
        return a + b * len;
    }
    static constexpr E id() { return 0; }
};
