template<typename T, typename E>
struct SegmentTree {
    using F = function<T(T, T)>;
    using G = function<T(T, E)>;
    using H = function<E(E, E)>;
    int n, height;
    F fvv;//(v, v)
    G fvl;//(v, l, len)
    H fll;//(l, l)
    T ve; //演算における単位元
    E le; //作用素に対しての単位元
    vector<T> dat;
    vector<E> laz;
    vi len;
    SegmentTree(F fvv, G g, H h, T ti, E ei) : fvv(fvv), fvl(g), fll(h), ve(ti), le(ei) {}

    void init(int n_) {
        n = 1;
        height = 0;
        while (n < n_) n <<= 1, height++;
        dat.assign(n << 1, ve);
        laz.assign(n << 1, le);
        len.assign(n << 1, 0);
        int l = 1, v = n;
        rep(i, 1, n << 1) {
            if ((l << 1) == i) {
                l <<= 1;
                v >>= 1;
            }
            len[i] = v;
        }
    }
    void build(const vector<T> &v) {
        int n_ = v.size();
        init(n_);
        for (int i = 0; i < n_; i++) dat[n + i] = v[i];
        for (int i = n - 1; i; i--)
            dat[i] = fvv(dat[(i << 1) | 0], dat[(i << 1) | 1]);
    }
    //おそらく1-indexed
    inline T reflect(int k) {
        return laz[k] == le ? dat[k] : fvl(dat[k], laz[k]);
    }
    inline void eval(int k) {
        if (laz[k] == le) return;
        laz[(k << 1) | 0] = fll(laz[(k << 1) | 0], laz[k]);
        laz[(k << 1) | 1] = fll(laz[(k << 1) | 1], laz[k]);
        dat[k] = reflect(k);
        laz[k] = le;
    }
    inline void thrust(int k) {
        for (int i = height; i; i--) eval(k >> i);
    }
    inline void recalc(int k) {
        while (k >>= 1)dat[k] = fvv(reflect((k << 1) | 0), reflect((k << 1) | 1));
    }
    void update(int a, int b, E x) {
        thrust(a += n);
        thrust(b += n - 1);
        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) laz[l] = fll(laz[l], x), l++;
            if (r & 1) --r, laz[r] = fll(laz[r], x);
        }
        recalc(a);
        recalc(b);
    }
    void set_val(int a, T x) {
        thrust(a += n);
        dat[a] = x;
        laz[a] = le;
        recalc(a);
    }
    T query(int a, int b) {
        thrust(a += n);
        thrust(b += n - 1);
        T vl = ve, vr = ve;
        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) vl = fvv(vl, reflect(l++));
            if (r & 1) vr = fvv(reflect(--r), vr);
        }
        return fvv(vl, vr);
    }
    void debu() {
        rep(i, n) {
            cout << query(i, i + 1) << " ";
        }
        cout << "" << endl;
    }
};


signed main() {
    int n, q;
    cin >> n >> q;

    auto f = [](P a, P b) { return P(a.first + b.first, a.second + b.second); };
    auto g = [](P a, int b) { return P(a.first + b * a.second, a.second); };
    auto h = [](int a, int b) { return a + b; };

    SegmentTree<P, int> ch(f, g, h, P(0, 0), 0);
    ch.build(vector<P>(n, P(0, 1)));
    for (int i = 0; i < q; i++) {
        int c, s, t, x;
        cin >> c;
        if (c) {
            cin >> s >> t;
            cout << ch.query(s - 1, t).first << endl;
            rep(i, 20) {
                ch.query(s - 1, t);
            }
        } else {
            cin >> s >> t >> x;
            ch.update(s - 1, t, x);
            rep(i, 10) {
                ch.update(s - 1, t, x);
                ch.update(s - 1, t, -x);
            }
        }
    }

    return 0;
}

