using namespace std;
typedef long long ll;

const int MAX_N = 1 << 17;

class LazySegTree{
private:
    ll dat[2*MAX_N - 1];
    ll lazy[2*MAX_N - 1];
public:
    int n;
    LazySegTree(int n);
    void add(int a, int b, int k, int l, int r, int x);
    ll sum(int a, int b, int k, int l, int r);
};

LazySegTree::LazySegTree(int n_){
    n = 1;
    // 葉の数 n を2のべき乗にする
    while(n < n_) n *= 2;
    for(int i=0; i<2*n-1; i++){
        dat[i] = 0;
        lazy[i] = 0;
    }
}

// 配列arrの[a, b)の値にxを加算
void LazySegTree::add(int a, int b, int k, int l, int r, int x){
    if (a <= l && r <= b){
        // 一様に加算する区間
        lazy[k] += x;
    }else if (l < b && a < r){
        // 一様に加算されない区間
        // min(b, r) - max(a, l) : 重なっている区間の数
        dat[k] += (min(b, r) - max(a, l)) * x;
        //
        add(a, b, 2*k+1, l, (l+r)/2, x);
        add(a, b, 2*k+2, (l+r)/2, r, x);
    }
}

// [a, b) の和を求める
ll LazySegTree::sum(int a, int b, int k, int l, int r){
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b){
        // 一様に計算できる区間
        return dat[k] + lazy[k] * (min(b, r) - max(a, l));
    }else{
        // 一様に計算できない区間
        // min(b, r) - max(a, l) : 重なっている区間の数
        ll res = lazy[k] * (min(b, r) - max(a, l));
        // vl:左の子の和, vr:右の子の和 をそれぞれ再帰的に求める
        ll sum_l = sum(a, b, 2*k+1, l, (l+r)/2);
        ll sum_r = sum(a, b, 2*k+2, (l+r)/2, r);
        res += sum_l + sum_r;
        return res;
    }
}

