void init(int &n_) {
	int N = 1;
	while (N < n_)N *= 2;
	n_ = N;
}

void judge(int k, int l, int r) {
	if (add[k]) {
		node[k] += add[k];
		if (r - l > 1) {
			add[k * 2 + 1] += add[k] / 2;
			add[k * 2 + 2] += add[k] / 2;
		}
		add[k] = 0;
	}
}

void update(int a, int b, LL x, int k, int l, int r) {
	judge(k, l, r);
	if (b <= l || r <= a)return ;
	if (a <= l && r <= b) {
		add[k] += ((LL)r - (LL)l)*x;
		judge(k, l, r);
	}
	else {
		update(a, b, x, k * 2 + 1, l, (r + l) / 2);
		update(a, b, x, k * 2 + 2, (l + r) / 2, r);
		node[k] = node[k * 2 + 1] + node[k * 2 + 2];
	}
}

LL getsum(int a, int b, int k, int l, int r) {
	judge(k, l, r);
	if (r <= a || b <= l)return 0LL;
	if (a <= l && r <= b)return node[k];
	LL vl = getsum(a, b, k * 2 + 1, l, (l + r) / 2);
	LL vr = getsum(a, b, k * 2 + 2, (l + r) / 2, r);
	return vl + vr;
}

