struct Add {
    int64_t operator ()(int64_t lhs, int64_t rhs) {
        return lhs + rhs;
    }
} add;

template <class T>
struct SegmentTree {
    size_t m, n;
    T e;
    vector<T> tree, buffer;
    SegmentTree(size_t m, T e=T()): m(m), n(1), e(e) {
        while (n <= m) n <<= 1;
        tree.assign(n<<1, e);
        buffer.assign(n<<1, e);
    }
    void range_modify(size_t l, size_t r, T x, size_t i, size_t a, size_t b) {
        if (l <= a && b <= r) {
            // [a, b) contains [l, r)
            tree[i] += x;
        } else if (a < r && l < b) {
            // [a, b) overlaps [l, r)
            buffer[i] += (min(r, b)-max(l, a)) * x;
            size_t c=(a+b)>>1;
            range_modify(l, r, x, i<<1|0, a, c);
            range_modify(l, r, x, i<<1|1, c, b);
        }
    }
    T range_query(size_t l, size_t r, size_t i, size_t a, size_t b) {
        if (b <= l || r <= a) {
            // [a, b) does not overlap [l, r)
            return e;
        } else if (l <= a && b <= r) {
            // [a, b) contains [l, r)
            return buffer[i] + tree[i]*(b-a);
        }

        // [a, b) overlaps [l, r)
        size_t c=(a+b)>>1;
        T vl=range_query(l, r, i<<1|0, a, c);
        T vr=range_query(l, r, i<<1|1, c, b);

        return add(vl, vr) + tree[i]*(min(r, b)-max(l, a));
    }
    void range_modify(size_t l, size_t r, T x) {
        range_modify(l, r, x, 1, 0, n);
    }
    void modify(size_t i, T x) {
        range_modify(i, i+1, x, 1, 0, n);
    }
    T range_query(size_t l, size_t r) {
        return range_query(l, r, 1, 0, n);
    }
    T range_query() {
        return range_query(0, m, 1, 0, n);
    }
};

int main() {
    size_t n;
    int q;
    scanf("%zu %d\n", &n, &q);

    SegmentTree<int64_t> tree(n);
    for (int i=0; i<q; ++i) {
        int query;
        scanf("%d", &query);

        if (query == 0) {
                size_t s, t;
                int64_t x;
                scanf("%zu %zu %lld", &s, &t, &x);
                --s, --t;
                tree.range_modify(s, t+1, x);
        } else if (query == 1) {
                size_t s, t;
                scanf("%zu %zu", &s, &t);
                --s, --t;
                printf("%lld\n", tree.range_query(s, t+1));
        } else {
            break;
        }
    }

    return 0;
}

