const int N = 2e5 + 7;
struct node{
    int l, r, tag;
    LL val;
};

int n, m, op, x, y, w;
node T[N << 2];

void build(int rt, int l, int r){
    T[rt].l = l, T[rt].r = r, T[rt].val = 0, T[rt].tag = 0;
    if (l == r) return;
    int mid = (l + r) >> 1;
    build(ls(rt), l, mid);
    build(rs(rt), mid + 1, r);
}

void push_down(int rt){
    if (T[rt].tag){
        T[ls(rt)].tag += T[rt].tag, T[rs(rt)].tag += T[rt].tag;
        T[ls(rt)].val += (LL)T[rt].tag * (T[ls(rt)].r - T[ls(rt)].l + 1);
        T[rs(rt)].val += (LL)T[rt].tag * (T[rs(rt)].r - T[rs(rt)].l + 1);
        T[rt].tag = 0;
    }
}

void push_up(int rt){
    T[rt].val = T[ls(rt)].val + T[rs(rt)].val;
}

void update(int rt, int l, int r, int val){
    if (l > T[rt].r || r < T[rt].l) return;
    if (l <= T[rt].l && T[rt].r <= r){
        T[rt].val += (LL)val * (T[rt].r - T[rt].l + 1);
        T[rt].tag += val; return;
    }
    push_down(rt);
    int mid = (T[rt].l + T[rt].r) >> 1;
    if (l <= mid) update(ls(rt), l, r, val);
    if (r > mid) update(rs(rt), l, r, val);
    push_up(rt);
}

LL query(int rt, int l, int r){
    if (l > T[rt].r || T[rt].l > r) return 0;
    if (l <= T[rt].l && T[rt].r <= r) return T[rt].val;
    push_down(rt);
    LL ret = 0;
    int mid = (T[rt].l + T[rt].r) >> 1;
    if (l <= mid) ret += query(ls(rt), l, r);
    if (r > mid) ret += query(rs(rt), l, r);
    return ret;
}

