int get_size(int n){
	int res=0;
	while(n) n=n>>1,res++;

	return (1<<res);
}

int build(int n){
	sz=get_size(n);
	REP(i,0,2*sz) all[i]=0;
	REP(i,0,2*sz) part[i]=0;
	return 0;
}

int _range_add(int a,int b,int x,int k,int l,int r){
	if(a<=l&&r<=b) all[k]+=x;
	else if(l<b&&a<r){
		part[k]+=(min(b,r)-max(a,l))*x;
		_range_add(a,b,x,2*k+1,l,(l+r)>>1);
		_range_add(a,b,x,2*k+2,(l+r)>>1,r);
	}

	return 0;
}

int range_add(int a,int b,int x){
	return _range_add(a,b,x,0,0,sz);
}

int _get(int a,int b,int k,int l,int r){
	if(b<=l||r<=a) return 0;
	if(a<=l&&r<=b) return all[k]*(r-l)+part[k];
	ll res=(min(b,r)-max(a,l))*all[k];
	res+=_get(a,b,k*2+1,l,(l+r)>>1);
	res+=_get(a,b,k*2+2,(l+r)>>1,r);

	return res;
}	

int get(int a,int b){
	return _get(a,b,0,0,sz);
}

