template< typename Monoid, typename OperatorMonoid = Monoid >
struct LazySegmentTree {
  int sz, height;
  vector< Monoid > data;
  vector< OperatorMonoid > lazy;
  const Monoid M1;
  const OperatorMonoid OM0;

  // M1: mempty for Monoid
  // OM0: mempty for OperatorMonoid
  LazySegmentTree(int n, const Monoid &M1, const OperatorMonoid OM0)
      : M1(M1), OM0(OM0) {
    sz = 1;
    height = 0;
    while(sz < n) sz <<= 1, height++;
    data.assign(2 * sz, M1);
    lazy.assign(2 * sz, OM0);
  }

  void set(int k, const Monoid &x) {
    data[k + sz] = x;
  }

  void build() {
    for(int k = sz - 1; k > 0; k--) {
      data[k] = f(data[2 * k + 0], data[2 * k + 1]);
    }
  }

  inline void eval(int len, int k) {
      if (lazy[k] == OM0) return;
      if (k * 2 + 1 < sz * 2 - 1) {
          lazy[k * 2 + 1] += lazy[k];
          lazy[k * 2 + 2] += lazy[k];
      }
      data[k] += lazy[k] * len;
      lazy[k] = OM0;
  }

  Monoid update(int a, int b, const OperatorMonoid &x) {
      return update(a, b, x, 0, 0, sz);
  }

  Monoid update(int a, int b, const OperatorMonoid &x, int k, int l, int r) {
      int len = r - l;
      eval(len, k);
      if (r <= a || b <= l) return data[k];
      if (a <= l && r <= b) {
          lazy[k] += x;
          return data[k] + lazy[k] * len;
      }
      return data[k] =
          update(a, b, x, k * 2 + 1, l, (l + r) / 2) +
          update(a, b, x, k * 2 + 2, (l + r) / 2, r);
  }

  Monoid query(int a, int b) {
      return query(a, b, 0, 0, sz);
  }

  Monoid query(int a, int b, int k, int l, int r) {
      int len = r - l;
      eval(len, k);
      if (r <= a || b <= l) return M1;
      if (a <= l && r <= b) return data[k];
      Monoid vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      Monoid vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
      return vl + vr;
  }
};

