//Range Sum Query
class Lz_segtree{
public:
    int n;
    ll e=0;
    vector<ll> dat,lz;
    Lz_segtree(int n_):n(n_){
        n=1;
        while(n<n_) n*=2;
        dat.resize(n*2,e);
        lz.resize(n*2,e);
    }
    void update_f(ll& d,ll x){
        d+=x;
    }
    void dat_propergatef(ll& d,ll x){
        d=x;
    }
    void lz_propergatef(ll& l,ll& r,ll x){
        l+=x,r+=x;
    }
    ll q_func(ll l,ll r){
        return l+r;
    }
    void eval(int len,int k){
        if(lz[k]!=e) update_f(dat[k],lz[k]);//dat[k]+=lz[k];
        if(len>1){
            lz_propergatef(lz[k*2+1],lz[k*2+2],lz[k]/2);
            /*
            lz[k*2+1]+=lz[k]/2;
            lz[k*2+2]+=lz[k]/2;
            */
        }
        lz[k]=e;
    }
    //range [a,b)
    void update(int a,int b,int k,int l,int r,ll x){
        eval(r-l,k);
        if(r<=a||b<=l) return;
        if(a<=l&&r<=b){
            update_f(lz[k],(r-l)*x);
            //lz[k]+=(r-l)*x;
            eval(r-l,k);
        }
        else{
            update(a,b,k*2+1,l,(l+r)/2,x);
            update(a,b,k*2+2,(l+r)/2,r,x);
            dat_propergatef(dat[k],dat[2*k+1]+dat[2*k+2]);
            //dat[k]=dat[2*k+1]+dat[2*k+2];
        }
    }
    //range [a,b)
    ll query(int a,int b,int k,int l,int r){
        eval(r-l,k);
        if(r<=a||b<=l) return e;
        if(a<=l&&r<=b) return dat[k];
        else{
            ll vl=query(a,b,k*2+1,l,(l+r)/2);
            ll vr=query(a,b,k*2+2,(l+r)/2,r);
            return q_func(vl,vr);
            //return vl+vr;
        }
    }
    void update(int a,int b,ll x){
        return update(a,b,0,0,n,x);
    }
    ll query(int a,int b){
        return query(a,b,0,0,n);
    }
};

int main(){
    int n,q,c,s,t,x;
    cin>>n>>q;
    Lz_segtree seg(n);
    rep(i,q){
        cin>>c;
        if(c==0){
            cin>>s>>t>>x;
            seg.update(s-1,t,x);
        }
        else{
            cin>>s>>t;
            ll ans=seg.query(s-1,t);
            cout<<ans<<endl;
        }
    }
    return 0;
}

