using namespace std;

template<typename T> class dynamic_segtree{
private:
    struct node {
    	T val, lazy;
        int st_size;
    	node *par, *left, *right;
    	node() : val(identity), lazy(identity), st_size(1),
            par(nullptr), left(nullptr), right(nullptr){}
    };
    void opr1(T& arg1,T& arg2){
        arg1 += arg2;
    }
    T opr2(T arg1,T arg2){
        return arg1 + arg2;
    }
    static const int POOL_SIZE = 4000000;
    static node *root;
    static node pool[POOL_SIZE];
    static const T identity = 0;
    int nw_size;
    node *alloc(){
        assert(nw_size < POOL_SIZE);
        return (&pool[nw_size++]);
    }
    void eval(node* k, int l, int r){
        if(k->lazy != 0){
            opr1(k->val,k->lazy);
            if(r-l>1){
                if(k->left){
                    opr1(k->left->lazy, k->lazy);
                }
                if(k->right){
                    opr1(k->right->lazy, k->lazy);
                }
            }
            k->lazy = 0;
        }
    }
public:
    static const int MAX_SIZE = 31;
    dynamic_segtree(){ nw_size = 0; root = alloc(); }
    void insert(int a, T x, node *k = root, int l = 0, int r = MAX_SIZE){
        k->val += x;
        if(r - l == 1){
            return;
        }
        k->st_size++;
        eval(k, l, r);
        if(a < (l + r) / 2){
            if(!(k->left)){
                k->left = alloc();
                k->left->par = k;
            }
            insert(a, x, k->left, l, (l+r)/2);
        }else{
            if(!(k->right)){
                k->right = alloc();
                k->right->par = k;
            }
            insert(a, x, k->right, (l+r)/2, r);
        }
    }
    void range(int a, int b, const T x, node *k = root, int l = 0, int r = MAX_SIZE){
        eval(k, l, r);
    	if(b <= l || r <= a) return;
    	if(a <= l && r <= b){
            k->lazy += k->st_size * x;
    		eval(k, l, r);
    		return;
    	}
    	if(!(k->left)){
    		k->left = alloc();
    		k->left->par = k;
    	}
    	range(a, b, x, k->left, l, (l+r)/2);
    	if(!(k->right)){
    		k->right = alloc();
    		k->right->par = k;
    	}
    	range(a, b, x, k->right, (l+r)/2, r);
    }
    T query(int a, int b, node *k = root, int l=0, int r = MAX_SIZE){
        eval(k, l, r);
        if(b <= l || r <= a){
            return identity;
        }
        if(a <= l && r <= b){
            return k->val;
        }
        T vl = identity,vr = identity;
        if(k->left){
            vl = query(a, b, k->left, l, (l+r)/2);
        }
        if(k->right){
            vr = query(a, b, k->right, (l+r)/2, r);
        }
        return opr2(vl, vr);
    }
};
