struct edge {
	int from, to, cost;
	edge() {
		*this = edge(-1, -1, -1);
	}
	edge(int from_, int to_, int cost_) {
		from = from_;
		to = to_;
		cost = cost_;
	}
	bool operator<(const edge& e) const {
		return cost < e.cost;
	}
};

static const int MAX_N = 1 << 19;
static const int VAL_INIT = 0;
static const int LAZY_INIT = 0;
int N, sum[MAX_N * 2], lazy[MAX_N * 2];

void init(int n_) {
	N = 1;
	while (N < n_) {
		N *= 2;
	}
	rep(i,0,N*2-1)
	{
		sum[i] = VAL_INIT;
		lazy[i] = LAZY_INIT;
	}
}

void setLazy(int k, int x, int nodeL, int nodeR) {
	lazy[k] += x;
	sum[k] += (nodeR - nodeL) * x;
}

void push(int k, int nodeL, int nodeR) {
	if (lazy[k] == LAZY_INIT) {
		return;
	}
	int nodeM = (nodeL + nodeR) / 2;
	setLazy(k * 2 + 1, lazy[k], nodeL, nodeM);
	setLazy(k * 2 + 2, lazy[k], nodeM, nodeR);
	lazy[k] = LAZY_INIT;
}

void fix(int k) {
	sum[k] = sum[k * 2 + 1] + sum[k * 2 + 2];
}

void add(int queryL, int queryR, int x, int k = 0, int nodeL = 0,
		int nodeR = N) {
	if (queryR <= nodeL || nodeR <= queryL) {
		return;
	}
	if (queryL <= nodeL && nodeR <= queryR) {
		setLazy(k, x, nodeL, nodeR);
		return;
	}
	push(k, nodeL, nodeR);
	int nodeM = (nodeL + nodeR) / 2;
	add(queryL, queryR, x, k * 2 + 1, nodeL, nodeM);
	add(queryL, queryR, x, k * 2 + 2, nodeM, nodeR);
	fix(k);
}

int getSum(int queryL, int queryR, int k = 0, int nodeL = 0, int nodeR = N) {
	if (queryR <= nodeL || nodeR <= queryL) {
		return 0;
	}
	if (queryL <= nodeL && nodeR <= queryR) {
		return sum[k];
	}
	push(k, nodeL, nodeR);
	int nodeM = (nodeL + nodeR) / 2;
	int vl = getSum(queryL, queryR, k * 2 + 1, nodeL, nodeM);
	int vr = getSum(queryL, queryR, k * 2 + 2, nodeM, nodeR);
	fix(k);
	return vl + vr;
}

void print() {
	cout << "sum:";
	rep(i,N-1,2*N-1)
	{
		printf("%2d ", sum[i]);
	}
	cout << endl;
}

