class SegTree {
public:
	int n;
	VL nodes;
	VL lazy;
	SegTree(VL a) {
		int size = a.size();
		n = 1;
		while(n < size) n *= 2;
		nodes.resize(n * 2 - 1, 0);
		lazy.resize(n * 2 - 1, 0);
		for (int i = 0; i < size; ++i) {
			nodes[n - 1 + i] = a[i];
		}
		for (int i = n - 2; i >= 0; --i) {
			nodes[i] = nodes[i * 2 + 1] + nodes[i * 2 + 2];
		}
	}

	void eval(int k, int l, int r) {
		if(lazy[k] != 0) {
			nodes[k] += lazy[k];
			if(r - l > 1) {
				lazy[k * 2 + 1] += lazy[k] / 2;
				lazy[k * 2 + 2] += lazy[k] / 2;
			}
			lazy[k] = 0;
		}
	}

	void add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
		if(r < 0) r = n;
		eval(k, l, r);
		if(r <= a || l >= b) return;
		if(a <= l && r <= b) {
			lazy[k] += x * (r - l); eval(k, l, r);  return;
		}
		add(a, b, x, k * 2 + 1, l, (l + r) / 2);
		add(a, b, x, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = nodes[k * 2 + 1] + nodes[k * 2 + 2];
	}

	ll get(int a, int b, int k = 0, int l = 0, int r = -1) {
		if(r < 0) r = n;
		if(r <= a || l >= b) return 0;
		eval(k, l, r);
		if(a <= l && r <= b) return nodes[k];
		return get(a, b, k * 2 + 1, l, (l + r) / 2)
			+ get(a, b, k * 2 + 2, (l + r) / 2, r);
	}
};

