template <typename T>
struct LazySegTreeAddSum {
public:
  int n;
  std::vector<T> node, lazy;
  LazySegTreeAddSum(int sz) {
    n = 1; while(n < sz) n <<= 2;
    node.resize(2*n);
    lazy.resize(2*n, 0);
  }
  LazySegTreeAddSum(std::vector<T> v) {
    int sz = (int)(v.size());
    n = 1; while(n < sz) n <<= 2;
    node.resize(2*n);
    lazy.resize(2*n, 0);
    for(int i=n-1;i<n-1+sz;++i) {
      node[i] = v[i-n+1];
    }
    for(int i=n-2;i>=0;--i) {
      node[i] = node[2*i+1] + node[2*i+2];
    }
  }
  void eval(int k, int l, int r) {
    if(lazy[k] != 0) {
      node[k] += lazy[k];
      if(r-l > 1) {
        lazy[2*k+1] += lazy[k] / 2;
        lazy[2*k+2] += lazy[k] / 2;
      }
      lazy[k] = 0;
    }
  }
  void update(int a, int b, T x, int k, int l, int r) {
    eval(k, l, r);
    if(b <= l || r <= a) return;
    if(a <= l && r <= b) {
      lazy[k] += (r - l) * x;
      eval(k, l, r);
    } else {
      update(a, b, x, 2*k+1, l, (l+r)/2);
      update(a, b, x, 2*k+2, (l+r)/2, r);
      node[k] = node[2*k+1] + node[2*k+2];
    }
  }
  void update(int a, int b, T x) {
    update(a, b, x, 0, 0, n);
  }
  T query(int a, int b, int k, int l, int r) {
    if(b <= l || r <= a) return 0;
    eval(k, l, r);
    if(a <= l && r <= b) return node[k];
    T v1 = query(a, b, 2*k+1, l, (l+r)/2);
    T v2 = query(a, b, 2*k+2, (l+r)/2, r);
    return v1 + v2;
  }
  T query(int a, int b) {
    return query(a, b, 0, 0, n);
  }
};
