    if(lazy[k]!=0){
        dat[k]+=lazy[k];

    if(r-l>1){
        lazy[2*k+1]+=lazy[k]/2;
        lazy[2*k+2]+=lazy[k]/2;
    }

    lazy[k]=0;
    }
