    if(r < 0) r = n;

	eval(k,l,r);

	if(r<a||b<l)return;
	if(a<=l&&r<=b){
	    lazy[k]+=(r-l)*x;
	    eval(k,l,r);
	}
	else{
		add(a,b,x,k*2+1,l,(l+r)/2);
		add(a,b,x,k*2+2,(l+r)/2+1,r);
