void propagate(int cur, int l, int r)
{
    if(prop[cur])
    {
        st[cur] += 1LL * (r - l + 1LL) * prop[cur];
        prop[cur * 2] += 1LL * prop[cur];
        prop[cur * 2 + 1] += 1LL * prop[cur];
        prop[cur] = 0LL;
    }
}

void update(int cur, int l, int r, int li, int ri, ll val)
{
    propagate(cur, l, r);
    if( l > ri || r < li )return;

    if(li <= l && r <= ri)
    {
        prop[cur] += 1LL * val;
        propagate(cur, l, r);
        return;
    }
    int mid = (l + r) >> 1;
    update(cur * 2, l, mid, li, ri, val);
    update(cur * 2 + 1, mid + 1, r, li, ri, val);
    st[cur] = st[cur * 2] + st[cur * 2 + 1];
}

ll sum(int cur, int l, int r, int li, int ri)
{
    propagate(cur, l, r);
    if(l > ri || r < li)return 0LL;
    if(li <= l && r <= ri)return st[cur];

    int mid = (l + r) >> 1;

    return ll(sum(cur * 2, l, mid, li, ri) + sum(cur * 2 + 1, mid + 1, r, li, ri));
}

