    for (int query = 0; query < Q; ++query) {
        int type; cin >> type;
        if (type == 0) {
            int s, t, x; cin >> s >> t >> x;
            bit.add(s, t+1, x);
        }
        else {
            int s, t; cin >> s >> t;
            cout << bit.sum(s, t+1) << endl;
        }
    }
}

