    vector<bool> isLazy;
    Upd upd;
    Map mp;
    const Val Id; // 
    explicit SegTreeLazy(int n_, const Val& id_ = Val())
        : upd(Upd()), mp(Map()), Id(id_) { init(n_);}
    void init(int n_) { // 0 init
        for(n = 1; n < n_; n <<= 1);
        data.assign(2 * n - 1, Id);
        lazy.assign(2 * n - 1, Val());
        isLazy.assign(2 * n - 1, false);
    }
    // lazy propagation type 2
    inline void setLazy(int cn, int mul, Val x) {
        isLazy[cn] = true;
        lazy[cn] = upd(lazy[cn], x);
        data[cn] = upd(data[cn], x * mul);
    }
    inline void push(int cn, int cl, int cr) {
        if(isLazy[cn] == false) return;
        int mid = (cl + cr) / 2;
        setLazy(cn * 2 + 1, mid - cl, lazy[cn]);
        setLazy(cn * 2 + 2, cr - mid, lazy[cn]);
        lazy[cn] = Val();
        isLazy[cn] = false;
    }
    // operation : upd [ql, qr) by x
    // current node : cn [cl, cr)
    void updrange(int ql, int qr, const Val& x) {
        updrange(ql, qr, x, 0, 0, n);
        return;
    }
    void updrange(int ql, int qr, const Val& x, int cn, int cl, int cr) {
        if(qr <= cl || cr <= ql) return;
        if(ql <= cl && cr <= qr) {
            setLazy(cn, cr - cl, x);
            return;
        }
        push(cn, cl, cr);
        updrange(ql, qr, x, cn * 2 + 1, cl, (cl + cr) / 2);
        updrange(ql, qr, x, cn * 2 + 2, (cl + cr) / 2, cr);
        data[cn] = mp(data[cn * 2 + 1], data[cn * 2 + 2]);
    }
    Val query(int ql, int qr) {
        return query(ql, qr, 0, 0, n);
    }
    Val query(int ql, int qr, int cn, int cl, int cr) {
        if(qr <= cl || cr <= ql) return Id;
        if(ql <= cl && cr <= qr) return data[cn];
        push(cn, cl, cr);
        Val a = query(ql, qr, cn * 2 + 1, cl, (cl + cr) / 2);
        Val b = query(ql, qr, cn * 2 + 2, (cl + cr) / 2, cr);
        return mp(a, b);
    }
};

template<class T> // requirement : operator +
struct adder {
    T operator ()(const T& a, const T& b) { return a + b;}
};

