struct ST
{
	vector<int> data;
	vector<int> lazy;
	int size;

	ST(int n)
	{
		size = 1;
		while (size < n)size *= 2;
		data = vector<int>(2 * size - 1, 0);
		lazy = vector<int>(2 * size - 1, 0);
	}

	void apply(int k)
	{
		if (lazy[k] == 0)
		{
			return;
		}

		data[k] += lazy[k];

		if ((size - 1) > k)
		{
			lazy[2 * k + 1] += lazy[k] / 2;
			lazy[2 * k + 2] += lazy[k] / 2;
		}

		lazy[k] = 0;
	}

	void add(int s, int t, int x, int k, int l, int r)
	{
		if (r == -1)
		{
			r = size;
		}
		if (t <= l || r <= s)
		{
			return;
		}
		if (s <= l&&r <= t)
		{
			apply(k);
			lazy[k] += (x*(r - l));
			return;
		}
		apply(k);
		data[k] += (x*(min(r, t) - max(s, l)));
		add(s, t, x, 2 * k + 1, l, (l + r) / 2);
		add(s, t, x, 2 * k + 2, (l + r) / 2, r);
	}

	int getSum(int s, int t, int k, int l, int r)
	{
		if (r == -1)
		{
			r = size;
		}
		if (t <= l || r <= s)
		{
			return 0;
		}
		if (s <= l&&r <= t)
		{
			apply(k);
			return data[k];
		}
		apply(k);
		int sum = 0;
		sum += getSum(s, t, 2 * k + 1, l, (l + r) / 2);
		sum += getSum(s, t, 2 * k + 2, (l + r) / 2, r);
		return sum;
	}

	void draw()
	{
		printf("data\n");
		for (int i = 0; i != data.size(); i++)
		{
			printf("data[%d]:%d\n", i, data[i]);
		}
		printf("lazy\n");
		for (int i = 0; i != lazy.size(); i++)
		{
			printf("lazy[%d]:%d\n", i, lazy[i]);
		}
	}
};

