#include <bits/stdc++.h>
using namespace std;
typedef long long lint;

template <class T>
class LazySegmentTree{
private:
    int n;
    vector<T> dat, lazy;
    T def, lazy_def;
    function<T(T, T)> operation;
    function<T(T, T)> update;
    function<T(T, T)> lazy_update;
    function<T(T, T)> propagate;

    void _eval(int k, int l, int r){
        if(lazy[k]!=lazy_def){
            dat[k] = update(dat[k], lazy[k]);
            if(1<r-l){
                lint u = propagate(lazy[2*k+1], lazy[k]);
                lazy[2*k+1] = propagate(lazy[2*k+1], lazy[k]);
                lazy[2*k+2] = propagate(lazy[2*k+2], lazy[k]);
            }
            lazy[k] = lazy_def;
        }
    }

    T _query(int a, int b, int k, int l, int r){
        // [a, b), [l, r)
        if(r<=a or b<=l) return def;
        _eval(k, l, r);
        if(a<=l and r<=b){
            return dat[k];
        }
        else{
            T c1 = _query(a, b, 2*k+1, l, (l+r)/2);
            T c2 = _query(a, b, 2*k+2, (l+r)/2, r);
            return operation(c1, c2);
        }
    }

    void _change(int a, int b, T x, int k, int l, int r){
        _eval(k, l, r);
        if(b<=l or r<=a) return;
        else if(a<=l and r<=b){
            lazy[k] = lazy[k] + lazy_update(lazy[k], x) * (r-l);
            _eval(k, l, r);
        } else {
            _change(a, b, x, 2*k+1, l, (l+r)/2);
            _change(a, b, x, 2*k+2, (l+r)/2, r);
            dat[k] = operation(dat[2*k+1], dat[2*k+2]);
        }
    }

public:
    // [a, b)
    T query(int a, int b){
        return _query(a, b, 0, 0, n);
    }

    void change(int a, int b, T x){
        _change(a, b, x, 0, 0, n);
    }

    T operator[](int i){
        return dat[i+n-1];
    }

    LazySegmentTree(size_t _n, T _def, T _lazy_def, function<T(T, T)> _operation,
                    function<T(T, T)> _update, function<T(T, T)> _lazy_update,
                    function<T(T, T)> _propagate)
            : def(_def), lazy_def(_lazy_def), operation(_operation), update(_update),
            lazy_update(_lazy_update), propagate(_propagate){
        n = 1;
        while(n < _n){
            n *= 2;
        }
        dat = vector<T>(2*n-1, def);
        lazy = vector<T>(2*n-1, lazy_def);
    }
};

