template <class T> struct FenwickTree {
  const int n;
  vector<T> t;
  FenwickTree(int _n) : n(_n), t(n + 1) {}
  void add(int i, T a) { for (++i; i <= n; i += i & -i) t[i] += a; }
  T sum(int i) const {
    T s = 0;
    for (; i; i -= i & -i) s += t[i];
    return s;
  }
  T sum(int l, int r) const { return sum(r) - sum(l); }
  int kth(T k) const {
    int i = 0;
    for (int w = 1 << __lg(n); w; w >>= 1)
      if (i + w <= n and t[i + w] <= k) k -= t[i += w];
    return i;
  }
};
template <class T> struct AddSumTree {
  const int n;
  vector< FenwickTree<T> > ft;
  AddSumTree(int _n) : n(_n), ft(2, n + 1) {}
  void add(int l, int r, T a) {
    ft[0].add(l, a), ft[0].add(r, -a);
    ft[1].add(l, l * a), ft[1].add(r, -(r * a));
  }
  T sum(int i) const { return i * ft[0].sum(i) - ft[1].sum(i); }
  T sum(int l, int r) const { return sum(r) - sum(l); }
};

int main() {
