template<typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> all, part;

	SegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		all.resize(n * 2 - 1, init_val);
		part.resize(n * 2 - 1, init_val);
	}

	// [a,b)???????´????x???????§???????
	void add(int a, int b, T x, int k, int l, int r) {
		if (r <= a || b <= l) return;

		if (a <= l && r <= b) {
			all[k] += x;
		}
		else {
			part[k] += (min(b, r) - max(a, l)) * x;
			add(a, b, x, k * 2 + 1, l, (l + r) / 2);
			add(a, b, x, k * 2 + 2, (l + r) / 2, r);
		}
	}
	void add(int a, int b, T x) {
		add(a, b, x, 0, 0, n);
	}

	// [a,b)???????¨?????±???????
	T query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return (r - l) * all[k] + part[k];

		T res = (min(b, r) - max(a, l)) * all[k];
		res += query(a, b, k * 2 + 1, l, (l + r) / 2);
		res += query(a, b, k * 2 + 2, (l + r) / 2, r);
		return res;
	}
	T query(int a, int b) {
		return query(a, b, 0, 0, n);
	}
};

