template<class M> struct SegmentLazyAdd {
    using func=function<M(M, M)>;
    using feval = function<M(int, M/*作用素,Mとは違う型を使うのを横着している*/)>;//区間の値に加算される値
    int n;
    vector<M> seg;
    vi lazy;//全体に足された数を持つ 3333なら3
    const func f;        //M同士の演算結果を返す
    const feval getAdd;  //len,xを受け取り、segに加える数を返す
    const M e;
    vi arch;//遅延評価を行うやつ
    vi lens;
    SegmentLazyAdd(vi a, func f, feval fe, M e) : f(f), getAdd(fe), e(e) {
        n = 1;
//        rep(i, 100) a.pb(e);
        int asz = a.size();
        while (n < asz)n <<= 1;
        seg.resize(2 * n - 1, e);
        lazy.resize(2 * n - 1, 0);
        lens.resize(2 * n - 1);
        rep(i, asz) seg[i + n - 1] = a[i];
        rer(i, n - 2)seg[i] = f(seg[(i << 1) + 1], seg[(i << 1) + 2]);
        int l = 1, v = n;
        rep(i, 1, n << 1) {
            if ((l << 1) == i) {
                l <<= 1;
                v >>= 1;
            }
            lens[i - 1] = v;
        }
    }
    void eval() {
        rer(j, sz(arch) - 1) {
            int i = arch[j];
            //iは1index
            //lazyは0index
            int v = lazy[i - 1];
            if (!v)continue;
            lazy[i * 2 - 1] += v;
            lazy[i * 2] += v;
            seg[i * 2 - 1] += getAdd(lens[i * 2 - 1], v);//
            seg[i * 2] += getAdd(lens[i * 2], v);
            lazy[i - 1] = 0;
        }
    }
    void gindex(int l, int r) {
        arch.clear();
        l += n;
        r += n;
        int lm = (l / (l & -l)) >> 1;
        int rm = (r / (r & -r)) >> 1;
        while (l < r) {
            if (r <= rm)arch.pb(r);
            if (l <= lm)arch.pb(l);
            l >>= 1;
            r >>= 1;
        }
        while (l) {
            arch.pb(l);
            l >>= 1;
        }
    }
    void add(int l, int r, int x) {
        int L = l + n;
        int R = r + n;
        while (L < R) {
            if (R & 1) {
                R--;
                lazy[R - 1] += x;
                seg[R - 1] += getAdd(lens[R - 1], x);
            }
            if (L & 1) {
                lazy[L - 1] += x;
                seg[L - 1] += getAdd(lens[L - 1], x);
                L++;
            }
            L >>= 1;
            R >>= 1;
        }
        gindex(l, r);
        fora(i, arch) {
            seg[i - 1] = f(seg[i * 2 - 1], seg[i * 2]);
            seg[i - 1] += getAdd(lens[i - 1], lazy[i - 1]);
        }
    }
    M get(int l, int r) {
        gindex(l, r);
        eval();
        int L = l + n;
        int R = r + n;
        M retl = e, retr = e;
        while (L < R) {
            if (R & 1) {
                R--;
                retr = f(seg[R - 1], retr);
            }
            if (L & 1) {
                retl = f(retl, seg[L - 1]);
                L++;
            }
            L >>= 1;
            R >>= 1;
        }
        return f(retl, retr);
    }
#ifdef _DEBUG
    void debu(int len = 10) {
        rep(i, min(n, min(len, n))) {
            int v = get(i, i + 1);
            if (v == e) {
                cerr << "e ";
            } else {
                cerr << v << " ";
            }
        }
        cerr << "" << endl;
    }
#else
    inline void debu(){;}
#endif
};
