struct s_tree
{
		vector<ll> st , lazy;

		s_tree(int n) :
				st(4 * n , 0), lazy(4 * n , 0)
		{
		}

		inline void push(int pos , int begin , int end)
		{
			if (lazy[pos] != 0)
			{
				int md = (begin + end) >> 1;

				st[pos << 1] += ((md - begin + 1) * lazy[pos]);
				st[pos << 1 | 1] += ((end - md) * lazy[pos]);
				lazy[pos << 1] += lazy[pos];
				lazy[pos << 1 | 1] += lazy[pos];

				lazy[pos] = 0;
			}
		}

		int query(int a , int b , int begin , int end , int pos)
		{

			if (a > end || b < begin) return 0;

			if (begin >= a && end <= b) return st[pos];

			int md = (begin + end) >> 1;

			push(pos , begin , end);

			return query(a , b , begin , md , pos << 1)
					+ query(a , b , md + 1 , end , pos << 1 | 1);

		}

		void updt(int a , int b , int begin , int end , int pos , int val)
		{

			if (a > end || b < begin) return;

			if (begin >= a && end <= b)
			{
				lazy[pos] += val;
				st[pos] += (val * (end - begin + 1));
				return;
			}

			int md = (begin + end) >> 1;

			push(pos , begin , end);

			updt(a , b , begin , md , pos << 1 , val);
			updt(a , b , md + 1 , end , pos << 1 | 1 , val);

			st[pos] = st[pos << 1] + st[pos << 1 | 1];
		}
};

int main()
{
	cin.tie(0) , cout.tie(0) , ios_base::sync_with_stdio(0);

	int n , q;
	cin >> n >> q;

	s_tree st(n + 2);

	ll x , y , op;

	while (q--)
	{
		cin >> op;

		if (op == 0)
		{
			cin >> x >> y >> op;

			if (x > y) swap(x , y);

			st.updt(x , y , 1 , n , 1 , op);
		}
		else
		{

			cin >> x >> y;

			if (x > y) swap(x , y);

			cout << st.query(x , y , 1 , n , 1) << endl;
		}
	}
	return 0;
}

