template<typename T,typename E>
struct lazysegtree{
using F=function<T(T,T)>;
using G=function<T(T,E)>;
using H=function<E(E,E)>;
int n,height;
F f;G g;H h;T t;E e;
vector<T> dat;
vector<E> laz;
lazysegtree(int n_,F f,G g,H h,T t,E e):f(f),g(g),h(h),t(t),e(e){
    n=1;height=0;
    while(n<n_)n*=2,height++;
    dat.assign(2*n,t);
    laz.assign(2*n,e);
}
lazysegtree(int n_,vector<T> &v,F f,G g,H h,T t,E e):f(f),g(g),h(h),t(t),e(e){
    n=1;height=0;
    while(n<n_)n*=2,height++;
    dat.assign(2*n,t);
    for(int i=n;i-(n-2)<v.size();i++)dat[i]=v[i-(n-2)];
    for(int i=n-1;i>0;i--)dat[i]=f(dat[i*2+1],dat[i*2+2]);
    laz.assign(2*n,e);
}
inline T reflect(int k){
    return (laz[k]==e?dat[k]:g(dat[k],laz[k]));
}
inline void eval(int k){
    if(laz[k]==e)return;
    laz[(k<<1)|0]=h(laz[(k<<1)|0],laz[k]);
    laz[(k<<1)|1]=h(laz[(k<<1)|1],laz[k]);
    dat[k]=reflect(k);
    laz[k]=e;
}
inline void thrust(int k){
    for(int i=height;i>0;i--)eval(k>>i);
}
inline void recalc(int k){
    while(k>>=1)dat[k]=f(reflect((k<<1)|0),reflect((k<<1)|1));
}
void update(int a,int b,E x){
    thrust(a+=n);
    thrust(b+=n-1);
    for(int l=a,r=b+1;l<r;l>>=1,r>>=1){
        if(l&1)laz[l]=h(laz[l],x),l++;
        if(r&1)--r,laz[r]=h(laz[r],x);
    }
recalc(a);
recalc(b);
}
void set_val(int a,T x){
    thrust(a+=n);
    dat[a]=x;laz[a]=e;
    recalc(a);
}
T query(int a,int b){
    thrust(a+=n);
    thrust(b+=n-1);
    T vl=t,vr=t;
    for(int l=a,r=b+1;l<r;l>>=1,r>>=1){
        if(l&1)vl=f(vl,reflect(l++));
        if(r&1)vr=f(reflect(--r),vr);
    }
    return f(vl,vr);
}
};
