template<typename T> struct BIT {
   vector<T> bit;
   int len;
   BIT(int n) : len(n+1), bit(n+1) {}
   void add(int i, T x) {
      i += 1;
      while (i < len) { bit[i] += x; i += i & -i; }
   }
   T sum(int i) {
      i += 1; T s = 0;
      while (i > 0) { s += bit[i]; i -= i & -i; }
      return s;
   }
};
template<typename T> struct RAQ_RSQ {
   BIT<T> bit1, bit2;
   RAQ_RSQ(int n) : bit1(n), bit2(n) {}
   void add(int l, int r, int x) {
      bit1.add(l, x);
      bit1.add(r+1, -x);
      bit2.add(l, -x*(l-1));
      bit2.add(r+1, x*r);
   }
   T sum(int i) {
      return bit1.sum(i) * i + bit2.sum(i);
   }
   T sum(int l, int r) {
      return sum(r) - sum(l-1);
   }
};

