struct SegmentTree{
private:
    ll unit=0;
    ll op(ll a,ll b){return a+b;}
    int n;
    vector<ll> node;

public:
    // initialize
    SegmentTree(vector<ll> v){
        int sz=(int)v.size();
        n=1;while(n<sz) n*=2;
        node.resize(2*n-1,unit);
        for(int i=0;i<sz;i++) node[i+n-1]=v[i];
        for(int i=n-2;i>=0;i--) node[i]=op(node[2*i+1],node[2*i+2]);
    }

    void update(int x,int val){
        x+=n-1;
        node[x]+=val;
        while(x>0){
            x=(x-1)/2;
            node[x]=op(node[2*x+1],node[2*x+2]);
        }
    }

    int query(int a,int b,int k=0,int l=0,int r=-1){
        if (r<0) r=n;
        if (r<=a || b<=l) return unit;
        if (a<=l && r<=b) return node[k];
        int vl = query(a,b,2*k+1,l,(l+r)/2);
        int vr = query(a,b,2*k+2,(l+r)/2,r);
        return op(vl,vr);
    }
};

// 区間加算・区間和クエリ
struct LazySegmentTree{
private:
    int n;
    vector<ll> node,lazy;
public:
    // initialize
    LazySegmentTree(vector<ll> v){
        int sz=(int)v.size();
        n=1;while(n<sz) n*=2;
        node.resize(2*n-1);
        lazy.resize(2*n-1);
        for(int i=0;i<sz;i++) node[i+n-1]=v[i];
        for(int i=n-2;i>=0;i--) node[i]=node[2*i+1]+node[2*i+2];
    }

    void lazyEval(int k,int l,int r){
        if(lazy[k]!=0){
            node[k]+=lazy[k];
            // r-l==1であるとき、kはleafであるため子を参照してはいけない
            if(r-l>1){
                lazy[2*k+1]+=lazy[k]/2;
                lazy[2*k+2]+=lazy[k]/2;
            }
            lazy[k]=0;
        }
    }
    //　ノードkに適切な値を入れ、遅延情報を初期化する
    void update(int a,int b,ll x,int k=0,int l=0,int r=-1){
        if(r<0) r=n;
        // もともと入ってた遅延情報の処理
        lazyEval(k,l,r);
        if(b<=l || r<=a) return;
        if(a<=l && r<=b){
            lazy[k]+=(r-l)*x;
            lazyEval(k,l,r);
        }
        else{
            update(a,b,x,2*k+1,l,(l+r)/2);
            update(a,b,x,2*k+2,(l+r)/2,r);
            // update内で遅延評価が必要なのは多分ここのため
            node[k]=node[2*k+1]+node[2*k+2];
        }
    }

    ll query(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0) r=n;
        if(b<=l || r<=a) return 0; 

        lazyEval(k,l,r);
        if(a<=l && r<=b) return node[k];
        ll vl=query(a,b,2*k+1,l,(l+r)/2);
        ll vr=query(a,b,2*k+2,(l+r)/2,r);
        return vl+vr;
    }
};

int main(){
    int N,Q;cin>>N>>Q;
    LazySegmentTree BIT(vector<ll>(N,0));
    rep(i,Q){
