#define LEFT(a) (a-SZ(a))
#define UP(a) (a+SZ(a))

	vector<T> x,lazy;
	Lazy_BIT(int n) : x(n + 1, 0), lazy(n + 1, 0) {}
	T sum(int r) {
		T S = 0;
		for (int k = r; k > 0; k -= SZ(k)) {
			S += x[k]+lazy[k]*SZ(k);
			for (int cp = UP(k); cp < x.size() && LEFT(k) == LEFT(cp); cp += SZ(cp))
				S += lazy[cp] * (r - LEFT(k));
		}
		return S;
	}
	void add(int r, T a) {
		for (int k=r; k > 0; k -= SZ(k)) {
			lazy[k] += a;
			for (int cp = UP(k); cp < x.size() && LEFT(k) == LEFT(cp); cp += SZ(cp))
				x[cp] += a * (r-LEFT(k));
		}
	}
};


