	bool* lazy;
	size_t size, i, hight = 0;
	//?????????????????????
	SegTree(size_t length) {
		--length;
		size = length;
		if (size & 0xffff0000) { size = size & 0xffff0000;hight += 16; }
		if (size & 0xff00ff00) { size = size & 0xff00ff00;hight += 8; }
		if (size & 0xf0f0f0f0) { size = size & 0xf0f0f0f0;hight += 4; }
		if (size & 0xcccccccc) { size = size & 0xcccccccc;hight += 2; }
		if (size & 0xaaaaaaaa) { size = size & 0xaaaaaaaa;hight += 1; }
		if (length) { size <<= 1;hight += 1; }
		else { size = 1;hight = 0; }
		tree = (Monoid *)calloc(size << 1, sizeof(Monoid));
		calc = (Operand *)calloc(size << 1, sizeof(Operand));
		lazy = (bool *)calloc(size << 1, sizeof(bool));
	}
	//?????????
	void set(bool merge) {
		i = size << 1;
		while (--i) {
			tree[i].set();
			lazy[i] = false;
		}
		if (merge) {
			i = size;
			while (--i) {
				tree[i] = tree[i << 1] + tree[i << 1 | 1];
			}
		}
	}
	//calc[begin,end)???data???????????????????¨????
	void update(size_t begin, size_t end, Operand &data) {
		begin += size;
		end += size - 1;
		size_t left, right;
		i = hight;
		while (i--) {
			left = begin >> i;
			right = end >> i;
			if (lazy[left >> 1]) {
				calc[left] = lazy[left] ? calc[left] * calc[left >> 1] : calc[left >> 1];
				calc[left ^ 1] = lazy[left ^ 1] ? calc[left ^ 1] * calc[left >> 1] : calc[left >> 1];
				lazy[left >> 1] = false; lazy[left] = true; lazy[left ^ 1] = true;
			}
			if (lazy[right >> 1]) {
				calc[right] = lazy[right] ? calc[right] * calc[right >> 1] : calc[right >> 1];
				calc[right ^ 1] = lazy[right ^ 1] ? calc[right ^ 1] * calc[right >> 1] : calc[right >> 1];
				lazy[right >> 1] = false; lazy[right] = true; lazy[right ^ 1] = true;
			}
		}
		for (left = begin, right = end + 1;left < right;left >>= 1, right >>= 1) {
			if (left & 1) {
				calc[left] = lazy[left] ? calc[left] * data : data;
				lazy[left] = true;
				++left;
			}
			if (right & 1) {
				--right;
				calc[right] = lazy[right] ? calc[right] * data : data;
				lazy[right] = true;
			}
		}
		for (begin >>= 1, end >>= 1;begin < end;begin >>= 1, end >>= 1) {
			tree[begin] = (lazy[begin << 1] ? tree[begin << 1] * calc[begin << 1] : tree[begin << 1]) + (lazy[begin << 1 | 1] ? tree[begin << 1 | 1] * calc[begin << 1 | 1] : tree[begin << 1 | 1]);
			tree[end] = (lazy[end << 1] ? tree[end << 1] * calc[end << 1] : tree[end << 1]) + (lazy[end << 1 | 1] ? tree[end << 1 | 1] * calc[end << 1 | 1] : tree[end << 1 | 1]);
		}
		begin <<= 1;
		while (begin >>= 1) {
			tree[begin] = (lazy[begin << 1] ? tree[begin << 1] * calc[begin << 1] : tree[begin << 1]) + (lazy[begin << 1 | 1] ? tree[begin << 1 | 1] * calc[begin << 1 | 1] : tree[begin << 1 | 1]);
		}
	}
	//[begin,end)??????????????????
	Monoid range(size_t begin, size_t end) {
		Monoid retL, retR;
		begin += size;end += size - 1;
		size_t left, right;
		i = hight;
		while (i--) {
			left = begin >> i;
			right = end >> i;
			if (lazy[left >> 1]) {
				calc[left] = lazy[left] ? calc[left] * calc[left >> 1] : calc[left >> 1];
				calc[left ^ 1] = lazy[left ^ 1] ? calc[left ^ 1] * calc[left >> 1] : calc[left >> 1];
				tree[left >> 1] = tree[left >> 1] * calc[left >> 1];
				lazy[left >> 1] = false; lazy[left] = true; lazy[left ^ 1] = true;
			}
			if (lazy[right >> 1]) {
				calc[right] = lazy[right] ? calc[right] * calc[right >> 1] : calc[right >> 1];
				calc[right ^ 1] = lazy[right ^ 1] ? calc[right ^ 1] * calc[right >> 1] : calc[right >> 1];
				tree[right >> 1] = tree[right >> 1] * calc[right >> 1];
				lazy[right >> 1] = false; lazy[right] = true; lazy[right ^ 1] = true;
			}
		}
		++end;
		for (;begin < end;(++begin) >>= 1, end >>= 1) {
			if (begin & 1) {
				if (lazy[begin]) { retL = retL + (tree[begin] * calc[begin]); }
				else { retL = retL + tree[begin]; }
			}
			if (end & 1) {
				if (lazy[--end]) { retR = retR + (tree[end] * calc[end]); }
				else { retR = retR + tree[end]; }
			}
		}
		return retL + retR;
	}
};

