void add(int a, long long int w, long long int BIT[]){

	// a番目の要素にwを足す O(log N)

	for(int x = a; x <= N; x += x & -x){
		BIT[x] += w;
	}
}

long long int sum(int a, long long int BIT[]){

	// 1からaまでの要素の合計を返す O(log N)

	long long int ret = 0;
	for(int x = a; x > 0; x -= x & -x){
		ret += BIT[x];
	}
	return ret;
}

void init(long long int BIT[]){
	for(int i = 0; i < N; i++){
		BIT[i] = 0;
	}
}

