#pragma gcc optimize("Ofast")
#include <bits/stdc++.h>
using namespace std;
#define ls (id * 2)
#define rs (id * 2 + 1)

int n, q, s, t, x;
long long S[400020], lazy[400020];
bool com;
bitset<400020> tag;

void pd(int id, int l, int m, int r) {
    if (!tag[id]) return;
    S[ls] += lazy[id] * (m - l + 1);
    S[rs] += lazy[id] * (r - m);
    lazy[ls] += lazy[id];
    lazy[rs] += lazy[id];
    lazy[id] = 0;
    tag[ls] = tag[rs] = 1;
    tag[id] = 0;
}

void update(int id, int l, int r, int ql, int qr, int v) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        S[id] += v * (r - l + 1);
        lazy[id] += v;
        tag[id] = 1;
        return;
    }
    int m = (l + r) /2;
    pd(id, l, m, r);
    update(ls, l, m, ql, qr, v);
    update(rs, m + 1, r, ql, qr, v);
    S[id] = S[ls] + S[rs];
}

long long query(int id, int l, int r, int ql, int qr) {
	if (ql > r || qr < l) return 0;
	if (ql <= l && r <= qr) return S[id];
	int m = l + r >> 1;
	pd(id, l, m, r);
	return (query(ls, l, m, ql, qr) + query(rs, m + 1, r, ql, qr));
}

int main() {
    ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
    cin >> n >> q;
    while (q--) {
        cin >> com >> s >> t;
        if (!com) {
            cin >> x;
            update(1, 1, n, s, t, x);
        } 
        else cout << query(1, 1, n, s, t) << endl;
    }
}

