void init(int &n_) {
	int N = 1;
	while (N < n_)N *= 2;
	n_ = N;
}

void judge(int k, int l, int r) {
	if (add[k]) {
		node[k] += add[k];
		if (r - l > 1) {
			add[k * 2 + 1] += add[k] / 2;
			add[k * 2 + 2] += add[k] / 2;
		}
		add[k] = 0;
	}
}

void update(int a, int b, int x, int k, int l, int r) {
	judge(k, l, r);
	if (b <= l || r <= a)return ;
	if (a <= l && r <= b) {
		add[k] += (r - l)*x;
		judge(k, l, r);
	}
	else {
		update(a, b, x, k * 2 + 1, l, (r + l) / 2);
		update(a, b, x, k * 2 + 2, (l + r) / 2, r);
		node[k] = node[k * 2 + 1] + node[k * 2 + 2];
	}
}

int getsum(int a, int b, int k, int l, int r) {
	judge(k, l, r);
	if (r <= a || b <= l)return 0;
	if (a <= l && r <= b)return node[k];
	int vl = getsum(a, b, k * 2 + 1, l, (l + r) / 2);
	int vr = getsum(a, b, k * 2 + 2, (l + r) / 2, r);
	return vl + vr;
}

int main() {
	std::cin >> n >> q;
	init(n);
	std::cout << n << std::endl;
	for (int i = 0; i < q; i++) {
		int a;
		std::cin >> a;
		if (!a) {
			int s, t, x;
			std::cin >> s >> t >> x;
			update(s - 1, t, x, 0, 0, n);
		}
		else {
			int s, t;
			std::cin >> s >> t;
			std::cout << getsum(s - 1, t, 0, 0, n) << std::endl;
		}
	}
	return 0;
}

