template <typename T>
struct service {
  size_t L;
  std::vector<T> dat;
  std::vector<T> dividend;
  std::vector<T> sum;

  explicit service(size_t n)
    : L(csqrt(n))
    , dat(L * L, 0)
    , dividend(L, 0)
    , sum(L, 0)
  { }

  void pay(size_t alpha) {
    T offset = dividend[alpha];
    if (offset <= 0) { return; }
    for (size_t i = alpha * L; i < (alpha + 1) * L; ++i) {
      dat[i] += offset;
    }
    dividend[alpha] = 0;
  }

  void add(size_t begin, size_t end, T x) {
    pay(begin / L);
    pay(end / L);
    size_t i;
    for (i = begin; i < end && i % L != 0; ++i) {
      dat[i] += x;
      sum[i / L] += x;
    }
    for (; i + L < end; i += L) {
      dividend[i / L] += x;
      sum[i / L] += x * L;
    }
    for (; i < end; ++i) {
      dat[i] += x;
      sum[i / L] += x;
    }
  }

  T get_sum(size_t begin, size_t end) {
    pay(begin / L);
    pay(end / L);
    T ans = 0;
    size_t i;
    for (i = begin; i < end && i % L != 0; ++i) { ans += dat[i]; }
    for (; i + L <= end; i += L) { ans += sum[i / L]; }
    for (; i < end; ++i) { ans += dat[i]; }
    return ans;
  }


  static size_t csqrt(size_t n) {
    size_t k = 1;
    while (k * k < n + 3) { ++k; }
    return k;
  }
};

