struct LazySegmentTree{
	vector<ll> data, lazy;
	int sz;

	LazySegmentTree(int n){
		sz = 1;
		while(sz < n) sz *= 2;
		data.assign(2*sz, 0);
		lazy.assign(2*sz, 0);
	}

	void update(int k, int x){
		k  += sz-1;
		data[k] = x;

		while(k){
			k = (k-1)/2;
			data[k] = data[2*k+1] + data[2*k+2];
		}
	}

	void push(int k, int len){
		if(k < sz){
			lazy[2*k+1] += lazy[k];
			lazy[2*k+2] += lazy[k];
		}

		data[k] += lazy[k] * len;
		lazy[k] = 0;
	}

	void add(int a, int b, int x){
		_add(a, b, 0, 0, sz, x);
	}

	void _add(int a, int b, int k, int l, int r, int x){
		push(k, r-l);
		if(b<=l||r<=a) return ;
		if(a<=l&&r<=b){
			lazy[k] += x;
			push(k, r-l);
			return ;
		}

		_add(a, b, 2*k+1, l, (l+r)/2, x);
		_add(a, b, 2*k+2, (l+r)/2, r, x);
		data[k] = data[2*k+1] + data[2*k+2];
	}

	ll get(int a, int b){
		return _get(a, b, 0, 0, sz);
	}

	ll _get(int a, int b, int k, int l, int r){
		push(k, r-l);
		if(b<=l||r<=a) return 0;
		if(a<=l&&r<=b) return data[k];

		return _get(a, b, 2*k+1, l, (l+r)/2) + _get(a, b, 2*k+2, (l+r)/2, r);
	}
};

