typedef long long ll;
typedef vector<ll> vec;

class Seg
{
public:
    vec data;
    vec lazy;
    int n;

    Seg(int _n)
    {
        data.resize(4*_n);
        lazy.resize(4*_n);
        for(n=1;n<_n;n<<=1);
        fill(data.begin(),data.end(),0);
        fill(lazy.begin(),lazy.end(),0);
    }

    void Down(int p,int l,int r)
    {
        data[p]+=lazy[p]*(r-l);
        if(1+l<r)
        {
            lazy[p*2+1]+=lazy[p];
            lazy[p*2+2]+=lazy[p];
        }
        lazy[p]=0;
    }

    void add(int p,int l,int r,int x,int a,int b)
    {
        if(a>=r||b<=l) return;
        else if(a<=l&&r<=b)
        {
            lazy[p]+=x;
        }else
        {
            int mid=(l+r)/2;
            add(p*2+1,l,mid,x,a,b);
            add(p*2+2,mid,r,x,a,b);
            data[p]+=(min(b,r)-max(a,l))*x;
        }
    }

    ll getSum(int p,int l,int r,int a,int b)
    {
        if(a>=r||b<=l) return 0;
        else if(a<=l&&r<=b) return data[p]+lazy[p]*(r-l);
        else
        {
            Down(p,l,r);
            int mid=(l+r)/2;
            return getSum(p*2+1,l,mid,a,b)+getSum(p*2+2,mid,r,a,b);
        }
    }
};

