const int MAXN=1e5+10;
using ll=long long int;

struct Node{
    int lbound,rbound;
    ll diff;
    ll sum;
    Node *left,*right;
};

Node segtree[MAXN*2];
Node* next_pos=segtree;
int n,q;

Node* build(int left,int right){
    auto* cur=next_pos;
    next_pos++;
    cur->lbound=left;
    cur->rbound=right;

    cur->diff=0;


    int mid=(left+right)/2;

    //リーフノードのケース
    if (right-left==1) return cur;

    cur->left=build(left,mid);
    cur->right=build(mid,right);
    //総和を集計
    cur->sum=0;
    return cur;
}

//シングルノードの更新
void update(Node& self,ll d){
    self.diff+=d;
    self.sum+=d*(self.rbound-self.lbound);
}

void update(Node& self,int l,int r,int u){
    int mid=(self.lbound+self.rbound)/2;

    if (self.rbound-self.lbound!=1&&self.diff!=0){
        update(*self.left,self.diff);
        update(*self.right,self.diff);
        self.diff=0;
    }

    if (l==self.lbound&&r==self.rbound){
        update(self,u);
    }else if (l>=mid){
        update(*self.right,l,r,u);
        self.sum=self.left->sum+self.right->sum;
    }else if (r<=mid){
        update(*self.left,l,r,u);
        self.sum=self.left->sum+self.right->sum;
    }else{
        update(*self.left,l,mid,u);
        update(*self.right,mid,r,u);
        self.sum=self.left->sum+self.right->sum;
    }
}

//シングルポイント
int query(Node& self,int i){
    // puts("q");
    if (self.rbound-self.lbound==1&&self.lbound==i) return self.diff;
    int mid=(self.lbound+self.rbound)/2;
    if (i>=mid) return query(*self.right,i)+self.diff;
    else return query(*self.left,i)+self.diff;
}

//区間
ll query(Node& self,int l,int r){
    int mid=(self.lbound+self.rbound)/2;

    //更新があるノードの区間をプッシュボタン
    if (self.rbound-self.lbound!=1&&self.diff!=0){
        update(*self.left,self.lbound,mid,self.diff);
        update(*self.right,mid,self.rbound,self.diff);
        self.diff=0;
    }

    if (l==self.lbound&&r==self.rbound){
        return self.sum;
    }else if (l>=mid){
        return query(*self.right,l,r);
    }else if (r<=mid){
        return query(*self.left,l,r);
    }else{
        return query(*self.left,l,mid)+query(*self.right,mid,r);
    }
}

