vvi bit_z(int size, int n) {
	vvi A;
	int s = (1<<n)-1;
	A.push_back(bit(size,s));
	while (true) {
		int x = s & (-s);
		int y = s + x;
		int z = s & (~y);

		z /= x;
		z = z >> 1;
		s = (y | z);
		if (s >= (1 << size))break;
		A.push_back(bit(size,s));
	}
	return A;
}
