typedef long long int ll;

class SegmentTree {
private:
    vector<ll> st, lazy;
    int n;


    void build(int p, int l, int r) {
        if (l == r)
            st[p] = l + 1;
        else {
            int lc = p * 2, rc = p * 2 + 1;
            int mid = (l + r) / 2;
            build(lc, l, mid);
            build(rc, mid + 1, r);
            st[p] = st[lc] + st[rc];
        }
    }

    inline void upd(int id, int l, int r, ll x) {
        lazy[id] += x;
        st[id] += (r - l + 1) * x;
    }

    inline void shift(int id, int l, int r) {
        int mid = (l + r) / 2;
        upd(id * 2, l, mid, lazy[id]);
        upd(id * 2 + 1, mid + 1, r, lazy[id]);
        lazy[id] = 0;
    }

    void update(int i, int j, int x, int id, int l, int r) {
        if (l > j || r < i) return;
        if (l >= i && r <= j) {
            upd(id, l, r, x);
            return;
        }
        shift(id, l, r);
        int mid = (l + r) / 2;
        update(i, j, x, id * 2, l, mid);
        update(i, j, x, id * 2 + 1, mid + 1, r);
        st[id] = st[id * 2] + st[id * 2 + 1];
    }

    ll sum(int i, int j, int id, int l, int r) {
        if (l > j || r < i) return 0;
        if (l >= i && r <= j) return st[id];
        shift(id, l, r);
        int mid = (l + r) / 2;
        return sum(i, j, id * 2, l, mid) + sum(i, j, id * 2 + 1, mid + 1, r);
    }

public:
    SegmentTree(int _n) {
        n = _n;
        st.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
        //build(1, 0, n - 1);
    }

    void update(int i, int j, int x) {
        update(i - 1, j - 1, x, 1, 0, n - 1);
    }

    ll query(int i, int j) {
        return sum(i - 1, j - 1, 1, 0, n - 1);
    }
};


int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, q, s, t, x, qt;
    cin >> n >> q;
    SegmentTree st(n);
    while (q--) {
        cin >> qt >> s >> t;
        if (qt == 0) {
            cin >> x;
            st.update(s , t , x);
        } else {
            cout << st.query(s , t) << endl;
        }
    }

    return 0;
}

