using namespace std;

struct SegmentTree {

    int sum[1 << 18];
    int lazy[1 << 18];
    int size;

    void init(int size) {
        this->size = 1 << (int)ceil(log2(size));
    }

    void propagate(int k) {
        if (lazy[k]) {
            sum[k] += lazy[k];
            if (k < size - 1) {
                lazy[k * 2 + 1] += lazy[k] / 2;
                lazy[k * 2 + 2] += lazy[k] / 2;
            }
            lazy[k] = 0;
        }
    }

    void add(int a, int b, int v, int k, int l, int r) {
        if (b <= l || r <= a) {
            propagate(k);
            return;
        }
        if (a <= l && r <= b) {
            lazy[k] += v * (r - l);
            propagate(k);
            return;
        }
        propagate(k);
        add(a, b, v, k * 2 + 1, l, (l + r) / 2);
        add(a, b, v, k * 2 + 2, (l + r) / 2, r);
        sum[k] = sum[k * 2 + 1] + sum[k * 2 + 2];
    }

    void add(int a, int b, int v) {
        add(a, b, v, 0, 0, size);
    }

    int get(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) {
            return 0;
        }
        if (a <= l && r <= b) {
            propagate(k);
            return sum[k];
        }
        propagate(k);
        int vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
        return vl + vr;
    }

    int get(int a, int b) {
        return get(a, b, 0, 0, size);
    }
} st;

