/// template end ///
////////////////////

void solve()
{
	READ(int, n, q);
	auto tree = RangeSegTrees<llong>::RSQnRAQ(n);
	int origin = 1;
	REP(qq, q)
	{
		READ(int, c);
		if (c == 0)
		{
			READ(int, s, t, x);
			tree.update_range(s - origin, t + 1 - origin, x);
		}
		else
		{
			READ(int, s, t);
			llong v = tree.query(s - origin, t + 1 - origin);
			WRITE(v);
		}
	}
}

