int n;
ll dat[MAX*2], add[MAX*2];
void init(int m){
	n = 1;
	while(n < m)n *= 2;
}

void lazy_update(int k){
	if(k < n-1){
		add[k*2+1] += add[k];
		add[k*2+2] += add[k];
	}
	add[k] = 0;
}

void update(int a, int b, int x, int k, int l, int r){
	if(r <= a || b <= l)return;
	if(a <= l && r <= b){
		add[k] += x;
		dat[k] += add[k]*(r-l);
		lazy_update(k);
		return;
	}
	lazy_update(k);
	update(a, b, x, k*2+1, l, (l+r)/2);
	update(a, b, x, k*2+2, (l+r)/2, r);
	int m = ((l+r)/2-l);
	dat[k] = dat[k*2+1]+dat[k*2+2]+add[k*2+1]*m+add[k*2+2]*m;
	return;
}

ll find(int a, int b, int k, int l, int r){
	if(r <= a || b <= l)return 0;
	if(a <= l && r <= b){
		dat[k] += add[k]*(r-l);
		lazy_update(k);
		return dat[k];
	}
	lazy_update(k);
	ll vl = find(a, b, k*2+1, l, (l+r)/2);
	ll vr = find(a, b, k*2+2, (l+r)/2, r);
	int m = ((l+r)/2-l);
	dat[k] = dat[k*2+1]+dat[k*2+2]+add[k*2+1]*m+add[k*2+2]*m;
	return vl+vr;
}

