struct ST
{
	vector<int> data;
	vector<int> lazy;
	int size;

	ST(int n)
	{
		size = 1;
		while (size < n)size *= 2;
		data = vector<int>(2 * size - 1, 0);
		lazy = vector<int>(2 * size - 1, 0);
	}

	void apply(int k)
	{
		if (lazy[k] == 0)
		{
			return;
		}

		data[k] += lazy[k];

		if ((size - 1) > k)
		{
			lazy[2 * k + 1] += lazy[k] / 2;
			lazy[2 * k + 2] += lazy[k] / 2;
		}

		lazy[k] = 0;
	}

	void add(int s, int t, int x, int k, int l, int r)
	{
		if (r == -1)
		{
			r = size;
		}
		apply(k);
		if (t <= l || r <= s)
		{
			return;
		}
		if (s <= l&&r <= t)
		{
			lazy[k] += (x*(r - l));
			apply(k);
			return;
		}
		add(s, t, x, 2 * k + 1, l, (l + r) / 2);
		add(s, t, x, 2 * k + 2, (l + r) / 2, r);
		data[k] += data[2 * k + 1] + data[2 * k + 2];
	}

	int getSum(int s, int t, int k, int l, int r)
	{
		if (r == -1)
		{
			r = size;
		}
		apply(k);
		if (t <= l || r <= s)
		{
			return 0;
		}
		if (s <= l&&r <= t)
		{
			return data[k];
		}
		int sum = 0;
		sum += getSum(s, t, 2 * k + 1, l, (l + r) / 2);
		sum += getSum(s, t, 2 * k + 2, (l + r) / 2, r);
		return sum;
	}

	void draw()
	{
		printf("data\n");
		for (int i = 0; i != data.size(); i++)
		{
			printf("data[%d]:%d\n", i, data[i]);
		}
		printf("lazy\n");
		for (int i = 0; i != lazy.size(); i++)
		{
			printf("lazy[%d]:%d\n", i, lazy[i]);
		}
	}
};

int main() {
	int n, q;
	scanf("%d %d", &n, &q);

	ST st(n);

	int c, s, t, v;

	for (int i = 0; i < q; i++) {
		scanf("%d", &c);

		switch (c)
		{
		case 0:
			cin >> s >> t >> v;
			st.add(s - 1, t, v, 0, 0, -1);
			break;
		case 1:
			cin >> s >> t;
			cout << st.getSum(s - 1, t, 0, 0, -1) << endl;
			break;
		}

		//st.draw();
	}
}

