// 区間加算(RAQ) + 最小値取得(RMQ)
void RAQ_RMQ() {
    ll n, q;
    cin >> n >> q;

    using X = ll;
    using M = ll;
    auto fx = [](X x1, X x2) -> X { return min(x1, x2); };
    auto fa = [](X x, M m) -> X { return x + m; };
    auto fm = [](M m1, M m2) -> M { return m1 + m2; };
    auto fp = [](M m, ll n) -> M { return m; };

