}

// 一点更新 + 区間和 (RSQ)
void basic_RSQ() {
    ll n, q;
    cin >> n >> q;

    vector<ll> com(q), x(q), y(q);
    rep(i, q) { cin >> com[i] >> x[i] >> y[i]; }

    using X = ll;
    using M = ll;
    auto fx = [](X x1, X x2) -> X { return x1 + x2; };
    auto fa = [](X x, M m) -> X { return x + m; };
    auto fm = [](M m1, M m2) -> M { return m1 + m2; };
    auto fp = [](M m, long long n) -> M { return m * n; };
    int ex = 0;
    int em = 0;
    SegTreeLazyProportional<X, M> rmq(n, fx, fa, fm, fp, ex, em);

    rep(i, n) rmq.set(i, 0);
    rmq.build();
    // rmq.print_dat();
    // rmq.print_lazy();

    rep(i, q) {
        if (com[i] == 0) {
            x[i]--;
            rmq.update(x[i], x[i] + 1, y[i]);
            // rmq.print_dat();
            // rmq.print_lazy();
        } else {
            x[i]--;
            y[i]--;
            cout << rmq.query(x[i], y[i] + 1) << endl;
            // rmq.print_dat();
            // rmq.print_lazy();
        }
    }
}

// 区間加算(RAQ) + 区間和 (RSQ)
void RAQ_RSQ() {
    ll n, q;
    cin >> n >> q;
    using X = ll;
    using M = ll;
    auto fx = [](X x1, X x2) -> X { return x1 + x2; };
    auto fa = [](X x, M m) -> X { return x + m; };
    auto fm = [](M m1, M m2) -> M { return m1 + m2; };
    auto fp = [](M m, long long n) -> M { return m * n; };
    int ex = 0;
    int em = 0;
    SegTreeLazyProportional<X, M> rmq(n, fx, fa, fm, fp, ex, em);

    rep(i, n) rmq.set(i, 0);
    rmq.build();

    rep(i, q) {
        ll c;
        cin >> c;
        if (c == 0) {
            ll s, t, x;
            cin >> s >> t >> x;
            s--;
            t--;
            rmq.update(s, t + 1, x);
            // rmq.print_dat();
            // rmq.print_lazy();
        } else {
            ll s, t;
            cin >> s >> t;
            s--;
            t--;
            cout << rmq.query(s, t + 1) << endl;
            // rmq.print_dat();
            // rmq.print_lazy();
        }
    }
}

int main() {
    INIT;

    int flg = 4;

    switch (flg) {
        case 0:  // 一点更新 + 最小値取得(RMQ)
            basic_RMQ();
            break;
        case 1:  // 区間更新(RUQ) + 最小値取得(RMQ)
            RUQ_RMQ();
            break;

        case 2:  // 区間加算(RAQ) + 最小値取得(RMQ)
            RAQ_RMQ();
            break;

        case 3:  // 一点更新 + 区間和 (RSQ)
            basic_RSQ();
            break;

        case 4:  // 区間加算(RAQ) + 区間和 (RSQ)
            RAQ_RSQ();
            break;
    }

    return 0;
}

