typedef pair<int,int> P;
typedef vector<int> vec;
typedef vector<vec> mat;
const int MAX_N=200000;
ll n,dat[2*MAX_N-1];
vector<ll> lazy;
void init(int n_){
    n=1;
    while(n<n_) n*=2;
    fill(dat,dat+2*n-1,0);
    lazy.resize(2*n-1,0);
}
void eval(int k,int l,int r) {
    if(lazy[k]!=0){
        dat[k]+=lazy[k];
        if(r-l>1){
            lazy[2*k+1]+=lazy[k]/2;
            lazy[2*k+2]+=lazy[k]/2;
        }
        lazy[k]=0;
    }
}
void add(int a,int b,int x,int k,int l,int r){
    eval(k,l,r);
    if(r<=a||b<=l) return;
    if(a<=l&&r<=b){
        lazy[k]+=(r-l)*x;
        eval(k,l,r);
    }
    else{
        add(a,b,x,2*k+1,l,(l+r)/2);
        add(a,b,x,2*k+2,(l+r)/2,r);
        dat[k]=dat[2*k+1]+dat[2*k+2];
    }
}
ll sum(int a,int b,int k,int l,int r){
    if(r<=a||b<=l) return 0;
    eval(k,l,r);
    if(a<=l&&r<=b) return dat[k];
    ll vl=sum(a,b,2*k+1,l,(l+r)/2);
    ll vr=sum(a,b,2*k+2,(l+r)/2,r);
    return vl+vr;
}
int main(){
    int N,Q;
    cin>>N>>Q;
    init(N);
    rep(i,Q){
        int c,s,t,x;
        cin>>c;
        if(c==0) cin>>s>>t>>x,add(s-1,t,x,0,0,n);
        else cin>>s>>t,cout<<sum(s-1,t,0,0,n)<<"\n";
    }
}

