template<typename T, typename U>
class segment_tree {
  int sz;
  int Sz;
  int ht;
  vector<T> seg;
  vector<U> act;
  vector<bool> has_act;
  const function<T(T, T)> o;
  const function<void(T&, U)> oo;
  const function<void(U&, U)> ooo;
  const function<void(U&)> twice;
  const function<U(U)> half;
  const T tid;
  const U uid;

  public:
    segment_tree(
        int n,
        const function<T(T, T)> merge_function,
        const function<void(T&, U)> action,
        const function<void(U&, U)> composition,
        const function<void(U&)> twice,
        const function<U(U)> half,
        const T seg_id,
        const U act_id
      )
        : o(merge_function)
        , oo(action)
        , ooo(composition)
        , twice(twice)
        , half(half)
        , tid(seg_id)
        , uid(act_id)
      {
        ht = 1, sz = 1;
        while(sz < n) ht++, sz <<= 1;
        Sz = sz << 1;
        seg.assign(Sz, tid);
        act.resize(Sz, act_id);
        has_act.assign(Sz, false);
      }

    segment_tree(
        const vector<T>& data,
        const function<T(T, T)> merge_function,
        const function<void(T&, U)> action,
        const function<void(U&, U)> composition,
        const function<void(U&)> twice,
        const function<U(U)> half,
        const T seg_id,
        const U act_id
      )
        : segment_tree(
            data.size(),
            merge_function,
            action,
            composition,
            twice,
            half,
            seg_id,
            act_id
          )
      {
        copy(data.begin(), data.end(), seg.begin() + sz);
        for (int i = sz - 1; i >= 1; i--) seg[i] = o(seg[i << 1], seg[(i << 1) + 1]);
      }

    template<typename V, typename M, typename A>
    segment_tree(
        const V n_or_v,
        const M& merge_instance,
        const A& action_instance
      )
        : segment_tree(
          n_or_v,
          merge_instance.merge_function,
          action_instance.action,
          action_instance.composition,
          merge_instance.twice,
          merge_instance.half,
          merge_instance.id,
          action_instance.id
        )
      {
      }

    inline int lft (int i) {return i << 1;}
    inline int rgt (int i) {return (i << 1) + 1;}
    inline int upp (int i) {return i >> 1;}

    inline void propagate (
        int k,
        int L,
        int R
      )
      {
        if (has_act[k]) {
          oo(seg[k], act[k]);
          if (k < sz) {
            ooo(act[lft(k)], half(act[k]));
            ooo(act[rgt(k)], half(act[k]));
            has_act[lft(k)] = has_act[rgt(k)] = true;
          }
          act[k] = uid, has_act[k] = false;
        }
      }

    void update (
        int l,
        int r,
        T x,
        int k = 1,
        int L = 0,
        int R = -1
      )
      {
        if (R == -1) R = sz;
        if (k == 1) for (int i = 0; i < ht - 1; i++) twice(x);
        propagate(k, L, R);
        if (R <= l || r <= L) return;
        if (l <= L && R <= r) {
          ooo(act[k], x), has_act[k] = true;
          propagate(k, L, R);
        } else {
          int C = (L + R) >> 1;
          update(l, r, half(x), lft(k), L, C);
          update(l, r, half(x), rgt(k), C, R);
          seg[k] = o(seg[lft(k)], seg[rgt(k)]);
        }
      }

    T find (
        int l,
        int r,
        int k = 1,
        int L = 0,
        int R = -1
      )
      {
        if (R == -1) R = sz;
        propagate(k, L, R);
        if (R <= l || r <= L) return tid;
        if (l <= L && R <= r) {
          propagate(k, L, R);
          return seg[k];
        } else {
          int C = (L + R) >> 1;
          T lv = find(l, r, lft(k), L, C);
          T rv = find(l, r, rgt(k), C, R);
          seg[k] = o(seg[lft(k)], seg[rgt(k)]);
          return o(lv, rv);
        }
      }

    void print(int w = 4) {
      for (int i(1), last(2), output_size(w << ht); last <= Sz; last <<= 1, output_size >>= 1) {
        for (; i < last; i++) {
          cout << right << setw(w);
          cout << (seg[i] != tid ? to_string(seg[i]) : "");
          cout << setw(2) <<	"<";
          cout << left << setw(output_size - w - 2);
          cout << (has_act[i] ? to_string(act[i]) : "");
        }
        cout << endl;
      }
    }
};
int main() {
  int n, q;
  cin >> n >> q;
  segment_tree<long long, long long> sgt(
    vector<long long>(n, 0),
    range_sum_query<long long, long long>(),
    range_add_query<long long, long long>()
  );
  while (q--) {
    int c;
    cin >> c;
    if (c == 0) {
      int l, r, x;
      cin >> l >> r >> x;
      sgt.update(--l, r, x);
    } else {
      int l, r;
      cin >> l >> r;
      cout << sgt.find(--l, r) << endl; 
    }
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int INF=INT_MAX;
struct segtree
{
    vector<ll> node;
    vector<ll> lazy;
    vector<bool> lflg;
    int n;
    segtree(int sz)
    {
        n=1;while(n<sz) n*=2;
        node.resize(2*n,0);
        lazy.resize(2*n,0);
        lflg.resize(2*n,false);
    }
    void lazyupdate(int k, int l, int r)
    {
        if(lflg[k])
        {
            node[k]+=(r-l+1)*lazy[k];
            push(lazy[k],k,l,r);
            lazy[k]=0;
            lflg[k]=false;
        }
    }
    void push(int v,int k,int l,int r)
    {
        if(r-l>0)
        {
            lazy[2*k]+=v;
            lazy[2*k+1]+=v;
            lflg[2*k]=lflg[2*k+1]=true;
        }
    }
    void update(int qa, int qb, int v, int k=1, int l=1,int r=-1)
    {
        if(r<0) r=n;
        lazyupdate(k, l, r);
        if(qb<l||r<qa) return;
        if(qa<=l&&r<=qb)
        {
            node[k]+=(r-l+1)*v;
            push(v,k,l,r);
        }
        else
        {
            int m=(l+r)/2;
            update(qa,qb,v,2*k,l,m);
            update(qa,qb,v,2*k+1,m+1,r);
            node[k]=node[2*k]+node[2*k+1];
        }
    }
    ll get(int qa, int qb, int k=1, int l=1, int r=-1)
    {
        if(r<0) r=n;
        lazyupdate(k ,l, r);
        if(qb<l||r<qa) return 0;
        if(qa<=l&&r<=qb) return node[k];
        else
        {
            int m=(l+r)/2;
            ll lv=get(qa, qb, 2*k, l, m);
            ll rv=get(qa, qb, 2*k+1, m+1, r);
            return lv+rv;
        }
    }
};

int main()
{
    int n,q;
    scanf("%d %d",&n,&q);
    segtree tree(n);
    for(int i=0;i<q;i++){
        int c;
        scanf("%d",&c);
        if(c){
            int x,y;
            scanf("%d %d",&x,&y);
            cout<<tree.get(x,y)<<endl;
        }else{
            int s,t,v;
            scanf("%d %d %d",&s,&t,&v);
            tree.update(s,t,v);
        }
    }
}

