//abstruct lazy segment tree 抽象化遅延評価セグメント木（非再帰）
template<typename D, typename L>
struct segtree {
    using F = function<D(D, D)>;
    using G = function<D(L, D)>;
    using H = function<L(L, L)>;
    F f;
    G g;
    H h;
    D De;
    L Le;
    int n, height;
    vector<D> dat;
    vector<L> lazy;

    segtree(F f, G g, H h, D De, L Le):
        f(f), g(g), h(h), De(De), Le(Le){}

    void init(int n_) {
        n = 1;
        height = 0;
        while (n < n_) {
            n <<= 1;
            height++;
        }
        lazy.assign(2 * n, Le);
        dat.assign(2 * n, De);
    }

    void build(const vector<D> &v) {
        int n_ = v.size();
        init(n_);
        for (int i = 0; i < n_; i++) {
            dat[i + n] = v[i];
        }
        for (int i = n - 1; i > 0; i--) {
            dat[i] = f(dat[i << 1], dat[(i << 1) | 1]);
        }
    }

    D reflect(int k) {
        if (lazy[k] == Le) {
            return dat[k];
        } else {
            return g(lazy[k], dat[k]);
        }
    }

    void propagate(int k) {
        if (lazy[k] == Le) {
            return;
        }
        if (k < n) {
            lazy[k << 1] = h(lazy[k], lazy[k << 1]);
            lazy[(k << 1) | 1] = h(lazy[k], lazy[(k << 1) | 1]);
        }
        dat[k] = reflect(k);
        lazy[k] = Le;
    }

    void thrust(int k) {
        for (int i = height; i > 0; i--) {
            propagate(k >> i);
        }
    }

    void recalc(int k) {
        while (k >>= 1) {
            dat[k] = f(reflect(k << 1), reflect((k << 1) | 1));
        }
    }

    //[a, b)の範囲に何かする
    void update(int a, int b, L x) {
        if (a >= b) {
            return;
        }
        a += n;
        thrust(a);
        b += n - 1;
        thrust(b);
        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                lazy[l] = h(x, lazy[l]);
                l++;
            }
            if (r & 1) {
                r--;
                lazy[r] = h(x, lazy[r]);
            }
        }
        recalc(a);
        recalc(b);
    }

    //k番目にaを代入する
    void setval(int a, D x) {
        a += n;
        thrust(a);
        dat[a] = x;
        lazy[a] = Le;
        recalc(a);
    }

    //[a, b)の範囲の情報を得る
    D query(int a, int b) {
        if (a >= b) {
            return De;
        }
        a += n;
        thrust(a);
        b += n - 1;
        thrust(b);
        D vl = De, vr = De;
        for (int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {
                vl = f(vl, reflect(l));
                l++;
            }
            if (r & 1) {
                r--;
                vr = f(reflect(r), vr);
            }
        }
        return f(vl, vr);
    }
};

