template<class T> class Segtree_Lazy {
private:
    vector<T> datA, datB;
    int n;
    T INF;
public:
    Segtree_Lazy(int n_) {
      INF = 0; // edit here
      n = 1;
      while (n < n_) n *= 2;
      datA.assign(2 * n - 1, INF);
      datB.assign(2 * n - 1, INF);
    }
    Segtree_Lazy(vector<T>& A) {
      Segtree_Lazy(A.size());
      for (int i = 0; i < A.size(); i++) {
        add(i, i + 1, A[i], 0, 0, n);
      }
    }
    void add(int a, int b, T x, int k, int l, int r) {
      if (a <= l && r <= b) {
        datA[k] += x;
      } else if (l < b && a < r) {
        datB[k] += (min(b, r) - max(a, l)) * x;
        add(a, b, x, k * 2 + 1, l, (l + r) / 2);
        add(a, b, x, k * 2 + 2, (l + r) / 2, r);
      }
    }
    void add(int a,int b,T x){
      add(a,b,x,0,0,n);
    }
    T sum(int a, int b, int k, int l, int r) {
      if (b <= l || r <= a) {
        return INF;
      } else if (a <= l && r <= b) {
        return datA[k] * (r - l) + datB[k];
      } else {
        T res = (min(b, r) - max(a, l)) * datA[k];
        res += sum(a, b, k * 2 + 1, l, (l + r) / 2);
        res += sum(a, b, k * 2 + 2, (l + r) / 2, r);
        return res;
      }
    }
    T sum(int a,int b){
      return sum(a,b,0,0,n);
    }
};

int main(){
  int n,q;cin >> n >> q;
  Segtree_Lazy<ll> SL(n);
  for(int i = 0;i < q;i++){
    int c;cin >> c;
    if(c == 0){
      int s,t;cin >> s >> t;
      s--,t--;
      ll x;cin >> x;
      SL.add(s,t + 1,x);
    }else{
      int s,t;cin >> s >> t;
      s--,t--;
      cout << SL.sum(s,t+1) << '\n';
    }
  }
}

