/*
	update the value in the array, no return 
	foramtion: if() return; 
				f();
*/
void update(int update_left,int update_right,int new_value,int node_id,int node_left,int node_right){
    if(update_right < node_left || update_left > node_right)return;
    else if(update_left <= node_left && update_right >= node_right){
        data[node_id] += new_value;//to update the value(if in the right rage or a single point;
    }else{
        if(data[node_id] >= 0){ //deal with previous node (to check the if there is previous vlue to update)
            update(node_left,node_right,data[node_id],2*node_id+1,node_left,(node_left+node_right)/2);
            update(node_left,node_right,data[node_id],2*node_id+2,(node_left+node_right)/2+1,node_right);
            data[node_id] = 0;//why set -1 (unfold it)
        }
        //update with update_left and update_right
        update(update_left,update_right,new_value,2*node_id+1,node_left,(node_left+node_right)/2);
        update(update_left,update_right,new_value,2*node_id+2,(node_left+node_right)/2+1,node_right);
    }
}
ll query(int search_left,int search_right,int node_id,int node_left,int node_right){
    if(search_right < node_left || search_left > node_right){
        return 0;//not in the range
    }else{
    	if(node_left!=node_right&&data[node_id]!=0) {
    		data[node_id*2+1] += data[node_id];
    		data[node_id*2+2] += data[node_id];
    		data[node_id] = 0;
    	}
        if(node_left==node_right){
        	return data[node_id]; //not unfold
        }
        else{
            ll left = query(search_left,search_right,2*node_id+1,node_left,(node_left+node_right)/2);
            ll right = query(search_left,search_right,2*node_id+2,(node_left+node_right)/2+1,node_right);
            return (left+right);
        }
    }
}

#include <iostream>
