int get_n(int n) {
    int ret = 1; while(ret < n) ret <<= 1;

    return ret;
}

template<typename T>
struct LazySegTree {
    int N;
    vector<T> dat, lazy;

    LazySegTree(int n, T init = 0): N(get_n(n)), dat(2*N-1, init), lazy(2*N-1, 0) {}

    // add v to [a, b), current range: [l, r), node id: k
    void add (int a, int b, T v, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = N;

        if (r <= a || b <= l) return;

        if (a <= l && r <= b) {
            lazy[k] += v;
            return;
        }

        dat[k] += v * (min(b, r) - max(a, l));
        int mid = (l + r) / 2;
        add(a, b, v, 2 * k + 1, l, mid);
        add(a, b, v, 2 * k + 2, mid, r);
    }

    T sum(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = N;

        if (r <= a || b <= l) return 0;

        if (a <= l && r <= b) {
            return dat[k] + lazy[k] * (r - l);
        }

        T ret = lazy[k] * (min(b, r) - max(a, l));
        int mid = (l + r) / 2;
        ret += sum(a, b, 2 * k + 1, l, mid);
        ret += sum(a, b, 2 * k + 2, mid, r);

        return ret;
    }
};

