//LazySegtree t(/*initial vector*/,[](lint a,lint b){return a+b},0,lt_add|lt_upd);
#define lt_add 0b01//range add
#define lt_upd 0b10//range update
class LazySegtree{
public:
	using T=lint;
	using func=function<T(T,T)>;

	int n,sz;
	vector<T> node,lazyA,lazyU;
	vector<bool>lazyUFlag;
	int lazytype;

	//inline lint f(lint x,lint y){ return x|y; }
	func f;
	T e;

	LazySegtree(vector<T> v,func f,T e,int lazytype):f(f),e(e),lazytype(lazytype){
		sz=v.size();n=1;
		while(n<sz)n<<=1;
		node.resize(2*n,e);
		if(lazytype&lt_add)lazyA.resize(2*n);
		if(lazytype&lt_upd)lazyU.resize(2*n),lazyUFlag.resize(2*n);
		rep(sz)node[n+i]=v[i];
		rrep(sz)node[i]=f(node[2*i],node[2*i+1]);
	}
	void eval(int k,int l,int r){
		if(lazytype&lt_add){
			if(!lazyA[k])return;
			node[k]+=lazyA[k];
			if(r-l>1){
				lazyA[2*k]+=lazyA[k]/2;
				lazyA[2*k+1]+=lazyA[k]/2;
			}
			lazyA[k]=0;
		}
		if(lazytype&lt_upd){
			if(!lazyUFlag[k])return;
			node[k]=lazyU[k];
			if(r-l>1){
				lazyU[2*k]=lazyU[2*k+1]=lazyU[k];
				lazyUFlag[2*k]=lazyUFlag[2*k+1]=1;
			}
			lazyUFlag[k]=0;
		}
	}
	void update(int i,T x){
		node[i+=n]=x;
		while(i>>=1)node[i]=f(node[2*i],node[2*i+1]);
	}
	int update(int a,int b,T x,int k=1,int l=0,int r=-1){
		if(!(lazytype&lt_upd))return -1;
		if(r<0)r=n;
		eval(k,l,r);
		if(b<=l||r<=a)return 0;
		if(a<=l&&r<=b){
			lazyU[k]=x;
			lazyUFlag[k]=1;
			eval(k,l,r);
		} else{
			update(a,b,x,2*k,l,(l+r)/2);
			update(a,b,x,2*k+1,(l+r)/2,r);
			node[k] = min(node[2*k],node[2*k+1]);
		}
		return 0;
	}
	int add(int a,int b,T x,int k=1,int l=0,int r=-1){
		if(!(lazytype&lt_add))return -1;
		if(r<0)r=n;
		eval(k,l,r);
		if(b<=l||r<=a)return 0;
		if(a<=l&&r<=b)lazyA[k]+=(r-l)*x,eval(k,l,r);
		else{
			add(a,b,x,2*k,l,(l+r)/2);
			add(a,b,x,2*k+1,(l+r)/2,r);
			node[k]=f(node[2*k],node[2*k+1]);
		}
	}
	lint query(int a,int b,int k=1,int l=0,int r=-1){
		if(r<0)r=n;
		if(r<=a||b<=l)return e;
		eval(k,l,r);
		if(a<=l&&r<=b)return node[k];
		return f(query(a,b,2*k,l,(l+r)/2),query(a,b,2*k+1,(l+r)/2,r));
	}
};//unverified

int DSL_2_G(){//unverified
	lint n,q,com,s,t,x;in(n,q);
	vector<lint> a(n);
	LazySegtree tree(a,[](lint a,lint b){return a+b;},0,lt_add);
	rep(q){
		in(com,s,t);--s;//0-indexed,half-closed
		if(com)o(tree.query(s,t));
		else in(x),tree.add(s,t,x);
	}
	return 0;
}

int DSL_2_F(){//unverified
	lint n,q,com,s,t,x;in(n,q);
	vector<lint>a(n,INT_MAX);
	LazySegtree tree(a,[](lint a,lint b){return min(a,b);},INT_MAX,lt_upd);
	rep(q){
