#define top (int)(1e5)

int elems[top ], st[4 * top ], lazy[4 * top ], n, q, op, x, y;

void push(int pos) {

	if (lazy[pos] != 0) {

		st[pos << 1] *= lazy[pos << 1];
		st[pos << 1 | 1] *= lazy[pos << 1 | 1];
		lazy[pos << 1] += lazy[pos << 1];
		lazy[pos << 1 | 1] += lazy[pos << 1 | 1];

		lazy[pos] = 0;	
	}
}

int build(int start, int end, int pos) {

	if (start == end)
		return st[pos] = elems[start];

	int md = (start + end) >> 1;

	return st[pos] = build(start, md, pos << 1)
			+ build(md + 1, end, pos << 1 | 1);

}

int query(int a, int b, int start, int end, int pos) {

	if (a > end || b < start)
		return 0;

	if (start >= a && end <= b)
		return st[pos];

	int md = (start + end) >> 1;

	push(pos);

	return query(a, b, start, md, pos << 1)
			+ query(a, b, md + 1, end, pos << 1 | 1);

}

void updt(int a, int b, int start, int end, int pos, int val) {

	if (a > end || b < start)
		return;

	if (start >= a && end <= b) {
		st[pos] += val;
		lazy[pos] += val;
		return;
	}

	int md = (start + end) >> 1;

	push(pos);

	updt(a, b, start, md, pos << 1, val);
	updt(a, b, md + 1, end, pos << 1 | 1, val);

	st[pos] = st[pos << 1] + st[pos << 1 | 1];
}

int query(int a, int b) {

	if (a > b)
		swap(a, b);

	return query(a, b, 1, n, 1);
}

