#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAX = 1e5;

const ll id1 = 0;
const ll id2 = 0;
ll op(ll a, ll b) {
	return a + b;
}

struct node {
	int lb, ub;
	ll val, all;
	ll lazy;
	node *lch, *rch;
};

const int pmax = 5e6;
int it = 0;
node pool[pmax];

node *new_node(int l, int r, ll val) {
	pool[it] = (node) { l, r, val, val, id2, nullptr, nullptr };
	return pool + it++;
}

node *update(node *t, int lb, int ub) {
	t->all = op(op(t->lch ? t->lch->all : id1, t->val * (t->ub - t->lb)), t->rch ? t->rch->all : id1) + t->lazy * (ub - lb);
	return t;
}

node* add(node *t, int l, int r, ll val, int lb = 0, int ub = MAX) {
	if (r - l == 0) return t;
	if (!t) return new_node(l, r, val);
	if (l == lb && ub == r) {
		t->lazy += val;
		return update(t, lb, ub);
	}
	if (l == t->lb && r == t->ub) {
		t->val += val;
		return update(t, lb, ub);
	}
	int m = (lb + ub) >> 1;
	if (l <= m && m <= r && (m <= t->lb || t->ub <= m)) {
		swap(t->val, val);
		swap(t->lb, l);
		swap(t->ub, r);
	}
	if (r <= m) {
		t->lch = add(t->lch, l, min(r, m), val, lb, m);
	}
	else if (m <= l) {
		t->rch = add(t->rch, max(l, m), r, val, m, ub);
	}
	else {
		t->lch = add(t->lch, l, min(r, m), val, lb, m);
		t->rch = add(t->rch, max(l, m), r, val, m, ub);
	}
	return update(t, lb, ub);
}

ll find(node *t, int l, int r, ll lazy = id2, int lb = 0, int ub = MAX) {
	if (r - l <= 0) return id1;
	if (!t) return lazy * (r - l);
	if (l <= lb && ub <= r) return t->all + lazy * (r - l);
	int m = (lb + ub) >> 1;
	ll val = t->val * max(min(r, t->ub) - max(l, t->lb), 0);
	lazy += t->lazy;
	return op(op(find(t->lch, l, min(r, m), lazy, lb, m), val), find(t->rch, max(l, m), r, lazy, m, ub));
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int n, q;
	cin >> n >> q;
	node *root = nullptr;
	while (q--) {
		int type, s, t;
		cin >> type >> s >> t; --s;
		if (type) {
			printf("%lld\n", find(root, s, t));
		}
		else {
			ll x;
			cin >> x;
			root = add(root, s, t, x);
		}
	}
	return 0;
}

