class LazySegmentTree {
public:
    int N;
    vector<ll> node, lazy;

    LazySegmentTree(int _N, ll *a) {
        N = 1;
        while(N < _N) N *= 2;
        node.resize(2 * N - 1, 0);
        lazy.resize(2 * N - 1, 0);

        for(int i = 0; i < _N; i++){
            int k = i + N - 1;
            node[k] = a[i];
        }
        for(int i = N - 2; i >= 0; i--) {
            node[i] = node[2 * i + 1] + node[2 * i + 2];
        }
    }

    LazySegmentTree(vector<ll> a) {
        int sz = a.size();
        N = 1;
        while(N < sz) N *= 2;
        node.resize(2 * N - 1, 0);
        lazy.resize(2 * N - 1, 0);

        for(int i = 0; i < sz; i++){
            int k = i + N - 1;
            node[k] = a[i];
        }
        for(int i = N - 2; i >= 0; i--) {
            node[i] = node[2 * i + 1] + node[2 * i + 2];
        }
    }

    //[a, b) に c を加算
    void update(int a, int b, ll c) {
        Update(a, b, c, 0, 0, N);
    }

    void Update(int a, int b, ll c, int k, int l, int r) {
        eval(k, l, r);

        //範囲外
        if(b <= l || r <= a) return;

        //完全被覆
        else if(a <= l && r <= b) {
            lazy[k] += (r - l) * c;
            eval(k, l, r);
        }

        //一部被覆
        else {
            Update(a, b, c, 2 * k + 1, l, (l + r) / 2);
            Update(a, b, c, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }

        return;
    }

    //[a, b)の合計
    ll query(int a, int b) {
        return Query(a, b, 0, 0, N);
    }

    ll Query(int a, int b, int k, int l, int r) {
        eval(k, l, r);

        //範囲外
        if(b <= l || r <= a) return 0;

        //完全被覆
        else if(a <= l && r <= b) {
            return node[k];
        }

        //一部被覆
        else {
            ll v1 = Query(a, b, 2 * k + 1, l, (l + r) / 2);
            ll v2 = Query(a, b, 2 * k + 2, (l + r) / 2, r);
            return v1 + v2;
        }
    }

    void eval(int k, int l, int r) {
        if(lazy[k] != 0) {
            node[k] += lazy[k];
            if(r - l > 1) {
                lazy[2 * k + 1] += lazy[k] / 2;
                lazy[2 * k + 2] += lazy[k] / 2;
            }
            lazy[k] = 0;
        }
        return;
    }
};

int main(){
    int N, Q;
    cin >> N >> Q;

    vector<ll> ans;

    LazySegmentTree sg = LazySegmentTree(vector<ll>(N, 0));
    for(int q = 0; q < Q; q++) {
        int id, s, t, x;
        cin >> id;

        if(id == 0) {
            cin >> s >> t >> x;
            sg.update(s - 1, t, x);
        }
        else {
            cin >> s >> t;
            ans.push_back(sg.query(s - 1, t));
        }
    }

    for(ll val : ans) {
        cout << val << endl;
    }

    return 0;
}

#include <cstdio>
