using namespace std;

struct Add {
    int64_t operator ()(int64_t lhs, int64_t rhs) {
        return lhs + rhs;
    }
} add;

template <class T>
struct SegmentTree {
    size_t m, n;
    T e;
    vector<T> tree_modify, tree_query;
    SegmentTree(size_t m, T e=T()): m(m), n(1), e(e) {
        while (n <= m) n <<= 1;
        tree_modify.assign(n<<1, e);
        tree_query.assign(n<<1, e);
    }
    void range_modify(size_t a, size_t b, T x, size_t i, size_t l, size_t r) {
        if (a <= l && r <= b) {
            // [a, b) contains [l, r)
            tree_modify[i] += x;
        } else if (l < b && a < r) {
            // [a, b) overlaps [l, r)
            tree_query[i] += (min(b, r)-max(a, l)) * x;
            size_t c=(l+r)>>1;
            range_modify(a, b, x, i<<1|0, l, c);
            range_modify(a, b, x, i<<1|1, c, r);

            tree_query[i] = add(
                tree_query[i<<1|0]+tree_modify[i<<1|0],
                tree_query[i<<1|1]+tree_modify[i<<1|1]
            );
        }
    }
    T range_query(size_t a, size_t b, size_t i, size_t l, size_t r) {
        if (r <= a || b <= l) {
            // [a, b) does not overlap [l, r)
            return e;
        } else if (a <= l && r <= b) {
            // [a, b) contains [l, r)
            return tree_query[i] + tree_modify[i]*(r-l);
        }

        // [a, b) overlaps [l, r)
        size_t c=(l+r)>>1;
        T vl=range_query(a, b, i<<1|0, l, c);
        T vr=range_query(a, b, i<<1|1, c, r);

        return add(vl, vr) + tree_modify[i]*(min(b, r)-max(a, l));
    }
    void range_modify(size_t a, size_t b, T x) {
        range_modify(a, b, x, 1, 0, n);
    }
    void modify(size_t a, T x) {
        range_modify(a, a+1, x, 1, 0, n);
    }
    T range_query(size_t a, size_t b) {
        return range_query(a, b, 1, 0, n);
    }
    T range_query() {
        return range_query(0, m, 1, 0, n);
    }
};

int main() {
    size_t n;
    int q;
    scanf("%zu %d\n", &n, &q);

    SegmentTree<int64_t> tree(n);
    for (int i=0; i<q; ++i) {
        int query;
        scanf("%d", &query);

        if (query == 0) {
                size_t s, t;
                int64_t x;
                scanf("%zu %zu %lld", &s, &t, &x);
                --s, --t;
                tree.range_modify(s, t+1, x);
        } else if (query == 1) {
                size_t s, t;
                scanf("%zu %zu", &s, &t);
                --s, --t;
                printf("%lld\n", tree.range_query(s, t+1));
        } else {
            break;
        }
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

class LazySegmentTree{
    public:
    ll size;
    vector<ll> dat, lazy;

    LazySegmentTree(ll n){
        size = 1;
        while(size < n) size *= 2;

        dat = vector<ll>(2*size - 1, 0LL);
        lazy = vector<ll>(2*size - 1, 0LL);
    }

    void eval(ll k, ll l, ll r){
        if(lazy[k] != 0){
            dat[k] += lazy[k];

            // if not bottom of the tree
            if(r - l > 1){
                lazy[k*2+1] += lazy[k] / 2; 
                lazy[k*2+2] += lazy[k] / 2;
            }

            lazy[k] = 0;
        }
    }

    // Add x to [l, r)
    void add(ll a, ll b, ll x, ll k=0, ll l=0, ll r=-1){
        if(r < 0) r = size;

        eval(k, l, r);

        if(b <= l || r <= a) return;

        if(a <= l && r <= b){
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }else{
            add(a, b, x, k * 2 + 1, l, (l + r) / 2);
            add(a, b, x, k * 2 + 2, (l + r) / 2, r);
            dat[k] = dat[k*2+1] + dat[k*2+2];
        }
    }

    // Get sum of [l, r)
    ll getSum(ll a, ll b, ll k=0, ll l=0, ll r=-1){
        if(r < 0) r = size;
        if(b <= l || r <= a) return 0;

        eval(k, l, r);
        if(a <= l && r <= b) return dat[k];
        else{
            ll vl = getSum(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = getSum(a, b, k * 2 + 2, (l + r) / 2, r);
            return vl + vr;
        }
    }
};

