// ******************************************************************
// Segment Tree with Lazy Propagation
// Increment modification on range, queries for sum on range.
// ******************************************************************
template<typename T>
class SegTree{
    size_t n;
    int h;
    const T identity_element = 0;
    vector<T> data;
    vector<T> lazy;
    void apply(size_t i, T v, size_t k){
        data[i] = data[i] + v * k;
        if (i < n) lazy[i] = lazy[i] + v;
    }
    void build(size_t i){      // update all the parents of node i.
        for (size_t k = 2; i > 1; k <<= 1, i >>= 1){
            data[i/2] = data[i] + data[i^1] + lazy[i/2] * k;
        }
    }
    void push(size_t p){       // propagates the changes from the root to node p.
        for (int s = h, k = 1 << (h - 1); s > 0; --s, k >>= 1){
            size_t i = p >> s;
            if (lazy[i] != 0){
                apply(i*2, lazy[i], k);
                apply(i*2+1, lazy[i], k);
                lazy[i] = 0;
            }
        }
    }
    int calc_h(size_t nn){
        int hh = 1;
        for (; nn > 1; ++hh, nn >>= 1);
        return hh;
    }
public:
    SegTree(size_t _n): n(_n), h(calc_h(n)), data(2 * n, 0), lazy(n, 0){}
    SegTree(const vector<T> &src): n(src.size()), h(calc_h(n)), data(2 * n, 0), lazy(n, 0){
        for (int i = 0; i != n; ++i) data[n + i] = src[i];
        for (int i = n - 1; i != 0; --i) data[i] = data[i*2] + data[i*2+1];
    }
    void add(size_t L, size_t R, T v){  // add v to range [L, R)
        L += n;
        R += n;
        size_t L0 = L;
        size_t R0 = R;
        for (size_t k = 1; L < R; L >>= 1, R >>= 1, k <<= 1){
            if (L & 1) apply(L++, v, k);
            if (R & 1) apply(--R, v, k);
        }
        build(L0);
        build(R0 - 1);
    }
    T query(size_t L, size_t R){
        L += n;
        R += n;
        push(L);
        push(R - 1);
        T ret = identity_element;
        for (; L < R; L >>= 1, R >>= 1){
            if (L & 1) ret += data[L++];
            if (R & 1) ret += data[--R];
        }
        return ret;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, q;
    cin >> n >> q;
    SegTree<long long> seg(n);
    while (q--){
        int c;
        cin >> c;
        if (c == 0){
            int s, t, x;
            cin >> s >> t >> x;
            seg.add(s - 1, t, x);
        }else{
            int s, t;
            cin >> s >> t;
            cout << seg.query(s - 1, t) << '\n';
        }
    }
    return 0;
}

