template<class Monoid>
class SegmentTree {
private:
    using T = typename Monoid::T;
    Monoid op;
    const int n;
    vector<T> dat;
    void prop_to(int i) { dat[i] = op(dat[2*i], dat[2*i+1]); }

public:
    SegmentTree(int _n) : n(_n), dat(2*_n, op.identity()) {}
    SegmentTree(const vector<T> &v) : n(v.size()), dat(2*n)
    {
        copy(v.begin(), v.end(), dat.begin() + n);
        for (int i=n-1; i>0; i--) prop_to(i);
    }

    T get(int i)
    {
        T res = dat[i += n];
        while (i >>= 1) res = op(res, dat[i]);
        return res;
    }

    void update(int l, int r, const T &x) // [l, r)
    {
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) {dat[l] = op(dat[l], x); l++; }
            if (r & 1) {dat[r-1] = op(x, dat[r-1]); }
        }
    }
};

struct RSQ {
    using T = int;
    T operator() (const T &a, const T &b) { return a + b; }
    static constexpr T identity() { return 0; }
};


template<class T>
class SegmentTreeLazy {
private:
    const int n, h;
    vector<T> dat, lazy;

    void calc(int p, int k)
    {
        dat[p] = dat[p<<1] + dat[p<<1|1] + lazy[p] * k;
    }

    void apply(int p, T &value, int k)
    {
        dat[p] += value * k;
        if (p < n) lazy[p] += value;
    }

    void build(int l, int r)
    {
        int k = 2;
        for (l += n, r += n-1; l > 1; k <<= 1) {
            l >>= 1, r >>= 1;
            for (int i = r; i >= l; i--) calc(i, k);
        }
    }

    void push(int l, int r)
    {
        int s = h, k = 1 << (h - 1);
        for (l += n, r += n-1; s > 0; s--, k >>= 1) {
            for (int i = l>>s; i <= r>>s; i++) {
                if (lazy[i] != 0) {
                    apply(i<<1, lazy[i], k);
                    apply(i<<1|1, lazy[i], k);
                    lazy[i] = 0;
                }
            }
        }
    }

public:
    SegmentTreeLazy(int _n) : n(_n), h(__lg(n)), dat(2*n), lazy(2*n) {}

    void modify(int l, int r, T &value)
    {
        push(l, l+1);
        push(r-1, r);

        int l0 = l, r0 = r, k = 1;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1, k <<= 1) {
            if (l&1) apply(l++, value, k);
            if (r&1) apply(r-1, value, k);
        }

        build(l0, l0 + 1);
        build(r0 - 1, r0);
    }

    T query(int l, int r)
    {
        push(l, l+1);
        push(r-1, r);

        T res = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l&1) res += dat[l++];
            if (r&1) res += dat[r-1];
        }

        return res;
    }

    void dump()
    {
        cerr << "-----------" << endl;
        int hh = __lg(2*n);
        for (int i=1; i<=hh; i++) {
            for (int j=0; j<1<<(i-1); j++) {
                int idx = (1<<(i-1)) + j;
                cerr << dat[idx] << " (" << lazy[idx] << ") ";
            }
            cerr << endl;
        }
        cerr << "-----------" << endl;
    }

};

