template <typename T>
struct LazzySegTreeSum
{
  private:
    ll N = 1;
    vector<T> node,lazy;

  public:
    LazzySegTreeSum(vector<T> vec)
    {
        ll size = vec.size();

        while (N < size)
        {
            N *= 2;
        }

        node.resize(2 * N - 1);
        lazy.resize(2 * N - 1, 0);

        REP(i, size)
        {
            node[i + N - 1] = vec[i];
        }

        for (int i = N - 2; 0 <= i; i--)
        {
            node[i] = node[2 * i + 1] + node[2 * i + 2];
        }
    }

    void eval(int k, int l, int r)
    {
        if(lazy[k] != 0)
        {
            node[k] += lazy[k];

            if(r - l > 1)
            {
                lazy[2 * k + 1] += lazy[k] / 2;
                lazy[2 * k + 2] += lazy[k] / 2;
            }
        }

        lazy[k] = 0;
    }

    //[a, b]
    void add(int a, int b, T value, int k = 0, int l = 0, int r = -1)
    {
        if(r < 0) r = N;

        eval(k, l, r);

        if(b <= l || r <= a) return;

        if(a <= l && r <= b) 
        {
            lazy[k] += (r - l) * value;
            eval(k, l, r);
        }
        else
        {
            add(a, b, value, 2 * k + 1, l, (l + r) / 2);
            add(a, b, value, 2 * k + 2, (l + r) / 2, r);

            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }

    //[a, b]
    T getSum(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if(r < 0) r = N;

        eval(k, l, r);

        if(b <= l || r <= a) return 0;
        if(a <= l && r <= b) return node[k];

        ll vl = getSum(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getSum(a, b, 2 * k + 2, (l + r) / 2, r);

        return vl + vr;
    }
};


int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, Q;
    cin >> N >> Q;

    LazzySegTreeSum<ll> seg(vector<ll> (N, 0));

    REP(i, Q)
    {
        int com;
        cin >> com;
        if(com == 0)
        {
            int s, t, x;
            cin >> s >> t >> x;

            seg.add(s - 1, t, x);
        }
        else
        {
            int s, t;
            cin >> s >> t;

            Cout(seg.getSum(s - 1, t));
        }
    }
    return 0;
}

