#include <bits/stdc++.h>
#define endl '\n'
using namespace std;

#define top (int)(1e5)
#define ll long long

ll elems[top ], st[4 * top ], lazy[4 * top ];
int n, q, op, x, y;

void push(int pos, int a, int b) {

	if (lazy[pos] != 0) {

		int md = (a + b) >> 1;

		st[pos << 1] += ((md - a + 1) * lazy[pos]);
		st[pos << 1 | 1] += ((b - md) * lazy[pos]);
		lazy[pos << 1] += lazy[pos];
		lazy[pos << 1 | 1] += lazy[pos];

		lazy[pos] = 0;
	}
}

int build(int start, int end, int pos) {

	if (start == end)
		return st[pos] = elems[start];

	int md = (start + end) >> 1;

	return st[pos] = build(start, md, pos << 1)
			+ build(md + 1, end, pos << 1 | 1);

}

ll query(int a, int b, int start, int end, int pos) {

	if (a > end || b < start)
		return 0;

	if (start >= a && end <= b)
		return st[pos];

	int md = (start + end) >> 1;

	push(pos, start, end);

	return query(a, b, start, md, pos << 1)
			+ query(a, b, md + 1, end, pos << 1 | 1);

}

void updt(int a, int b, int start, int end, int pos, ll val) {

	if (a > end || b < start)
		return;

	if (start >= a && end <= b) {
		st[pos] += ((end - start + 1) * val);
		lazy[pos] += val;
		return;
	}

	int md = (start + end) >> 1;

	push(pos, start, end);

	updt(a, b, start, md, pos << 1, val);
	updt(a, b, md + 1, end, pos << 1 | 1, val);

	st[pos] = st[pos << 1] + st[pos << 1 | 1];
}

int query(int a, int b) {

	if (a > b)
		swap(a, b);

	return query(a, b, 1, n, 1);
}

int main() {

	cin.tie(0), cout.tie(0), ios_base::sync_with_stdio(0);

	cin >> n >> q;

	while (q--) {

		cin >> op;

		if (!op) {

			cin >> x >> y >> op;

			if (x > y)
				swap(x, y);

			updt(x, y, 1, n, 1, op);

		} else {

			cin >> x >> y;

			cout << query(x, y) << endl;
		}
	}
	return 0;
}

#include <iostream>
