template<typename T>
struct SegTree {
  int n;
  vector<T> dat, lazy;
  SegTree(int _n) : n(), dat(_n*4,0), lazy(_n*4,0) {
    int x = 1;
    while (x < _n) x <<= 1;
    n = x;
  }

  void eval(int k, int p) {
    if (lazy[k] == 0) return;
    if (k < n-1) {
      lazy[k*2+1] += lazy[k];
      lazy[k*2+2] += lazy[k];
    }
    dat[k] += lazy[k] * p;
    lazy[k] = 0;
  }
  void update(int a, int b, int x, int k, int l, int r) {
    eval(k, r-l);
    if (r <= a || b <= l) return;
    if (a <= l && r <= b) {
      lazy[k] += x;
      eval(k, r-l);
    } else {
      int mid = (l+r)>>1;
      update(a,b,x,k*2+1,l,mid);
      update(a,b,x,k*2+2,mid,r);
      dat[k] = dat[k*2+1] + dat[k*2+2];
    }
  }
  void update(int a, int b, int x) { update(a,b,x,0,0,n); }

  T query(int a, int b, int k, int l, int r) {
    eval(k, r-l);
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return dat[k];
    int mid = (l+r)>>1;
    T vl = query(a,b,k*2+1,l,mid);
    T vr = query(a,b,k*2+2,mid,r);
    return vl + vr;
  }
  T query(int a, int b) { return query(a,b,0,0,n); }
  inline T operator[](int a) { return query(a,a+1); }
};

