const intt initt = 0;

intt n, q;
intt t[maxx << 2], lazy[maxx << 2];

void init () {
    memset (lazy, -1, sizeof (lazy));
}

void relax (intt v, intt l, intt r) {
    t[v] += (r - l + 1) * lazy[v];
    if (l != r)
        lazy[v << 1] += lazy[v] + (lazy[v << 1] == -1), lazy[v << 1 | 1] += lazy[v] + (lazy[v << 1 | 1] == -1);
    lazy[v] = -1;
}

/*
void build (intt v, intt l, intt r) {
    if (l == r) {
        t[v] += initt;
        return;
    }
    intt mid = (l + r) >> 1;
    build (v << 1, l, mid);
    build (v << 1 | 1, mid + 1, r);
    t[v] = t[v << 1] + t[v << 1 | 1];
}
*/

void update (intt v, intt l, intt r, intt i, intt j, intt val) {
    if (lazy[v] != -1)
        relax (v, l, r);
    if (j < l || i > r)
        return;
    if (i <= l && r <= j) {
        lazy[v] += val + (lazy[v] == -1);
        relax (v, l, r);
        return;
    }
    intt mid = (l + r) >> 1;
    update (v << 1, l, mid, i, j, val);
    update (v << 1 | 1, mid + 1, r, i, j, val);
    t[v] = t[v << 1] + t[v << 1 | 1];
}

intt query (intt v, intt l, intt r, intt i, intt j) {
    if (j < l || i > r)
        return 0;
    if (lazy[v] != -1)
        relax (v, l, r);
    if (i <= l && r <= j)
        return t[v];
    intt mid = (l + r) >> 1;
    return query (v << 1, l, mid, i, j) +
           query (v << 1 | 1, mid + 1, r, i, j);
}

