class segtree {
  private:
    struct node {
      int sum = 0, uniform = 0, size = 1;
      int value() {
        return size * uniform + sum;
      }
    };
    vector<node> dat;
    int sz;
    void add(int a, int b, int x, int k, int l, int r) {
      if (b <= l || r <= a) return;
      if (a <= l && r <= b) {
        dat[k].uniform += x;
        return;
      }
      auto const m = (l + r) / 2;
      add(a, b, x, 2 * k + 1, l, m);
      add(a, b, x, 2 * k + 2, m, r);
      dat[k].sum = dat[2 * k + 1].value() + dat[2 * k + 2].value();
    }
    int sum(int a, int b, int k, int l, int r) {
      if (b <= l || r <= a) return 0;
      if (a <= l && r <= b)
        return dat[k].value();
      dat[2 * k + 1].uniform += dat[k].uniform;
      dat[2 * k + 2].uniform += dat[k].uniform;
      dat[k].sum += dat[k].uniform * dat[k].size;
      dat[k].uniform = 0;
      auto const m = (l + r) / 2;
      return sum(a, b, 2 * k + 1, l, m) + sum(a, b, 2 * k + 2, m, r);
    }
  public:
    void add(int a, int b, int x) {
      add(a, b, x, 0, 0, sz);
    }
    int sum(int a, int b) {
      return sum(a, b, 0, 0, sz);
    }
    segtree(int n) {
      sz = 1;
      while (sz < n) sz *= 2;
      dat.resize(2 * sz - 1);
      for (int i = sz - 2; i >= 0; i--)
        dat[i].size = dat[2 * i + 1].size + dat[2 * i + 2].size;
    }
};

