/** 区间表示：[p->dl,p->dr]
 *  从0开始计数，[0,n-1]
 *  线段树RSQ
 *
 */

struct Node
{
    int dl,dr,s,delta;
    Node *pl,*pr;
};
int n,q;

void build(Node *&p,int l,int r)
{
    p=(Node *)malloc(sizeof(Node));
    p->dl=l,p->dr=r,p->s=0,p->delta=0;
    p->pl=null,p->pr=null;
    int mid=(l+r)/2;
    if(r>l)
    {
        build(p->pl,l,mid);
        build(p->pr,mid+1,r);
    }
}
void pushdown(Node *&p,int delta)
{
    p->pl->s += p->delta*(p->pl->dr - p->pl->dl+1);
    p->pr->s += p->delta*(p->pr->dr - p->pr->dl+1);
    p->pl->delta += p->delta;
    p->pr->delta += p->delta;
    p->delta=0;
}

void update(Node *&p,int l,int r,int data)
{
    ///[l,r]必然位于[p->dl,p->dr]子区间
    if(p->delta>0 && p->dr>p->dl)
        pushdown(p,p->delta);

    p->s+=data*(r-l+1);
    if(p->dl==l &&p->dr==r)
    {
        p->delta=data;
        return ;
    }
    int mid=(p->dl+p->dr)/2;
    if(r<=mid)
        update(p->pl,l,r,data);
    else if(l>mid)
        update(p->pr,l,r,data);
    else
        update(p->pl,l,mid,data),update(p->pr,mid+1,r,data);
}
int query(Node *&p,int l,int r)
{
    ///一个查询区间最终必然被分成若干个小的区间和，最后一个定会完全和区间贴合
    if(p->delta>0 && p->dr>p->dl)
        pushdown(p,p->delta);

    if(p->dl==l &&p->dr==r)
        return p->s;
    int mid=(p->dl+p->dr)/2;
    ///判断查询区间与当前区间的位置关系
    //全部位于左侧
    if(r<=mid)
        return query(p->pl,l,r);
    //全部位于右侧
    else if(l>mid)
        return query(p->pr,l,r);
    //两个都有
    else
        return query(p->pl,l,mid)+query(p->pr,mid+1,r);
}

int main()
{
    int i,type,tx,ty,x;
    Node *tree=null;
    scanf("%d%d",&n,&q);
    build(tree,0,n-1);
    for(i=0;i<q;i++)
    {
        scanf("%d",&type);
        if(type==0)
        {
            scanf("%d%d%d",&tx,&ty,&x);
            tx--,ty--;
            update(tree,tx,ty,x);
        }else
        {
            scanf("%d%d",&tx,&ty);
            tx--,ty--;
            int ans=query(tree,tx,ty);
            printf("%d\n",ans);
        }
    }
    return 0;
}

