int size;
vector<int> val;
vector<int> lazy;
vector<int> width;

void lazy_propagate(int p) {
    val[p] += lazy[p] * width[p];
    if (p < size-1) {
        lazy[p*2+1] += lazy[p];
        lazy[p*2+2] += lazy[p];
    }
    lazy[p] = 0;
}

void update(int wishl,int wishr,int watchl,int watchr,int k,int x) {
    if(wishr<=watchl || watchr<=wishl) {
        lazy_propagate(k);
        return;
    }
    if(wishl<=watchl && watchr<=wishr) {
        lazy[k]+=x;
        lazy_propagate(k);
        return;
    }
    int mid=(watchl+watchr)/2;
    lazy_propagate(k);
    update(wishl,wishr,watchl,mid,k*2+1,x);
    update(wishl,wishr,mid,watchr,k*2+2,x);
    val[k]=val[k*2+1]+val[k*2+2];
}

int getsum(int wishl,int wishr,int watchl,int watchr,int k) {
    if(wishr<=watchl || watchr<=wishl) {
        return 0;
    }
    if(wishl<=watchl && watchr<=wishr) {
        lazy_propagate(k);
        return val[k];
    }
    int mid=(watchl+watchr)/2;
    lazy_propagate(k);
    int sl=getsum(wishl,wishr,watchl,mid,k*2+1);
    int sr=getsum(wishl,wishr,mid,watchr,k*2+2);
    return sl+sr;
}

