/*
この遅延セグメント木でできること
range_sum_segment_tree tree(v) (vはvec v(n))で宣言したとする
・tree.add(x,y,z):区間[x,y)に対してzを加算
・tree.getsum(x,y):区間[x,y)の和を取得
*/
struct range_sum_segment_tree
{
private:
    ll n;
    vec node, lazy; //値配列と遅延配列
public:
    range_sum_segment_tree(vec v)
    {
        // 最下段のノード数は元配列のサイズ以上になる最小の 2 冪 -> これを n とおく
        // セグメント木全体で必要なノード数は 2n-1 個である
        ll sz = v.size();
        n = 1;
        while (n < sz)
            n *= 2;
        node.resize(2 * n - 1);
        lazy.resize(2 * n - 1, 0);
        // 最下段に値を入れたあとに、下の段から順番に値を入れる
        // 値を入れるには、自分の子の 2 値を参照すれば良い
        loop(i, sz) node[i + n - 1] = v[i];
        pool(i, n - 2) node[i] = node[2 * i + 1] + node[2 * i + 2];
    }
    // k 番目のノードについて遅延評価を行う
    void eval(ll k, ll l, ll r)
    {

        // 遅延配列が空でない場合、自ノード及び子ノードへの
        // 値の伝播が起こる
        if (lazy[k] != 0)
        {
            node[k] += lazy[k];

            // 最下段かどうかのチェックをしよう
            // 子ノードは親ノードの 1/2 の範囲であるため、
            // 伝播させるときは半分にする
            if (r - l > 1)
            {
                lazy[2 * k + 1] += lazy[k] / 2;
                lazy[2 * k + 2] += lazy[k] / 2;
            }

            // 伝播が終わったので、自ノードの遅延配列を空にする
            lazy[k] = 0;
        }
    }
    //区間[a,b)に対してxを加算
    void add(ll a, ll b, ll x, ll k = 0, ll l = 0, ll r = -1)
    {
        if (r < 0)
            r = n;

        // k 番目のノードに対して遅延評価を行う
        eval(k, l, r);

        // 範囲外なら何もしない
        if (b <= l || r <= a)
            return;

        // 完全に被覆しているならば、遅延配列に値を入れた後に評価
        if (a <= l && r <= b)
        {
            lazy[k] += (r - l) * x;
            eval(k, l, r);
        }

        // そうでないならば、子ノードの値を再帰的に計算して、
        // 計算済みの値をもらってくる
        else
        {
            add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = node[2 * k + 1] + node[2 * k + 2];
        }
    }
    //区間[a,b)の和を求める
    ll getsum(ll a, ll b, ll k = 0, ll l = 0, ll r = -1)
    {
        if (r < 0)
            r = n;
        if (b <= l || r <= a)
            return 0;

        // 関数が呼び出されたら評価！
        eval(k, l, r);
        if (a <= l && r <= b)
            return node[k];
        ll vl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;
    }
};
int main()
{
    cout << fixed << setprecision(30);
    ll n, q;
    cin >> n >> q;
    vec a(n);
    range_sum_segment_tree tree(a);
    loop(i, q)
    {
        ll que, s, t, x;
        cin >> que >> s >> t;
        s--;
        t--;
        if (que == 0)
        {
            cin >> x;
            tree.add(s, t + 1, x);
        }
        else
        {
            putout(tree.getsum(s, t + 1));
        }
    }
    return 0;
}

