const int INF = 1e9;
const ll MOD = 1e9 + 7;
double EPS = 1e-8;

const int sqrtN = 350;      // N : 1e5 => 350, 2e5 => 450
const int MAX_N = sqrtN * sqrtN + 1;
using TYPE = ll;
const TYPE DFLT = 0LL;    // max => -INF, min => INF, sum => 0

// change f1, f2
inline void f1(TYPE& a, const TYPE& b) {
    a += b;
}
inline void f2(TYPE& a, const TYPE& b) {
    a += b;
}

TYPE dat[MAX_N];
TYPE ans[sqrtN];
TYPE lazy[sqrtN];

inline int get_i(int x) {return x / sqrtN;}
inline int get_j(int x) {return x % sqrtN;}
inline int get_idx(int i, int j) {return i * sqrtN + j;}


void calcLazy(int i) {
    REP(j, 0, sqrtN) {
        f1(dat[get_idx(i, j)], lazy[i]);
    }
    lazy[i] = 0;
}

void add(int l, int r, TYPE s) {
    REP(i, get_i(l), sqrtN) {
        int x = get_idx(i, 0), y = x + sqrtN;
        if (r <= x) break;
        if (l <= x && y <= r) {
            f1(ans[i], s);
            f1(lazy[i], s);
        } else {
            calcLazy(i);
            REP(idx, max(x, l), min(y, r)) {
                f1(dat[idx], s);
            }
            REP(j, 0, sqrtN) {
                f2(ans[i], dat[get_idx(i, j)]);
            }
        }
    }
}

TYPE query(int l, int r) {
    TYPE ret = DFLT;
    REP(i, get_i(l), sqrtN) {
        int x = get_idx(i, 0), y = x + sqrtN;
        if (r <= x) break;
        if (l <= x && y <= r) {
            f2(ret, ans[i]);
        } else {
            calcLazy(i);
            REP(idx, max(x, l), min(y, r)) {
                f2(ret, dat[idx]);
            }
        }
    }
    return ret;
}

int main() {
    int n, q;
    cin >> n >> q;
    rep(i, q) {
        ll a, s, t, x;
        cin >> a >> s >> t;
        s--;
        if(a == 0) {
            cin >> x;
            add(s, t, x);
        } 
        else {
            cout << query(s, t) << endl;
        }
    }
}

