#include<bits/stdc++.h>
using namespace std;

struct BinaryIndexedTree{
  int N;
  vector<long long> bit[2]; 
  //全て0で初期化
  BinaryIndexedTree(int size){
    bit[0].resize(size+1,0);
    bit[1].resize(size+1,0);
    N=size+1;
  }
  void add_sub(int a,int b,int w){
    for(int i=b;i<N;i+=(i & (-i))){
      bit[a][i]+=w;
    }
    return;
  }
  //区間[a,b)のところv[a],v[a+1], ,v[b-1]に値wを加える
  void add(int a,int b,int w){
    add_sub(0,a,-w*(a-1));
    add_sub(0,b,w*(b-1));
    add_sub(1,a,w);
    add_sub(1,b,-w);
    return;
  } 

  long long sum_sub(int p,int c){
    long long sum=0;
    for(int i=c;i>0;i-=(i & (-i))){
      sum+=bit[p][i];
    }
    return(sum);
  }
  //区間[0,c)のところの和v[0]+v[1]+ +v[c-1]を求める。
  long long sum(int c){
    //(p[0]+p[1]+  +p[c])+(q[0]+q[1]+ +q[c])c を求める。
    long long ret=0;
    ret+=sum_sub(0,c);
    ret+=(sum_sub(1,c)*c);
    return(ret);
  }
  //[a,b)の区間和を取得する。
  long long query(int a,int b){
    long long ret=0;
    ret=sum(b-1);
    ret-=sum(a-1);
    return(ret);
  }
};
