class LazySegmentTree
{
 private:
    int n;
    vector<int> node,lazy;
 public:
    LazySegmentTree(int sz){
        n=1;
        while(n<sz) n*=2;
        node.assign(2*n-1,0LL);
        lazy.assign(2*n-1,0LL);
    }
    void update(int a,int b,int x,int k,int l,int r){
        if(a<=l and r<=b){
            node[k]+=x*(r-l);
            lazy[k]+=x;
        }else{
            if(lazy[k]!=0) push(k,l,r),lazy[k]=0;
            if(check(a,b,l,(l+r)/2)) update(a,b,x,2*k+1,l,(l+r)/2);
            if(check(a,b,(l+r)/2,r)) update(a,b,x,2*k+2,(l+r)/2,r);
            node[k]=node[2*k+1]+node[2*k+2];
        }
    }
    int get(int a,int b,int k,int l,int r){
        if(a<=l and r<=b){
            return node[k];
        }else{
            if(lazy[k]!=0) push(k,l,r),lazy[k]=0;
            int res=0;
            if(check(a,b,l,(l+r)/2)) res+=get(a,b,2*k+1,l,(l+r)/2);
            if(check(a,b,(l+r)/2,r)) res+=get(a,b,2*k+2,(l+r)/2,r);
            return res;
        }
    }
    void push(int k,int l,int r){
        node[2*k+1]+=lazy[k]*(r-l)/2; lazy[2*k+1]+=lazy[k];
        node[2*k+2]+=lazy[k]*(r-l)/2; lazy[2*k+2]+=lazy[k];
    }
    bool check(int a,int b,int l,int r){
        return max(a,l)<min(b,r);
    }
    void update(int a,int b,int x){ update(a,b,x,0,0,n); }
    int get(int a,int b){ return get(a,b,0,0,n); }
};

