template<typename T>
class SegmentTree
{
    private:
        int n;
        vector<T> node, lazy;

    public:
        SegmentTree(vector<T> V) {
            int a = V.size();
            n = 1;
            while (n < a) {
                n *= 2;
            }
            node.resize(2 * n - 1);
            lazy.resize(2 * n - 1);

            rep(i, a) {
                node[n - 1 + i] = V[i];
            }
            for (int i = n - 2; i >= 0; i--) {
                node[i] = node[2 * i + 1] + node[2 * i + 2];
            }
        }

        void eval(int k, int l, int r) {
            if (lazy[k] != 0) {
                node[k] += lazy[k];

                if (r - l > 1) {
                    lazy[2 * k + 1] += (lazy[k] / 2);
                    lazy[2 * k + 2] += (lazy[k] / 2);
                }

                lazy[k] = 0;
            }
        }

        void add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
            if (r < 0) r = n;
            eval(k, l, r);
            if (r <= a || b <= l) return;
            if (a <= l && r <= b) {
                lazy[k] += (r - l) * x;
                eval(k, l, r);
            }
            else {
                add(a, b, x, 2 * k + 1, l, (l + r) / 2);
                add(a, b, x, 2 * k + 2, (l + r) / 2, r);
                node[k] = node[2 * k + 1] + node[2 * k + 2];
            }
        }

        T get(int a, int b, int k = 0, int l = 0, int r = -1) {
            if (r < 0) r = n;
            if (r <= a || b <= l) return 0; 

            eval(k, l, r);

            if (a <= l && r <= b) return node[k];
            T vl = get(a, b, 2 * k + 1, l, (l + r) / 2);
            T vr = get(a, b, 2 * k + 2, (l + r) / 2, r);
            return vl + vr;
        }

        void show() {
            cout << "n: " << n << endl;
            rep(i, 2 * n - 1) {
                cout << "i: " << i << ", node[i]: " << node[i] << endl;
            }
        }
};

int main() {
    int N, Q; cin >> N >> Q;
    SegmentTree<ll> sg(vector<ll>(N, 0));

    rep(i, Q) {
        int C;
        cin >> C;

        if (C == 0) {
            int S, T, X;
            cin >> S >> T >> X;
            sg.add(S - 1, T, X);
        } else {
            int S, T;
            cin >> S >> T;
            cout << sg.get(S - 1, T) << endl;
        }
    }
}

