    }else if(cmd==1){
      int s,t;
      scanf("%d %d",&s,&t);
      printf("%d\n",query(s-1,t,0,0,size));
    }
  }
  for(int i=0;i<2*size-1;i++) printf("laz[%d] = %d\n",i,dat[i]);
  return 0;
}

