    val = vector<long long>(size*2, 0);
    lazy = vector<long long>(size*2, 0);
    width = vector<long long>(size*2, 1);

    for (int i = size-2; i >= 0; i--) {
        width[i] = width[i*2+1] + width[i*2+2];
    }

    while (q--) {
