enum type {
    COMMAND_ADD,
    COMMAND_GET_SUM,
};

struct pair {
    int64_t sum;
    int64_t lazy_sum;
};

struct range {
    int start;
    int end;
};

#define NUM_MAX 100000
#define NUM2_MAX (1<<17)

#define ROOT_NODE 1

int is_overlap(struct range r1, struct range r2) {
    return r1.end > r2.start && r2.end > r1.start;
}

int is_contain(struct range elem, struct range box) {
    return elem.start >= box.start && elem.end <= box.end;
}

void unlazy(struct pair *seg, int node, struct range nr) {
    if(!seg[node].lazy_sum) return;
    int64_t lazy = seg[node].lazy_sum;
    seg[node].sum += lazy;
    seg[node].lazy_sum = 0;
    // if not simple
    if(nr.end - nr.start > 1) {
        seg[node*2].lazy_sum += lazy / 2;
        seg[node*2+1].lazy_sum += lazy / 2;
    }
}

void add_range(struct pair *seg, int64_t val, struct range r, int node, struct range nr) {

    // First of all, the lazy value should be woken
    unlazy(seg, node, nr);
    if(!is_overlap(r, nr)) return;
    if(is_contain(nr, r)) {
        seg[node].lazy_sum += val * (nr.end-nr.start);
#ifdef DEBUG
        printf("add_range: %d.lazy_sum -> %d\n", node, val*(nr.end-nr.start));
#endif
        unlazy(seg, node, nr);
        return;
    }
    struct range left = { nr.start, (nr.start+nr.end)/2 };
    struct range right = { (nr.start+nr.end)/2, nr.end };
    add_range(seg, val, r, node*2, left);
    add_range(seg, val, r, node*2+1, right);
    seg[node].sum = seg[node*2].sum + seg[node*2+1].sum;
}

int64_t get_sum(struct pair *seg, struct range r, int node, struct range nr) {

    // First of all, the lazy value should be woken
    unlazy(seg, node, nr);
    if(!is_overlap(r, nr)) return 0;
    if(is_contain(nr, r)) return seg[node].sum;

    struct range left = { nr.start, (nr.start+nr.end)/2 };
    struct range right = { (nr.start+nr.end)/2, nr.end };
    int64_t s1 = get_sum(seg, r, node*2, left);
    int64_t s2 = get_sum(seg, r, node*2+1, right);
    return s1 + s2;
}


int main(void) {
    int num, queries;
    get_int2(&num, &queries);
    int i;
    static struct pair seg[NUM2_MAX*2];
    static int64_t ans[NUM_MAX];
    int aidx = 0;

    int num2 = 1;
    while(num > num2) num2 *= 2;

    struct range whole = {0, num2};
    for(i = 0; i < queries; i++) {
        int type = get_int();
        switch(type) {
            case COMMAND_ADD:
                {
                    int start, end, val;
                    get_int3(&start, &end, &val);
                    // 1-indexed -> 0-indexed
                    start--; end--;
                    struct range r = {start, end+1};
                    add_range(seg, val, r, ROOT_NODE, whole);
                }
                break;
            case COMMAND_GET_SUM:
                {
                    int start, end;
                    get_int2(&start, &end);
                    // 1-indexed -> 0-indexed
                    start--; end--;
                    struct range r = {start, end+1};
                    ans[aidx++] = get_sum(seg, r, ROOT_NODE, whole);
                }
                break;
            default:
                break;
        }
    }
    for(i = 0; i < aidx; i++) {
        printf("%lld\n", ans[i]);
    }

    return 0;
}

#include<stdio.h>

int nums1[400005], nums2[400005], leaves;

void help(int node, int left, int right) {
  if (nums2[node] == 0)
    return;
  nums1[node] += nums2[node] * (right - left);

  if (right - left > 1) {
    nums2[node * 2] += nums2[node];
    nums2[node * 2 + 1] += nums2[node];
  }

  nums2[node] = 0;
}

void add(int nl, int nr, int val, int node, int left, int right) {
  help(node, left, right);

  if (right <= nl || left >= nr)
    return;
  else if (left >= nl && right <= nr) {
    nums2[node] += val;
    help(node, left, right);
  } else {
    add(nl, nr, val, node * 2, left, (left + right) / 2);
    add(nl, nr, val, node * 2 + 1, (left + right) / 2, right);
    nums1[node] = nums1[node * 2] + nums1[node * 2 + 1];
  }
}

int get(int nl, int nr, int node, int left, int right) {
  help(node, left, right);

  if (left >= nr || right <= nl)
    return 0;
  else if (left >= nl && right <= nr)
    return nums1[node];
  else
    return get(nl, nr, node * 2, left, (left + right) / 2) + get(nl, nr, node * 2 + 1, (left + right) / 2, right);
}

int main() {
  int n, q, i, x, y, z, command, d[100010] = {};

  scanf("%d %d", &n, &q);

  for(leaves = 1; leaves < n; leaves *= 2);

  for(i = 0; i < leaves; i++) {
    if (i < n)
      nums1[leaves + i] = d[i];
    else
      nums1[leaves + i] = 0;
  }

  for (i = leaves - 1; i; i--)
    nums1[i] = nums1[i * 2] + nums1[i * 2 + 1];

  for(i = 0; i < q; i++) {
    scanf("%d %d %d", &command, &x, &y);

    if (command)
      printf("%d\n", get(x - 1, y, 1, 0, leaves));
    else {
      scanf("%d", &z);
      add(x - 1, y, z, 1, 0, leaves);
    }
  }
}

