#define MAX_N 100005

int s, t, x;
long long ans;

typedef struct { int l, r; long long w; int f; } NODE;
NODE node[1<<19];

void segTree(int k, int l, int r) 
{
	int m;

	node[k].l = l, node[k].r = r;
	if (node[k].l == node[k].r) return;
	m = (l + r) >> 1;
    segTree( k << 1, l, m);
    segTree((k << 1) | 1, m+1, r);
}

void down(int k) 
{
    node[ k << 1     ].f += node[k].f;
    node[(k << 1) | 1].f += node[k].f;
    node[ k << 1     ].w += (long long)node[k].f * (node[ k << 1     ].r - node[ k << 1     ].l + 1);
    node[(k << 1) | 1].w += (long long)node[k].f * (node[(k << 1) | 1].r - node[(k << 1) | 1].l + 1);
    node[k].f = 0;
}

void ask_point(int k)
{
	int m;

    if (node[k].l == node[k].r) {
        ans = node[k].w;
        return;
    }
    if (node[k].f) down(k);
    m = (node[k].l + node[k].r) >> 1;
    if (s <= m) ask_point(k << 1);
    else ask_point((k << 1) | 1);
}

void change_point(int k) 
{
	int m;

    if (node[k].l == node[k].r) {
        node[k].w += x;
        return;
    }
    if (node[k].f) down(k);
    m = (node[k].l + node[k].r) >> 1;
    if (s <= m) change_point(k << 1);
    else change_point((k << 1) | 1);
    node[k].w = node[k << 1].w + node[(k << 1) | 1].w;
}

void ask_interval(int k)
{
	int m;

    if (node[k].l >= s && node[k].r <= t) {
        ans += node[k].w;
        return;
    }
    if (node[k].f) down(k);
    m = (node[k].l + node[k].r) >> 1;
    if (s <= m) ask_interval(k << 1);
    if (m < t) ask_interval((k << 1) | 1);
}

void change_interval(int k) 
{
	int m;

	if (node[k].l >= s && node[k].r <= t) {
        node[k].w += (node[k].r - node[k].l + 1) * x;
        node[k].f += x;
        return;
    }
    if (node[k].f) down(k);
    m = (node[k].l + node[k].r) >> 1;
    if (s <= m) change_interval(k << 1);
    if (m < t) change_interval((k << 1) | 1);
    node[k].w = node[k << 1].w + node[(k << 1) | 1].w;
}

int main()
{
	int n, q, op;

	n = in();
    segTree(1, 1, n);

	q = in();
	while (q--) {
		op = gc() & 1, gc();
		if (op) {
			ans = 0;
			s = in(), t = in();
			if (s == t) ask_point(1);
			else ask_interval(1);
			out(ans);
		} else {
			s = in(), t = in(), x = in();
			if (s == t) change_point(1);
			else change_interval(1);
		}
	}
	return 0;
}

#include <stdio.h>
#include <stdlib.h>
#define ll long long
#define rep(i,l,r)for(ll i=(l);i<(r);i++)

//*
//遅延セグ木ここから
//↓ここを変える
typedef struct sayouso{ll k;}sayouso;
typedef struct atai{ll a,len;}atai;
//↑ここを変える

typedef struct node{sayouso T;atai x;}node;
node *lsegN,*lseg;
ll lsegNUM;

//↓ここから変える
sayouso sid={0};
atai aid={0,1};
atai xx(atai x,atai y){
	atai ret;
	ret.a=x.a+y.a;
	ret.len=x.len+y.len;
	return ret;
}
atai Tx(sayouso T,atai x){
	atai ret;
	ret.a=T.k*x.len+x.a;
	ret.len=x.len;
	return ret;
}
sayouso TT(sayouso S,sayouso T){
	sayouso ret;
	ret.k=S.k+T.k;
	return ret;
}
//↑ここまで変える

//要素数(2ベキ)でこれを呼ぶ
void lseguse(ll n){
	lsegN=(node*)calloc(2*n,sizeof(node));
	lsegNUM=n;
	lseg=lsegN+lsegNUM;
	rep(i,0,lsegNUM){
		lseg[i].x=aid;
		lseg[i].T=sid;
	}
	for(int i=lsegNUM-1;i>0;i--){
		lsegN[i].x=xx(lsegN[2*i].x,lsegN[2*i+1].x);
		lsegN[i].T=sid;
	}
}
//lseg[i].xに値を与えてから初期化
void lseginit(){
	for(int i=lsegNUM-1;i>0;i--)lsegN[i].x=xx(lsegN[2*i].x,lsegN[2*i+1].x);
}
void lsegupdatesub(ll l,ll r,sayouso T,ll i,ll cl,ll cr){
	if(l>=r)return;
	//disjointなとき
	if(cr<=l||r<=cl)return;
	//完全に含むとき
	if(l<=cl&&cr<=r){
		lsegN[i].T=TT(T,lsegN[i].T);
		return;
	}
	//どちらでもないとき
	//遅延伝播
	lsegN[2*i  ].T=TT(lsegN[i].T,lsegN[2*i  ].T);
	lsegN[2*i+1].T=TT(lsegN[i].T,lsegN[2*i+1].T);
	//再帰的に更新
	ll cm=(cl+cr)/2;
	lsegupdatesub(l,r,T,2*i  ,cl,cm);
	lsegupdatesub(l,r,T,2*i+1,cm,cr);
	//自身のnodeを更新
	lsegN[i].x=xx(Tx(lsegN[2*i].T,lsegN[2*i].x),Tx(lsegN[2*i+1].T,lsegN[2*i+1].x));
	lsegN[i].T=sid;
}
void lsegupdate(ll l,ll r,sayouso T){lsegupdatesub(l,r,T,1,0,lsegNUM);}
