//Unordered Pair
class UP<A, B> {
	A a;
	B b;

	UP(A a, B b) {
		this.a = a;
		this.b = b;
	}

	static <A, B> UP<A, B> make(A a, B b) {
		return new UP<A, B>(a, b);
	}

	public UP<A, B> clone() {
		return make(a, b);
	}

	public boolean equals(Object o) {
		if (o == this)
			return true;
		if (!(o instanceof UP))
			return false;
		UP<?, ?> p = (UP<?, ?>) o;
		boolean aok = a == null ? p.a == null : a.equals(p.a);
		boolean bok = b == null ? p.b == null : b.equals(p.b);
		return aok && bok;
	}

	public String toString() {
		return "(" + a.toString() + ", " + b.toString() + ")";
	}
}

interface F1<A> {
	A f();
}

interface F2<A, B> {
	B f(A a);
}

interface F3<A, B, C> {
	C f(A a, B b);
}

interface F4<A, B, C, D> {
	D f(A a, B b, C c);
}

// util
class U {
	static <A> ArrayList<A> make(int n, F2<Integer, A> maker) {
		ArrayList<A> res = new ArrayList<A>();
		for (int i = 0; i < n; i++) {
			res.add(maker.f(i));
		}
		return res;
	}

	static <A> ArrayList<A> filter(ArrayList<A> as, F2<A, Boolean> pred) {
		ArrayList<A> res = new ArrayList<A>();
		for (A a : as) {
			if (pred.f(a))
				res.add(a);
		}
		return res;
	}

	static <A> ArrayList<A> map(ArrayList<A> as, F2<A, A> f) {
		return make(as.size(), (i) -> f.f(as.get(i)));
	}

	static <A, B> ArrayList<UP<A, B>> zip(ArrayList<A> as, ArrayList<B> bs) {
		return make(min(as.size(), bs.size()), (i) -> UP.make(as.get(i), bs.get(i)));
	}

	static <A extends Comparable<A>> A min(A a, A b) {
		return a.compareTo(b) < 0 ? a : b;
	}

	static <A extends Comparable<A>> A max(A a, A b) {
		return a.compareTo(b) > 0 ? a : b;
	}

	static <A extends Comparable<A>> A clamp(A a, A min, A max) {
		return a.compareTo(min) < 0 ? min : a.compareTo(max) > 0 ? max : a;
	}
}
// Lazy Segment Tree
class LST<A, Op> {
	// 0: unused, 1: root
	private ArrayList<A> dat;
	private ArrayList<Op> lazy;
	private F3<A, A, A> merger;
	private F3<A, Op, A> applier;
	private F3<Op, Op, Op> opMerger;
	private F3<Op, Integer, Op> multiplier;
	private A e;
	private Op id;
	private int h;
	private int n;

	LST(int num, F3<A, A, A> merger, F3<A, Op, A> applier, F3<Op, Op, Op> opMerger, A e, Op id) {
		this(num, merger, applier, opMerger, null, e, id);
	}

	LST(int num, F3<A, A, A> merger, F3<A, Op, A> applier, F3<Op, Op, Op> opMerger, F3<Op, Integer, Op> multiplier,
			A e, Op id) {
		this.merger = merger;
		this.applier = applier;
		this.opMerger = opMerger;
		this.multiplier = multiplier;
		this.e = e;
		this.id = id;
		h = 0;
		while ((1 << h) < num)
			h++;
		n = 1 << h;
		int size = n << 1;
		dat = U.make(size, i -> e);
		lazy = U.make(size, i -> id);
	}

	void init(A[] as) {
		for (int i = 0; i < n << 1; i++) {
			lazy.set(i, id);
		}
		for (int i = 0; i < n; i++) {
			dat.set(n + i, i < as.length ? as[i] : e);
		}
		for (int i = n - 1; i > 0; i--) {
			dat.set(i, merge(dat.get(i << 1), dat.get(i << 1 | 1)));
		}
	}

	A get(int i) {
		return query(i, i + 1);
	}

	void set(int i, A a) {
		prop(i += n);
		dat.set(i, a);
		lazy.set(i, id);
		backprop(i);
	}

	A query(int from, int until) {
		int a = from + n;
		int b = until + n - 1;
		prop(a);
		prop(b);
		int l = a;
		int r = b + 1;
		A al = e;
		A ar = e;
		int len = 1;
		while (l < r) {
			if ((l & 1) != 0) {
				al = merge(al, eval(l++, len));
			}
			if ((r & 1) != 0) {
				ar = merge(eval(--r, len), ar);
			}
			l >>= 1;
			r >>= 1;
			len <<= 1;
		}
		return merge(al, ar);
	}

	void apply(int from, int until, Op o) {
		int a = from + n;
		int b = until + n - 1;
		prop(a);
		prop(b);
		int l = a;
		int r = b + 1;
		while (l < r) {
			if ((l & 1) != 0) {
				lazy.set(l, mergeOp(lazy.get(l), o));
				l++;
			}
			if ((r & 1) != 0) {
				r--;
				lazy.set(r, mergeOp(lazy.get(r), o));
			}
			l >>= 1;
			r >>= 1;
		}
		backprop(a);
		backprop(b);
	}

	int size() {
		return n;
	}

	private A merge(A a, A b) {
		return a == e ? b : b == e ? a : merger.f(a, b);
	}

	private Op mergeOp(Op o, Op p) {
		return o == id ? p : p == id ? o : opMerger.f(o, p);
	}

	private A apply(A a, Op o) {
		return o == id ? a : applier.f(a, o);
	}

	private Op multiply(Op o, int num) {
		return o == id || multiplier == null || num == 1 ? o : multiplier.f(o, num);
	}

	private void flush(int k, int len) {
		A a = dat.get(k);
		Op o = lazy.get(k);
		if (o == id)
			return;
		if (k < n) {
			lazy.set(k << 1, mergeOp(lazy.get(k << 1), o));
			lazy.set(k << 1 | 1, mergeOp(lazy.get(k << 1 | 1), o));
		}
		a = apply(a, multiply(o, len));
		dat.set(k, a);
		lazy.set(k, id);
	}

	private A eval(int k, int len) {
		return apply(dat.get(k), multiply(lazy.get(k), len));
	}

	private void prop(int k) {
		for (int i = h; i > 0; i--) {
			flush(k >> i, 1 << i);
		}
	}

	private void backprop(int k) {
		int len = 1;
		while ((k >>= 1) > 0) {
			dat.set(k, merge(eval(k << 1, len), eval(k << 1 | 1, len)));
			len <<= 1;
		}
	}
}

