import java.util.*;
import java.io.*;

class SegmentTree{
	int n;
	long node[], lazy[];
	SegmentTree(int m){
		n = 1;
		while(n<m) {
			n<<=1;
		}
		node = new long[2*n-1];
		lazy = new long[2*n-1];
	}

	void add(int a, int b, int x, int k, int l, int r) {
		if(r < 0) r = n;//初期呼び出し用

		eval(k, l, r);//ここでなぜ必要？
		if(r<=a || b<=l) {
			return;
		}
		if(a<=l&&r<=b) {
			lazy[k] += x * (r - l);
			eval(k, l, r);//なぜ必要？
			return;
		}
		add(a, b, x, 2*k+1,l, (l+r)/2);
		add(a, b, x, 2*k+2,(l+r)/2, r);
		node[k] = node[2*k+1] + node[2*k+2];
	}

	long getSum(int a, int b, int k, int l, int r) {
		if(r<0) r = n;
		if(r<=a||b<=l) return 0;
		eval(k, l, r);
		if(a<=l&&r<=b) {
			return node[k];
		}
		long vl = getSum(a, b, 2*k+1, l, (l+r)/2);
		long vr = getSum(a, b, 2*k+2, (l+r)/2, r);
		return vl + vr;
	}

	void eval(int k, int l, int r) {
		if(lazy[k]!=0) {
			node[k] += lazy[k];
			if(r - l > 1) {
				lazy[2*k+1] += lazy[k]/2;
				lazy[2*k+2] += lazy[k]/2;
			}
		}
		lazy[k] = 0;
	}

}


