class SqrtDecompositionRSQRAQ {
	int N, K;
	long[] data;
	long[] bucketAdd;
	long[] bucketSum;
	static final int sqrtN = 512;

	public SqrtDecompositionRSQRAQ(int n) {
		N = n;
		K = (N + sqrtN - 1) / sqrtN;
		data = new long[K * sqrtN];
		bucketAdd = new long[K];
		bucketSum = new long[K];
	}

	void add(int s, int t, int x) {
		for (int k = 0; k < K; ++k) {
			int l = k * sqrtN, r = (k + 1) * sqrtN;
			if (r <= s || t <= l)
				continue;
			if (s <= l && r <= t) {
				bucketAdd[k] += x;
			} else {
				for(int i = Math.max(s, l); i < Math.min(t, r); ++i) {
					data[i] += x;
				}
				bucketSum[k] = 0;
				for(int i = l; i < r; i++){
					bucketSum[k] += data[i];
				}
			}
		}
	}

	long getSum(int s, int t){
		long result = 0;
		for (int k = 0; k < K; ++k) {
			int l = k * sqrtN, r = (k + 1) * sqrtN;
			if (r <= s || t <= l)
				continue;
			if (s <= l && r <= t) {
				result += bucketAdd[k]*sqrtN + bucketSum[k];
			} else {
				int count = 0;
				for(int i = Math.max(s, l); i < Math.min(t, r); ++i) {
					result += data[i];
					count++;
				}

				result += bucketAdd[k]*count;
			}
		}
		return result;
	}

	void printBucket(){
		System.out.println("********************");
		for(int i = 0; i < 20; i++){
			System.out.print(bucketAdd[i]+" ");
		}
		System.out.println();
		for(int i = 0; i < 20; i++){
			System.out.print(bucketSum[i]+" ");
		}
		System.out.println("\n*********************\n");
	}
