		int m; // bakets?????°

		public RSQ_RAQ_SqrtDecomposition(int[] data) {
			this.n = data.length;
			this.data = data;
			this.d = (int)Math.sqrt(n);

			this.m = (n + d - 1) / d;
			bakets = new int[m];
			Arrays.fill(bakets, 0);
			sb = new int[m];
		}

		// l,r:0-indexed
		// [l,r)?????????add
		void add(int l, int r, int x) {
			int bl = l / d;
			int br = (r - 1) / d;
			for (int i = bl; i <= br; i++) {
				int tmpl = i * d;
				int tmpr = Math.min((i + 1) * d, n);
				if (tmpl >= l && tmpr <= r) {
					bakets[i] += x;
				} else {
					tmpl = Math.max(tmpl, l);
					tmpr = Math.min(tmpr, r);
					for (int j = tmpl; j < tmpr; j++) {
						data[j] += x;
						sb[i] += x;
					}
				}
			}
		}

		// l,r:0-indexed
		// [l,r)?????????add
		int getSum(int l, int r) {
			int bl = l / d;
			int br = (r - 1) / d;
			int ret = 0;
			for (int i = bl; i <= br; i++) {
				int tmpl = i * d;
				int tmpr = Math.min((i + 1) * d, n);
				if (tmpl >= l && tmpr <= r) {
					ret += d * bakets[i];
					ret += sb[i];
				} else {
					tmpl = Math.max(tmpl, l);
					tmpr = Math.min(tmpr, r);
					for (int j = tmpl; j < tmpr; j++) {
						ret += data[j];
						ret += bakets[i];
					}
				}
			}

			return ret;
		}
	}

