class RUQ extends LazySqrtDecomposition<Long> {
    public RUQ(int n, Long e) {
        super(n, e);
    }

    @Override
    protected Long f(Long x, Long y) {
        return x + y;
    }

    @Override
    protected Long g(Long x, Long y, int t) {
        return x + (y * t);
    }

    @Override
    protected Long h(Long x, Long y) {
        return x + y;
    }
}

