class LazySegTree {
	long e = 0;
	long f(long a, long b) { return sum(a, b); }
	long e2 = 0;
	long g(long a, long b) { return sum(a, b); }

	int n;
	long nodes[];
	long lazy[];

	LazySegTree(long[] a) { init(a); }
	LazySegTree(int len, long x) {
		long a[] = new long[len];
		fill(a, x);
		init(a);
	}
	LazySegTree(int len) { init(len); }

	void init(long[] a) {
		init(a.length);
		for(int i = 0; i < a.length; i ++) {
			nodes[i + n - 1] = a[i];
		}
		for(int i = n - 2; i >= 0; i --) {
			nodes[i] = f(nodes[i * 2 + 1], nodes[i * 2 + 2]);
		}
	}
	void init(int len) {
		n = 1;
		while(n < len) { n *= 2; }
		nodes = new long[n * 2 - 1];
		fill(nodes, e);
		lazy = new long[n * 2 - 1];
		fill(lazy, e2);
		for(int i = n - 2; i >= 0; i --) {
			nodes[i] = f(nodes[i * 2 + 1], nodes[i * 2 + 2]);
		}
	}

	void eval(int k, int l, int r) {
		if(lazy[k] != e2) {
			nodes[k] = g(nodes[k], lazy[k]);
			if(r - l > 1) {
				lazy[k * 2 + 1] = g(lazy[k * 2 + 1], lazy[k] / 2);
				lazy[k * 2 + 2] = g(lazy[k * 2 + 2], lazy[k] / 2);
			}
			lazy[k] = e2;
		}
	}

	void update(int a, int b, long val) { update(a, b, val, 0, 0, n); }
	void update(int a, int b, long val, int k, int l, int r) {
		eval(k, l, r);
		if(b <= l || r <= a) { return; }
		if(a <= l && r <= b) {
			lazy[k] = g(lazy[k], val * (r - l));
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	long find(int a, int b) { return find(a, b, 0, 0, n); }
	long find(int a, int b, int k, int l, int r) {
		if(b <= l || r <= a) { return e; }
		eval(k, l, r);
		if(a <= l && r <= b) { return nodes[k]; }
		return f(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}
}

	}
}

