	public interface Inverse<T> {
		public T inverse(T element);
	}

	public interface Group<T> extends Monoid<T>, Inverse<T>{

	}

	public interface Abelian<T> extends Group<T>, Commutative<T> {

	}

	public class AdditionLong implements Abelian<Long>, LazySegmentInterface<Long, Long>{

		@Override
		public Long operate(Long left, Long right) {
			return left + right;
		}

		@Override
		public Long unit() {
			return 0L;
		}

		@Override
		public Long inverse(Long element) {
