	private static class RSQ_RAQ_SqrtDecomposition {
		int[] data;
		// buckets???????????????????¶???????
		int[] bucketsAdd;
		// buckets??????????¨????(??????????¨?????????????????¶???????)
		long[] bucketsSum;
		int n; // data???????´???°
		int d; // 1??????buckets?????§??????
		int m; // buckets?????°

		// ???????´???????????????????bucketsSum, getSum ???????¨??????????????????????????????¨???
		public RSQ_RAQ_SqrtDecomposition(int[] data) {
			this.n = data.length;
			this.data = data;
			this.d = (int)Math.sqrt(n);
			this.m = (n + d - 1) / d;

			bucketsAdd = new int[m];
			Arrays.fill(bucketsAdd, 0);

			bucketsSum = new long[m];
		}

		// l,r:0-indexed
		// [l,r)?????????add
		void add(int l, int r, int x) {
			int bl = l / d;
			int br = (r - 1) / d;
			for (int i = bl; i <= br; i++) {
				int tmpl = i * d;
				int tmpr = Math.min((i + 1) * d, n);

				if (tmpl >= l && tmpr <= r) {
					bucketsAdd[i] += x;
				} else {
					tmpl = Math.max(tmpl, l);
					tmpr = Math.min(tmpr, r);
					for (int j = tmpl; j < tmpr; j++) {
						data[j] += x;
						bucketsSum[i] += x;
					}
				}
			}
		}

		// l,r:0-indexed
		// [l,r)??????
		long getSum(int l, int r) {
			int bl = l / d;
			int br = (r - 1) / d;
			long ret = 0;
			for (int i = bl; i <= br; i++) {
				int tmpl = i * d;
				int tmpr = Math.min((i + 1) * d, n);

				if (tmpl >= l && tmpr <= r) {
					ret += (long)(tmpr - tmpl) * bucketsAdd[i];
					ret += bucketsSum[i];
				} else {
					tmpl = Math.max(tmpl, l);
					tmpr = Math.min(tmpr, r);
					for (int j = tmpl; j < tmpr; j++) {
						ret += data[j];
						ret += bucketsAdd[i];
					}
				}
			}

			return ret;
		}
	}

