// AOJ DSL_2_G RSQ and Range Add Query by Sqrt Decomposition
public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int[] data = new int[n];
		RSQ_RAQ_SqrtDecomposition ruq = new RSQ_RAQ_SqrtDecomposition(data);

		int q = sc.nextInt();
		for (int i = 0; i < q; i++) {
			int cmd = sc.nextInt();

			if (cmd == 0) {
				int s = sc.nextInt() - 1;
				int t = sc.nextInt() - 1;
				int x = sc.nextInt();

				ruq.add(s, t + 1, x);
			} else if (cmd == 1) {
				int s = sc.nextInt() - 1;
				int t = sc.nextInt() - 1;

				pr.println(ruq.query(s, t + 1));
//				pr.flush();
			}
		}
	}

	// RSQ and RAQ by Sqrt Decomposition
	private static class RSQ_RAQ_SqrtDecomposition {
		int[] data;
		// buckets内のすべてに足す値
		int[] bucketsAdd;
		// buckets内の合計値(除く上記のすべてに足す値)
		long[] bucketsSum;
		int n; // dataの要素数
		int d; // 1つのbucketsの大きさ
		int m; // bucketsの数

		// 各要素の値の範囲、bucketsSum, getSum の合計値のオーバフローに注意
		public RSQ_RAQ_SqrtDecomposition(int[] data) {
			this.n = data.length;
			this.data = data;
			this.d = (int)Math.sqrt(n);
			this.m = (n + d - 1) / d;

			bucketsAdd = new int[m];
			Arrays.fill(bucketsAdd, 0);

			bucketsSum = new long[m];
		}

		// l,r:0-indexed
		// [l,r)の値にadd
		void add(int l, int r, int x) {
			int bl = l / d;
			int br = (r - 1) / d;
			for (int i = bl; i <= br; i++) {
				int tmpl = i * d;
				int tmpr = Math.min((i + 1) * d, n);

				if (tmpl >= l && tmpr <= r) {
					bucketsAdd[i] += x;
				} else {
					tmpl = Math.max(tmpl, l);
					tmpr = Math.min(tmpr, r);
					for (int j = tmpl; j < tmpr; j++) {
						data[j] += x;
						bucketsSum[i] += x;
					}
				}
			}
		}

		// l,r:0-indexed
		// [l,r)の和
		long query(int l, int r) {
			int bl = l / d;
			int br = (r - 1) / d;
			long ret = 0;
			for (int i = bl; i <= br; i++) {
				int tmpl = i * d;
				int tmpr = Math.min((i + 1) * d, n);

				if (tmpl >= l && tmpr <= r) {
					ret += (long)(tmpr - tmpl) * bucketsAdd[i];
					ret += bucketsSum[i];
				} else {
					tmpl = Math.max(tmpl, l);
					tmpr = Math.min(tmpr, r);
					for (int j = tmpl; j < tmpr; j++) {
						ret += data[j];
						ret += bucketsAdd[i];
					}
				}
			}

			return ret;
		}
	}

