    static long[] datb;

    static void add(int a, int b, int x, int k, int l, int r){
        if (a<=l && r<=b) data[k]+=x;
        else if (!(b<=l || r<=a)) {
            datb[k]+=(long)x*(Math.min(b, r)-Math.max(a, l));
            add(a, b, x, k*2+1, l, (l+r)/2);
            add(a, b, x, k*2+2, (l+r)/2, r);
        }
    }

