        if (a<=l && r<=b) return data[k]*(r-l)+datb[k];
        else if (!(b<=l || r<=a)) {
            long tmp = data[k]*(Math.min(b, r)-Math.max(a, l));
            tmp += sum(a, b, k*2+1, l, (l+r)/2);
            tmp += sum(a, b, k*2+2, (l+r)/2, r);
            return tmp;
        } else {
            return 0L;
        }
    }

