public class RAQRSQSegmentTree
{
    long[] buffer;
    long[] lazy;
    int N;

    public RAQRSQSegmentTree(int cap)
    {
        var c = 1;
        while (c < cap) c <<= 1;

        N = c;
        buffer = new long[N * 2 - 1];
        lazy = new long[N * 2 - 1];
    }

    public RAQRSQSegmentTree(int[] init)
    {
        var c = 1;
        while (c < init.Length) c <<= 1;

        N = c;
        buffer = new long[N * 2 - 1];
        lazy = new long[N * 2 - 1];

        Array.Copy(init, 0, buffer, N - 1, init.Length);
        for (int i = N - 2; i >= 0; i--)
        {
            buffer[i] = buffer[i * 2 + 1] + buffer[i * 2 + 2];
        }
    }

    public void Add(int index, long value)
    {
        index += N - 1;
        buffer[index] += value;
        while (index > 0)
        {
            index = (index - 1) >> 1;
            buffer[index] = buffer[index * 2 + 1] + buffer[index * 2 + 2];
        }
    }

    public long this[int index]
    {
        set
        {
            Add(index, value);
        }
        get
        {
            return buffer[index + N - 1];
        }
    }

    void Eval(int k, int l, int r)
    {
        if (lazy[k] != 0)
        {
            buffer[k] += lazy[k];
            if (r - l > 1)
            {
                lazy[2 * k + 1] += lazy[k] / 2;
                lazy[2 * k + 2] += lazy[k] / 2;
            }
            lazy[k] = 0;
        }
    }

    public void Add(int a, int b, long x, int k, int l, int r)
    {
        Eval(k, l, r);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b)
        {
            lazy[k] += (r - l) * x;
            Eval(k, l, r);
        }
        else
        {
            Add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            Add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            buffer[k] = buffer[2 * k + 1] + buffer[2 * k + 2];
        }
    }

    public void Add(int l, int r, long v)
    {
        Add(l, r, v, 0, 0, N);
    }

    public long Query(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0) r = N;
        if (b <= l || r <= a) return 0;
        Eval(k, l, r);
        if (a <= l && r <= b) return buffer[k];
        var vl = Query(a, b, 2 * k + 1, l, (l + r) / 2);
        var vr = Query(a, b, 2 * k + 2, (l + r) / 2, r);
        return vl + vr;
    }
}

