public class Avl2{
	public class Nd{
		public int h=1,c=1;
		public int nl,nr;
		public long d,ds=0,dd=0;
		public Nd l,r;
		public bool lf;
		public Nd(int nl,int nr,long d,Nd du){this.nl=nl;this.nr=nr;this.d=d;ds=(nr-nl+1)*d;l=du;r=du;lf=true;}
		public Nd(int nl,int nr,Nd l,Nd r){
			this.nl=nl;this.nr=nr;this.l=l;this.r=r;
			Sum(this);
			h=Max(l.h,r.h)+1;
			lf=false;
		}
	}
	public Nd root,du;
	public int cnt=0;
	public Avl2(){
		du=new Nd(int.MinValue,int.MaxValue,0,du);
		du.h=0;du.c=0;
		root=du;
	}
	private static void Sum(Nd nd){
		nd.ds=nd.l.ds+nd.r.ds;
	}
	private void Sum2(Nd nd,long d){
		nd.d+=d;
		nd.ds+=(nd.nr-nd.nl+1)*d;
	}
	public void Ud(int a,int b,long d){
		if(a>b){a^=b;b^=a;a^=b;}
		if(root!=du){
			root=Fu(root,a,b,d);
			if(Abs(root.l.h-root.r.h)>1){root=Rotate(root);}
		}
		else{root=new Nd(a,b,d,du);}
	}
	private Nd Fu(Nd t,int nl,int nr,long d){
		Fdd(t);
		if(!t.lf){
			if(t.nl==nl&&t.nr==nr){
				Sum2(t,d);
				t.l.dd+=d;
				t.r.dd+=d;
				return t;
			}
			if(t.l.nr>=nl){t.l=Fu(t.l,nl,Min(t.l.nr,nr),d);}
			if(t.l.nr<nr){t.r=Fu(t.r,Max(t.l.nr+1,nl),nr,d);}
			if(Abs(t.l.l.h-t.l.r.h)>1){t.l=Rotate(t.l);}
			if(Abs(t.r.l.h-t.r.r.h)>1){t.r=Rotate(t.r);}
			Fdd(t.l);Fdd(t.r);
			Sum(t);
			t.nl=t.l.nl;
			t.nr=t.r.nr;
			t.h=Max(t.l.h,t.r.h)+1;
		}
		else{
			if(t.nr<nl){return new Nd(t.nl,nr,t,new Nd(nl,nr,d,du));}
			else if(t.nl>nr){return new Nd(nl,t.nr,new Nd(nl,nr,d,du),t);}
			else if(t.nl<nl){
				if(t.nr<nr){
					Nd e=new Nd(nl,nr,new Nd(nl,t.nr,t.d+d,du),new Nd(t.nr+1,nr,d,du));
					t.nr=nl-1;
					t.ds=(t.nr-t.nl+1)*t.d;
					return new Nd(t.nl,nr,t,e);
				}
				else if(t.nr>nr){
					Nd e=new Nd(nl,t.nr,new Nd(nl,nr,t.d+d,du),new Nd(nr+1,t.nr,t.d,du));
					int z=t.nr;
					t.nr=nl-1;
					t.ds=(t.nr-t.nl+1)*t.d;
					return new Nd(t.nl,z,t,e);
				}
				else{
					t.nr=nl-1;
					t.ds=(t.nr-t.nl+1)*t.d;
					return new Nd(t.nl,nr,t,new Nd(nl,nr,t.d+d,du));
				}
			}
			else if(t.nl>nl){
				if(t.nr<nr){
					Sum2(t,d);
					Nd e=new Nd(nl,nr,new Nd(nl,t.nl-1,d,du),new Nd(t.nl,nr,t,new Nd(t.nr+1,nr,d,du)));
					return e;
				}
				else if(t.nr>nr){
					Nd e=new Nd(nl,nr,new Nd(nl,t.nl-1,d,du),new Nd(t.nl,nr,t.d+d,du));
					t.nl=nr+1;
					t.ds=(t.nr-t.nl+1)*t.d;
					return new Nd(nl,t.nr,e,t);
				}
				else{
					Sum2(t,d);
					return new Nd(nl,nr,new Nd(nl,t.nl-1,d,du),t);
				}
			}
			else{
				if(t.nr<nr){
					Sum2(t,d);
					return new Nd(nl,nr,t,new Nd(t.nr+1,nr,d,du));
				}
				else if(t.nr>nr){
					t.nl=nr+1;
					t.ds=(t.nr-t.nl+1)*t.d;
					return new Nd(nl,t.nr,new Nd(nl,nr,t.d+d,du),t);
				}
				else{
					Sum2(t,d);
					return t;
				}
			}
		}
		return t;
	}
	public long Get(int a,int b){
		return Fdg(root,a,b);
	}
	private long Fdg(Nd t,int nl,int nr){
		Fdd(t);
		if(t.lf){
			return (Min(t.nr,nr)-Max(t.nl,nl)+1)*t.d;
		}
		if(nl<=t.nl&&nr>=t.nr){return t.ds;}
		long d=0;
		if(t.l.nr>=nl){d=Fdg(t.l,nl,nr);}
		if(t.r.nl<=nr){d+=Fdg(t.r,nl,nr);}
		return d;
	}
	private void Fdd(Nd t){
		if(t.dd!=0){
			Sum2(t,t.dd);
			t.l.dd+=t.dd;
			t.r.dd+=t.dd;
			t.dd=0;
		}
	}
	private Nd Rotate(Nd t){
		Nd nd=du;
		Fdd(t);
		if(t.l.h>t.r.h){
			Fdd(t.l);
			if(t.l.l.h>t.l.r.h){
				nd=t.l;t.l=t.l.r;nd.r=t;
				Ft(t);
			}
			else{
				Fdd(t.l.r);
				nd=t.l.r;
				t.l.r=nd.l;nd.l=t.l;
				Ft(t.l);
				t.l=nd.r;nd.r=t;
				Ft(t);
			}
		}
		else{
			Fdd(t.r);
			if(t.r.l.h>t.r.r.h){
				Fdd(t.r.l);
				nd=t.r.l;
				t.r.l=nd.r;nd.r=t.r;
				Ft(t.r);
				t.r=nd.l;nd.l=t;
				Ft(t);
			}
			else{
				nd=t.r;t.r=t.r.l;nd.l=t;
				Ft(t);
			}
		}
		Ft(nd);
		return nd;
	}
	private void Ft(Nd t){
		if(!t.lf){
			t.h=Max(t.l.h,t.r.h)+1;
			t.c=t.l.c+t.r.c;
			Fdd(t.l);Fdd(t.r);
			Sum(t);
			t.nl=t.l.nl;
			t.nr=t.r.nr;
		}
	}
}

