  static void AreaChangeMinGetReady()
  {//区間以上以下の値を全てchangeNumに変更し、区間以上以下の最小値を求める初期値前処理。
    for(int i = 0; i < 600*600; i++)
    {
      nums[i] = 2147483647;
    }
    for(int i = 0; i < 600; i++)
    {
      numSets[i] = 2147483647;
      numSetsSub[i] = long.MinValue;
    } 
  }

  static void AreaChangePointGetReady()
  {//区間以上以下の値を全てchangeNumに変更し、ある１点の値を求める初期値前処理。
    AreaChangeMinGetReady();
  }

  static void AreaAddSumGetReady()
  {//区間以上以下の値に全てchangeNum加算し、区間以上以下の和を求める初期値前処理。
    for(int i = 0; i < 600*600; i++)
    {
      nums[i] = 0;
    }
    for(int i = 0; i < 600; i++)
    {
      numSets[i] = 0;
      for(int j = 0; j < 600; j++)
      {
        numSetsSub[i] += nums[600*i+j];//区間の和
      }
    }
  }

  static void AreaChangeMinGet(int leftNum, int rightNum, long changeNum)
  {//区間以上以下の値を全てchangeNumに変更し、区間以上以下の最小値を求める。入力側
    int leftPosition = WherePosition(leftNum);
    int rightPosition = WherePosition(rightNum);

    NumberApply(leftNum, rightNum);

    if(leftPosition == rightPosition)//左右が同じ分類のとき
    {
      for(long i = leftNum; i <= rightNum; i++)
      {
        nums[i] = changeNum;
      }
      long minMemo = long.MaxValue;
      for(long i = 0; i < 600; i++)//区間内全てを見る
      {
        minMemo = Math.Min(minMemo, nums[leftPosition*600+i]);
      }
      numSets[leftPosition] = minMemo;
    }else
    {
      for(long i = leftNum; i < 600*(leftPosition+1); i++)//左区間内（左端より右だけ見る）
      {
        nums[i] = changeNum;
      }
      for(long i = 600*rightPosition; i <= rightNum; i++)//右区間内
      {
        nums[i] = changeNum;
      }
      long minMemoL = long.MaxValue;
      long minMemoR = long.MaxValue;
      for(long i = 0; i < 600; i++)//区間内全てを見る
      {
        minMemoL = Math.Min(minMemoL, nums[leftPosition*600+i]);
        minMemoR = Math.Min(minMemoR, nums[rightPosition*600+i]);
      }
      numSets[leftPosition] = minMemoL;
      numSets[rightPosition] = minMemoR;

      for(int i = leftPosition+1; i < rightPosition; i++)//見ていない区間内
      {
        numSetsSub[i] = changeNum;
        numSets[i] = changeNum;
      }
    }
  }

  static void AreaChangePointGet(int leftNum, int rightNum, long changeNum)
  {//区間以上以下の値を全てchangeNumに変更し、ある１点の値を求める。入力側
    AreaChangeMinGet(leftNum, rightNum, changeNum);
  }

  static void AreaAddSumGet(int leftNum, int rightNum, long changeNum)
  {//区間以上以下の値に全てchangeNum加算し、区間以上以下の和を求める。入力側
    int leftPosition = WherePosition(leftNum);
    int rightPosition = WherePosition(rightNum);

    if(leftPosition == rightPosition)//左右が同じ分類のとき
    {
      for(long i = leftNum; i <= rightNum; i++)
      {
        nums[i] += changeNum;
        numSetsSub[leftPosition] += changeNum;
      }
    }else
    {
      for(long i = leftNum; i < 600*(leftPosition+1); i++)//左区間内（左端より右だけ見る）
      {
        nums[i] += changeNum;
        numSetsSub[leftPosition] += changeNum;
      }
      for(long i = 600*rightPosition; i <= rightNum; i++)//右区間内
      {
        nums[i] += changeNum;
        numSetsSub[rightPosition] += changeNum;
      }
      for(int i = leftPosition+1; i < rightPosition; i++)//見ていない区間内
      {
        numSetsSub[i] += changeNum*600;
        numSets[i] += changeNum*600;
      }
    }
  }

  static long AreaChangeMinGetAnswer(int leftNum, int rightNum)
  {//区間以上以下の値を全てchangeNumに変更し、区間以上以下の最小値を求める。出力側
    long minMemo = long.MaxValue;
    int leftPosition = WherePosition(leftNum);
    int rightPosition = WherePosition(rightNum);

    NumberApply(leftNum, rightNum);

    if(leftPosition == rightPosition)
    {
      for(long i = leftNum; i <= rightNum; i++)//左右が同じ分類のとき
      {
        minMemo = Math.Min(minMemo, nums[i]);
      }
    }else
    {
      for(long i = leftNum; i < 600*(leftPosition+1); i++)//左区間内（左端より右だけ見る）
      {
        minMemo = Math.Min(minMemo, nums[i]);
      }
      for(long i = 600*rightPosition; i <= rightNum; i++)//右区間内
      {
        minMemo = Math.Min(minMemo, nums[i]);
      }
      for(long i = leftPosition+1; i < rightPosition; i++)//見ていない区間内
      {
        minMemo = Math.Min(minMemo, numSets[i]);
      }
    }
    return minMemo;
  }

  static long AreaChangePointGetAnswer(int pointNum)
  {//区間以上以下の値を全てchangeNumに変更し、ある１点の値を求める。出力側
    int numPosition = WherePosition(pointNum);

    NumberApply(pointNum);

    return nums[pointNum];
  }

  static long AreaAddSumGetAnswer(int leftNum, int rightNum)
  {//区間以上以下の値に全てchangeNum加算し、区間以上以下の和を求める。出力側
    long sum = 0;
    int leftPosition = WherePosition(leftNum);
    int rightPosition = WherePosition(rightNum);

    if(leftPosition == rightPosition)
    {
      for(long i = leftNum; i <= rightNum; i++)//左右が同じ分類のとき
      {
        sum += numSets[leftPosition] + nums[i];
      }
    }else
    {
      for(long i = leftNum; i < 600*(leftPosition+1); i++)//左区間内（左端より右だけ見る）
      {
        sum += numSets[leftPosition] + nums[i];
      }
      for(long i = 600*rightPosition; i <= rightNum; i++)//右区間内
      {
        sum += numSets[rightPosition] + nums[i];
      }
      for(long i = leftPosition+1; i < rightPosition; i++)//見ていない区間内
      {
        sum += numSetsSub[i];
      }
    }
    return sum;
  }

  static void NumberApply(int pointNum)
  {//控え中の数を個々に割り当てる
    int numPosition = WherePosition(pointNum);

    if(numSetsSub[numPosition] != long.MinValue)
    {
      for(int i = 0; i < 600; i++)//区間内全てを見る
      {
        nums[numPosition*600+i] = numSetsSub[numPosition];
      }
      numSetsSub[numPosition] = long.MinValue;
    }
  }

  static void NumberApply(int leftNum, int rightNum)
  {
    NumberApply(leftNum);
    NumberApply(rightNum);
  }

  static int WherePosition(int num)//左から何番目の分類に属するか
  {
    return num / 600;
  }

}

using System;
