class Program
{
    static void Main()
    {
        SetOut(new System.IO.StreamWriter(OpenStandardOutput()) { AutoFlush = false });
        var N = FastIO.Int();
        var Q = FastIO.Int();
        var d = new SplayTree<long, long>((x, y) => x + y, (x, y, s) => x + y * s, (x, y) => x + y, 0, 0);
        d.Init(N);
        for (int i = 0; i < Q; i++)
        {
            if (FastIO.Int() == 0)
            {
                var s = FastIO.Int() - 1;
                var t = FastIO.Int();
                var x = FastIO.Int();
                d.Update(s, t, x);
            }
            else
