public class LazySegmentTree//RAQ
{
    int[] buffer;
    int[] lazy;
    int N;
    int IE;
    Func<int, int, int> Op;

    public LazySegmentTree(int cap,  Func<int, int, int> op, int E)
    {
        var c = 1;
        while (c < cap) c <<= 1;

        N = c;
        buffer = new int[N * 2 - 1];
        lazy = new int[N * 2 - 1];
        for (int i = 0; i < buffer.Length; i++) buffer[i] = E;
        Op = op;
        IE = E;
    }

    public LazySegmentTree(int[] init, Func<int, int, int> op, int E)
    {
        var c = 1;
        while (c < init.Length) c <<= 1;

        N = c;
        buffer = new int[N * 2 - 1];
        lazy = new int[N * 2 - 1];

        Array.Copy(init, 0, buffer, N - 1, init.Length);
        for (int i = init.Length + N - 1; i < buffer.Length; i++) buffer[i] = E;
        for (int i = N - 2; i >= 0; i--)
        {
            buffer[i] = op(buffer[i * 2 + 1], buffer[i * 2 + 2]);
        }
        Op = op;
        IE = E;
    }

    public void Update(int index, int value)
    {
        index += N - 1;
        buffer[index] = value;
        while (index > 0)
        {
            index = (index - 1) >> 1;
            buffer[index] = Op(buffer[index * 2 + 1], buffer[index * 2 + 2]);
        }
    }

    public int this[int index]
    {
        set
        {
            Update(index, value);
        }
        get
        {
            return buffer[index + N - 1];
        }
    }

    void Eval(int k, int l, int r)
    {

        // 遅延配列が空でない場合、自ノード及び子ノードへの
        // 値の伝播が起こる
        if (lazy[k] != 0)
        {
            buffer[k] += lazy[k];

            // 最下段かどうかのチェックをしよう
            // 子ノードは親ノードの 1/2 の範囲であるため、
            // 伝播させるときは半分にする
            if (r - l > 1)
            {
                lazy[2 * k + 1] += lazy[k] / 2;
                lazy[2 * k + 2] += lazy[k] / 2;
            }

            // 伝播が終わったので、自ノードの遅延配列を空にする
            lazy[k] = 0;
        }
    }
    public void Add(int a, int b, int x, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0) r = N;

        // k 番目のノードに対して遅延評価を行う
       Eval(k, l, r);

        // 範囲外なら何もしない
        if (b <= l || r <= a) return;

        // 完全に被覆しているならば、遅延配列に値を入れた後に評価//評価必要？
        if (a <= l && r <= b)
        {
            lazy[k] += (r - l) * x;
            Eval(k, l, r);
        }

        // そうでないならば、子ノードの値を再帰的に計算して、
        // 計算済みの値をもらってくる
        else
        {
            Add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            Add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            buffer[k] = buffer[2 * k + 1] + buffer[2 * k + 2];
        }
    }
    public int Query(int l, int r)//[l, r) 0 <= l, r <= N // 0 <= r - l のとき空区間
    {
        var lv = IE;
        var rv = IE;
        l += N - 1;
        r += N - 1;
        while (l < r)
        {
            if ((l & 1) == 0)
            {
                lv = Op(lv, buffer[l]);
            }
            if ((r & 1) == 0)
            {
                rv = Op(buffer[r - 1], rv);
            }
            l >>= 1;
            r = (r - 1) >> 1;
        }
        return Op(lv, rv);
    }
}

using System;
using System.Collections.Generic;
using System.Text;
using CompLib.DataStructures;

public class Program
{
    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int q = sc.NextInt();

        var st = new LazySegmentTreeRsq(n);
        var sb = new StringBuilder();
        for (int i = 0; i < q; i++)
        {
            string type = sc.Next();
            if (type == "0")
            {
                int s = sc.NextInt();
                int t = sc.NextInt();
                int x = sc.NextInt();
                st.Add(s - 1, t, x);
            }
            else
            {
                int s = sc.NextInt();
                int t = sc.NextInt();
                sb.AppendLine(st.Sum(s - 1, t).ToString());
            }
        }

        Console.Write(sb.ToString());
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

namespace CompLib.DataStructures
{
    #region RangeSumQuery

    using N = Int64;

    /// <summary>
    /// 遅延セグメント木 (RangeSumQuery)
    /// 指定した範囲の和を求める、更新 それぞれO(log N)
    /// </summary>
    public class LazySegmentTreeRsq
    {
        private readonly int _size;
        private readonly N[] _array;
        private readonly N[] _add;
        private readonly N[] _update;
        private readonly bool[] _updateFlag;

        /// <summary>
        /// コンストラクタ
        /// 全て0で初期化
        /// </summary>
        /// <param name="size">配列の大きさ = N</param>
        public LazySegmentTreeRsq(int size)
        {
            _size = 1;
            while (_size < size)
                _size *= 2;
            _array = new N[_size * 2];
            _add = new N[_size * 2];
            _update = new N[_size * 2];
            _updateFlag = new bool[_size * 2];
        }

        /// <summary>
        /// コンストラクタ
        /// 配列aをコピー
        /// </summary>
        /// <param name="a">配列</param>
        public LazySegmentTreeRsq(N[] a) : this(a.Length)
        {
            for (int i = 0; i < a.Length; i++)
                _array[i + _size] = a[i];
            for (int i = _size - 1; i >= 1; i--)
                _array[i] = _array[i * 2] + _array[i * 2 + 1];
        }

        private void Eval(int l, int r, int k)
        {
            if (_updateFlag[k])
            {
                _array[k] = _update[k] * (r - l);
                if (r - l > 1)
                {
                    _update[k * 2] = _update[k];
                    _update[k * 2 + 1] = _update[k];
                    _add[k * 2] = 0;
                    _add[k * 2 + 1] = 0;
                    _updateFlag[k * 2] = true;
                    _updateFlag[k * 2 + 1] = true;
                }

                _updateFlag[k] = false;
            }

            if (_add[k] != 0)
            {
                _array[k] += _add[k] * (r - l);
                if (r - l > 1)
                {
                    _add[k * 2] += _add[k];
                    _add[k * 2 + 1] += _add[k];
                }

                _add[k] = 0;
            }
        }

        private void Add(int left, int right, int k, int l, int r, N n)
        {
            Eval(l, r, k);
            if (r <= left || right <= l) return;
            if (left <= l && r <= right)
            {
                _add[k] += n;
                Eval(l, r, k);
            }
            else
            {
                Add(left, right, k * 2, l, (l + r) / 2, n);
                Add(left, right, k * 2 + 1, (l + r) / 2, r, n);
                _array[k] = _array[k * 2] + _array[k * 2 + 1];
            }
        }

        /// <summary>
        /// [left,right)にnを足す O(log N)
        /// </summary>
        /// <param name="left">左端</param>
        /// <param name="right">右端</param>
        /// <param name="n">増やす値</param>
        public void Add(int left, int right, N n) => Add(left, right, 1, 0, _size, n);

        /// <summary>
        /// i番目にnを足す O(log N)
        /// </summary>
        /// <param name="i">インデックス</param>
        /// <param name="n">増やす値</param>
        public void Add(int i, N n) => Add(i, i + 1, n);

        private void Update(int left, int right, int k, int l, int r, N n)
        {
            Eval(l, r, k);
            if (r <= left || right <= l) return;
            if (left <= l && r <= right)
            {
                _update[k] = n;
                _updateFlag[k] = true;
                _add[k] = 0;
                Eval(l, r, k);
            }
            else
            {
                Update(left, right, k * 2, l, (l + r) / 2, n);
                Update(left, right, k * 2 + 1, (l + r) / 2, r, n);
                _array[k] = _array[k * 2] + _array[k * 2 + 1];
            }
        }

        /// <summary>
        /// [left, right)をnに置き換える
        /// </summary>
        /// <param name="left">右端</param>
        /// <param name="right">左端</param>
        /// <param name="n">置き換える値</param>
        public void Update(int left, int right, N n) => Update(left, right, 1, 0, _size, n);

        /// <summary>
        /// i番目をnに置き換える
        /// </summary>
        /// <param name="i">インデックス</param>
        /// <param name="n">置き換える値</param>
        public void Update(int i, N n) => Update(i, i + 1, n);

        private N Sum(int left, int right, int k, int l, int r)
        {
            Eval(l, r, k);
            if (r <= left || right <= l) return 0;
            if (left <= l && r <= right) return _array[k];
            return Sum(left, right, k * 2, l, (l + r) / 2) + Sum(left, right, k * 2 + 1, (l + r) / 2, r);
        }

        /// <summary>
        /// [left, right)の和を求める O(log N)
        /// </summary>
        /// <param name="left">左端</param>
        /// <param name="right">右端</param>
        /// <returns></returns>
        public N Sum(int left, int right) => Sum(left, right, 1, 0, _size);

        public N this[int i]
        {
            get { return Sum(i, i + 1); }
            set { Update(i, value); }
        }
    }

    #endregion
}

