struct RSQ2
{
    private int n;
    private long[] dat;
    private long[] lazy; // 遅延
    public int Length { get; private set; }

    /* nを要素数として、すべて0で初期化 */
    public RSQ2(int n)
    {
        Length = n;
        this.n = 1;
        while (this.n < n) this.n *= 2;
        dat = new long[2 * this.n - 1];
        lazy = new long[2 * this.n - 1];
    }

    /* k番目のノードについて遅延評価を行う */
    private void Eval(int k, int l, int r)
    {
        if (lazy[k] == 0) return;
        dat[k] += lazy[k];
        if (r - l > 1)
        {
            lazy[2 * k + 1] += lazy[k] / 2;
            lazy[2 * k + 2] += lazy[k] / 2;
        }
        lazy[k] = 0;
    }


    public void Add(int a, int b, long x, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0) r = n;
        Eval(k, l, r);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b)
        {
            lazy[k] += (r - l) * x;
            Eval(k, l, r);
        }
        else
        {
            Add(a, b, x, 2 * k + 1, l, (l + r) / 2);
            Add(a, b, x, 2 * k + 2, (l + r) / 2, r);
            dat[k] = dat[2 * k + 1] + dat[2 * k + 2];
        }
    }

    private long Query_(int a, int b, int k, int l, int r)
    {
        if (r <= a || b <= l) return 0;
        Eval(k, l, r);
        if (a <= l && r <= b) return dat[k];
        long v1 = Query_(a, b, k * 2 + 1, l, (l + r) / 2);
        long v2 = Query_(a, b, k * 2 + 2, (l + r) / 2, r);
        return v1 + v2;
    }

    /* [a,b)の和を求める */
    public long Query(int a, int b)
    {
        return Query_(a, b, 0, 0, n);
    }
}

