class BIT //[1, n]
{
    int n;
    int[] bit;

    public BIT(int N)
    {
        n = N;
        bit = new int[n + 1];
    }

    public void Add(int i, int x)
    {
        while (i <= n)
        {
            bit[i] += x;
            i += i & -i;
        }
    }

    // [1, i] sum
    public int Sum(int i)
    {
        int s = 0;
        while(i > 0)
        {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    //[a, b] sum
    public int Sum(int a, int b)
    {
        return Sum(b) - Sum(a - 1);
    }
}
