type LazySegTree struct {
	nodes []int
	lazy  []int
}

const Inf = 1 << 62
const None = -Inf

func NewLazySegTree(n_ int) *LazySegTree {
	n := 1
	for n < n_ {
		n <<= 1
	}
	t := &LazySegTree{
		nodes: make([]int, n*2),
		lazy:  make([]int, n*2),
	}
	for i := 1; i < len(t.lazy); i++ {
		t.lazy[i] = None
	}
	return t
}

func (t *LazySegTree) addLazy(k, x int) {
	if t.lazy[k] == None {
		t.lazy[k] = x
	} else {
		t.lazy[k] += x
	}
}

func (t *LazySegTree) lazyEval(k, l, r int) {
	if t.lazy[k] == None {
		return
	}
	t.nodes[k] += t.lazy[k]
	if r-l > 1 {
		t.addLazy(k*2, t.lazy[k]>>1)
		t.addLazy(k*2+1, t.lazy[k]>>1)
	}
	t.lazy[k] = None
}

func (t *LazySegTree) Add(a, b, x int) {
	t.addRecur(a, b, x, 1, 0, len(t.nodes)>>1)
}
func (t *LazySegTree) addRecur(a, b, x, k, l, r int) {
	t.lazyEval(k, l, r)
	if r <= a || b <= l {
		return
	}
	if a <= l && r <= b {
		t.addLazy(k, (r-l)*x)
		t.lazyEval(k, l, r)
	} else {
		t.addRecur(a, b, x, k*2, l, (l+r)/2)
		t.addRecur(a, b, x, k*2+1, (l+r)/2, r)
		t.nodes[k] = t.nodes[k*2] + t.nodes[k*2+1]
	}
}

func (t *LazySegTree) GetSum(a, b int) int {
	return t.getSumRecur(a, b, 1, 0, len(t.nodes)>>1)
}
func (t *LazySegTree) getSumRecur(a, b, k, l, r int) int {
	t.lazyEval(k, l, r)
	if r <= a || b <= l {
		return 0
	}
	if a <= l && r <= b {
		return t.nodes[k]
	} else {
		return t.getSumRecur(a, b, k*2, l, (l+r)/2) +
			t.getSumRecur(a, b, k*2+1, (l+r)/2, r)
	}
}

