      data0.add(s,-x*(s-1))
      data0.add(t+1,x*t)
      data1.add(s,x)
      data1.add(t+1,-x)
    else:
      s,t = y
      ans.append(data1.sum(t)*t+data0.sum(t)-data1.sum(s-1)*(s-1)-data0.sum(s-1))
  return ans
