        } else {
            println!("{}", seg.sum(v[1] - 1, v[2], 0, 0, n));
        }
    }
}

use std::io;
use std::io::prelude::*;
use std::iter::repeat;

struct SumSegTree {
    n: usize,
    nodes: Vec<(u64, u64)>,
}

impl SumSegTree {
    fn new(n: usize) -> SumSegTree {
        let n = 1 << f64::log2(n as f64).ceil() as usize;
        SumSegTree {
            n,
            nodes: repeat((0, 0)).take(2 * n - 1).collect(),
        }
    }

    fn add(&mut self, s: usize, t: usize, x: u64, ni: usize, l: usize, r: usize) {
        self.eval(ni);
        if r <= s || t <= l {
            return;
        }
        if s <= l && r <= t {
            self.nodes[ni].1 = (r - l) as u64 * x;
            self.eval(ni);
            return;
        }
        let m = (l + r) / 2;
        self.add(s, t, x, 2 * ni + 1, l, m);
        self.add(s, t, x, 2 * ni + 2, m, r);
        self.nodes[ni].0 = self.nodes[2 * ni + 1].0 + self.nodes[2 * ni + 2].0;
    }

    fn eval(&mut self, ni: usize) -> u64 {
        self.nodes[ni].0 += self.nodes[ni].1;
        if ni < self.n - 1 {
            self.nodes[2 * ni + 1].1 += self.nodes[ni].1 / 2;
            self.nodes[2 * ni + 2].1 += self.nodes[ni].1 / 2;
        }
        self.nodes[ni].1 = 0;
        self.nodes[ni].0
    }

    fn get_sum(&mut self, s: usize, t: usize, ni: usize, l: usize, r: usize) -> u64 {
        self.eval(ni);
        if s <= l && r <= t {
            self.nodes[ni].0
        } else if r <= s || t <= l {
            0
        } else {
            self.get_sum(s, t, 2 * ni + 1, l, (l + r) / 2)
                + self.get_sum(s, t, 2 * ni + 2, (l + r) / 2, r)
        }
    }
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let line0 = lines.next().unwrap().unwrap();
    let n = line0.split_whitespace().next().unwrap().parse().unwrap();

    let mut mst = SumSegTree::new(n);

    for l in lines.map(Result::unwrap) {
        let mut words = l.split_whitespace();
        let com = words.next().unwrap().parse().unwrap();
        let s: usize = words.next().unwrap().parse().unwrap();
