trait SEGImpl {
    type Elem: Clone;
    fn id() -> Self::Elem;
    // node value 0, node value 1 -> node value
    fn op(x: &Self::Elem, y: &Self::Elem) -> Self::Elem;
    // propagate lazy value upward
    fn up(l: usize, r: usize, e: Self::Elem) -> Self::Elem;
    /// current value, lazy value -> new value, child's lazy value
    fn down(cur: Self::Elem, lazy_val: Self::Elem) -> (Self::Elem, Self::Elem);
    // current lazy value, propagated lazy value -> new lazy value
    fn lazy_op(cur: &Self::Elem, propagated: &Self::Elem) -> Self::Elem;
}
struct SEG<T: SEGImpl> {
    n: usize,
    node: Vec<T::Elem>,
    lazy: Vec<Option<T::Elem>>,
}

impl <T: SEGImpl> SEG<T> {
    fn new(n: usize) -> SEG<T> {
        let mut m = 1;
        while m < n { m *= 2; }
        SEG {
            n: m,
            node: vec![T::id(); m*2-1],
            lazy: vec![None; m*2-1],
        }
    }
    fn eval(&mut self, k: usize, l: usize, r: usize) {
        if let Some(lzv) = self.lazy[k].clone() {
            let cur_val = self.node[k].clone();
            let (new_val, child_lzv) = T::down(cur_val, lzv);
            self.node[k] = new_val;
            // propagate the lazy value to its children
            if r - l > 1 {
                self.lazy[k*2+1] = match self.lazy[k*2+1].clone() {
                    Some(x) => Some(T::lazy_op(&x, &child_lzv)),
                    None => Some(child_lzv.clone()),
                };
                self.lazy[k*2+2] = match self.lazy[k*2+2].clone() {
                    Some(x) => Some(T::lazy_op(&x, &child_lzv)),
                    None => Some(child_lzv.clone()),
                };
            }
            self.lazy[k] = None;
        }
    }
    fn do_update(&mut self, a: usize, b: usize, x: T::Elem, k: usize, l: usize, r: usize) {
        self.eval(k,l,r);

        if b <= l || r <= a {
            return;
        }

        if a <= l && r <= b {
            self.lazy[k] = match self.lazy[k].clone() {
                Some(a) => Some(T::lazy_op(&a, &T::up(l,r,x))),
                None => Some(T::up(l,r,x)),
            };
            self.eval(k,l,r);
        }

        else {
            self.do_update(a,b,x.clone(),2*k+1,l,(l+r)/2);
            self.do_update(a,b,x.clone(),2*k+2,(l+r)/2,r);
            self.node[k] = T::op(&self.node[2*k+1],&self.node[2*k+2]);
        }
    }
    fn update(&mut self, a: usize, b: usize, x: T::Elem) {
        let n = self.n;
        self.do_update(a,b,x,0,0,n)
    }
    fn do_query(&mut self, a: usize, b: usize, k: usize, l: usize, r: usize) -> T::Elem {
        if r <= a || b <= l {
            return T::id();
        }

        self.eval(k,l,r);

        if a <= l && r <= b {
            return self.node[k].clone();
        } else {
            let vl = self.do_query(a,b,k*2+1,l,(l+r)/2);
            let vr = self.do_query(a,b,k*2+2,(l+r)/2,r);
            return T::op(&vl,&vr);
        }
    }
    fn query(&mut self, a: usize, b: usize) -> T::Elem {
        let n = self.n;
        self.do_query(a,b,0,0,n)
    }
}
struct Impl;
impl SEGImpl for Impl {
    type Elem = i64;
    fn id() -> Self::Elem {
        0
    }
    fn op(x: &Self::Elem, y: &Self::Elem) -> Self::Elem {
        x.clone() + y.clone()
    }
    fn up(l: usize, r: usize, e: Self::Elem) -> Self::Elem {
        e * (r - l) as i64
    }
    fn down(cur: Self::Elem, lazy_val: Self::Elem) -> (Self::Elem, Self::Elem) {
        (cur+lazy_val, lazy_val/2)
    }
    fn lazy_op(x: &Self::Elem, y: &Self::Elem) -> Self::Elem {
        x.clone() + y.clone()
    }
}
fn solve() {
    input! {
        new_stdin_parser = parser,
        n: usize, q: usize,
    }

    let mut seg: SEG<Impl> = SEG::new(n);

    for _ in 0..q {
        input! {
            parser = parser,
            com: usize,
        }
        if com == 0 {
            input! {
                parser = parser,
                s: usize, t: usize, x: i64,
            }
            seg.update(s-1,t,x);
        } else {
            input! {
                parser = parser,
                i: usize, j: usize,
            }
            println!("{}", seg.query(i-1,j));
        }
    }
}

use std::io::*;

mod segment_tree {
    use std::cmp::*;
    pub struct SegmentTree {
        data: Vec<usize>,
        datb: Vec<usize>,
    }
    impl SegmentTree {
        pub fn new(n: usize) -> SegmentTree {
            let size = n.next_power_of_two();
            SegmentTree {
                data: vec![0; size * 2],
                datb: vec![0; size * 2],
            }
        }
        pub fn update(&mut self, a: usize, b: usize, x: usize, i: usize, l: usize, r: usize) {
            if a <= l && r <= b {
                self.data[i] += x;
            } else if l < b && a < r {
                self.datb[i] += x * (min(b, r) - max(a, l));
                self.update(a, b, x, i * 2 + 1, l, (l + r) >> 1);
                self.update(a, b, x, i * 2 + 2, (l + r) >> 1, r);
            }
        }
        pub fn query(&self, a: usize, b: usize, i: usize, l: usize, r: usize) -> usize {
            if r <= a || b <= l {
                0
            } else if a <= l && r <= b {
                self.data[i] * (r - l) + self.datb[i]
            } else {
                let mut res = self.data[i] * (min(b, r) - max(a, l));
                res += self.query(a, b, i * 2 + 1, l, (l + r) >> 1);
                res += self.query(a, b, i * 2 + 2, (l + r) >> 1, r);
                res
            }
        }
    }
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let q: usize = itr.next().unwrap().parse().unwrap();
    let mut st = segment_tree::SegmentTree::new(n + 2);
    for _ in 0..q {
        let c: usize = itr.next().unwrap().parse().unwrap();
        let s: usize = itr.next().unwrap().parse().unwrap();
        let t: usize = itr.next().unwrap().parse().unwrap();
        if c == 0 {
            let x: usize = itr.next().unwrap().parse().unwrap();
            st.update(s - 1, t, x, 0, 0, n);
        } else {
            println!("{}", st.query(s - 1, t, 0, 0, n));
        }
    }
}

